fn keyword(s: &[u8]) -> Option<Tok> {
    Some(match s {
        b"and" => Tok::And,
        b"break" => Tok::Break,
        b"do" => Tok::Do,
        b"else" => Tok::Else,
        b"elseif" => Tok::Elseif,
        b"end" => Tok::End,
        b"false" => Tok::False,
        b"for" => Tok::For,
        b"function" => Tok::Function,
        b"goto" => Tok::Goto,
        b"if" => Tok::If,
        b"in" => Tok::In,
        b"local" => Tok::Local,
        b"nil" => Tok::Nil,
        b"not" => Tok::Not,
        b"or" => Tok::Or,
        b"repeat" => Tok::Repeat,
        b"return" => Tok::Return,
        b"then" => Tok::Then,
        b"true" => Tok::True,
        b"until" => Tok::Until,
        b"while" => Tok::While,
        _ => return None,
    })
}

pub fn parse_number_literal(s: &[u8]) -> Option<f64> {
    // Accepts decimal and hex numbers (with optional fraction/exponent)
    let st = std::str::from_utf8(s).ok()?;
    let t = st.trim_matches(|c: char| c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\x0b' || c == '\x0c');
    if t.is_empty() {
        return None;
    }
    let (neg, body) = if let Some(r) = t.strip_prefix('-') {
        (true, r)
    } else if let Some(r) = t.strip_prefix('+') {
        (false, r)
    } else {
        (false, t)
    };
    let v = if body.len() > 1 && (body.starts_with("0x") || body.starts_with("0X")) {
        parse_hex(&body[2..])?
    } else {
        // decimal: validate charset
        let b = body.as_bytes();
        let mut i = 0;
        let mut digits = 0;
        while i < b.len() && b[i].is_ascii_digit() {
            i += 1;
            digits += 1;
        }
        if i < b.len() && b[i] == b'.' {
            i += 1;
            while i < b.len() && b[i].is_ascii_digit() {
                i += 1;
                digits += 1;
            }
        }
        if digits == 0 {
            let lower = body.to_ascii_lowercase();
            if lower == "inf" || lower == "nan" || lower == "infinity" {
                return None;
            }
            return None;
        }
        if i < b.len() && (b[i] == b'e' || b[i] == b'E') {
            i += 1;
            if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
                i += 1;
            }
            let st = i;
            while i < b.len() && b[i].is_ascii_digit() {
                i += 1;
            }
            if i == st {
                return None;
            }
        }
        if i != b.len() {
            return None;
        }
        body.parse::<f64>().ok()?
    };
    Some(if neg { -v } else { v })
}

fn parse_hex(s: &str) -> Option<f64> {
    let b = s.as_bytes();
    let mut i = 0;
    let mut v: f64 = 0.0;
    let mut any = false;
    while i < b.len() && b[i].is_ascii_hexdigit() {
        v = v * 16.0 + (b[i] as char).to_digit(16).unwrap() as f64;
        i += 1;
        any = true;
    }
    let mut exp: i32 = 0;
    if i < b.len() && b[i] == b'.' {
        i += 1;
        while i < b.len() && b[i].is_ascii_hexdigit() {
            v = v * 16.0 + (b[i] as char).to_digit(16).unwrap() as f64;
            exp -= 4;
            i += 1;
            any = true;
        }
    }
    if !any {
        return None;
    }
    if i < b.len() && (b[i] == b'p' || b[i] == b'P') {
        i += 1;
        let mut neg = false;
        if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
            neg = b[i] == b'-';
            i += 1;
        }
        let st = i;
        let mut e: i32 = 0;
        while i < b.len() && b[i].is_ascii_digit() {
            e = e.saturating_mul(10).saturating_add((b[i] - b'0') as i32);
            i += 1;
        }
        if st == i {
            return None;
        }
        exp += if neg { -e } else { e };
    }
    if i != b.len() {
        return None;
    }
    Some(v * (2f64).powi(exp))
}

impl<'a> Lexer<'a> {
    pub fn new(src: &'a [u8], chunkname: &str) -> Self {
        let mut pos = 0;
        // skip shebang
        if src.starts_with(b"#") {
            while pos < src.len() && src[pos] != b'\n' {
                pos += 1;
            }
        }
        Lexer {
            src,
            pos,
            line: 1,
            chunkname: chunkname.to_string(),
        }
    }

    fn peek(&self) -> u8 {
        if self.pos < self.src.len() {
            self.src[self.pos]
        } else {
            0
        }
    }
    fn peek_at(&self, n: usize) -> u8 {
        if self.pos + n < self.src.len() {
            self.src[self.pos + n]
        } else {
            0
        }
    }
    fn at_end(&self) -> bool {
        self.pos >= self.src.len()
    }

    pub fn err(&self, msg: &str, near: Option<&str>) -> String {
        match near {
            Some(n) => format!("{}:{}: {} near '{}'", self.chunkname, self.line, msg, n),
            None => format!("{}:{}: {}", self.chunkname, self.line, msg),
        }
    }

    fn newline(&mut self) {
        // handles \n, \r, \r\n, \n\r
        let c = self.peek();
        self.pos += 1;
        let d = self.peek();
        if (d == b'\n' || d == b'\r') && d != c {
            self.pos += 1;
        }
        self.line += 1;
    }

    fn long_bracket_level(&self) -> Option<usize> {
        // at '[' ; returns level if valid long bracket start
        let mut i = self.pos + 1;
        let mut level = 0;
        while i < self.src.len() && self.src[i] == b'=' {
            level += 1;
            i += 1;
        }
        if i < self.src.len() && self.src[i] == b'[' {
            Some(level)
        } else {
            None
        }
    }

    fn read_long_string(&mut self, level: usize, is_comment: bool) -> Result<Vec<u8>, String> {
        // positioned at first '['
        self.pos += level + 2;
        // skip first newline
        if self.peek() == b'\n' || self.peek() == b'\r' {
            self.newline();
        }
        let mut buf = Vec::new();
        loop {
            if self.at_end() {
                let what = if is_comment {
                    "unfinished long comment"
                } else {
                    "unfinished long string"
                };
                return Err(self.err(what, Some("<eof>")));
            }
            let c = self.peek();
            if c == b']' {
                let mut i = self.pos + 1;
                let mut l = 0;
                while i < self.src.len() && self.src[i] == b'=' {
                    l += 1;
                    i += 1;
                }
                if l == level && i < self.src.len() && self.src[i] == b']' {
                    self.pos = i + 1;
                    return Ok(buf);
                }
                buf.push(c);
                self.pos += 1;
            } else if c == b'\n' || c == b'\r' {
                buf.push(b'\n');
                self.newline();
            } else {
                buf.push(c);
                self.pos += 1;
            }
        }
    }

    fn read_string(&mut self, quote: u8) -> Result<Vec<u8>, String> {
        self.pos += 1;
        let mut buf = Vec::new();
        loop {
            if self.at_end() {
                return Err(self.err("unfinished string", Some("<eof>")));
            }
            let c = self.peek();
            if c == quote {
                self.pos += 1;
                return Ok(buf);
            }
            match c {
                b'\n' | b'\r' => {
                    let s = String::from_utf8_lossy(&buf).into_owned();
                    return Err(self.err("unfinished string", Some(&format!("{}{}", quote as char, s))));
                }
                b'\\' => {
                    self.pos += 1;
                    let e = self.peek();
                    match e {
                        b'n' => {
                            buf.push(b'\n');
                            self.pos += 1;
                        }
                        b't' => {
                            buf.push(b'\t');
                            self.pos += 1;
                        }
                        b'r' => {
                            buf.push(b'\r');
                            self.pos += 1;
                        }
                        b'a' => {
                            buf.push(7);
                            self.pos += 1;
                        }
                        b'b' => {
                            buf.push(8);
                            self.pos += 1;
                        }
                        b'f' => {
                            buf.push(12);
                            self.pos += 1;
                        }
                        b'v' => {
                            buf.push(11);
                            self.pos += 1;
                        }
                        b'\\' => {
                            buf.push(b'\\');
                            self.pos += 1;
                        }
                        b'"' => {
                            buf.push(b'"');
                            self.pos += 1;
                        }
                        b'\'' => {
                            buf.push(b'\'');
                            self.pos += 1;
                        }
                        b'\n' | b'\r' => {
                            buf.push(b'\n');
                            self.newline();
                        }
                        b'x' => {
                            self.pos += 1;
                            let mut v: u32 = 0;
                            for _ in 0..2 {
                                let h = self.peek();
                                if !h.is_ascii_hexdigit() {
                                    return Err(self.err("invalid escape sequence", Some("\\x")));
                                }
                                v = v * 16 + (h as char).to_digit(16).unwrap();
                                self.pos += 1;
                            }
                            buf.push(v as u8);
                        }
                        b'z' => {
                            self.pos += 1;
                            loop {
                                let w = self.peek();
                                if w == b'\n' || w == b'\r' {
                                    self.newline();
                                } else if w == b' ' || w == b'\t' || w == 11 || w == 12 {
                                    self.pos += 1;
                                } else {
                                    break;
                                }
                            }
                        }
                        b'u' => {
                            self.pos += 1;
                            if self.peek() != b'{' {
                                return Err(self.err("invalid escape sequence", Some("\\u")));
                            }
                            self.pos += 1;
                            let mut v: u32 = 0;
                            while self.peek().is_ascii_hexdigit() {
                                v = v.wrapping_mul(16) + (self.peek() as char).to_digit(16).unwrap();
                                self.pos += 1;
                            }
                            if self.peek() != b'}' {
                                return Err(self.err("invalid escape sequence", Some("\\u")));
                            }
                            self.pos += 1;
                            let mut tmp = [0u8; 4];
                            if let Some(ch) = char::from_u32(v) {
                                buf.extend_from_slice(ch.encode_utf8(&mut tmp).as_bytes());
                            } else {
                                // encode raw (surrogates etc.)
                                utf8_encode_raw(v, &mut buf);
                            }
                        }
                        d if d.is_ascii_digit() => {
                            let mut v: u32 = 0;
                            let mut n = 0;
                            while n < 3 && self.peek().is_ascii_digit() {
                                v = v * 10 + (self.peek() - b'0') as u32;
                                self.pos += 1;
                                n += 1;
                            }
                            if v > 255 {
                                return Err(self.err("invalid escape sequence", Some("\\")));
                            }
                            buf.push(v as u8);
                        }
                        0 if self.at_end() => {
                            return Err(self.err("unfinished string", Some("<eof>")));
                        }
                        _ => {
                            return Err(self.err(
                                "invalid escape sequence",
                                Some(&format!("\\{}", e as char)),
                            ));
                        }
                    }
                }
                _ => {
                    buf.push(c);
                    self.pos += 1;
                }
            }
        }
    }

    fn read_number(&mut self) -> Result<Tok, String> {
        let start = self.pos;
        if self.peek() == b'0' && (self.peek_at(1) == b'x' || self.peek_at(1) == b'X') {
            self.pos += 2;
            loop {
                let c = self.peek();
                if c.is_ascii_hexdigit() || c == b'.' {
                    self.pos += 1;
                } else if (c == b'p' || c == b'P')
                    && (self.peek_at(1) == b'+' || self.peek_at(1) == b'-')
                {
                    self.pos += 2;
                } else if c == b'p' || c == b'P' {
                    self.pos += 1;
                } else {
                    break;
                }
            }
        } else {
            loop {
                let c = self.peek();
                if c.is_ascii_digit() || c == b'.' {
                    self.pos += 1;
                } else if (c == b'e' || c == b'E')
                    && (self.peek_at(1) == b'+' || self.peek_at(1) == b'-')
                {
                    self.pos += 2;
                } else if c == b'e' || c == b'E' {
                    self.pos += 1;
                } else {
                    break;
                }
            }
        }
        // trailing alnum chars are part of malformed number
        while self.peek().is_ascii_alphanumeric() || self.peek() == b'_' {
            self.pos += 1;
        }
        let text = &self.src[start..self.pos];
        // LuaJIT LL/ULL/i suffixes: treat as number
        let mut t: &[u8] = text;
        for suf in [&b"ULL"[..], b"ull", b"LL", b"ll"] {
            if t.ends_with(suf) {
                t = &t[..t.len() - suf.len()];
                break;
            }
        }
        match parse_number_literal(t) {
            Some(v) => Ok(Tok::Num(v)),
            None => Err(self.err(
                "malformed number",
                Some(&String::from_utf8_lossy(text)),
            )),
        }
    }

    pub fn next_token(&mut self) -> Result<(Tok, u32), String> {
        loop {
            if self.at_end() {
                return Ok((Tok::Eof, self.line));
            }
            let c = self.peek();
            match c {
                b'\n' | b'\r' => {
                    self.newline();
                }
                b' ' | b'\t' | 11 | 12 => {
                    self.pos += 1;
                }
                b'-' => {
                    if self.peek_at(1) == b'-' {
                        self.pos += 2;
                        if self.peek() == b'[' {
                            if let Some(level) = self.long_bracket_level() {
                                self.read_long_string(level, true)?;
                                continue;
                            }
                        }
                        while !self.at_end() && self.peek() != b'\n' && self.peek() != b'\r' {
                            self.pos += 1;
                        }
                    } else {
                        self.pos += 1;
                        return Ok((Tok::Minus, self.line));
                    }
                }
                _ => break,
            }
        }
        let line = self.line;
        let c = self.peek();
        let tok = match c {
            b'a'..=b'z' | b'A'..=b'Z' | b'_' => {
                let start = self.pos;
                while self.peek().is_ascii_alphanumeric() || self.peek() == b'_' {
                    self.pos += 1;
                }
                let s = &self.src[start..self.pos];
                keyword(s).unwrap_or_else(|| Tok::Name(s.to_vec()))
            }
            b'0'..=b'9' => self.read_number()?,
            b'.' => {
                if self.peek_at(1) == b'.' {
                    if self.peek_at(2) == b'.' {
                        self.pos += 3;
                        Tok::Dots
                    } else {
                        self.pos += 2;
                        Tok::Concat
                    }
                } else if self.peek_at(1).is_ascii_digit() {
                    self.read_number()?
                } else {
                    self.pos += 1;
                    Tok::Dot
                }
            }
            b'"' | b'\'' => Tok::Str(self.read_string(c)?),
            b'[' => {
                if let Some(level) = self.long_bracket_level() {
                    Tok::Str(self.read_long_string(level, false)?)
                } else {
                    self.pos += 1;
                    Tok::LBracket
                }
            }
            b'=' => {
                if self.peek_at(1) == b'=' {
                    self.pos += 2;
                    Tok::EqEq
                } else {
                    self.pos += 1;
                    Tok::Assign
                }
            }
            b'~' => {
                if self.peek_at(1) == b'=' {
                    self.pos += 2;
                    Tok::NotEq
                } else {
                    self.pos += 1;
                    return Err(self.err("unexpected symbol", Some("~")));
                }
            }
            b'<' => {
                if self.peek_at(1) == b'=' {
                    self.pos += 2;
                    Tok::LtEq
                } else {
                    self.pos += 1;
                    Tok::Lt
                }
            }
            b'>' => {
                if self.peek_at(1) == b'=' {
                    self.pos += 2;
                    Tok::GtEq
                } else {
                    self.pos += 1;
                    Tok::Gt
                }
            }
            b':' => {
                if self.peek_at(1) == b':' {
                    self.pos += 2;
                    Tok::DoubleColon
                } else {
                    self.pos += 1;
                    Tok::Colon
                }
            }
            b'+' => {
                self.pos += 1;
                Tok::Plus
            }
            b'*' => {
                self.pos += 1;
                Tok::Star
            }
            b'/' => {
                self.pos += 1;
                Tok::Slash
            }
            b'%' => {
                self.pos += 1;
                Tok::Percent
            }
            b'^' => {
                self.pos += 1;
                Tok::Caret
            }
            b'#' => {
                self.pos += 1;
                Tok::Hash
            }
            b'(' => {
                self.pos += 1;
                Tok::LParen
            }
            b')' => {
                self.pos += 1;
                Tok::RParen
            }
            b'{' => {
                self.pos += 1;
                Tok::LBrace
            }
            b'}' => {
                self.pos += 1;
                Tok::RBrace
            }
            b']' => {
                self.pos += 1;
                Tok::RBracket
            }
            b';' => {
                self.pos += 1;
                Tok::Semi
            }
            b',' => {
                self.pos += 1;
                Tok::Comma
            }
            _ => {
                self.pos += 1;
                let s = if c.is_ascii_graphic() {
                    (c as char).to_string()
                } else {
                    format!("<\\{}>", c)
                };
                return Err(self.err("unexpected symbol", Some(&s)));
            }
        };
        Ok((tok, line))
    }
}

pub fn utf8_encode_raw(v: u32, buf: &mut Vec<u8>) {
    if v < 0x80 {
        buf.push(v as u8);
    } else if v < 0x800 {
        buf.push((0xC0 | (v >> 6)) as u8);
        buf.push((0x80 | (v & 0x3F)) as u8);
    } else if v < 0x10000 {
        buf.push((0xE0 | (v >> 12)) as u8);
        buf.push((0x80 | ((v >> 6) & 0x3F)) as u8);
        buf.push((0x80 | (v & 0x3F)) as u8);
    } else {
        buf.push((0xF0 | (v >> 18)) as u8);
        buf.push((0x80 | ((v >> 12) & 0x3F)) as u8);
        buf.push((0x80 | ((v >> 6) & 0x3F)) as u8);
        buf.push((0x80 | (v & 0x3F)) as u8);
    }
}
