pub struct Lexer<'a> {
    src: &'a [u8],
    pos: usize,
    pub line: u32,
    pub chunkname: String,
}

pub fn tok_text(t: &Tok) -> String {
    match t {
        Tok::Name(n) => String::from_utf8_lossy(n).into_owned(),
        Tok::Str(s) => String::from_utf8_lossy(s).into_owned(),
        Tok::Num(n) => crate::lua::value::fmt_num(*n),
