                            while let Some(Value::Nil) = self.arr.last() {
                                self.arr.pop();
                            }
                        }
                        return Ok(());
                    } else if i == len + 1 {
                        if v.is_nil() {
                            self.hash_set(k, v);
                            return Ok(());
                        }
                        self.arr.push(v);
                        // remove from hash if existed
                        if !self.hash.is_empty() {
                            if let Some(old) = self.hash.get_mut(&Key(k.clone())) {
                                if !old.is_nil() {
                                    *old = Value::Nil;
                                    self.tombstones += 1;
                                }
                            }
                            self.migrate();
                        }
                        return Ok(());
                    }
                }
                let k = if *n == 0.0 { Value::Num(0.0) } else { k };
                self.hash_set(k, v);
                Ok(())
            }
            _ => {
                self.hash_set(k, v);
                Ok(())
            }
        }
    }

    fn migrate(&mut self) {
        loop {
            let next = Value::Num((self.arr.len() + 1) as f64);
            let key = Key(next);
            match self.hash.get_mut(&key) {
                Some(v) if !v.is_nil() => {
                    let val = std::mem::replace(v, Value::Nil);
                    self.tombstones += 1;
                    self.arr.push(val);
                }
                _ => break,
            }
        }
    }

    fn hash_set(&mut self, k: Value, v: Value) {
        let key = Key(k);
        if let Some(slot) = self.hash.get_mut(&key) {
            let was_nil = slot.is_nil();
            let is_nil = v.is_nil();
            *slot = v;
            if !was_nil && is_nil {
                self.tombstones += 1;
            } else if was_nil && !is_nil {
                self.tombstones = self.tombstones.saturating_sub(1);
            }
            return;
        }
        if v.is_nil() {
            return;
        }
        if self.tombstones > 8 && self.tombstones * 2 > self.hash.len() {
            self.hash.retain(|_, v| !v.is_nil());
            self.tombstones = 0;
        }
        self.hash.insert(key, v);
    }

    pub fn set_str(&mut self, k: &str, v: Value) {
        let _ = self.set(Value::str(k), v);
    }

    pub fn push(&mut self, v: Value) {
        let n = self.len();
        let _ = self.set(Value::Num((n + 1) as f64), v);
    }

    pub fn len(&self) -> usize {
        let n = self.arr.len();
        if n > 0 {
            return n;
        }
        if self.hash.is_empty() {
            return 0;
        }
        // border search in hash part
        let mut i = 0usize;
        loop {
            let k = Key(Value::Num((i + 1) as f64));
            match self.hash.get(&k) {
                Some(v) if !v.is_nil() => i += 1,
                _ => return i,
            }
        }
    }

    /// next for iteration: returns next (key, value) after given key
    pub fn next(&self, k: &Value) -> Result<Option<(Value, Value)>, ()> {
        let mut start_hash = 0usize;
        match k {
            Value::Nil => {
                for (i, v) in self.arr.iter().enumerate() {
                    if !v.is_nil() {
                        return Ok(Some((Value::Num((i + 1) as f64), v.clone())));
                    }
                }
            }
            _ => {
                let mut in_arr = false;
                if let Value::Num(n) = k {
                    if let Some(i) = arr_index(*n) {
                        if i <= self.arr.len() {
                            in_arr = true;
                            for j in i..self.arr.len() {
                                if !self.arr[j].is_nil() {
                                    return Ok(Some((
                                        Value::Num((j + 1) as f64),
                                        self.arr[j].clone(),
                                    )));
                                }
                            }
                        }
                    }
                }
                if !in_arr {
                    match self.hash.get_index_of(&Key(k.clone())) {
                        Some(idx) => start_hash = idx + 1,
                        None => return Err(()),
                    }
                }
            }
        }
        for idx in start_hash..self.hash.len() {
            let (kk, vv) = self.hash.get_index(idx).unwrap();
            if !vv.is_nil() {
                return Ok(Some((kk.0.clone(), vv.clone())));
            }
        }
        Ok(None)
    }

    pub fn iter_pairs(&self) -> Vec<(Value, Value)> {
        let mut out = Vec::with_capacity(self.arr.len() + self.hash.len());
        for (i, v) in self.arr.iter().enumerate() {
            if !v.is_nil() {
                out.push((Value::Num((i + 1) as f64), v.clone()));
            }
        }
        for (k, v) in self.hash.iter() {
            if !v.is_nil() {
                out.push((k.0.clone(), v.clone()));
            }
        }
        out
    }

    pub fn hash_len_nonnil(&self) -> usize {
        self.hash.values().filter(|v| !v.is_nil()).count()
    }

    pub fn insert_at(&mut self, pos: usize, v: Value) {
        // assumes pure array semantics like table.insert
        let n = self.len();
        if self.arr.len() == n && pos >= 1 && pos <= n + 1 {
            self.arr.insert(pos - 1, v);
            if !self.hash.is_empty() {
                self.migrate();
            }
            return;
        }
        let mut i = n;
        while i >= pos {
            let val = self.get_int(i);
            let _ = self.set(Value::Num((i + 1) as f64), val);
            i -= 1;
            if i == 0 {
                break;
            }
        }
        let _ = self.set(Value::Num(pos as f64), v);
    }

    pub fn remove_at(&mut self, pos: usize) -> Value {
        let n = self.len();
        if self.arr.len() == n && pos >= 1 && pos <= n {
            let v = self.arr.remove(pos - 1);
            return v;
        }
        let v = self.get_int(pos);
        let mut i = pos;
        while i < n {
            let nv = self.get_int(i + 1);
            let _ = self.set(Value::Num(i as f64), nv);
            i += 1;
        }
        if pos <= n {
            let _ = self.set(Value::Num(n as f64), Value::Nil);
        }
        v
    }
}

impl fmt::Debug for Value {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        match self {
            Value::Nil => write!(f, "nil"),
            Value::Bool(b) => write!(f, "{}", b),
            Value::Num(n) => write!(f, "{}", fmt_num(*n)),
            Value::Str(s) => write!(f, "{:?}", s.to_str_lossy()),
            Value::Table(_) => write!(f, "table: 0x{:08x}", self.ptr()),
            Value::Func(_) => write!(f, "function: 0x{:08x}", self.ptr()),
            Value::UserData(_) => write!(f, "userdata: 0x{:08x}", self.ptr()),
        }
    }
}
