use std::cell::Cell;
use std::rc::Rc;

use super::ast::*;
use super::lexer::{tok_text, Lexer, Tok};
use super::value::LuaStr;

struct FuncState {
    blocks: Vec<Vec<(Rc<str>, VarRef)>>,
    upvals: Vec<(Rc<str>, UpvalDesc)>,
    all_vars: Vec<VarRef>,
    is_vararg: bool,
}

enum Res {
    Local(VarRef),
    Upval(u32),
}

pub struct Parser<'a> {
    lex: Lexer<'a>,
    tok: Tok,
    line: u32,
    ahead: Option<(Tok, u32)>,
    fs: Vec<FuncState>,
    chunk: Rc<str>,
}

type PResult<T> = Result<T, String>;

pub fn chunkid(name: &str) -> String {
    if let Some(r) = name.strip_prefix('=') {
        return r.chars().take(59).collect();
    }
    if let Some(r) = name.strip_prefix('@') {
        let n = r.chars().count();
        if n <= 59 {
            return r.to_string();
        }
        let skip = n - 56;
        return format!("...{}", r.chars().skip(skip).collect::<String>());
    }
    // [string "..."]
    let first_line: &str = name.split(['\n', '\r']).next().unwrap_or("");
    let max = 60 - 15;
    let truncated = first_line.len() < name.len();
    if !truncated && first_line.chars().count() <= max {
        format!("[string \"{}\"]", first_line)
    } else {
        let s: String = first_line.chars().take(max - 3).collect();
        format!("[string \"{}...\"]", s)
    }
}

impl<'a> Parser<'a> {
    pub fn new(src: &'a [u8], chunkname: &str) -> Self {
        let id = chunkid(chunkname);
        Parser {
            lex: Lexer::new(src, &id),
            tok: Tok::Eof,
            line: 1,
            ahead: None,
            fs: vec![],
            chunk: Rc::from(id.as_str()),
        }
    }

    fn advance(&mut self) -> PResult<()> {
        if let Some((t, l)) = self.ahead.take() {
            self.tok = t;
            self.line = l;
        } else {
            let (t, l) = self.lex.next_token()?;
            self.tok = t;
            self.line = l;
        }
        Ok(())
    }

    fn peek_ahead(&mut self) -> PResult<&Tok> {
        if self.ahead.is_none() {
            let (t, l) = self.lex.next_token()?;
            self.ahead = Some((t, l));
        }
        Ok(&self.ahead.as_ref().unwrap().0)
    }

    fn near(&self) -> String {
        match &self.tok {
            Tok::Str(s) => String::from_utf8_lossy(s).into_owned(),
            Tok::Eof => "<eof>".into(),
            t => tok_text(t),
        }
    }

    fn err<T>(&self, msg: &str) -> PResult<T> {
        Err(format!(
            "{}:{}: {} near '{}'",
            self.chunk,
            self.line,
            msg,
            self.near()
        ))
    }

    fn check(&self, t: &Tok) -> bool {
        &self.tok == t
    }

    fn expect(&mut self, t: Tok, what: &str) -> PResult<()> {
        if self.tok == t {
            self.advance()
        } else {
            self.err(&format!("'{}' expected", what))
        }
    }

    fn expect_match(&mut self, t: Tok, what: &str, who: &str, line: u32) -> PResult<()> {
        if self.tok == t {
            self.advance()
        } else if line == self.line {
            self.err(&format!("'{}' expected", what))
        } else {
            self.err(&format!(
                "'{}' expected (to close '{}' at line {})",
                what, who, line
            ))
        }
    }

    fn name(&mut self) -> PResult<Rc<str>> {
        if let Tok::Name(n) = &self.tok {
            let s: Rc<str> = Rc::from(String::from_utf8_lossy(n).as_ref());
            self.advance()?;
            Ok(s)
        } else {
            self.err("<name> expected")
        }
    }

    // ---------- scopes ----------
    fn open_func(&mut self, is_vararg: bool) {
        self.fs.push(FuncState {
            blocks: vec![vec![]],
            upvals: vec![],
            all_vars: vec![],
            is_vararg,
        });
    }

    fn declare(&mut self, name: Rc<str>) -> VarRef {
        let v = Rc::new(VarInfo {
            name: name.clone(),
            slot: Cell::new(Slot::Unassigned),
            captured: Cell::new(false),
        });
        let f = self.fs.last_mut().unwrap();
        f.all_vars.push(v.clone());
        v
    }

    fn activate(&mut self, v: &VarRef) {
        let f = self.fs.last_mut().unwrap();
        f.blocks.last_mut().unwrap().push((v.name.clone(), v.clone()));
    }

    fn open_block(&mut self) {
        self.fs.last_mut().unwrap().blocks.push(vec![]);
    }
    fn close_block(&mut self) {
        self.fs.last_mut().unwrap().blocks.pop();
    }

    fn resolve_in(&mut self, fi: usize, name: &str) -> Option<Res> {
        {
            let f = &self.fs[fi];
            for b in f.blocks.iter().rev() {
                for (n, v) in b.iter().rev() {
                    if &**n == name {
                        return Some(Res::Local(v.clone()));
                    }
                }
            }
            for (i, (n, _)) in f.upvals.iter().enumerate() {
                if &**n == name {
                    return Some(Res::Upval(i as u32));
                }
            }
        }
        if fi == 0 {
            return None;
        }
        let r = self.resolve_in(fi - 1, name)?;
        let desc = match r {
            Res::Local(v) => {
                v.captured.set(true);
                UpvalDesc::ParentLocal(v)
            }
            Res::Upval(j) => UpvalDesc::ParentUpval(j),
        };
        let f = &mut self.fs[fi];
        f.upvals.push((Rc::from(name), desc));
        Some(Res::Upval((f.upvals.len() - 1) as u32))
    }

    fn resolve_name(&mut self, name: &str) -> Expr {
        let fi = self.fs.len() - 1;
        match self.resolve_in(fi, name) {
            Some(Res::Local(v)) => Expr::Local(v),
            Some(Res::Upval(i)) => Expr::Upval(i, Rc::from(name)),
            None => Expr::Global(LuaStr::new(name.as_bytes())),
        }
    }

    fn close_func(&mut self, name: String, line: u32, params: Vec<VarRef>, body: Block) -> FuncProto {
        let f = self.fs.pop().unwrap();
        let mut nregs = 0u32;
        let mut ncells = 0u32;
        for v in &f.all_vars {
            if v.captured.get() {
                v.slot.set(Slot::Cell(ncells));
                ncells += 1;
            } else {
                v.slot.set(Slot::Reg(nregs));
                nregs += 1;
            }
        }
        let upval_names = f.upvals.iter().map(|(n, _)| n.clone()).collect();
        let upvals = f.upvals.into_iter().map(|(_, d)| d).collect();
        FuncProto {
            name,
            chunk: self.chunk.clone(),
            line,
            params,
            is_vararg: f.is_vararg,
            body,
            upvals,
            upval_names,
            nregs,
            ncells,
        }
    }

    // ---------- entry ----------
    pub fn parse_chunk(mut self) -> PResult<FuncProto> {
        self.advance()?;
        self.open_func(true);
        let body = self.block()?;
        if !self.check(&Tok::Eof) {
            return self.err("'<eof>' expected");
        }
        Ok(self.close_func("main chunk".into(), 0, vec![], body))
    }

    fn block_follow(&self) -> bool {
        matches!(
            self.tok,
            Tok::Else | Tok::Elseif | Tok::End | Tok::Until | Tok::Eof
        )
    }

    fn block(&mut self) -> PResult<Block> {
        let mut stmts = Vec::new();
        let mut has_labels = false;
        loop {
            if self.block_follow() {
                break;
            }
            if self.check(&Tok::Return) {
                let line = self.line;
                self.advance()?;
                let mut exprs = vec![];
                if !self.block_follow() && !self.check(&Tok::Semi) {
                    exprs = self.exprlist()?;
                }
                if self.check(&Tok::Semi) {
                    self.advance()?;
                }
                stmts.push(Stmt::Return(exprs, line));
                if !self.block_follow() {
                    return self.err("'<eof>' expected");
                }
                break;
            }
            if self.check(&Tok::Break) {
                self.advance()?;
                stmts.push(Stmt::Break);
                if self.check(&Tok::Semi) {
                    self.advance()?;
                }
                continue;
            }
            let s = self.statement()?;
            if let Some(s) = s {
                if matches!(s, Stmt::Label(_)) {
                    has_labels = true;
                }
                stmts.push(s);
            }
        }
        Ok(Block { stmts, has_labels })
    }

    fn statement(&mut self) -> PResult<Option<Stmt>> {
        let line = self.line;
        match self.tok.clone() {
            Tok::Semi => {
                self.advance()?;
                Ok(None)
            }
            Tok::If => self.if_stat(line).map(Some),
            Tok::While => {
                self.advance()?;
                let cond = self.expr()?;
                self.expect(Tok::Do, "do")?;
                self.open_block();
                let body = self.block()?;
                self.close_block();
                self.expect_match(Tok::End, "end", "while", line)?;
                Ok(Some(Stmt::While(cond, body)))
            }
            Tok::Do => {
                self.advance()?;
                self.open_block();
                let body = self.block()?;
                self.close_block();
                self.expect_match(Tok::End, "end", "do", line)?;
                Ok(Some(Stmt::Do(body)))
            }
            Tok::For => self.for_stat(line).map(Some),
            Tok::Repeat => {
                self.advance()?;
                self.open_block();
                let body = self.block()?;
                self.expect_match(Tok::Until, "until", "repeat", line)?;
                let cond = self.expr()?; // cond can see body locals
                self.close_block();
                Ok(Some(Stmt::Repeat(body, cond)))
            }
            Tok::Function => {
                self.advance()?;
                // funcname: Name {'.' Name} [':' Name]
                let n = self.name()?;
                let mut full = n.to_string();
                let mut target_expr = self.resolve_name(&n);
                let mut is_method = false;
                let mut keys: Vec<Rc<str>> = vec![];
                while self.check(&Tok::Dot) {
                    self.advance()?;
                    let k = self.name()?;
                    full.push('.');
                    full.push_str(&k);
                    keys.push(k);
                }
                if self.check(&Tok::Colon) {
                    self.advance()?;
                    let k = self.name()?;
                    full.push(':');
                    full.push_str(&k);
                    keys.push(k);
                    is_method = true;
                }
