            }
            Tok::Local => {
                self.advance()?;
                if self.check(&Tok::Function) {
                    self.advance()?;
                    let n = self.name()?;
                    let v = self.declare(n.clone());
                    self.activate(&v);
                    let f = self.func_body(false, line, n.to_string())?;
                    Ok(Some(Stmt::LocalFunction(v, Rc::new(f))))
                } else {
