                self.advance()?;
                let n = self.name()?;
                Ok(Some(Stmt::Goto(n, line)))
            }
            _ => self.expr_stat(line).map(Some),
        }
    }

    fn if_stat(&mut self, line: u32) -> PResult<Stmt> {
        let mut conds = vec![];
        let mut else_block = None;
        self.advance()?; // if
        let c = self.expr()?;
        self.expect(Tok::Then, "then")?;
        self.open_block();
        let b = self.block()?;
        self.close_block();
        conds.push((c, b));
        loop {
            if self.check(&Tok::Elseif) {
                self.advance()?;
                let c = self.expr()?;
                self.expect(Tok::Then, "then")?;
                self.open_block();
                let b = self.block()?;
                self.close_block();
                conds.push((c, b));
            } else if self.check(&Tok::Else) {
                self.advance()?;
                self.open_block();
                let b = self.block()?;
                self.close_block();
                else_block = Some(b);
                self.expect_match(Tok::End, "end", "if", line)?;
                break;
            } else {
                self.expect_match(Tok::End, "end", "if", line)?;
                break;
            }
        }
        Ok(Stmt::If(conds, else_block))
    }

    fn for_stat(&mut self, line: u32) -> PResult<Stmt> {
        self.advance()?; // for
        let n1 = self.name()?;
        if self.check(&Tok::Assign) {
            self.advance()?;
            let start = self.expr()?;
            self.expect(Tok::Comma, ",")?;
            let limit = self.expr()?;
            let step = if self.check(&Tok::Comma) {
                self.advance()?;
                Some(self.expr()?)
            } else {
                None
            };
            self.expect(Tok::Do, "do")?;
            self.open_block();
            let v = self.declare(n1);
            self.activate(&v);
            let body = self.block()?;
            self.close_block();
            self.expect_match(Tok::End, "end", "for", line)?;
            Ok(Stmt::NumFor {
                var: v,
                start,
                limit,
                step,
                body,
                line,
            })
        } else if self.check(&Tok::Comma) || self.check(&Tok::In) {
            let mut names = vec![n1];
            while self.check(&Tok::Comma) {
                self.advance()?;
                names.push(self.name()?);
            }
            self.expect(Tok::In, "in")?;
            let exprs = self.exprlist()?;
            self.expect(Tok::Do, "do")?;
            self.open_block();
            let vars: Vec<VarRef> = names.into_iter().map(|n| self.declare(n)).collect();
            for v in &vars {
                self.activate(v);
            }
            let body = self.block()?;
            self.close_block();
            self.expect_match(Tok::End, "end", "for", line)?;
            Ok(Stmt::GenFor {
                vars,
                exprs,
                body,
                line,
            })
        } else {
            self.err("'=' or 'in' expected")
        }
    }

    fn expr_stat(&mut self, line: u32) -> PResult<Stmt> {
        let e = self.suffixed_expr()?;
        if self.check(&Tok::Assign) || self.check(&Tok::Comma) {
            let mut targets = vec![];
            match expr_to_target(e) {
                Some(t) => targets.push(t),
                None => return self.err("syntax error"),
            }
            while self.check(&Tok::Comma) {
                self.advance()?;
                let e = self.suffixed_expr()?;
                match expr_to_target(e) {
                    Some(t) => targets.push(t),
                    None => return self.err("syntax error"),
                }
            }
            self.expect(Tok::Assign, "=")?;
            let exprs = self.exprlist()?;
            Ok(Stmt::Assign(targets, exprs, line))
        } else {
            match e {
                Expr::Call(_) => Ok(Stmt::Expr(e, line)),
                _ => self.err("syntax error"),
            }
        }
    }

    fn exprlist(&mut self) -> PResult<Vec<Expr>> {
        let mut v = vec![self.expr()?];
        while self.check(&Tok::Comma) {
            self.advance()?;
            v.push(self.expr()?);
        }
        Ok(v)
    }

    fn func_body(&mut self, is_method: bool, line: u32, name: String) -> PResult<FuncProto> {
        self.open_func(false);
        let mut params = vec![];
        if is_method {
            let v = self.declare(Rc::from("self"));
            self.activate(&v);
            params.push(v);
        }
        self.expect(Tok::LParen, "(")?;
        if !self.check(&Tok::RParen) {
            loop {
                match self.tok.clone() {
                    Tok::Name(_) => {
                        let n = self.name()?;
                        let v = self.declare(n);
                        self.activate(&v);
                        params.push(v);
                    }
                    Tok::Dots => {
                        self.advance()?;
                        self.fs.last_mut().unwrap().is_vararg = true;
                        break;
                    }
                    _ => return self.err("<name> expected"),
                }
                if self.check(&Tok::Comma) {
                    self.advance()?;
                } else {
                    break;
                }
            }
        }
        self.expect(Tok::RParen, ")")?;
        let body = self.block()?;
        self.expect_match(Tok::End, "end", "function", line)?;
        Ok(self.close_func(name, line, params, body))
    }

    fn primary_expr(&mut self) -> PResult<Expr> {
        match self.tok.clone() {
            Tok::Name(_) => {
                let n = self.name()?;
                Ok(self.resolve_name(&n))
            }
            Tok::LParen => {
                let line = self.line;
                self.advance()?;
                let e = self.expr()?;
                self.expect_match(Tok::RParen, ")", "(", line)?;
                Ok(match e {
                    Expr::Call(_) | Expr::Vararg => Expr::Paren(Box::new(e)),
                    other => other,
                })
            }
            _ => self.err("unexpected symbol"),
        }
    }

    fn suffixed_expr(&mut self) -> PResult<Expr> {
        let mut e = self.primary_expr()?;
        loop {
            let line = self.line;
            match self.tok.clone() {
                Tok::Dot => {
                    self.advance()?;
                    let n = self.name()?;
                    e = Expr::Index(
                        Box::new(e),
                        Box::new(Expr::Str(LuaStr::new(n.as_bytes()))),
                        line,
                    );
                }
                Tok::LBracket => {
                    self.advance()?;
                    let k = self.expr()?;
                    self.expect(Tok::RBracket, "]")?;
                    e = Expr::Index(Box::new(e), Box::new(k), line);
                }
                Tok::Colon => {
                    self.advance()?;
                    let n = self.name()?;
                    let args = self.call_args()?;
                    e = Expr::Call(Box::new(CallExpr {
                        func: e,
                        method: Some(LuaStr::new(n.as_bytes())),
                        args,
                        line,
                    }));
                }
                Tok::LParen | Tok::Str(_) | Tok::LBrace => {
                    let args = self.call_args()?;
                    e = Expr::Call(Box::new(CallExpr {
                        func: e,
                        method: None,
                        args,
                        line,
                    }));
                }
                _ => return Ok(e),
            }
        }
    }

    fn call_args(&mut self) -> PResult<Vec<Expr>> {
        match self.tok.clone() {
            Tok::Str(s) => {
                self.advance()?;
                Ok(vec![Expr::Str(LuaStr::new(&s))])
            }
            Tok::LBrace => Ok(vec![self.table_cons()?]),
            Tok::LParen => {
                let line = self.line;
                self.advance()?;
                if self.check(&Tok::RParen) {
                    self.advance()?;
                    return Ok(vec![]);
                }
                let args = self.exprlist()?;
                self.expect_match(Tok::RParen, ")", "(", line)?;
                Ok(args)
            }
            _ => self.err("function arguments expected"),
        }
    }

    fn table_cons(&mut self) -> PResult<Expr> {
        let line = self.line;
        self.expect(Tok::LBrace, "{")?;
        let mut fields = vec![];
        loop {
            if self.check(&Tok::RBrace) {
                break;
            }
            match self.tok.clone() {
                Tok::Name(n) => {
                    if self.peek_ahead()? == &Tok::Assign {
                        self.advance()?;
                        self.advance()?;
                        let v = self.expr()?;
                        fields.push(TField::Named(LuaStr::new(&n), v));
                    } else {
                        fields.push(TField::Pos(self.expr()?));
                    }
                }
                Tok::LBracket => {
                    self.advance()?;
                    let k = self.expr()?;
                    self.expect(Tok::RBracket, "]")?;
                    self.expect(Tok::Assign, "=")?;
                    let v = self.expr()?;
                    fields.push(TField::Keyed(k, v));
                }
                _ => fields.push(TField::Pos(self.expr()?)),
            }
            if self.check(&Tok::Comma) || self.check(&Tok::Semi) {
                self.advance()?;
            } else {
                break;
            }
        }
        self.expect_match(Tok::RBrace, "}", "{", line)?;
        Ok(Expr::Table(fields, line))
    }

    fn simple_expr(&mut self) -> PResult<Expr> {
        let e = match self.tok.clone() {
            Tok::Num(n) => Expr::Num(n),
            Tok::Str(s) => Expr::Str(LuaStr::new(&s)),
            Tok::Nil => Expr::Nil,
            Tok::True => Expr::True,
            Tok::False => Expr::False,
            Tok::Dots => {
                if !self.fs.last().unwrap().is_vararg {
                    return self.err("cannot use '...' outside a vararg function");
                }
                Expr::Vararg
            }
            Tok::LBrace => return self.table_cons(),
            Tok::Function => {
                let line = self.line;
                self.advance()?;
                let f = self.func_body(false, line, String::new())?;
                return Ok(Expr::Function(Rc::new(f)));
            }
            _ => return self.suffixed_expr(),
        };
        self.advance()?;
        Ok(e)
    }

    pub fn expr(&mut self) -> PResult<Expr> {
        self.subexpr(0)
    }

    fn subexpr(&mut self, limit: u8) -> PResult<Expr> {
        let mut left = match self.tok {
            Tok::Not | Tok::Minus | Tok::Hash => {
                let op = match self.tok {
                    Tok::Not => UnOp::Not,
                    Tok::Minus => UnOp::Neg,
                    _ => UnOp::Len,
                };
                let line = self.line;
                self.advance()?;
                let e = self.subexpr(8)?;
                // constant folding for negative numbers
                match (op, e) {
                    (UnOp::Neg, Expr::Num(n)) => Expr::Num(-n),
                    (op, e) => Expr::Un(op, Box::new(e), line),
                }
            }
            _ => self.simple_expr()?,
        };
        loop {
            let (op, lp, rp) = match self.tok {
                Tok::Plus => (Some(BinOp::Add), 6, 6),
                Tok::Minus => (Some(BinOp::Sub), 6, 6),
                Tok::Star => (Some(BinOp::Mul), 7, 7),
                Tok::Slash => (Some(BinOp::Div), 7, 7),
                Tok::Percent => (Some(BinOp::Mod), 7, 7),
                Tok::Caret => (Some(BinOp::Pow), 10, 9),
                Tok::Concat => (Some(BinOp::Concat), 5, 4),
                Tok::EqEq => (Some(BinOp::Eq), 3, 3),
                Tok::NotEq => (Some(BinOp::Ne), 3, 3),
                Tok::Lt => (Some(BinOp::Lt), 3, 3),
                Tok::LtEq => (Some(BinOp::Le), 3, 3),
                Tok::Gt => (Some(BinOp::Gt), 3, 3),
                Tok::GtEq => (Some(BinOp::Ge), 3, 3),
                Tok::And => (None, 2, 2),
                Tok::Or => (None, 1, 1),
                _ => return Ok(left),
            };
            if lp <= limit {
                return Ok(left);
            }
            let is_and = self.tok == Tok::And;
            let line = self.line;
            self.advance()?;
            let right = self.subexpr(rp)?;
            left = match op {
                Some(op) => Expr::Bin(op, Box::new(left), Box::new(right), line),
                None => {
                    if is_and {
                        Expr::And(Box::new(left), Box::new(right))
                    } else {
                        Expr::Or(Box::new(left), Box::new(right))
                    }
                }
            };
        }
    }
}

fn expr_to_target(e: Expr) -> Option<Target> {
    match e {
        Expr::Local(v) => Some(Target::Local(v)),
        Expr::Upval(i, _) => Some(Target::Upval(i)),
        Expr::Global(n) => Some(Target::Global(n)),
        Expr::Index(o, k, line) => Some(Target::Index(*o, *k, line)),
        _ => None,
    }
}
