cat > /workspace/src/lua/parser.rs <<'EOF'
use std::cell::Cell;
use std::rc::Rc;

use super::ast::*;
use super::lexer::{tok_text, Lexer, Tok};
use super::value::LuaStr;

struct FuncState {
    blocks: Vec<Vec<(Rc<str>, VarRef)>>,
    upvals: Vec<(Rc<str>, UpvalDesc)>,
    all_vars: Vec<VarRef>,
    is_vararg: bool,
}

enum Res {
    Local(VarRef),
    Upval(u32),
}

pub struct Parser<'a> {
    lex: Lexer<'a>,
    tok: Tok,
    line: u32,
    ahead: Option<(Tok, u32)>,
    fs: Vec<FuncState>,
    chunk: Rc<str>,
}

type PResult<T> = Result<T, String>;

pub fn chunkid(name: &str) -> String {
    if let Some(r) = name.strip_prefix('=') {
        return r.chars().take(59).collect();
    }
    if let Some(r) = name.strip_prefix('@') {
        let n = r.chars().count();
        if n <= 59 {
            return r.to_string();
        }
        let skip = n - 56;
        return format!("...{}", r.chars().skip(skip).collect::<String>());
    }
    // [string "..."]
    let first_line: &str = name.split(['\n', '\r']).next().unwrap_or("");
    let max = 60 - 15;
    let truncated = first_line.len() < name.len();
    if !truncated && first_line.chars().count() <= max {
        format!("[string \"{}\"]", first_line)
    } else {
        let s: String = first_line.chars().take(max - 3).collect();
        format!("[string \"{}...\"]", s)
    }
}

impl<'a> Parser<'a> {
    pub fn new(src: &'a [u8], chunkname: &str) -> Self {
        let id = chunkid(chunkname);
        Parser {
            lex: Lexer::new(src, &id),
            tok: Tok::Eof,
            line: 1,
            ahead: None,
            fs: vec![],
            chunk: Rc::from(id.as_str()),
        }
    }

    fn advance(&mut self) -> PResult<()> {
        if let Some((t, l)) = self.ahead.take() {
            self.tok = t;
            self.line = l;
        } else {
            let (t, l) = self.lex.next_token()?;
            self.tok = t;
            self.line = l;
        }
        Ok(())
    }

    fn peek_ahead(&mut self) -> PResult<&Tok> {
        if self.ahead.is_none() {
            let (t, l) = self.lex.next_token()?;
            self.ahead = Some((t, l));
        }
        Ok(&self.ahead.as_ref().unwrap().0)
    }

    fn near(&self) -> String {
        match &self.tok {
            Tok::Str(s) => String::from_utf8_lossy(s).into_owned(),
            Tok::Eof => "<eof>".into(),
            t => tok_text(t),
        }
    }

    fn err<T>(&self, msg: &str) -> PResult<T> {
        Err(format!(
            "{}:{}: {} near '{}'",
            self.chunk,
            self.line,
            msg,
            self.near()
        ))
    }

    fn check(&self, t: &Tok) -> bool {
        &self.tok == t
    }

    fn expect(&mut self, t: Tok, what: &str) -> PResult<()> {
        if self.tok == t {
            self.advance()
        } else {
            self.err(&format!("'{}' expected", what))
        }
    }

    fn expect_match(&mut self, t: Tok, what: &str, who: &str, line: u32) -> PResult<()> {
        if self.tok == t {
            self.advance()
        } else if line == self.line {
            self.err(&format!("'{}' expected", what))
        } else {
            self.err(&format!(
                "'{}' expected (to close '{}' at line {})",
                what, who, line
            ))
        }
    }

    fn name(&mut self) -> PResult<Rc<str>> {
        if let Tok::Name(n) = &self.tok {
            let s: Rc<str> = Rc::from(String::from_utf8_lossy(n).as_ref());
            self.advance()?;
            Ok(s)
        } else {
            self.err("<name> expected")
        }
    }

    // ---------- scopes ----------
    fn open_func(&mut self, is_vararg: bool) {
        self.fs.push(FuncState {
            blocks: vec![vec![]],
            upvals: vec![],
            all_vars: vec![],
            is_vararg,
        });
    }

    fn declare(&mut self, name: Rc<str>) -> VarRef {
        let v = Rc::new(VarInfo {
            name: name.clone(),
            slot: Cell::new(Slot::Unassigned),
            captured: Cell::new(false),
        });
        let f = self.fs.last_mut().unwrap();
        f.all_vars.push(v.clone());
        v
    }

    fn activate(&mut self, v: &VarRef) {
        let f = self.fs.last_mut().unwrap();
        f.blocks.last_mut().unwrap().push((v.name.clone(), v.clone()));
    }

    fn open_block(&mut self) {
        self.fs.last_mut().unwrap().blocks.push(vec![]);
    }
    fn close_block(&mut self) {
        self.fs.last_mut().unwrap().blocks.pop();
    }

    fn resolve_in(&mut self, fi: usize, name: &str) -> Option<Res> {
        {
            let f = &self.fs[fi];
            for b in f.blocks.iter().rev() {
                for (n, v) in b.iter().rev() {
                    if &**n == name {
                        return Some(Res::Local(v.clone()));
                    }
                }
            }
            for (i, (n, _)) in f.upvals.iter().enumerate() {
                if &**n == name {
                    return Some(Res::Upval(i as u32));
                }
            }
        }
        if fi == 0 {
            return None;
        }
        let r = self.resolve_in(fi - 1, name)?;
        let desc = match r {
            Res::Local(v) => {
                v.captured.set(true);
                UpvalDesc::ParentLocal(v)
            }
            Res::Upval(j) => UpvalDesc::ParentUpval(j),
        };
        let f = &mut self.fs[fi];
        f.upvals.push((Rc::from(name), desc));
        Some(Res::Upval((f.upvals.len() - 1) as u32))
    }

    fn resolve_name(&mut self, name: &str) -> Expr {
        let fi = self.fs.len() - 1;
        match self.resolve_in(fi, name) {
            Some(Res::Local(v)) => Expr::Local(v),
            Some(Res::Upval(i)) => Expr::Upval(i, Rc::from(name)),
            None => Expr::Global(LuaStr::new(name.as_bytes())),
        }
    }

    fn close_func(&mut self, name: String, line: u32, params: Vec<VarRef>, body: Block) -> FuncProto {
        let f = self.fs.pop().unwrap();
        let mut nregs = 0u32;
        let mut ncells = 0u32;
        for v in &f.all_vars {
            if v.captured.get() {
                v.slot.set(Slot::Cell(ncells));
                ncells += 1;
            } else {
                v.slot.set(Slot::Reg(nregs));
                nregs += 1;
            }
        }
        let upval_names = f.upvals.iter().map(|(n, _)| n.clone()).collect();
        let upvals = f.upvals.into_iter().map(|(_, d)| d).collect();
        FuncProto {
            name,
            chunk: self.chunk.clone(),
            line,
            params,
            is_vararg: f.is_vararg,
            body,
            upvals,
            upval_names,
            nregs,
            ncells,
        }
    }

    // ---------- entry ----------
    pub fn parse_chunk(mut self) -> PResult<FuncProto> {
        self.advance()?;
        self.open_func(true);
        let body = self.block()?;
        if !self.check(&Tok::Eof) {
            return self.err("'<eof>' expected");
        }
        Ok(self.close_func("main chunk".into(), 0, vec![], body))
    }

    fn block_follow(&self) -> bool {
        matches!(
            self.tok,
            Tok::Else | Tok::Elseif | Tok::End | Tok::Until | Tok::Eof
        )
    }

    fn block(&mut self) -> PResult<Block> {
        let mut stmts = Vec::new();
        let mut has_labels = false;
        loop {
            if self.block_follow() {
                break;
            }
            if self.check(&Tok::Return) {
                let line = self.line;
                self.advance()?;
                let mut exprs = vec![];
                if !self.block_follow() && !self.check(&Tok::Semi) {
                    exprs = self.exprlist()?;
                }
                if self.check(&Tok::Semi) {
                    self.advance()?;
                }
                stmts.push(Stmt::Return(exprs, line));
                if !self.block_follow() {
                    return self.err("'<eof>' expected");
                }
                break;
            }
            if self.check(&Tok::Break) {
                self.advance()?;
                stmts.push(Stmt::Break);
                if self.check(&Tok::Semi) {
                    self.advance()?;
                }
                continue;
            }
            let s = self.statement()?;
            if let Some(s) = s {
                if matches!(s, Stmt::Label(_)) {
                    has_labels = true;
                }
                stmts.push(s);
            }
        }
        Ok(Block { stmts, has_labels })
    }

    fn statement(&mut self) -> PResult<Option<Stmt>> {
        let line = self.line;
        match self.tok.clone() {
            Tok::Semi => {
                self.advance()?;
                Ok(None)
            }
            Tok::If => self.if_stat(line).map(Some),
            Tok::While => {
                self.advance()?;
                let cond = self.expr()?;
                self.expect(Tok::Do, "do")?;
                self.open_block();
                let body = self.block()?;
                self.close_block();
                self.expect_match(Tok::End, "end", "while", line)?;
                Ok(Some(Stmt::While(cond, body)))
            }
            Tok::Do => {
                self.advance()?;
                self.open_block();
                let body = self.block()?;
                self.close_block();
                self.expect_match(Tok::End, "end", "do", line)?;
                Ok(Some(Stmt::Do(body)))
            }
            Tok::For => self.for_stat(line).map(Some),
            Tok::Repeat => {
                self.advance()?;
                self.open_block();
                let body = self.block()?;
                self.expect_match(Tok::Until, "until", "repeat", line)?;
                let cond = self.expr()?; // cond can see body locals
                self.close_block();
                Ok(Some(Stmt::Repeat(body, cond)))
            }
            Tok::Function => {
                self.advance()?;
                // funcname: Name {'.' Name} [':' Name]
                let n = self.name()?;
                let mut full = n.to_string();
                let mut target_expr = self.resolve_name(&n);
                let mut is_method = false;
                let mut keys: Vec<Rc<str>> = vec![];
                while self.check(&Tok::Dot) {
                    self.advance()?;
                    let k = self.name()?;
                    full.push('.');
                    full.push_str(&k);
                    keys.push(k);
                }
                if self.check(&Tok::Colon) {
                    self.advance()?;
                    let k = self.name()?;
                    full.push(':');
                    full.push_str(&k);
                    keys.push(k);
                    is_method = true;
                }
                let f = self.func_body(is_method, line, full)?;
                let target = if keys.is_empty() {
                    expr_to_target(target_expr).unwrap()
                } else {
                    let last = keys.pop().unwrap();
                    for k in keys {
                        target_expr = Expr::Index(
                            Box::new(target_expr),
                            Box::new(Expr::Str(LuaStr::new(k.as_bytes()))),
                            line,
                        );
                    }
                    Target::Index(target_expr, Expr::Str(LuaStr::new(last.as_bytes())), line)
                };
                Ok(Some(Stmt::Assign(vec![target], vec![Expr::Function(Rc::new(f))], line)))
            }
            Tok::Local => {
                self.advance()?;
                if self.check(&Tok::Function) {
                    self.advance()?;
                    let n = self.name()?;
                    let v = self.declare(n.clone());
                    self.activate(&v);
                    let f = self.func_body(false, line, n.to_string())?;
                    Ok(Some(Stmt::LocalFunction(v, Rc::new(f))))
                } else {
                    let mut names = vec![self.name()?];
                    while self.check(&Tok::Comma) {
                        self.advance()?;
                        names.push(self.name()?);
                    }
                    // LuaJIT attribs not supported (5.4 <const>) - ignore
                    let exprs = if self.check(&Tok::Assign) {
                        self.advance()?;
                        self.exprlist()?
                    } else {
                        vec![]
                    };
                    let vars: Vec<VarRef> = names.into_iter().map(|n| self.declare(n)).collect();
                    for v in &vars {
                        self.activate(v);
                    }
                    Ok(Some(Stmt::Local(vars, exprs, line)))
                }
            }
            Tok::DoubleColon => {
                self.advance()?;
                let n = self.name()?;
                self.expect(Tok::DoubleColon, "::")?;
                Ok(Some(Stmt::Label(n)))
            }
            Tok::Goto => {
                // 'goto' is a keyword in LuaJIT 2.1 only when followed by a name
                self.advance()?;
                let n = self.name()?;
                Ok(Some(Stmt::Goto(n, line)))
            }
            _ => self.expr_stat(line).map(Some),
        }
    }

    fn if_stat(&mut self, line: u32) -> PResult<Stmt> {
        let mut conds = vec![];
        let mut else_block = None;
        self.advance()?; // if
        let c = self.expr()?;
        self.expect(Tok::Then, "then")?;
        self.open_block();
        let b = self.block()?;
        self.close_block();
        conds.push((c, b));
        loop {
            if self.check(&Tok::Elseif) {
                self.advance()?;
                let c = self.expr()?;
                self.expect(Tok::Then, "then")?;
                self.open_block();
                let b = self.block()?;
                self.close_block();
                conds.push((c, b));
            } else if self.check(&Tok::Else) {
                self.advance()?;
                self.open_block();
                let b = self.block()?;
                self.close_block();
                else_block = Some(b);
                self.expect_match(Tok::End, "end", "if", line)?;
                break;
            } else {
                self.expect_match(Tok::End, "end", "if", line)?;
                break;
            }
        }
        Ok(Stmt::If(conds, else_block))
    }

    fn for_stat(&mut self, line: u32) -> PResult<Stmt> {
        self.advance()?; // for
        let n1 = self.name()?;
        if self.check(&Tok::Assign) {
            self.advance()?;
            let start = self.expr()?;
            self.expect(Tok::Comma, ",")?;
            let limit = self.expr()?;
            let step = if self.check(&Tok::Comma) {
                self.advance()?;
                Some(self.expr()?)
            } else {
                None
            };
            self.expect(Tok::Do, "do")?;
            self.open_block();
            let v = self.declare(n1);
            self.activate(&v);
            let body = self.block()?;
            self.close_block();
            self.expect_match(Tok::End, "end", "for", line)?;
            Ok(Stmt::NumFor {
                var: v,
                start,
                limit,
                step,
                body,
                line,
            })
        } else if self.check(&Tok::Comma) || self.check(&Tok::In) {
            let mut names = vec![n1];
            while self.check(&Tok::Comma) {
                self.advance()?;
                names.push(self.name()?);
            }
            self.expect(Tok::In, "in")?;
            let exprs = self.exprlist()?;
            self.expect(Tok::Do, "do")?;
            self.open_block();
            let vars: Vec<VarRef> = names.into_iter().map(|n| self.declare(n)).collect();
            for v in &vars {
                self.activate(v);
            }
            let body = self.block()?;
            self.close_block();
            self.expect_match(Tok::End, "end", "for", line)?;
            Ok(Stmt::GenFor {
                vars,
                exprs,
                body,
                line,
            })
        } else {
            self.err("'=' or 'in' expected")
        }
    }

    fn expr_stat(&mut self, line: u32) -> PResult<Stmt> {
        let e = self.suffixed_expr()?;
        if self.check(&Tok::Assign) || self.check(&Tok::Comma) {
            let mut targets = vec![];
            match expr_to_target(e) {
                Some(t) => targets.push(t),
                None => return self.err("syntax error"),
            }
            while self.check(&Tok::Comma) {
                self.advance()?;
                let e = self.suffixed_expr()?;
                match expr_to_target(e) {
                    Some(t) => targets.push(t),
                    None => return self.err("syntax error"),
                }
            }
            self.expect(Tok::Assign, "=")?;
            let exprs = self.exprlist()?;
            Ok(Stmt::Assign(targets, exprs, line))
        } else {
            match e {
                Expr::Call(_) => Ok(Stmt::Expr(e, line)),
                _ => self.err("syntax error"),
            }
        }
    }

    fn exprlist(&mut self) -> PResult<Vec<Expr>> {
        let mut v = vec![self.expr()?];
        while self.check(&Tok::Comma) {
            self.advance()?;
            v.push(self.expr()?);
        }
        Ok(v)
    }

    fn func_body(&mut self, is_method: bool, line: u32, name: String) -> PResult<FuncProto> {
        self.open_func(false);
        let mut params = vec![];
        if is_method {
            let v = self.declare(Rc::from("self"));
            self.activate(&v);
            params.push(v);
        }
        self.expect(Tok::LParen, "(")?;
        if !self.check(&Tok::RParen) {
            loop {
                match self.tok.clone() {
                    Tok::Name(_) => {
                        let n = self.name()?;
                        let v = self.declare(n);
                        self.activate(&v);
                        params.push(v);
                    }
                    Tok::Dots => {
                        self.advance()?;
                        self.fs.last_mut().unwrap().is_vararg = true;
                        break;
                    }
                    _ => return self.err("<name> expected"),
                }
                if self.check(&Tok::Comma) {
                    self.advance()?;
                } else {
                    break;
                }
            }
        }
        self.expect(Tok::RParen, ")")?;
        let body = self.block()?;
        self.expect_match(Tok::End, "end", "function", line)?;
        Ok(self.close_func(name, line, params, body))
    }

    fn primary_expr(&mut self) -> PResult<Expr> {
        match self.tok.clone() {
            Tok::Name(_) => {
                let n = self.name()?;
                Ok(self.resolve_name(&n))
            }
            Tok::LParen => {
                let line = self.line;
                self.advance()?;
                let e = self.expr()?;
                self.expect_match(Tok::RParen, ")", "(", line)?;
                Ok(match e {
                    Expr::Call(_) | Expr::Vararg => Expr::Paren(Box::new(e)),
                    other => other,
                })
            }
            _ => self.err("unexpected symbol"),
        }
    }

    fn suffixed_expr(&mut self) -> PResult<Expr> {
        let mut e = self.primary_expr()?;
        loop {
            let line = self.line;
            match self.tok.clone() {
                Tok::Dot => {
                    self.advance()?;
                    let n = self.name()?;
                    e = Expr::Index(
                        Box::new(e),
                        Box::new(Expr::Str(LuaStr::new(n.as_bytes()))),
                        line,
                    );
                }
                Tok::LBracket => {
                    self.advance()?;
                    let k = self.expr()?;
                    self.expect(Tok::RBracket, "]")?;
                    e = Expr::Index(Box::new(e), Box::new(k), line);
                }
                Tok::Colon => {
                    self.advance()?;
                    let n = self.name()?;
                    let args = self.call_args()?;
                    e = Expr::Call(Box::new(CallExpr {
                        func: e,
                        method: Some(LuaStr::new(n.as_bytes())),
                        args,
                        line,
                    }));
                }
                Tok::LParen | Tok::Str(_) | Tok::LBrace => {
                    let args = self.call_args()?;
                    e = Expr::Call(Box::new(CallExpr {
                        func: e,
                        method: None,
                        args,
                        line,
                    }));
                }
                _ => return Ok(e),
            }
        }
    }

    fn call_args(&mut self) -> PResult<Vec<Expr>> {
        match self.tok.clone() {
            Tok::Str(s) => {
                self.advance()?;
                Ok(vec![Expr::Str(LuaStr::new(&s))])
            }
            Tok::LBrace => Ok(vec![self.table_cons()?]),
            Tok::LParen => {
                let line = self.line;
                self.advance()?;
                if self.check(&Tok::RParen) {
                    self.advance()?;
                    return Ok(vec![]);
                }
                let args = self.exprlist()?;
                self.expect_match(Tok::RParen, ")", "(", line)?;
                Ok(args)
            }
            _ => self.err("function arguments expected"),
        }
    }

    fn table_cons(&mut self) -> PResult<Expr> {
        let line = self.line;
        self.expect(Tok::LBrace, "{")?;
        let mut fields = vec![];
        loop {
            if self.check(&Tok::RBrace) {
                break;
            }
            match self.tok.clone() {
                Tok::Name(n) => {
                    if self.peek_ahead()? == &Tok::Assign {
                        self.advance()?;
                        self.advance()?;
                        let v = self.expr()?;
                        fields.push(TField::Named(LuaStr::new(&n), v));
                    } else {
                        fields.push(TField::Pos(self.expr()?));
                    }
                }
                Tok::LBracket => {
                    self.advance()?;
                    let k = self.expr()?;
                    self.expect(Tok::RBracket, "]")?;
                    self.expect(Tok::Assign, "=")?;
                    let v = self.expr()?;
                    fields.push(TField::Keyed(k, v));
                }
                _ => fields.push(TField::Pos(self.expr()?)),
            }
            if self.check(&Tok::Comma) || self.check(&Tok::Semi) {
                self.advance()?;
            } else {
                break;
            }
        }
        self.expect_match(Tok::RBrace, "}", "{", line)?;
        Ok(Expr::Table(fields, line))
    }

    fn simple_expr(&mut self) -> PResult<Expr> {
        let e = match self.tok.clone() {
            Tok::Num(n) => Expr::Num(n),
            Tok::Str(s) => Expr::Str(LuaStr::new(&s)),
            Tok::Nil => Expr::Nil,
            Tok::True => Expr::True,
            Tok::False => Expr::False,
            Tok::Dots => {
                if !self.fs.last().unwrap().is_vararg {
                    return self.err("cannot use '...' outside a vararg function");
                }
                Expr::Vararg
            }
            Tok::LBrace => return self.table_cons(),
            Tok::Function => {
                let line = self.line;
                self.advance()?;
                let f = self.func_body(false, line, String::new())?;
                return Ok(Expr::Function(Rc::new(f)));
            }
            _ => return self.suffixed_expr(),
        };
        self.advance()?;
        Ok(e)
    }

    pub fn expr(&mut self) -> PResult<Expr> {
        self.subexpr(0)
    }

    fn subexpr(&mut self, limit: u8) -> PResult<Expr> {
        let mut left = match self.tok {
            Tok::Not | Tok::Minus | Tok::Hash => {
                let op = match self.tok {
                    Tok::Not => UnOp::Not,
                    Tok::Minus => UnOp::Neg,
                    _ => UnOp::Len,
                };
                let line = self.line;
                self.advance()?;
                let e = self.subexpr(8)?;
                // constant folding for negative numbers
                match (op, e) {
                    (UnOp::Neg, Expr::Num(n)) => Expr::Num(-n),
                    (op, e) => Expr::Un(op, Box::new(e), line),
                }
            }
            _ => self.simple_expr()?,
        };
        loop {
            let (op, lp, rp) = match self.tok {
                Tok::Plus => (Some(BinOp::Add), 6, 6),
                Tok::Minus => (Some(BinOp::Sub), 6, 6),
                Tok::Star => (Some(BinOp::Mul), 7, 7),
                Tok::Slash => (Some(BinOp::Div), 7, 7),
                Tok::Percent => (Some(BinOp::Mod), 7, 7),
                Tok::Caret => (Some(BinOp::Pow), 10, 9),
                Tok::Concat => (Some(BinOp::Concat), 5, 4),
                Tok::EqEq => (Some(BinOp::Eq), 3, 3),
                Tok::NotEq => (Some(BinOp::Ne), 3, 3),
                Tok::Lt => (Some(BinOp::Lt), 3, 3),
                Tok::LtEq => (Some(BinOp::Le), 3, 3),
                Tok::Gt => (Some(BinOp::Gt), 3, 3),
                Tok::GtEq => (Some(BinOp::Ge), 3, 3),
                Tok::And => (None, 2, 2),
                Tok::Or => (None, 1, 1),
                _ => return Ok(left),
            };
            if lp <= limit {
                return Ok(left);
            }
            let is_and = self.tok == Tok::And;
            let line = self.line;
            self.advance()?;
            let right = self.subexpr(rp)?;
            left = match op {
                Some(op) => Expr::Bin(op, Box::new(left), Box::new(right), line),
                None => {
                    if is_and {
                        Expr::And(Box::new(left), Box::new(right))
                    } else {
                        Expr::Or(Box::new(left), Box::new(right))
                    }
                }
            };
        }
    }
}

fn expr_to_target(e: Expr) -> Option<Target> {
    match e {
        Expr::Local(v) => Some(Target::Local(v)),
        Expr::Upval(i, _) => Some(Target::Upval(i)),
        Expr::Global(n) => Some(Target::Global(n)),
        Expr::Index(o, k, line) => Some(Target::Index(*o, *k, line)),
        _ => None,
    }
}
