use std::any::Any;
use std::cell::RefCell;
use std::rc::Rc;

pub use super::ast::FuncProto;
use super::ast::*;
use super::value::*;

pub struct CallInfo {
    pub chunk: Rc<str>,
    pub line: u32,
    pub name: String,
    pub is_lua: bool,
}

pub struct Lua {
    pub globals: TableRef,
    pub string_meta: Option<TableRef>,
    pub stack: Vec<CallInfo>,
    pub depth: usize,
    pub app: Option<Box<dyn Any>>,
    pub loaded: TableRef,
}

enum Flow {
    Normal,
    Break,
    Return(Vec<Value>),
    Goto(Rc<str>, u32),
}

struct Frame<'a> {
    regs: Vec<Value>,
    cells: Vec<Rc<RefCell<Value>>>,
    varargs: Vec<Value>,
    upvals: &'a [Rc<RefCell<Value>>],
    proto: &'a FuncProto,
}

const MAX_DEPTH: usize = 7000;

fn desc_expr(e: &Expr) -> Option<String> {
    match e {
        Expr::Local(v) => Some(format!("local '{}'", v.name)),
        Expr::Upval(_, n) => Some(format!("upvalue '{}'", n)),
        Expr::Global(n) => Some(format!("global '{}'", n.to_str_lossy())),
        Expr::Index(_, k, _) => match &**k {
            Expr::Str(s) => Some(format!("field '{}'", s.to_str_lossy())),
            _ => None,
        },
        _ => None,
    }
}

fn type_err(op: &str, desc: Option<String>, v: &Value) -> String {
    match desc {
        Some(d) => format!("attempt to {} {} (a {} value)", op, d, v.type_name()),
        None => format!("attempt to {} a {} value", op, v.type_name()),
    }
}

impl Lua {
    pub fn new_bare() -> Lua {
        let globals = Rc::new(RefCell::new(Table::new()));
        let loaded = Rc::new(RefCell::new(Table::new()));
        Lua {
            globals,
            string_meta: None,
            stack: vec![],
            depth: 0,
            app: None,
            loaded,
        }
    }

    // ---------------- helpers ----------------
    pub fn pos_prefix(&self, level: usize) -> String {
        // level 1 = innermost lua function
        let mut lvl = 0;
        for ci in self.stack.iter().rev() {
            lvl += 1;
            if lvl == level {
                if ci.is_lua {
                    return format!("{}:{}: ", ci.chunk, ci.line);
                } else {
                    return String::new();
                }
            }
        }
        String::new()
    }

    pub fn current_lua_pos(&self) -> String {
        for ci in self.stack.iter().rev() {
            if ci.is_lua {
                return format!("{}:{}: ", ci.chunk, ci.line);
            }
        }
        String::new()
    }

    pub fn traceback(&self) -> String {
        let mut s = String::from("stack traceback:");
        for ci in self.stack.iter().rev() {
            if ci.is_lua {
                if ci.name == "main chunk" {
                    s.push_str(&format!("\n\t{}:{}: in main chunk", ci.chunk, ci.line));
                } else if ci.name.is_empty() {
                    s.push_str(&format!("\n\t{}:{}: in function <{}>", ci.chunk, ci.line, ci.chunk));
                } else {
                    s.push_str(&format!("\n\t{}:{}: in function '{}'", ci.chunk, ci.line, ci.name));
                }
            } else {
                s.push_str(&format!("\n\t[C]: in function '{}'", ci.name));
            }
        }
        s
    }

    fn rt_err(&self, frame: &Frame, line: u32, msg: String) -> LuaError {
        LuaError::val(Value::str(&format!("{}:{}: {}", frame.proto.chunk, line, msg)))
    }

    pub fn get_metatable(&self, v: &Value) -> Option<TableRef> {
        match v {
            Value::Table(t) => t.borrow().meta.clone(),
            Value::Str(_) => self.string_meta.clone(),
            Value::UserData(u) => u.meta.borrow().clone(),
            _ => None,
        }
    }

    pub fn get_metamethod(&self, v: &Value, name: &str) -> Value {
        match self.get_metatable(v) {
            Some(mt) => mt.borrow().get_str(name),
            None => Value::Nil,
        }
    }

    // ---------------- calls ----------------
    pub fn call(&mut self, f: &Value, args: Vec<Value>) -> LResult<Vec<Value>> {
        match f {
            Value::Func(Function::Lua(cl)) => {
                let cl = cl.clone();
                self.call_closure(&cl, args)
            }
            Value::Func(Function::Native(nf)) => {
                let nf = nf.clone();
                self.call_native(&nf, args)
            }
            _ => {
                let h = self.get_metamethod(f, "__call");
                if h.is_nil() {
                    return Err(LuaError::rt(type_err("call", None, f)));
                }
                let mut a = Vec::with_capacity(args.len() + 1);
                a.push(f.clone());
                a.extend(args);
                self.call(&h, a)
            }
        }
    }

    pub fn call1(&mut self, f: &Value, args: Vec<Value>) -> LResult<Value> {
        Ok(self.call(f, args)?.into_iter().next().unwrap_or(Value::Nil))
    }

    fn call_native(&mut self, nf: &Rc<NativeFn>, args: Vec<Value>) -> LResult<Vec<Value>> {
        if self.depth >= MAX_DEPTH {
            return Err(LuaError::rt("stack overflow"));
        }
        self.depth += 1;
        self.stack.push(CallInfo {
            chunk: Rc::from("[C]"),
            line: 0,
            name: nf.name.clone(),
            is_lua: false,
        });
        let r = (nf.f)(self, args);
        self.stack.pop();
        self.depth -= 1;
        match r {
            Err(e) if e.needs_pos() => {
                let msg = e.to_string_lossy();
                Err(LuaError::val(Value::str(&format!(
                    "{}{}",
                    self.current_lua_pos(),
                    msg
                ))))
            }
            r => r,
        }
    }

    fn call_closure(&mut self, cl: &Rc<LuaClosure>, mut args: Vec<Value>) -> LResult<Vec<Value>> {
        if self.depth >= MAX_DEPTH {
            return Err(LuaError::rt("stack overflow"));
        }
        let proto: &FuncProto = &cl.proto;
        let nparams = proto.params.len();
        let varargs = if proto.is_vararg && args.len() > nparams {
            args.split_off(nparams)
        } else {
            vec![]
        };
        let dummy = if proto.ncells > 0 {
            Some(Rc::new(RefCell::new(Value::Nil)))
        } else {
            None
        };
        let mut frame = Frame {
            regs: vec![Value::Nil; proto.nregs as usize],
            cells: match &dummy {
                Some(d) => vec![d.clone(); proto.ncells as usize],
                None => vec![],
            },
            varargs,
            upvals: &cl.upvals,
            proto,
        };
        let mut it = args.into_iter();
        for p in proto.params.iter() {
            let v = it.next().unwrap_or(Value::Nil);
            declare(&mut frame, p, v);
        }
        self.depth += 1;
        self.stack.push(CallInfo {
            chunk: proto.chunk.clone(),
            line: proto.line,
            name: proto.name.clone(),
            is_lua: true,
        });
        let r = self.exec_block(&proto.body, &mut frame);
        self.stack.pop();
        self.depth -= 1;
        match r {
            Ok(Flow::Return(v)) => Ok(v),
            Ok(Flow::Goto(l, line)) => Err(LuaError::val(Value::str(&format!(
                "{}:{}: no visible label '{}' for goto",
                proto.chunk, line, l
            )))),
            Ok(_) => Ok(vec![]),
            Err(e) => Err(e),
        }
    }

    // ---------------- indexing ----------------
    pub fn index(&mut self, obj: &Value, key: &Value) -> LResult<Value> {
        let mut obj = obj.clone();
        for _ in 0..100 {
            let h = match &obj {
                Value::Table(t) => {
                    let tb = t.borrow();
                    let v = tb.get(key);
                    if !v.is_nil() {
                        return Ok(v);
                    }
                    match &tb.meta {
                        None => return Ok(Value::Nil),
                        Some(mt) => {
                            let h = mt.borrow().get_str("__index");
                            if h.is_nil() {
                                return Ok(Value::Nil);
                            }
                            h
                        }
                    }
                }
                _ => {
                    let h = self.get_metamethod(&obj, "__index");
                    if h.is_nil() {
                        return Err(LuaError::rt(type_err("index", None, &obj)));
                    }
                    h
                }
            };
            if let Value::Func(_) = h {
                return self.call1(&h, vec![obj.clone(), key.clone()]);
            }
            obj = h;
        }
        Err(LuaError::rt("loop in gettable"))
    }

    pub fn setindex(&mut self, obj: &Value, key: Value, val: Value) -> LResult<()> {
        let mut obj = obj.clone();
        for _ in 0..100 {
            let h = match &obj {
                Value::Table(t) => {
                    let mt = {
                        let tb = t.borrow();
                        match &tb.meta {
                            None => None,
                            Some(mt) => {
                                let existing = tb.get(&key);
                                if !existing.is_nil() {
                                    None
                                } else {
                                    let h = mt.borrow().get_str("__newindex");
                                    if h.is_nil() {
                                        None
                                    } else {
                                        Some(h)
                                    }
                                }
                            }
                        }
                    };
                    match mt {
                        None => {
                            return t
                                .borrow_mut()
                                .set(key, val)
                                .map_err(|e| LuaError::rt(e));
                        }
                        Some(h) => h,
                    }
                }
                _ => {
                    let h = self.get_metamethod(&obj, "__newindex");
                    if h.is_nil() {
                        return Err(LuaError::rt(type_err("index", None, &obj)));
                    }
                    h
                }
            };
            if let Value::Func(_) = h {
                self.call(&h, vec![obj.clone(), key, val])?;
                return Ok(());
            }
            obj = h;
        }
        Err(LuaError::rt("loop in settable"))
    }

    // ---------------- conversions ----------------
    pub fn tostring(&mut self, v: &Value) -> LResult<Value> {
        let h = self.get_metamethod(v, "__tostring");
        if !h.is_nil() {
            return self.call1(&h, vec![v.clone()]);
        }
        Ok(Value::str(&tostring_basic(v)))
    }

    // ---------------- arithmetic ----------------
    fn arith(&mut self, op: BinOp, a: &Value, b: &Value) -> Result<Value, Option<LuaError>> {
        if let (Value::Num(x), Value::Num(y)) = (a, b) {
            return Ok(Value::Num(num_op(op, *x, *y)));
        }
        if let (Some(x), Some(y)) = (a.to_num(), b.to_num()) {
            return Ok(Value::Num(num_op(op, x, y)));
        }
        let name = match op {
            BinOp::Add => "__add",
            BinOp::Sub => "__sub",
            BinOp::Mul => "__mul",
            BinOp::Div => "__div",
            BinOp::Mod => "__mod",
            BinOp::Pow => "__pow",
            _ => "__add",
        };
        let mut h = self.get_metamethod(a, name);
        if h.is_nil() {
            h = self.get_metamethod(b, name);
        }
        if h.is_nil() {
            return Err(None);
        }
        self.call1(&h, vec![a.clone(), b.clone()]).map_err(Some)
    }

    pub fn arith_values(&mut self, op: BinOp, a: &Value, b: &Value) -> LResult<Value> {
        match self.arith(op, a, b) {
            Ok(v) => Ok(v),
            Err(Some(e)) => Err(e),
            Err(None) => {
                let bad = if a.to_num().is_none() { a } else { b };
                Err(LuaError::rt(type_err("perform arithmetic on", None, bad)))
            }
        }
    }

    pub fn values_eq(&mut self, a: &Value, b: &Value) -> LResult<bool> {
        if a.raw_eq(b) {
            return Ok(true);
        }
        match (a, b) {
            (Value::Table(_), Value::Table(_)) | (Value::UserData(_), Value::UserData(_)) => {
                let h1 = self.get_metamethod(a, "__eq");
                if h1.is_nil() {
                    return Ok(false);
                }
                let h2 = self.get_metamethod(b, "__eq");
                if !h1.raw_eq(&h2) {
                    return Ok(false);
                }
                Ok(self.call1(&h1, vec![a.clone(), b.clone()])?.truthy())
            }
            _ => Ok(false),
        }
    }

    pub fn less_than(&mut self, a: &Value, b: &Value) -> LResult<bool> {
        match (a, b) {
            (Value::Num(x), Value::Num(y)) => Ok(x < y),
            (Value::Str(x), Value::Str(y)) => Ok(x.as_bytes() < y.as_bytes()),
            _ => {
                let h = self.cmp_meta(a, b, "__lt")?;
                Ok(h)
            }
        }
    }

    pub fn less_equal(&mut self, a: &Value, b: &Value) -> LResult<bool> {
        match (a, b) {
            (Value::Num(x), Value::Num(y)) => Ok(x <= y),
            (Value::Str(x), Value::Str(y)) => Ok(x.as_bytes() <= y.as_bytes()),
            _ => {
                let h1 = self.get_metamethod(a, "__le");
                if !h1.is_nil() && a.type_name() == b.type_name() {
                    return Ok(self.call1(&h1, vec![a.clone(), b.clone()])?.truthy());
                }
                let h = self.get_metamethod(a, "__lt");
                if !h.is_nil() && a.type_name() == b.type_name() {
                    return Ok(!self.call1(&h, vec![b.clone(), a.clone()])?.truthy());
                }
                Err(cmp_err(a, b))
            }
        }
    }

    fn cmp_meta(&mut self, a: &Value, b: &Value, name: &str) -> LResult<bool> {
        if a.type_name() == b.type_name() {
            let h = self.get_metamethod(a, name);
            if !h.is_nil() {
                return Ok(self.call1(&h, vec![a.clone(), b.clone()])?.truthy());
            }
        }
        Err(cmp_err(a, b))
    }

    pub fn concat_values(&mut self, a: &Value, b: &Value) -> Result<Value, Option<LuaError>> {
        match (a, b) {
            (Value::Str(_) | Value::Num(_), Value::Str(_) | Value::Num(_)) => {
                let mut buf: Vec<u8> = Vec::new();
                append_strnum(&mut buf, a);
                append_strnum(&mut buf, b);
                Ok(Value::bytes(&buf))
            }
            _ => {
                let mut h = self.get_metamethod(a, "__concat");
                if h.is_nil() {
                    h = self.get_metamethod(b, "__concat");
                }
                if h.is_nil() {
                    return Err(None);
                }
                self.call1(&h, vec![a.clone(), b.clone()]).map_err(Some)
            }
        }
    }

    pub fn len_of(&mut self, v: &Value) -> Result<Value, Option<LuaError>> {
        match v {
            Value::Str(s) => Ok(Value::Num(s.as_bytes().len() as f64)),
            Value::Table(t) => Ok(Value::Num(t.borrow().len() as f64)),
            _ => {
                let h = self.get_metamethod(v, "__len");
                if h.is_nil() {
                    return Err(None);
                }
                self.call1(&h, vec![v.clone()]).map_err(Some)
            }
        }
    }

    // ---------------- execution ----------------
    fn exec_block(&mut self, b: &Block, f: &mut Frame) -> LResult<Flow> {
        let stmts = &b.stmts;
        let mut i = 0;
        while i < stmts.len() {
            let flow = self.exec_stmt(&stmts[i], f)?;
            match flow {
                Flow::Normal => {}
                Flow::Goto(ref label, _) if b.has_labels => {
                    let mut found = None;
                    for (j, s) in stmts.iter().enumerate() {
                        if let Stmt::Label(l) = s {
                            if l == label {
                                found = Some(j);
                                break;
                            }
                        }
                    }
                    match found {
                        Some(j) => {
                            i = j + 1;
                            continue;
                        }
                        None => return Ok(flow),
                    }
                }
                other => return Ok(other),
            }
            i += 1;
        }
        Ok(Flow::Normal)
    }

    fn set_line(&mut self, line: u32) {
        if let Some(ci) = self.stack.last_mut() {
            ci.line = line;
        }
    }

    fn exec_stmt(&mut self, s: &Stmt, f: &mut Frame) -> LResult<Flow> {
        match s {
            Stmt::Expr(e, _) => {
                if let Expr::Call(c) = e {
                    self.eval_call(c, f)?;
                } else {
                    self.eval(e, f)?;
                }
                Ok(Flow::Normal)
            }
            Stmt::Local(vars, exprs, _) => {
                if vars.len() == 1 && exprs.len() == 1 {
                    let v = self.eval(&exprs[0], f)?;
                    declare(f, &vars[0], v);
                } else {
                    let vals = self.eval_list(exprs, f, vars.len())?;
                    for (var, v) in vars.iter().zip(vals.into_iter()) {
                        declare(f, var, v);
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::LocalFunction(var, proto) => {
                declare(f, var, Value::Nil);
                let cl = self.make_closure(proto, f);
                assign_local(f, var, cl);
                Ok(Flow::Normal)
            }
            Stmt::Assign(targets, exprs, line) => {
                if targets.len() == 1 && exprs.len() == 1 {
                    match &targets[0] {
                        Target::Local(v) => {
                            let val = self.eval(&exprs[0], f)?;
                            assign_local(f, v, val);
                        }
                        Target::Upval(i) => {
                            let val = self.eval(&exprs[0], f)?;
                            *f.upvals[*i as usize].borrow_mut() = val;
                        }
                        Target::Global(n) => {
                            let val = self.eval(&exprs[0], f)?;
                            self.set_global_val(Value::Str(n.clone()), val, f, *line)?;
                        }
                        Target::Index(o, k, l) => {
                            let ov = self.eval(o, f)?;
                            let kv = self.eval(k, f)?;
                            let val = self.eval(&exprs[0], f)?;
                            self.assign_index(&ov, kv, val, o, f, *l)?;
                        }
                    }
                    return Ok(Flow::Normal);
                }
                // evaluate target prefixes
                let mut pre: Vec<Option<(Value, Value)>> = Vec::with_capacity(targets.len());
                for t in targets {
                    if let Target::Index(o, k, _) = t {
                        let ov = self.eval(o, f)?;
                        let kv = self.eval(k, f)?;
                        pre.push(Some((ov, kv)));
                    } else {
                        pre.push(None);
                    }
                }
                let vals = self.eval_list(exprs, f, targets.len())?;
                for (i, (t, val)) in targets.iter().zip(vals.into_iter()).enumerate().rev() {
                    match t {
                        Target::Local(v) => assign_local(f, v, val),
                        Target::Upval(i) => *f.upvals[*i as usize].borrow_mut() = val,
                        Target::Global(n) => {
                            self.set_global_val(Value::Str(n.clone()), val, f, *line)?
                        }
                        Target::Index(o, _, l) => {
                            let (ov, kv) = pre[i].take().unwrap();
                            self.assign_index(&ov, kv, val, o, f, *l)?;
                        }
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::If(conds, els) => {
                for (c, b) in conds {
                    if self.eval(c, f)?.truthy() {
                        return self.exec_block(b, f);
                    }
                }
                if let Some(b) = els {
                    return self.exec_block(b, f);
                }
                Ok(Flow::Normal)
            }
            Stmt::While(c, b) => {
                while self.eval(c, f)?.truthy() {
                    match self.exec_block(b, f)? {
                        Flow::Normal => {}
                        Flow::Break => break,
                        other => return Ok(other),
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::Repeat(b, c) => {
                loop {
                    match self.exec_block(b, f)? {
                        Flow::Normal => {}
                        Flow::Break => break,
                        other => return Ok(other),
                    }
                    if self.eval(c, f)?.truthy() {
                        break;
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::NumFor {
                var,
                start,
                limit,
                step,
                body,
                line,
            } => {
                let s = self.eval(start, f)?;
                let l = self.eval(limit, f)?;
                let st = match step {
                    Some(e) => self.eval(e, f)?,
                    None => Value::Num(1.0),
                };
                let s = match s.to_num() {
                    Some(n) => n,
                    None => {
                        return Err(self.rt_err(f, *line, "'for' initial value must be a number".into()))
                    }
                };
                let l = match l.to_num() {
                    Some(n) => n,
                    None => return Err(self.rt_err(f, *line, "'for' limit must be a number".into())),
                };
                let st = match st.to_num() {
                    Some(n) => n,
                    None => return Err(self.rt_err(f, *line, "'for' step must be a number".into())),
                };
                let mut i = s;
                loop {
                    if (st > 0.0 && i > l) || (st <= 0.0 && i < l) {
                        break;
                    }
                    declare(f, var, Value::Num(i));
                    match self.exec_block(body, f)? {
                        Flow::Normal => {}
                        Flow::Break => break,
                        other => return Ok(other),
                    }
                    i += st;
                }
                Ok(Flow::Normal)
            }
            Stmt::GenFor {
                vars,
                exprs,
                body,
                line,
            } => {
                let init = self.eval_list(exprs, f, 3)?;
                let mut it = init.into_iter();
                let func = it.next().unwrap();
                let state = it.next().unwrap();
                let mut ctl = it.next().unwrap();
                // fast path for next
                loop {
                    self.set_line(*line);
                    let rs = self.call(&func, vec![state.clone(), ctl.clone()])?;
                    let first = rs.first().cloned().unwrap_or(Value::Nil);
                    if first.is_nil() {
                        break;
                    }
                    ctl = first;
                    let mut ri = rs.into_iter();
                    for v in vars.iter() {
                        declare(f, v, ri.next().unwrap_or(Value::Nil));
                    }
                    match self.exec_block(body, f)? {
                        Flow::Normal => {}
                        Flow::Break => break,
                        other => return Ok(other),
                    }
                }
                Ok(Flow::Normal)
            }
            Stmt::Do(b) => self.exec_block(b, f),
            Stmt::Return(exprs, line) => {
                if exprs.len() == 1 {
                    if let Expr::Call(c) = &exprs[0] {
                        // tail call (not optimized, but keep line)
                        let _ = line;
                        let r = self.eval_call(c, f)?;
                        return Ok(Flow::Return(r));
                    }
                }
                let vals = self.eval_multi_list(exprs, f)?;
                Ok(Flow::Return(vals))
            }
            Stmt::Break => Ok(Flow::Break),
            Stmt::Goto(l, line) => Ok(Flow::Goto(l.clone(), *line)),
            Stmt::Label(_) => Ok(Flow::Normal),
        }
    }

    fn set_global_val(&mut self, k: Value, v: Value, f: &Frame, line: u32) -> LResult<()> {
        let g = Value::Table(self.globals.clone());
        let has_meta = self.globals.borrow().meta.is_some();
        if !has_meta {
            return self
                .globals
                .borrow_mut()
                .set(k, v)
                .map_err(|e| self.rt_err(f, line, e.to_string()));
        }
        self.set_line(line);
        self.setindex(&g, k, v).map_err(|e| self.fix_err(e, f, line))
    }

    fn assign_index(
        &mut self,
        ov: &Value,
        kv: Value,
        val: Value,
        oexpr: &Expr,
        f: &Frame,
        line: u32,
    ) -> LResult<()> {
        if let Value::Table(t) = ov {
            let fast = {
                let tb = t.borrow();
                tb.meta.is_none()
            };
            if fast {
                return t
                    .borrow_mut()
                    .set(kv, val)
                    .map_err(|e| self.rt_err(f, line, e.to_string()));
            }
        } else if !matches!(ov, Value::UserData(_)) {
            let h = self.get_metamethod(ov, "__newindex");
            if h.is_nil() {
                return Err(self.rt_err(f, line, type_err("index", desc_expr(oexpr), ov)));
            }
        }
        self.set_line(line);
        self.setindex(ov, kv, val).map_err(|e| self.fix_err(e, f, line))
    }

    fn fix_err(&self, e: LuaError, f: &Frame, line: u32) -> LuaError {
        if e.needs_pos() {
            self.rt_err(f, line, e.to_string_lossy())
        } else {
            e
        }
    }

    fn make_closure(&mut self, proto: &Rc<FuncProto>, f: &Frame) -> Value {
        let mut upvals = Vec::with_capacity(proto.upvals.len());
        for u in &proto.upvals {
            match u {
                UpvalDesc::ParentLocal(v) => match v.slot.get() {
                    Slot::Cell(i) => upvals.push(f.cells[i as usize].clone()),
                    _ => upvals.push(Rc::new(RefCell::new(Value::Nil))),
                },
                UpvalDesc::ParentUpval(i) => upvals.push(f.upvals[*i as usize].clone()),
            }
        }
        Value::Func(Function::Lua(Rc::new(LuaClosure {
            proto: proto.clone(),
            upvals,
        })))
    }

    fn eval_list(&mut self, exprs: &[Expr], f: &mut Frame, want: usize) -> LResult<Vec<Value>> {
        let mut out = Vec::with_capacity(want.max(exprs.len()));
        let n = exprs.len();
        for (i, e) in exprs.iter().enumerate() {
            if i == n - 1 {
                self.eval_multi_into(e, f, &mut out)?;
            } else {
                out.push(self.eval(e, f)?);
            }
        }
        out.resize(want, Value::Nil);
        Ok(out)
    }

    fn eval_multi_list(&mut self, exprs: &[Expr], f: &mut Frame) -> LResult<Vec<Value>> {
        let mut out = Vec::with_capacity(exprs.len());
        let n = exprs.len();
        for (i, e) in exprs.iter().enumerate() {
            if i == n - 1 {
                self.eval_multi_into(e, f, &mut out)?;
            } else {
                out.push(self.eval(e, f)?);
            }
        }
        Ok(out)
    }

    fn eval_multi_into(&mut self, e: &Expr, f: &mut Frame, out: &mut Vec<Value>) -> LResult<()> {
        match e {
            Expr::Call(c) => {
                let r = self.eval_call(c, f)?;
                out.extend(r);
            }
            Expr::Vararg => out.extend(f.varargs.iter().cloned()),
            _ => out.push(self.eval(e, f)?),
        }
        Ok(())
    }

    fn eval_call(&mut self, c: &CallExpr, f: &mut Frame) -> LResult<Vec<Value>> {
        let (func, mut args) = if let Some(m) = &c.method {
            let obj = self.eval(&c.func, f)?;
            let key = Value::Str(m.clone());
            let func = match &obj {
                Value::Table(t) if t.borrow().meta.is_none() => t.borrow().get(&key),
                _ => {
                    self.set_line(c.line);
                    match self.index(&obj, &key) {
                        Ok(v) => v,
                        Err(e) => {
                            if e.needs_pos() {
                                return Err(self.rt_err(
                                    f,
                                    c.line,
                                    type_err("index", desc_expr(&c.func), &obj),
                                ));
                            }
                            return Err(e);
                        }
                    }
                }
            };
            let mut args = Vec::with_capacity(c.args.len() + 1);
            args.push(obj);
            if let Value::Nil = func {
                return Err(self.rt_err(
                    f,
                    c.line,
                    format!("attempt to call method '{}' (a nil value)", m.to_str_lossy()),
                ));
            }
            (func, args)
        } else {
            let func = self.eval(&c.func, f)?;
            (func, Vec::with_capacity(c.args.len()))
        };
        let n = c.args.len();
        for (i, a) in c.args.iter().enumerate() {
            if i == n - 1 {
                self.eval_multi_into(a, f, &mut args)?;
            } else {
                args.push(self.eval(a, f)?);
            }
        }
        self.set_line(c.line);
        match &func {
            Value::Func(_) => {}
            _ => {
                let h = self.get_metamethod(&func, "__call");
                if h.is_nil() {
                    let d = if c.method.is_some() {
                        None
                    } else {
                        desc_expr(&c.func)
                    };
                    return Err(self.rt_err(f, c.line, type_err("call", d, &func)));
                }
            }
        }
        self.call(&func, args).map_err(|e| self.fix_err(e, f, c.line))
    }

    fn eval(&mut self, e: &Expr, f: &mut Frame) -> LResult<Value> {
        match e {
            Expr::Nil => Ok(Value::Nil),
            Expr::True => Ok(Value::Bool(true)),
            Expr::False => Ok(Value::Bool(false)),
            Expr::Num(n) => Ok(Value::Num(*n)),
            Expr::Str(s) => Ok(Value::Str(s.clone())),
            Expr::Vararg => Ok(f.varargs.first().cloned().unwrap_or(Value::Nil)),
            Expr::Local(v) => Ok(match v.slot.get() {
                Slot::Reg(i) => f.regs[i as usize].clone(),
                Slot::Cell(i) => f.cells[i as usize].borrow().clone(),
                Slot::Unassigned => Value::Nil,
            }),
            Expr::Upval(i, _) => Ok(f.upvals[*i as usize].borrow().clone()),
            Expr::Global(n) => {
                let g = self.globals.borrow();
                let key = Value::Str(n.clone());
                let v = g.get(&key);
                if !v.is_nil() || g.meta.is_none() {
                    return Ok(v);
                }
                drop(g);
                let gv = Value::Table(self.globals.clone());
                self.index(&gv, &key)
            }
            Expr::Index(o, k, line) => {
                let ov = self.eval(o, f)?;
                let kv = self.eval(k, f)?;
                if let Value::Table(t) = &ov {
                    let tb = t.borrow();
                    let v = tb.get(&kv);
                    if !v.is_nil() || tb.meta.is_none() {
                        return Ok(v);
                    }
                }
                match &ov {
                    Value::Table(_) | Value::Str(_) | Value::UserData(_) => {}
                    _ => {
                        return Err(self.rt_err(f, *line, type_err("index", desc_expr(o), &ov)));
                    }
                }
                self.set_line(*line);
                match self.index(&ov, &kv) {
                    Ok(v) => Ok(v),
                    Err(e) => {
                        if e.needs_pos() {
                            Err(self.rt_err(f, *line, type_err("index", desc_expr(o), &ov)))
                        } else {
                            Err(e)
                        }
                    }
                }
            }
            Expr::Call(c) => Ok(self.eval_call(c, f)?.into_iter().next().unwrap_or(Value::Nil)),
            Expr::Function(p) => Ok(self.make_closure(p, f)),
            Expr::And(a, b) => {
                let av = self.eval(a, f)?;
                if !av.truthy() {
                    Ok(av)
                } else {
                    self.eval(b, f)
                }
            }
            Expr::Or(a, b) => {
                let av = self.eval(a, f)?;
                if av.truthy() {
                    Ok(av)
                } else {
                    self.eval(b, f)
                }
            }
            Expr::Paren(e) => self.eval(e, f),
            Expr::Un(op, e, line) => {
                let v = self.eval(e, f)?;
                match op {
                    UnOp::Not => Ok(Value::Bool(!v.truthy())),
                    UnOp::Neg => {
                        if let Value::Num(n) = v {
                            return Ok(Value::Num(-n));
                        }
                        if let Some(n) = v.to_num() {
                            return Ok(Value::Num(-n));
                        }
                        let h = self.get_metamethod(&v, "__unm");
                        if h.is_nil() {
                            return Err(self.rt_err(
                                f,
                                *line,
                                type_err("perform arithmetic on", desc_expr(e), &v),
                            ));
                        }
                        self.set_line(*line);
                        self.call1(&h, vec![v.clone(), v])
                    }
                    UnOp::Len => {
                        self.set_line(*line);
                        match self.len_of(&v) {
                            Ok(r) => Ok(r),
                            Err(Some(err)) => Err(err),
                            Err(None) => Err(self.rt_err(
                                f,
                                *line,
                                type_err("get length of", desc_expr(e), &v),
                            )),
                        }
                    }
                }
            }
            Expr::Bin(op, a, b, line) => {
                let av = self.eval(a, f)?;
                let bv = self.eval(b, f)?;
                match op {
                    BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Mod | BinOp::Pow => {
                        if let (Value::Num(x), Value::Num(y)) = (&av, &bv) {
                            return Ok(Value::Num(num_op(*op, *x, *y)));
                        }
                        self.set_line(*line);
                        match self.arith(*op, &av, &bv) {
                            Ok(v) => Ok(v),
                            Err(Some(e)) => Err(e),
                            Err(None) => {
                                let (bad, d) = if av.to_num().is_none() {
                                    (&av, desc_expr(a))
                                } else {
                                    (&bv, desc_expr(b))
                                };
                                Err(self.rt_err(f, *line, type_err("perform arithmetic on", d, bad)))
                            }
                        }
                    }
                    BinOp::Concat => {
                        self.set_line(*line);
                        match self.concat_values(&av, &bv) {
                            Ok(v) => Ok(v),
                            Err(Some(e)) => Err(e),
                            Err(None) => {
                                let (bad, d) = if matches!(av, Value::Str(_) | Value::Num(_)) {
                                    (&bv, desc_expr(b))
                                } else {
                                    (&av, desc_expr(a))
                                };
                                Err(self.rt_err(f, *line, type_err("concatenate", d, bad)))
                            }
                        }
                    }
                    BinOp::Eq => Ok(Value::Bool(self.values_eq(&av, &bv)?)),
                    BinOp::Ne => Ok(Value::Bool(!self.values_eq(&av, &bv)?)),
                    BinOp::Lt => {
                        self.set_line(*line);
                        let r = self.less_than(&av, &bv).map_err(|e| self.fix_err(e, f, *line))?;
                        Ok(Value::Bool(r))
                    }
                    BinOp::Le => {
                        self.set_line(*line);
                        let r = self.less_equal(&av, &bv).map_err(|e| self.fix_err(e, f, *line))?;
                        Ok(Value::Bool(r))
                    }
                    BinOp::Gt => {
                        self.set_line(*line);
                        let r = self.less_than(&bv, &av).map_err(|e| self.fix_err(e, f, *line))?;
                        Ok(Value::Bool(r))
                    }
                    BinOp::Ge => {
                        self.set_line(*line);
                        let r = self.less_equal(&bv, &av).map_err(|e| self.fix_err(e, f, *line))?;
                        Ok(Value::Bool(r))
                    }
                }
            }
            Expr::Table(fields, line) => {
                let mut npos = 0;
                for fl in fields.iter() {
                    if let TField::Pos(_) = fl {
                        npos += 1;
                    }
                }
                let mut t = Table::with_capacity(npos, fields.len() - npos);
                let mut idx = 1usize;
                let nf = fields.len();
                for (fi, fl) in fields.iter().enumerate() {
                    match fl {
                        TField::Pos(e) => {
                            if fi == nf - 1 && matches!(e, Expr::Call(_) | Expr::Vararg) {
                                let mut vals = vec![];
                                self.eval_multi_into(e, f, &mut vals)?;
                                for v in vals {
                                    let _ = t.set(Value::Num(idx as f64), v);
                                    idx += 1;
                                }
                            } else {
                                let v = self.eval(e, f)?;
                                let _ = t.set(Value::Num(idx as f64), v);
                                idx += 1;
                            }
                        }
                        TField::Named(k, e) => {
                            let v = self.eval(e, f)?;
                            let _ = t.set(Value::Str(k.clone()), v);
                        }
                        TField::Keyed(k, e) => {
                            let kv = self.eval(k, f)?;
                            let v = self.eval(e, f)?;
                            t.set(kv, v).map_err(|m| self.rt_err(f, *line, m.to_string()))?;
                        }
                    }
                }
                Ok(Value::table(t))
            }
        }
    }

    // ---------------- loading ----------------
    pub fn load(&mut self, src: &[u8], chunkname: &str) -> Result<Value, String> {
        let p = super::parser::Parser::new(src, chunkname);
        let proto = p.parse_chunk()?;
        Ok(Value::Func(Function::Lua(Rc::new(LuaClosure {
            proto: Rc::new(proto),
            upvals: vec![],
        }))))
    }

    pub fn exec(&mut self, src: &[u8], chunkname: &str) -> LResult<Vec<Value>> {
        let f = self
            .load(src, chunkname)
            .map_err(|e| LuaError::val(Value::str(&e)))?;
        self.call(&f, vec![])
    }

    pub fn get_global(&self, name: &str) -> Value {
        self.globals.borrow().get_str(name)
    }
    pub fn set_global(&self, name: &str, v: Value) {
        self.globals.borrow_mut().set_str(name, v);
    }

    pub fn native<F>(name: &str, f: F) -> Value
    where
        F: Fn(&mut Lua, Vec<Value>) -> LResult<Vec<Value>> + 'static,
    {
        Value::Func(Function::Native(Rc::new(NativeFn {
            name: name.to_string(),
            f: Box::new(f),
        })))
    }
}

fn cmp_err(a: &Value, b: &Value) -> LuaError {
    if a.type_name() == b.type_name() {
        LuaError::rt(format!("attempt to compare two {} values", a.type_name()))
    } else {
        LuaError::rt(format!(
            "attempt to compare {} with {}",
            a.type_name(),
            b.type_name()
        ))
    }
}

pub fn append_strnum(buf: &mut Vec<u8>, v: &Value) {
    match v {
        Value::Str(s) => buf.extend_from_slice(s.as_bytes()),
        Value::Num(n) => buf.extend_from_slice(fmt_num(*n).as_bytes()),
        _ => {}
    }
}

pub fn tostring_basic(v: &Value) -> String {
    match v {
        Value::Nil => "nil".into(),
        Value::Bool(b) => if *b { "true".into() } else { "false".into() },
        Value::Num(n) => fmt_num(*n),
        Value::Str(s) => s.to_str_lossy(),
        Value::Table(_) => format!("table: 0x{:012x}", v.ptr()),
        Value::Func(Function::Native(_)) => format!("function: builtin#{}", v.ptr() % 256),
        Value::Func(_) => format!("function: 0x{:012x}", v.ptr()),
        Value::UserData(_) => format!("userdata: 0x{:012x}", v.ptr()),
    }
}

pub fn num_op(op: BinOp, x: f64, y: f64) -> f64 {
    match op {
        BinOp::Add => x + y,
        BinOp::Sub => x - y,
        BinOp::Mul => x * y,
        BinOp::Div => x / y,
        BinOp::Mod => {
            if y.is_infinite() && x.is_finite() {
                if (x >= 0.0) == (y > 0.0) {
                    x
                } else {
                    y
                }
            } else {
                x - (x / y).floor() * y
            }
        }
        BinOp::Pow => x.powf(y),
        _ => 0.0,
    }
}

#[inline]
fn declare(f: &mut Frame, v: &VarRef, val: Value) {
    match v.slot.get() {
        Slot::Reg(i) => f.regs[i as usize] = val,
        Slot::Cell(i) => f.cells[i as usize] = Rc::new(RefCell::new(val)),
        Slot::Unassigned => {}
    }
}

#[inline]
fn assign_local(f: &mut Frame, v: &VarRef, val: Value) {
    match v.slot.get() {
        Slot::Reg(i) => f.regs[i as usize] = val,
        Slot::Cell(i) => *f.cells[i as usize].borrow_mut() = val,
        Slot::Unassigned => {}
    }
}
