        let mut i = s + 1;
        while i < self.src.len() {
            let c = self.src[i];
            if c == e {
                cont -= 1;
                if cont == 0 {
                    return Ok(Some(i + 1));
                }
            } else if c == b {
                cont += 1;
            }
            i += 1;
        }
        Ok(None)
    }

    fn match_capture(&self, s: usize, l: u8) -> Result<Option<usize>, String> {
        let l = (l - b'1') as isize;
        if l < 0 || l as usize >= self.level || self.capture[l as usize].1 == CAP_UNFINISHED {
            return Err(format!("invalid capture index %{}", l + 1));
        }
        let (st, len) = self.capture[l as usize];
        let len = len as usize;
        if self.src.len() - s >= len && self.src[st..st + len] == self.src[s..s + len] {
