use std::cell::RefCell;
use std::rc::Rc;

use super::interp::{tostring_basic, Lua};
use super::lpattern::{self, Cap, MatchState};
use super::value::*;

pub fn arg_err(n: usize, fname: &str, msg: &str) -> LuaError {
    LuaError::rt(format!("bad argument #{} to '{}' ({})", n, fname, msg))
}

pub fn type_name_or_no_value(args: &[Value], i: usize) -> &'static str {
    match args.get(i) {
        None => "no value",
        Some(v) => v.type_name(),
    }
}

pub fn check_str(args: &[Value], i: usize, fname: &str) -> LResult<Vec<u8>> {
    match args.get(i) {
        Some(Value::Str(s)) => Ok(s.as_bytes().to_vec()),
        Some(Value::Num(n)) => Ok(fmt_num(*n).into_bytes()),
        _ => Err(arg_err(
            i + 1,
            fname,
            &format!("string expected, got {}", type_name_or_no_value(args, i)),
        )),
    }
}

pub fn check_lstr(args: &[Value], i: usize, fname: &str) -> LResult<LuaStr> {
    match args.get(i) {
        Some(Value::Str(s)) => Ok(s.clone()),
        Some(Value::Num(n)) => Ok(LuaStr::new(fmt_num(*n).as_bytes())),
        _ => Err(arg_err(
            i + 1,
            fname,
            &format!("string expected, got {}", type_name_or_no_value(args, i)),
        )),
    }
}

pub fn check_num(args: &[Value], i: usize, fname: &str) -> LResult<f64> {
    match args.get(i) {
        Some(Value::Num(n)) => Ok(*n),
        Some(v @ Value::Str(_)) => v.to_num().ok_or_else(|| {
            arg_err(i + 1, fname, &format!("number expected, got {}", "string"))
        }),
        _ => Err(arg_err(
            i + 1,
            fname,
            &format!("number expected, got {}", type_name_or_no_value(args, i)),
        )),
    }
}

pub fn opt_num(args: &[Value], i: usize, fname: &str, def: f64) -> LResult<f64> {
    match args.get(i) {
        None | Some(Value::Nil) => Ok(def),
        _ => check_num(args, i, fname),
    }
}

pub fn check_int(args: &[Value], i: usize, fname: &str) -> LResult<i64> {
    let n = check_num(args, i, fname)?;
    Ok(n as i64)
}

pub fn opt_int(args: &[Value], i: usize, fname: &str, def: i64) -> LResult<i64> {
    match args.get(i) {
        None | Some(Value::Nil) => Ok(def),
        _ => check_int(args, i, fname),
    }
}

pub fn check_table(args: &[Value], i: usize, fname: &str) -> LResult<TableRef> {
    match args.get(i) {
        Some(Value::Table(t)) => Ok(t.clone()),
        _ => Err(arg_err(
            i + 1,
            fname,
            &format!("table expected, got {}", type_name_or_no_value(args, i)),
        )),
    }
}

pub fn check_any(args: &[Value], i: usize, fname: &str) -> LResult<Value> {
    match args.get(i) {
        Some(v) => Ok(v.clone()),
        None => Err(arg_err(i + 1, fname, "value expected")),
    }
}

fn arg(args: &[Value], i: usize) -> Value {
    args.get(i).cloned().unwrap_or(Value::Nil)
}

pub fn reg(t: &TableRef, name: &str, f: impl Fn(&mut Lua, Vec<Value>) -> LResult<Vec<Value>> + 'static) {
    t.borrow_mut().set_str(name, Lua::native(name, f));
}

fn new_table() -> TableRef {
    Rc::new(RefCell::new(Table::new()))
}

// ---------------- number formatting ----------------

/// C-like %g formatting
pub fn format_g(v: f64, prec: usize, upper: bool, alt: bool) -> String {
    if v.is_nan() {
        return if upper { "NAN".into() } else { "nan".into() };
    }
    if v.is_infinite() {
        let s = if v > 0.0 { "inf" } else { "-inf" };
        return if upper { s.to_uppercase() } else { s.into() };
    }
    let p = if prec == 0 { 1 } else { prec };
    if v == 0.0 {
        let mut s = if v.is_sign_negative() { "-0".to_string() } else { "0".to_string() };
        if alt && p > 1 {
            s.push('.');
            for _ in 0..p - 1 {
                s.push('0');
            }
        }
        return s;
    }
    let es = format!("{:.*e}", p - 1, v);
    let epos = es.find('e').unwrap();
    let exp: i32 = es[epos + 1..].parse().unwrap();
    if exp < -4 || exp >= p as i32 {
        // exponential
        let mut mant = es[..epos].to_string();
        if !alt && mant.contains('.') {
            while mant.ends_with('0') {
                mant.pop();
            }
            if mant.ends_with('.') {
                mant.pop();
            }
        }
        let sign = if exp < 0 { '-' } else { '+' };
        let e = if upper { 'E' } else { 'e' };
        format!("{}{}{}{:02}", mant, e, sign, exp.abs())
    } else {
        let decimals = (p as i32 - 1 - exp).max(0) as usize;
        let mut s = format!("{:.*}", decimals, v);
        if !alt && s.contains('.') {
            while s.ends_with('0') {
                s.pop();
            }
            if s.ends_with('.') {
                s.pop();
            }
        }
        s
    }
}

pub fn format_e(v: f64, prec: usize, upper: bool) -> String {
    if !v.is_finite() {
        return format_g(v, prec, upper, false);
    }
    let es = format!("{:.*e}", prec, v);
    let epos = es.find('e').unwrap();
    let exp: i32 = es[epos + 1..].parse().unwrap();
    let sign = if exp < 0 { '-' } else { '+' };
    let e = if upper { 'E' } else { 'e' };
    format!("{}{}{}{:02}", &es[..epos], e, sign, exp.abs())
}

fn pad(s: String, width: usize, left: bool, zero: bool) -> String {
    let len = s.chars().count();
    if len >= width {
        return s;
    }
    let n = width - len;
    if left {
        format!("{}{}", s, " ".repeat(n))
    } else if zero {
        // put zeros after sign
        let (sign, rest) = if s.starts_with('-') || s.starts_with('+') || s.starts_with(' ') {
            (s[..1].to_string(), s[1..].to_string())
        } else if s.starts_with("0x") || s.starts_with("0X") {
            (s[..2].to_string(), s[2..].to_string())
        } else {
            (String::new(), s)
        };
        format!("{}{}{}", sign, "0".repeat(n), rest)
    } else {
        format!("{}{}", " ".repeat(n), s)
    }
}

fn pad_bytes(s: Vec<u8>, width: usize, left: bool) -> Vec<u8> {
    if s.len() >= width {
        return s;
    }
    let n = width - s.len();
    let mut out = Vec::with_capacity(width);
    if left {
        out.extend_from_slice(&s);
        out.extend(std::iter::repeat(b' ').take(n));
    } else {
        out.extend(std::iter::repeat(b' ').take(n));
        out.extend_from_slice(&s);
    }
    out
}

pub fn quote_string(s: &[u8], out: &mut Vec<u8>) {
    out.push(b'"');
    for (i, &c) in s.iter().enumerate() {
        if c == b'"' || c == b'\\' || c == b'\n' {
            out.push(b'\\');
            out.push(c);
        } else if c < 32 || c == 127 {
            out.push(b'\\');
            let next_digit = s.get(i + 1).map(|d| d.is_ascii_digit()).unwrap_or(false);
            if next_digit {
                out.extend_from_slice(format!("{:03}", c).as_bytes());
            } else {
                out.extend_from_slice(format!("{}", c).as_bytes());
            }
        } else {
            out.push(c);
        }
    }
    out.push(b'"');
}

fn str_format(lua: &mut Lua, args: Vec<Value>) -> LResult<Vec<Value>> {
    let fmt = check_str(&args, 0, "format")?;
    let mut out: Vec<u8> = Vec::with_capacity(fmt.len() + 16);
    let mut argi = 1;
    let mut i = 0;
    while i < fmt.len() {
        let c = fmt[i];
        if c != b'%' {
            out.push(c);
            i += 1;
            continue;
        }
        i += 1;
        if i < fmt.len() && fmt[i] == b'%' {
            out.push(b'%');
            i += 1;
            continue;
        }
        // flags
        let mut left = false;
        let mut zero = false;
        let mut plus = false;
        let mut space = false;
        let mut alt = false;
        while i < fmt.len() {
            match fmt[i] {
                b'-' => left = true,
                b'0' => zero = true,
                b'+' => plus = true,
                b' ' => space = true,
                b'#' => alt = true,
                _ => break,
            }
            i += 1;
        }
        let mut width = 0usize;
        while i < fmt.len() && fmt[i].is_ascii_digit() {
            width = width * 10 + (fmt[i] - b'0') as usize;
            i += 1;
        }
        let mut prec: Option<usize> = None;
        if i < fmt.len() && fmt[i] == b'.' {
            i += 1;
            let mut p = 0;
            while i < fmt.len() && fmt[i].is_ascii_digit() {
                p = p * 10 + (fmt[i] - b'0') as usize;
                i += 1;
            }
            prec = Some(p);
        }
        if i >= fmt.len() {
            return Err(LuaError::rt(
                "invalid option '%' to 'format'".to_string(),
            ));
        }
        let conv = fmt[i];
        i += 1;
        let argn = argi;
        argi += 1;
        match conv {
            b'd' | b'i' => {
                let n = check_num(&args, argn, "format")?;
                let iv = n.trunc() as i64;
                let mut s = iv.abs().to_string();
                if let Some(p) = prec {
                    while s.len() < p {
                        s.insert(0, '0');
                    }
                }
                if iv < 0 {
                    s.insert(0, '-');
                } else if plus {
                    s.insert(0, '+');
                } else if space {
                    s.insert(0, ' ');
                }
                out.extend_from_slice(pad(s, width, left, zero && prec.is_none()).as_bytes());
            }
            b'u' => {
                let n = check_num(&args, argn, "format")?;
                let s = (n as i64 as u64).to_string();
                out.extend_from_slice(pad(s, width, left, zero).as_bytes());
            }
            b'c' => {
                let n = check_num(&args, argn, "format")?;
                out.extend_from_slice(&pad_bytes(vec![n as i64 as u8], width, left));
            }
            b'x' | b'X' | b'o' => {
                let n = check_num(&args, argn, "format")?;
                let u = n as i64 as u64;
                let mut s = match conv {
                    b'x' => format!("{:x}", u),
                    b'X' => format!("{:X}", u),
                    _ => format!("{:o}", u),
                };
                if let Some(p) = prec {
                    while s.len() < p {
                        s.insert(0, '0');
                    }
                }
                if alt && u != 0 {
                    s = match conv {
                        b'x' => format!("0x{}", s),
                        b'X' => format!("0X{}", s),
                        _ => format!("0{}", s),
                    };
                }
                out.extend_from_slice(pad(s, width, left, zero && prec.is_none()).as_bytes());
            }
            b'e' | b'E' | b'f' | b'F' | b'g' | b'G' => {
                let n = check_num(&args, argn, "format")?;
                let p = prec.unwrap_or(6);
                let mut s = match conv {
                    b'e' | b'E' => format_e(n, p, conv == b'E'),
                    b'f' | b'F' => {
                        if n.is_finite() {
                            let mut s = format!("{:.*}", p, n);
                            if alt && p == 0 {
                                s.push('.');
                            }
                            s
                        } else {
                            format_g(n, p, conv == b'F', false)
                        }
                    }
                    _ => format_g(n, p, conv == b'G', alt),
                };
                if !s.starts_with('-') {
                    if plus {
                        s.insert(0, '+');
                    } else if space {
                        s.insert(0, ' ');
                    }
                }
                let z = zero && n.is_finite();
                out.extend_from_slice(pad(s, width, left, z).as_bytes());
            }
            b'a' | b'A' => {
                let n = check_num(&args, argn, "format")?;
                out.extend_from_slice(pad(format!("{}", n), width, left, zero).as_bytes());
            }
            b'q' => {
                let s = check_str(&args, argn, "format")?;
                quote_string(&s, &mut out);
            }
            b's' => {
                let v = match args.get(argn) {
                    Some(v) => v.clone(),
                    None => {
                        return Err(arg_err(argn + 1, "format", "string expected, got no value"))
                    }
                };
                let sv = lua.tostring(&v)?;
                let mut b = sv.as_str_bytes().unwrap_or(b"").to_vec();
                if let Some(p) = prec {
                    b.truncate(p);
                }
                out.extend_from_slice(&pad_bytes(b, width, left));
            }
            _ => {
                return Err(LuaError::rt(format!(
                    "invalid option '%{}' to 'format'",
                    conv as char
                )));
            }
        }
    }
    Ok(vec![Value::bytes(&out)])
}

// ---------------- string library ----------------

fn str_index(i: i64, len: usize) -> i64 {
    if i < 0 {
        len as i64 + i + 1
    } else {
        i
    }
}

fn push_captures(ms: &MatchState, s: usize, e: usize, whole: bool, out: &mut Vec<Value>) -> LResult<()> {
    let n = ms.ncaptures(whole);
    for i in 0..n {
        match ms.get_capture(i, s, e).map_err(LuaError::rt)? {
            Cap::Str(b) => out.push(Value::bytes(b)),
            Cap::Pos(p) => out.push(Value::Num(p as f64)),
        }
    }
    Ok(())
}

fn str_find_aux(args: Vec<Value>, find: bool) -> LResult<Vec<Value>> {
    let fname = if find { "find" } else { "match" };
    let s = check_lstr(&args, 0, fname)?;
    let p = check_lstr(&args, 1, fname)?;
    let sb = s.as_bytes();
    let pb = p.as_bytes();
    let mut init = str_index(opt_int(&args, 2, fname, 1)?, sb.len()) - 1;
    if init < 0 {
        init = 0;
    } else if init as usize > sb.len() {
        return Ok(vec![Value::Nil]);
    }
    let init = init as usize;
    let plain = args.get(3).map(|v| v.truthy()).unwrap_or(false);
    if find && (plain || lpattern::no_specials(pb)) {
        return Ok(match lpattern::find_plain(sb, pb, init) {
            Some(i) => vec![Value::Num((i + 1) as f64), Value::Num((i + pb.len()) as f64)],
            None => vec![Value::Nil],
        });
    }
    let (anchor, pstart) = if pb.first() == Some(&b'^') { (true, 1) } else { (false, 0) };
    let mut s1 = init;
    loop {
        let mut ms = MatchState::new(sb, &pb[..]);
        ms.level = 0;
        // pattern starting at pstart: use sub-slice semantics
        let mut ms2 = MatchState::new(sb, &pb[pstart..]);
        let _ = &mut ms;
        if let Some(e) = ms2.do_match(s1, 0).map_err(LuaError::rt)? {
            let mut out = vec![];
            if find {
                out.push(Value::Num((s1 + 1) as f64));
                out.push(Value::Num(e as f64));
                push_captures(&ms2, s1, e, false, &mut out)?;
            } else {
                push_captures(&ms2, s1, e, true, &mut out)?;
            }
            return Ok(out);
        }
        s1 += 1;
        if anchor || s1 > sb.len() {
            break;
        }
    }
    Ok(vec![Value::Nil])
}

fn str_gmatch(_lua: &mut Lua, args: Vec<Value>) -> LResult<Vec<Value>> {
    let s = check_lstr(&args, 0, "gmatch")?;
    let p = check_lstr(&args, 1, "gmatch")?;
    let pos = Rc::new(RefCell::new(0usize));
    let f = Lua::native("gmatch_iter", move |_lua, _a| {
        let sb = s.as_bytes();
        let pb = p.as_bytes();
        let mut src = *pos.borrow();
        while src <= sb.len() {
            let mut ms = MatchState::new(sb, pb);
            if let Some(e) = ms.do_match(src, 0).map_err(LuaError::rt)? {
                let newstart = if e == src { e + 1 } else { e };
                *pos.borrow_mut() = newstart;
                let mut out = vec![];
                push_captures(&ms, src, e, true, &mut out)?;
                return Ok(out);
            }
            src += 1;
        }
        *pos.borrow_mut() = sb.len() + 1;
        Ok(vec![Value::Nil])
    });
    Ok(vec![f])
}

fn add_value(
    lua: &mut Lua,
    ms: &MatchState,
    s: usize,
    e: usize,
    repl: &Value,
    out: &mut Vec<u8>,
) -> LResult<()> {
    let src = ms.src;
    let result = match repl {
        Value::Str(_) | Value::Num(_) => {
            let r = match repl {
                Value::Str(r) => r.as_bytes().to_vec(),
                Value::Num(n) => fmt_num(*n).into_bytes(),
                _ => unreachable!(),
            };
            let mut i = 0;
            while i < r.len() {
                let c = r[i];
                if c == b'%' {
                    i += 1;
                    let d = if i < r.len() { r[i] } else { 0 };
                    if !d.is_ascii_digit() {
                        out.push(d);
                    } else if d == b'0' {
                        out.extend_from_slice(&src[s..e]);
                    } else {
                        match ms
                            .get_capture((d - b'1') as usize, s, e)
                            .map_err(LuaError::rt)?
                        {
                            Cap::Str(b) => out.extend_from_slice(b),
                            Cap::Pos(p) => out.extend_from_slice(p.to_string().as_bytes()),
                        }
                    }
                    i += 1;
                } else {
                    out.push(c);
                    i += 1;
                }
            }
            return Ok(());
        }
        Value::Table(t) => {
            let k = match ms.get_capture(0, s, e).map_err(LuaError::rt)? {
                Cap::Str(b) => Value::bytes(b),
                Cap::Pos(p) => Value::Num(p as f64),
            };
            let tv = Value::Table(t.clone());
            lua.index(&tv, &k)?
        }
        Value::Func(_) => {
            let mut caps = vec![];
            push_captures(ms, s, e, true, &mut caps)?;
            lua.call1(repl, caps)?
        }
        _ => {
            return Err(arg_err(3, "gsub", "string/function/table expected"));
        }
    };
    match result {
        Value::Nil | Value::Bool(false) => out.extend_from_slice(&src[s..e]),
        Value::Str(r) => out.extend_from_slice(r.as_bytes()),
        Value::Num(n) => out.extend_from_slice(fmt_num(n).as_bytes()),
        v => {
            return Err(LuaError::rt(format!(
                "invalid replacement value (a {})",
                v.type_name()
            )))
        }
    }
    Ok(())
}

fn str_gsub(lua: &mut Lua, args: Vec<Value>) -> LResult<Vec<Value>> {
    let s = check_lstr(&args, 0, "gsub")?;
    let p = check_lstr(&args, 1, "gsub")?;
    let repl = arg(&args, 2);
    match repl {
        Value::Str(_) | Value::Num(_) | Value::Table(_) | Value::Func(_) => {}
        _ => {
            return Err(arg_err(
                3,
                "gsub",
                &format!("string/function/table expected, got {}", type_name_or_no_value(&args, 2)),
            ))
        }
    }
    let sb = s.as_bytes();
    let pb_full = p.as_bytes();
    let max_n = match args.get(3) {
        None | Some(Value::Nil) => i64::MAX,
        _ => check_int(&args, 3, "gsub")?,
    };
    let (anchor, pb) = if pb_full.first() == Some(&b'^') {
        (true, &pb_full[1..])
    } else {
        (false, pb_full)
    };
    let mut out = Vec::with_capacity(sb.len());
    let mut src = 0usize;
    let mut n = 0i64;
    while n < max_n {
        let mut ms = MatchState::new(sb, pb);
        let e = ms.do_match(src, 0).map_err(LuaError::rt)?;
        if let Some(e) = e {
            n += 1;
            add_value(lua, &ms, src, e, &repl, &mut out)?;
        }
        match e {
            Some(e) if e > src => src = e,
            _ => {
                if src < sb.len() {
                    out.push(sb[src]);
                    src += 1;
                } else {
                    break;
                }
            }
        }
        if anchor {
            break;
        }
    }
    if src < sb.len() {
        out.extend_from_slice(&sb[src..]);
    }
    Ok(vec![Value::bytes(&out), Value::Num(n as f64)])
}

pub fn open_string(lua: &mut Lua) {
    let t = new_table();
    reg(&t, "len", |_l, a| {
        let s = check_lstr(&a, 0, "len")?;
        Ok(vec![Value::Num(s.as_bytes().len() as f64)])
    });
    reg(&t, "sub", |_l, a| {
        let s = check_lstr(&a, 0, "sub")?;
        let b = s.as_bytes();
        let len = b.len();
        let mut i = str_index(opt_int(&a, 1, "sub", 1)?, len);
        let mut j = str_index(opt_int(&a, 2, "sub", -1)?, len);
        if i < 1 {
            i = 1;
        }
        if j > len as i64 {
            j = len as i64;
        }
        if i > j {
            return Ok(vec![Value::str("")]);
        }
        Ok(vec![Value::bytes(&b[(i - 1) as usize..j as usize])])
    });
    reg(&t, "upper", |_l, a| {
        let s = check_str(&a, 0, "upper")?;
        Ok(vec![Value::bytes(&s.to_ascii_uppercase())])
    });
    reg(&t, "lower", |_l, a| {
        let s = check_str(&a, 0, "lower")?;
        Ok(vec![Value::bytes(&s.to_ascii_lowercase())])
    });
    reg(&t, "rep", |_l, a| {
        let s = check_str(&a, 0, "rep")?;
        let n = check_int(&a, 1, "rep")?;
        let sep = match a.get(2) {
            None | Some(Value::Nil) => vec![],
            _ => check_str(&a, 2, "rep")?,
        };
        if n <= 0 {
            return Ok(vec![Value::str("")]);
        }
        let mut out = Vec::with_capacity((s.len() + sep.len()) * n as usize);
        for i in 0..n {
            if i > 0 {
                out.extend_from_slice(&sep);
            }
            out.extend_from_slice(&s);
        }
        Ok(vec![Value::bytes(&out)])
    });
    reg(&t, "reverse", |_l, a| {
        let mut s = check_str(&a, 0, "reverse")?;
        s.reverse();
        Ok(vec![Value::bytes(&s)])
    });
    reg(&t, "byte", |_l, a| {
        let s = check_lstr(&a, 0, "byte")?;
        let b = s.as_bytes();
        let len = b.len();
        let i = str_index(opt_int(&a, 1, "byte", 1)?, len);
        let j = str_index(opt_int(&a, 2, "byte", i)?, len);
        let i = i.max(1);
        let j = j.min(len as i64);
        let mut out = vec![];
        let mut k = i;
        while k <= j {
            out.push(Value::Num(b[(k - 1) as usize] as f64));
            k += 1;
        }
        Ok(out)
    });
    reg(&t, "char", |_l, a| {
        let mut out = Vec::with_capacity(a.len());
        for i in 0..a.len() {
            let n = check_int(&a, i, "char")?;
            if !(0..=255).contains(&n) {
                return Err(arg_err(i + 1, "char", "invalid value"));
            }
            out.push(n as u8);
        }
        Ok(vec![Value::bytes(&out)])
    });
    reg(&t, "format", str_format);
    reg(&t, "find", |_l, a| str_find_aux(a, true));
    reg(&t, "match", |_l, a| str_find_aux(a, false));
    reg(&t, "gmatch", str_gmatch);
    reg(&t, "gsub", str_gsub);
    reg(&t, "dump", |_l, _a| Err(LuaError::rt("unable to dump given function")));
    let meta = new_table();
    meta.borrow_mut().set_str("__index", Value::Table(t.clone()));
    lua.string_meta = Some(meta);
    lua.set_global("string", Value::Table(t.clone()));
    lua.loaded.borrow_mut().set_str("string", Value::Table(t));
}

// ---------------- table library ----------------

fn sort_cmp(lua: &mut Lua, cmp: &Value, a: &Value, b: &Value) -> LResult<bool> {
    if cmp.is_nil() {
        lua.less_than(a, b)
    } else {
        Ok(lua.call1(cmp, vec![a.clone(), b.clone()])?.truthy())
    }
}

fn auxsort(lua: &mut Lua, a: &mut Vec<Value>, mut lo: usize, mut up: usize, cmp: &Value) -> LResult<()> {
    // port of Lua 5.1 auxsort (0-based indices, inclusive)
    while lo < up {
        if sort_cmp(lua, cmp, &a[up], &a[lo])? {
            a.swap(lo, up);
        }
        if up - lo == 1 {
            break;
        }
        let mut p = (lo + up) / 2;
        if sort_cmp(lua, cmp, &a[p], &a[lo])? {
            a.swap(p, lo);
        } else if sort_cmp(lua, cmp, &a[up], &a[p])? {
            a.swap(p, up);
        }
        if up - lo == 2 {
            break;
        }
        let pv = a[p].clone();
        a.swap(p, up - 1);
        p = up - 1;
        let _ = p;
        let mut i = lo;
        let mut j = up - 1;
        loop {
            i += 1;
            while sort_cmp(lua, cmp, &a[i], &pv)? {
                if i >= up {
                    return Err(LuaError::rt("invalid order function for sorting"));
                }
                i += 1;
            }
            j -= 1;
            while sort_cmp(lua, cmp, &pv, &a[j])? {
                if j <= lo {
                    return Err(LuaError::rt("invalid order function for sorting"));
                }
                j -= 1;
            }
            if j < i {
                break;
            }
            a.swap(i, j);
        }
        a.swap(up - 1, i);
        if i - lo < up - i {
            if i > 0 {
                auxsort(lua, a, lo, i - 1, cmp)?;
            }
            lo = i + 1;
        } else {
            auxsort(lua, a, i + 1, up, cmp)?;
            if i == 0 {
                break;
            }
            up = i - 1;
        }
    }
    Ok(())
}

pub fn open_table(lua: &mut Lua) {
    let t = new_table();
    reg(&t, "insert", |_l, a| {
        let tb = check_table(&a, 0, "insert")?;
        let n = tb.borrow().len();
        match a.len() {
            2 => {
                tb.borrow_mut().push(a[1].clone());
            }
            3 => {
                let pos = check_int(&a, 1, "insert")?;
                if pos < 1 || pos as usize > n + 1 {
                    // LuaJIT allows any position; emulate by setting
                    let _ = tb.borrow_mut().set(Value::Num(pos as f64), a[2].clone());
                    return Ok(vec![]);
                }
                tb.borrow_mut().insert_at(pos as usize, a[2].clone());
            }
            _ => return Err(LuaError::rt("wrong number of arguments to 'insert'")),
        }
        Ok(vec![])
    });
    reg(&t, "remove", |_l, a| {
        let tb = check_table(&a, 0, "remove")?;
        let n = tb.borrow().len();
        if a.len() < 2 || a[1].is_nil() {
            if n == 0 {
                return Ok(vec![]);
            }
            let v = tb.borrow_mut().remove_at(n);
            return Ok(vec![v]);
        }
        let pos = check_int(&a, 1, "remove")?;
        if n == 0 && (pos == 0 || pos == n as i64) {
            let v = tb.borrow().get_int(pos as usize);
            return Ok(vec![v]);
        }
        if pos < 1 || pos as usize > n + 1 {
            return Ok(vec![]);
        }
        let v = tb.borrow_mut().remove_at(pos as usize);
        Ok(vec![v])
    });
    reg(&t, "concat", |_l, a| {
        let tb = check_table(&a, 0, "concat")?;
        let sep = match a.get(1) {
            None | Some(Value::Nil) => vec![],
            _ => check_str(&a, 1, "concat")?,
        };
        let i = opt_int(&a, 2, "concat", 1)?;
        let j = match a.get(3) {
            None | Some(Value::Nil) => tb.borrow().len() as i64,
            _ => check_int(&a, 3, "concat")?,
        };
        let mut out = Vec::new();
        let tbb = tb.borrow();
        let mut k = i;
        while k <= j {
            let v = tbb.get_int(k as usize);
            match &v {
                Value::Str(s) => out.extend_from_slice(s.as_bytes()),
                Value::Num(n) => out.extend_from_slice(fmt_num(*n).as_bytes()),
                _ => {
                    return Err(LuaError::rt(format!(
                        "invalid value (at index {}) in table for 'concat'",
                        k
                    )))
                }
            }
            if k < j {
                out.extend_from_slice(&sep);
            }
            k += 1;
        }
        Ok(vec![Value::bytes(&out)])
    });
    reg(&t, "sort", |l, a| {
        let tb = check_table(&a, 0, "sort")?;
        let cmp = arg(&a, 1);
        if !cmp.is_nil() && !matches!(cmp, Value::Func(_)) {
            return Err(arg_err(2, "sort", &format!("function expected, got {}", cmp.type_name())));
        }
        let n = tb.borrow().len();
        let mut v: Vec<Value> = (1..=n).map(|i| tb.borrow().get_int(i)).collect();
        if n > 1 {
            auxsort(l, &mut v, 0, n - 1, &cmp)?;
        }
        let mut tbm = tb.borrow_mut();
        for (i, x) in v.into_iter().enumerate() {
            let _ = tbm.set(Value::Num((i + 1) as f64), x);
        }
        Ok(vec![])
    });
    reg(&t, "getn", |_l, a| {
        let tb = check_table(&a, 0, "getn")?;
        let n = tb.borrow().len();
        Ok(vec![Value::Num(n as f64)])
    });
    reg(&t, "maxn", |_l, a| {
        let tb = check_table(&a, 0, "maxn")?;
        let mut m = 0.0f64;
        for (k, _) in tb.borrow().iter_pairs() {
            if let Value::Num(n) = k {
                if n > m {
                    m = n;
                }
            }
        }
        Ok(vec![Value::Num(m)])
    });
    reg(&t, "foreach", |l, a| {
        let tb = check_table(&a, 0, "foreach")?;
        let f = arg(&a, 1);
        for (k, v) in tb.borrow().iter_pairs() {
            let r = l.call1(&f, vec![k, v])?;
            if !r.is_nil() {
                return Ok(vec![r]);
            }
        }
        Ok(vec![])
    });
    reg(&t, "foreachi", |l, a| {
        let tb = check_table(&a, 0, "foreachi")?;
        let f = arg(&a, 1);
        let n = tb.borrow().len();
        for i in 1..=n {
            let v = tb.borrow().get_int(i);
            let r = l.call1(&f, vec![Value::Num(i as f64), v])?;
            if !r.is_nil() {
                return Ok(vec![r]);
            }
        }
        Ok(vec![])
    });
    reg(&t, "move", |_l, a| {
        let a1 = check_table(&a, 0, "move")?;
        let f = check_int(&a, 1, "move")?;
        let e = check_int(&a, 2, "move")?;
        let tpos = check_int(&a, 3, "move")?;
        let a2 = match a.get(4) {
            Some(Value::Table(t)) => t.clone(),
            _ => a1.clone(),
        };
        if e >= f {
            let vals: Vec<Value> = (f..=e).map(|i| a1.borrow().get(&Value::Num(i as f64))).collect();
            let mut t2 = a2.borrow_mut();
            for (k, v) in vals.into_iter().enumerate() {
                let _ = t2.set(Value::Num((tpos + k as i64) as f64), v);
            }
        }
        Ok(vec![Value::Table(a2)])
    });
    lua.set_global("table", Value::Table(t.clone()));
    lua.loaded.borrow_mut().set_str("table", Value::Table(t));
}

// ---------------- math ----------------

pub fn open_math(lua: &mut Lua) {
    let t = new_table();
    macro_rules! f1 {
        ($name:expr, $f:expr) => {
            reg(&t, $name, |_l, a| {
                let x = check_num(&a, 0, $name)?;
                let f: fn(f64) -> f64 = $f;
                Ok(vec![Value::Num(f(x))])
            });
        };
    }
    f1!("abs", |x| x.abs());
    f1!("acos", |x| x.acos());
    f1!("asin", |x| x.asin());
    f1!("atan", |x| x.atan());
    f1!("ceil", |x| x.ceil());
    f1!("cos", |x| x.cos());
    f1!("cosh", |x| x.cosh());
    f1!("deg", |x| x.to_degrees());
    f1!("exp", |x| x.exp());
    f1!("floor", |x| x.floor());
    f1!("log10", |x| x.log10());
    f1!("rad", |x| x.to_radians());
    f1!("sin", |x| x.sin());
    f1!("sinh", |x| x.sinh());
    f1!("sqrt", |x| x.sqrt());
    f1!("tan", |x| x.tan());
    f1!("tanh", |x| x.tanh());
    reg(&t, "log", |_l, a| {
        let x = check_num(&a, 0, "log")?;
        match a.get(1) {
            None | Some(Value::Nil) => Ok(vec![Value::Num(x.ln())]),
            _ => {
                let b = check_num(&a, 1, "log")?;
                Ok(vec![Value::Num(x.ln() / b.ln())])
            }
        }
    });
    reg(&t, "atan2", |_l, a| {
        let y = check_num(&a, 0, "atan2")?;
        let x = check_num(&a, 1, "atan2")?;
        Ok(vec![Value::Num(y.atan2(x))])
    });
    reg(&t, "pow", |_l, a| {
        let x = check_num(&a, 0, "pow")?;
        let y = check_num(&a, 1, "pow")?;
        Ok(vec![Value::Num(x.powf(y))])
    });
    reg(&t, "fmod", |_l, a| {
        let x = check_num(&a, 0, "fmod")?;
        let y = check_num(&a, 1, "fmod")?;
        Ok(vec![Value::Num(x % y)])
    });
    reg(&t, "modf", |_l, a| {
        let x = check_num(&a, 0, "modf")?;
        let ip = x.trunc();
        let fp = if x.is_infinite() { 0.0 } else { x - ip };
        Ok(vec![Value::Num(ip), Value::Num(fp)])
    });
    reg(&t, "frexp", |_l, a| {
        let x = check_num(&a, 0, "frexp")?;
        if x == 0.0 || !x.is_finite() {
            return Ok(vec![Value::Num(x), Value::Num(0.0)]);
        }
        let e = x.abs().log2().floor() as i32 + 1;
        let m = x / (2f64).powi(e);
        Ok(vec![Value::Num(m), Value::Num(e as f64)])
    });
    reg(&t, "ldexp", |_l, a| {
        let m = check_num(&a, 0, "ldexp")?;
        let e = check_int(&a, 1, "ldexp")?;
        Ok(vec![Value::Num(m * (2f64).powi(e as i32))])
    });
    reg(&t, "min", |_l, a| {
        let mut m = check_num(&a, 0, "min")?;
        for i in 1..a.len() {
            let x = check_num(&a, i, "min")?;
            if x < m {
                m = x;
            }
        }
        Ok(vec![Value::Num(m)])
    });
    reg(&t, "max", |_l, a| {
        let mut m = check_num(&a, 0, "max")?;
        for i in 1..a.len() {
            let x = check_num(&a, i, "max")?;
            if x > m {
                m = x;
            }
        }
        Ok(vec![Value::Num(m)])
    });
    let seed = Rc::new(RefCell::new(0x2545F4914F6CDD1Du64 ^ (std::process::id() as u64)));
    let s1 = seed.clone();
    reg(&t, "random", move |_l, a| {
        let mut s = s1.borrow_mut();
        // xorshift64*
        let mut x = *s;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        *s = x;
        let r = (x.wrapping_mul(0x2545F4914F6CDD1D) >> 11) as f64 / (1u64 << 53) as f64;
        match a.len() {
            0 => Ok(vec![Value::Num(r)]),
            1 => {
                let m = check_num(&a, 0, "random")?.floor();
                if m < 1.0 {
                    return Err(arg_err(1, "random", "interval is empty"));
                }
                Ok(vec![Value::Num((r * m).floor() + 1.0)])
            }
            _ => {
                let lo = check_num(&a, 0, "random")?.floor();
                let hi = check_num(&a, 1, "random")?.floor();
                if lo > hi {
                    return Err(arg_err(2, "random", "interval is empty"));
                }
                Ok(vec![Value::Num((r * (hi - lo + 1.0)).floor() + lo)])
            }
        }
    });
    let s2 = seed;
    reg(&t, "randomseed", move |_l, a| {
        let x = check_num(&a, 0, "randomseed")?;
        let mut v = x.to_bits() ^ 0x9E3779B97F4A7C15;
        if v == 0 {
            v = 1;
        }
        *s2.borrow_mut() = v;
        Ok(vec![])
    });
    t.borrow_mut().set_str("pi", Value::Num(std::f64::consts::PI));
    t.borrow_mut().set_str("huge", Value::Num(f64::INFINITY));
    lua.set_global("math", Value::Table(t.clone()));
    lua.loaded.borrow_mut().set_str("math", Value::Table(t));
}

// ---------------- bit ----------------

fn tobit(x: f64) -> i32 {
    let v = x + 6755399441055744.0; // 2^52 + 2^51
    (v.to_bits() as u64 & 0xffff_ffff) as u32 as i32
}

pub fn open_bit(lua: &mut Lua) {
    let t = new_table();
    reg(&t, "tobit", |_l, a| Ok(vec![Value::Num(tobit(check_num(&a, 0, "tobit")?) as f64)]));
    reg(&t, "bnot", |_l, a| Ok(vec![Value::Num((!tobit(check_num(&a, 0, "bnot")?)) as f64)]));
    reg(&t, "band", |_l, a| {
        let mut r = tobit(check_num(&a, 0, "band")?);
        for i in 1..a.len() {
            r &= tobit(check_num(&a, i, "band")?);
        }
        Ok(vec![Value::Num(r as f64)])
    });
    reg(&t, "bor", |_l, a| {
        let mut r = tobit(check_num(&a, 0, "bor")?);
        for i in 1..a.len() {
            r |= tobit(check_num(&a, i, "bor")?);
        }
        Ok(vec![Value::Num(r as f64)])
    });
    reg(&t, "bxor", |_l, a| {
        let mut r = tobit(check_num(&a, 0, "bxor")?);
        for i in 1..a.len() {
            r ^= tobit(check_num(&a, i, "bxor")?);
        }
        Ok(vec![Value::Num(r as f64)])
    });
    reg(&t, "lshift", |_l, a| {
        let x = tobit(check_num(&a, 0, "lshift")?) as u32;
        let n = (tobit(check_num(&a, 1, "lshift")?) & 31) as u32;
        Ok(vec![Value::Num((x << n) as i32 as f64)])
    });
    reg(&t, "rshift", |_l, a| {
        let x = tobit(check_num(&a, 0, "rshift")?) as u32;
        let n = (tobit(check_num(&a, 1, "rshift")?) & 31) as u32;
        Ok(vec![Value::Num((x >> n) as i32 as f64)])
    });
    reg(&t, "arshift", |_l, a| {
        let x = tobit(check_num(&a, 0, "arshift")?);
        let n = (tobit(check_num(&a, 1, "arshift")?) & 31) as u32;
        Ok(vec![Value::Num((x >> n) as f64)])
    });
    reg(&t, "rol", |_l, a| {
        let x = tobit(check_num(&a, 0, "rol")?) as u32;
        let n = (tobit(check_num(&a, 1, "rol")?) & 31) as u32;
        Ok(vec![Value::Num(x.rotate_left(n) as i32 as f64)])
    });
    reg(&t, "ror", |_l, a| {
        let x = tobit(check_num(&a, 0, "ror")?) as u32;
        let n = (tobit(check_num(&a, 1, "ror")?) & 31) as u32;
        Ok(vec![Value::Num(x.rotate_right(n) as i32 as f64)])
    });
    reg(&t, "bswap", |_l, a| {
        let x = tobit(check_num(&a, 0, "bswap")?) as u32;
        Ok(vec![Value::Num(x.swap_bytes() as i32 as f64)])
    });
    reg(&t, "tohex", |_l, a| {
        let x = tobit(check_num(&a, 0, "tohex")?) as u32;
        let n = opt_int(&a, 1, "tohex", 8)?;
        let upper = n < 0;
        let n = n.unsigned_abs().min(8) as usize;
        let s = if upper { format!("{:08X}", x) } else { format!("{:08x}", x) };
        Ok(vec![Value::str(&s[8 - n..])])
    });
    lua.set_global("bit", Value::Table(t.clone()));
    lua.loaded.borrow_mut().set_str("bit", Value::Table(t));
}

// ---------------- base ----------------

fn ipairs_iter(_l: &mut Lua, a: Vec<Value>) -> LResult<Vec<Value>> {
    let i = match a.get(1) {
        Some(Value::Num(n)) => *n as usize + 1,
        _ => 1,
    };
    let v = match a.first() {
        Some(Value::Table(t)) => t.borrow().get_int(i),
        _ => Value::Nil,
    };
    if v.is_nil() {
        Ok(vec![Value::Nil])
    } else {
        Ok(vec![Value::Num(i as f64), v])
    }
}

pub fn lua_next(_l: &mut Lua, a: Vec<Value>) -> LResult<Vec<Value>> {
    let t = check_table(&a, 0, "next")?;
    let k = arg(&a, 1);
    let r = t.borrow().next(&k);
    match r {
        Ok(Some((k, v))) => Ok(vec![k, v]),
        Ok(None) => Ok(vec![Value::Nil]),
        Err(()) => Err(LuaError::rt("invalid key to 'next'")),
    }
}

pub fn tonumber_base(s: &[u8], base: u32) -> Option<f64> {
    let st = std::str::from_utf8(s).ok()?.trim();
    let (neg, body) = if let Some(r) = st.strip_prefix('-') { (true, r) } else { (false, st) };
    if body.is_empty() {
        return None;
    }
    let mut v: f64 = 0.0;
    for c in body.chars() {
        let d = c.to_digit(36)?;
        if d >= base {
            return None;
        }
        v = v * base as f64 + d as f64;
    }
    Some(if neg { -v } else { v })
}

pub fn open_base(lua: &mut Lua) {
    let g = lua.globals.clone();
    g.borrow_mut().set_str("_G", Value::Table(g.clone()));
    g.borrow_mut().set_str("_VERSION", Value::str("Lua 5.1"));
    reg(&g, "print", |l, a| {
        use std::io::Write;
        let mut out = Vec::new();
        for (i, v) in a.iter().enumerate() {
            if i > 0 {
                out.push(b'\t');
            }
            let s = l.tostring(v)?;
            out.extend_from_slice(s.as_str_bytes().unwrap_or(b""));
        }
        out.push(b'\n');
        let mut so = std::io::stdout();
        let _ = so.write_all(&out);
        let _ = so.flush();
        Ok(vec![])
    });
    reg(&g, "type", |_l, a| {
        let v = check_any(&a, 0, "type")?;
        Ok(vec![Value::str(v.type_name())])
    });
