        }
    });
    reg(&g, "ipairs", |_l, a| {
        let t = check_any(&a, 0, "ipairs")?;
        if !matches!(t, Value::Table(_)) {
            return Err(arg_err(1, "ipairs", &format!("table expected, got {}", t.type_name())));
        }
        Ok(vec![Lua::native("ipairs_aux", ipairs_iter), t, Value::Num(0.0)])
    });
    let next_fn = Lua::native("next", lua_next);
    g.borrow_mut().set_str("next", next_fn.clone());
    reg(&g, "pairs", move |l, a| {
        let t = check_any(&a, 0, "pairs")?;
        let h = l.get_metamethod(&t, "__pairs");
        if !h.is_nil() {
