    });
    reg(&t, "execute", |_l, a| {
        match a.first() {
            None | Some(Value::Nil) => Ok(vec![Value::Num(1.0)]),
            _ => {
                let cmd = String::from_utf8_lossy(&check_str(&a, 0, "execute")?).into_owned();
                let st = std::process::Command::new("/bin/sh")
                    .arg("-c")
                    .arg(&cmd)
                    .status();
                match st {
                    Ok(s) => {
                        use std::os::unix::process::ExitStatusExt;
                        let code = s.code().unwrap_or(0);
                        let raw = if let Some(sig) = s.signal() { sig } else { code << 8 };
                        Ok(vec![Value::Num(raw as f64)])
                    }
                    Err(_) => Ok(vec![Value::Num(-1.0)]),
                }
            }
        }
    });
    reg(&t, "exit", |_l, a| {
        let code = match a.first() {
            Some(Value::Bool(b)) => {
                if *b {
                    0
                } else {
                    1
                }
            }
            Some(Value::Num(n)) => *n as i32,
            _ => 0,
        };
        let _ = std::io::stdout().flush();
        std::process::exit(code);
    });
    reg(&t, "remove", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "remove")?).into_owned();
        let r = match std::fs::symlink_metadata(&p) {
            Ok(m) if m.is_dir() => std::fs::remove_dir(&p),
            _ => std::fs::remove_file(&p),
        };
        match r {
            Ok(_) => Ok(vec![Value::Bool(true)]),
            Err(e) => Ok(vec![
                Value::Nil,
                Value::str(&format!("{}: {}", p, io_err_msg(&e))),
                Value::Num(e.raw_os_error().unwrap_or(0) as f64),
            ]),
        }
    });
    reg(&t, "rename", |_l, a| {
        let p1 = String::from_utf8_lossy(&check_str(&a, 0, "rename")?).into_owned();
        let p2 = String::from_utf8_lossy(&check_str(&a, 1, "rename")?).into_owned();
        match std::fs::rename(&p1, &p2) {
            Ok(_) => Ok(vec![Value::Bool(true)]),
            Err(e) => Ok(vec![
                Value::Nil,
                Value::str(&format!("{}: {}", p1, io_err_msg(&e))),
                Value::Num(e.raw_os_error().unwrap_or(0) as f64),
            ]),
        }
    });
    reg(&t, "tmpname", |_l, _a| {
        let n = format!("/tmp/lua_{:06x}", (now_secs() as u64 ^ std::process::id() as u64) & 0xffffff);
        Ok(vec![Value::str(&n)])
    });
    reg(&t, "setlocale", |_l, _a| Ok(vec![Value::str("C")]));
    lua.set_global("os", Value::Table(t.clone()));
    lua.loaded.borrow_mut().set_str("os", Value::Table(t));
}

pub fn io_err_msg(e: &std::io::Error) -> String {
    match e.raw_os_error() {
        Some(code) => unsafe {
            let p = libc::strerror(code);
            std::ffi::CStr::from_ptr(p).to_string_lossy().into_owned()
        },
        None => e.to_string(),
    }
}

// ---------------- io ----------------

pub enum FileKind {
    File(std::fs::File),
    Stdin,
    Stdout,
    Stderr,
    ProcRead(std::process::Child, std::process::ChildStdout),
    ProcWrite(std::process::Child, Option<std::process::ChildStdin>),
}

pub struct LFile {
    pub kind: FileKind,
    pub closed: bool,
    pub rbuf: Vec<u8>,
    pub rpos: usize,
    pub eof: bool,
}

impl LFile {
    fn new(kind: FileKind) -> Self {
        LFile {
            kind,
            closed: false,
            rbuf: vec![],
            rpos: 0,
            eof: false,
        }
    }

    fn fill(&mut self) -> bool {
        if self.rpos < self.rbuf.len() {
            return true;
        }
        if self.eof {
            return false;
        }
        let mut buf = vec![0u8; 8192];
        let n = match &mut self.kind {
            FileKind::File(f) => f.read(&mut buf).unwrap_or(0),
            FileKind::Stdin => std::io::stdin().read(&mut buf).unwrap_or(0),
            FileKind::ProcRead(_, o) => o.read(&mut buf).unwrap_or(0),
            _ => 0,
        };
        if n == 0 {
            self.eof = true;
            return false;
        }
        buf.truncate(n);
        self.rbuf = buf;
        self.rpos = 0;
        true
    }

    fn read_byte(&mut self) -> Option<u8> {
        if !self.fill() {
            return None;
        }
        let b = self.rbuf[self.rpos];
        self.rpos += 1;
        Some(b)
    }

    fn peek_byte(&mut self) -> Option<u8> {
        if !self.fill() {
            return None;
        }
        Some(self.rbuf[self.rpos])
    }

    fn read_line(&mut self, keep_nl: bool) -> Option<Vec<u8>> {
        let mut out = vec![];
        let mut any = false;
        loop {
            match self.read_byte() {
                None => break,
                Some(b'\n') => {
                    any = true;
                    if keep_nl {
                        out.push(b'\n');
                    }
                    break;
                }
                Some(b) => {
                    any = true;
                    out.push(b)
                }
            }
        }
        if !any {
            None
        } else {
            Some(out)
        }
    }

    fn read_all(&mut self) -> Vec<u8> {
        let mut out = vec![];
        while self.fill() {
            out.extend_from_slice(&self.rbuf[self.rpos..]);
            self.rpos = self.rbuf.len();
        }
        out
    }

    fn read_n(&mut self, n: usize) -> Option<Vec<u8>> {
        let mut out = vec![];
        while out.len() < n {
            match self.read_byte() {
                Some(b) => out.push(b),
                None => break,
            }
        }
        if out.is_empty() && n > 0 {
            None
        } else {
            Some(out)
        }
    }

    fn read_number(&mut self) -> Option<f64> {
        while let Some(b) = self.peek_byte() {
            if b.is_ascii_whitespace() {
                self.rpos += 1;
            } else {
                break;
            }
        }
        let mut s = vec![];
        while let Some(b) = self.peek_byte() {
            if b.is_ascii_alphanumeric() || b == b'.' || b == b'-' || b == b'+' {
                s.push(b);
                self.rpos += 1;
            } else {
                break;
            }
        }
        super::lexer::parse_number_literal(&s)
    }

    fn write(&mut self, b: &[u8]) -> std::io::Result<()> {
        match &mut self.kind {
            FileKind::File(f) => f.write_all(b),
            FileKind::Stdout => {
                let mut o = std::io::stdout();
                o.write_all(b)?;
                o.flush()
            }
            FileKind::Stderr => std::io::stderr().write_all(b),
            FileKind::ProcWrite(_, Some(i)) => i.write_all(b),
            _ => Err(std::io::Error::from_raw_os_error(libc::EBADF)),
        }
    }

    fn close(&mut self) -> Option<i32> {
        self.closed = true;
        let kind = std::mem::replace(&mut self.kind, FileKind::Stdin);
        match kind {
            FileKind::ProcRead(mut c, o) => {
                drop(o);
                c.wait().ok().and_then(|s| s.code())
            }
            FileKind::ProcWrite(mut c, i) => {
                drop(i);
                c.wait().ok().and_then(|s| s.code())
            }
            FileKind::File(f) => {
                drop(f);
                Some(0)
            }
            _ => Some(0),
        }
    }
}

fn file_meta(lua: &mut Lua) -> TableRef {
    if let Value::Table(t) = lua.loaded.borrow().get_str("\u{0}FILE*") {
        return t;
    }
    let meta = new_table();
    let methods = new_table();
    reg(&methods, "read", |l, a| file_read(l, a, 1));
    reg(&methods, "write", |_l, a| {
        let fv = arg(&a, 0);
        with_file(&fv, "write", |f| {
            for (i, v) in a.iter().enumerate().skip(1) {
                let b = match v {
                    Value::Str(s) => s.as_bytes().to_vec(),
                    Value::Num(n) => fmt_num(*n).into_bytes(),
                    _ => {
                        return Err(arg_err(
                            i,
                            "write",
                            &format!("string expected, got {}", v.type_name()),
                        ))
                    }
                };
                if let Err(e) = f.write(&b) {
                    return Ok(vec![Value::Nil, Value::str(&io_err_msg(&e))]);
                }
            }
            Ok(vec![fv.clone()])
        })
    });
    reg(&methods, "lines", |_l, a| {
        let fv = arg(&a, 0);
        with_file(&fv, "lines", |_f| Ok(()))?;
        let fv2 = fv.clone();
        Ok(vec![Lua::native("lines_iter", move |_l, _a| {
            with_file(&fv2, "lines", |f| match f.read_line(false) {
                Some(l) => Ok(vec![Value::bytes(&l)]),
                None => Ok(vec![Value::Nil]),
            })
        })])
    });
    reg(&methods, "close", |_l, a| {
        let fv = arg(&a, 0);
        with_file(&fv, "close", |f| {
            let code = f.close();
            match code {
                Some(0) | None => Ok(vec![Value::Bool(true)]),
                Some(c) => Ok(vec![Value::Nil, Value::str("exit"), Value::Num(c as f64)]),
            }
        })
    });
    reg(&methods, "flush", |_l, a| {
        let fv = arg(&a, 0);
        with_file(&fv, "flush", |f| {
            if let FileKind::File(fl) = &mut f.kind {
                let _ = fl.flush();
            }
            Ok(vec![fv.clone()])
        })
    });
    reg(&methods, "setvbuf", |_l, _a| Ok(vec![Value::Bool(true)]));
    reg(&methods, "seek", |_l, a| {
        use std::io::Seek;
        let fv = arg(&a, 0);
        let whence = match a.get(1) {
            Some(Value::Str(s)) => s.to_str_lossy(),
            _ => "cur".into(),
        };
        let off = opt_int(&a, 2, "seek", 0)?;
        with_file(&fv, "seek", |f| {
            let buffered = (f.rbuf.len() - f.rpos) as i64;
            let FileKind::File(fl) = &mut f.kind else {
                return Ok(vec![Value::Nil, Value::str("Illegal seek")]);
            };
            let pos = match whence.as_str() {
                "set" => std::io::SeekFrom::Start(off as u64),
                "end" => std::io::SeekFrom::End(off),
                _ => std::io::SeekFrom::Current(off - buffered),
            };
            let r = fl.seek(pos);
            f.rbuf.clear();
            f.rpos = 0;
            f.eof = false;
            match r {
                Ok(p) => Ok(vec![Value::Num(p as f64)]),
                Err(e) => Ok(vec![Value::Nil, Value::str(&io_err_msg(&e))]),
            }
        })
    });
    meta.borrow_mut().set_str("__index", Value::Table(methods));
    meta.borrow_mut().set_str(
        "__tostring",
        Lua::native("tostring", |_l, a| {
            let fv = arg(&a, 0);
            let closed = match &fv {
                Value::UserData(u) => u
                    .data
                    .borrow()
                    .downcast_ref::<LFile>()
                    .map(|f| f.closed)
                    .unwrap_or(true),
                _ => true,
            };
            if closed {
                Ok(vec![Value::str("file (closed)")])
            } else {
                Ok(vec![Value::str(&format!("file (0x{:x})", fv.ptr()))])
            }
        }),
    );
    lua.loaded
        .borrow_mut()
        .set_str("\u{0}FILE*", Value::Table(meta.clone()));
    meta
}

fn with_file<R>(fv: &Value, fname: &str, f: impl FnOnce(&mut LFile) -> LResult<R>) -> LResult<R> {
    if let Value::UserData(u) = fv {
        let mut d = u.data.borrow_mut();
        if let Some(lf) = d.downcast_mut::<LFile>() {
            if lf.closed {
                return Err(LuaError::rt("attempt to use a closed file"));
            }
            return f(lf);
        }
    }
    Err(arg_err(
        1,
        fname,
        &format!("FILE* expected, got {}", fv.type_name()),
    ))
}

fn file_read(_l: &mut Lua, a: Vec<Value>, first: usize) -> LResult<Vec<Value>> {
    let fv = arg(&a, 0);
    let fmts: Vec<Value> = if a.len() > first {
        a[first..].to_vec()
    } else {
        vec![Value::str("*l")]
    };
    with_file(&fv, "read", |f| {
        let mut out = vec![];
        for fm in fmts {
            let v = match &fm {
                Value::Num(n) => {
                    let n = *n as usize;
                    if n == 0 {
                        if f.peek_byte().is_some() {
                            Value::str("")
                        } else {
                            Value::Nil
                        }
                    } else {
                        match f.read_n(n) {
                            Some(b) => Value::bytes(&b),
                            None => Value::Nil,
                        }
                    }
                }
                Value::Str(s) => {
                    let s = s.as_bytes();
                    let s = if s.first() == Some(&b'*') { &s[1..] } else { s };
                    match s.first() {
                        Some(b'a') => Value::bytes(&f.read_all()),
                        Some(b'l') => match f.read_line(false) {
                            Some(l) => Value::bytes(&l),
                            None => Value::Nil,
                        },
                        Some(b'L') => match f.read_line(true) {
                            Some(l) => Value::bytes(&l),
                            None => Value::Nil,
                        },
                        Some(b'n') => match f.read_number() {
                            Some(n) => Value::Num(n),
                            None => Value::Nil,
                        },
                        _ => return Err(arg_err(1, "read", "invalid format")),
                    }
                }
                _ => return Err(arg_err(1, "read", "invalid format")),
            };
            let stop = v.is_nil();
            out.push(v);
            if stop {
                break;
            }
        }
        Ok(out)
    })
}

fn make_file(lua: &mut Lua, kind: FileKind) -> Value {
    let meta = file_meta(lua);
    Value::UserData(Rc::new(UserData {
        data: RefCell::new(Box::new(LFile::new(kind))),
        meta: RefCell::new(Some(meta)),
    }))
}

pub fn open_io(lua: &mut Lua) {
    let t = new_table();
    let stdin = make_file(lua, FileKind::Stdin);
    let stdout = make_file(lua, FileKind::Stdout);
    let stderr = make_file(lua, FileKind::Stderr);
    t.borrow_mut().set_str("stdin", stdin.clone());
    t.borrow_mut().set_str("stdout", stdout.clone());
    t.borrow_mut().set_str("stderr", stderr);
    let cur_in = Rc::new(RefCell::new(stdin));
    let cur_out = Rc::new(RefCell::new(stdout));
    reg(&t, "open", |l, a| {
        let path = String::from_utf8_lossy(&check_str(&a, 0, "open")?).into_owned();
        let mode = match a.get(1) {
            Some(Value::Str(s)) => s.to_str_lossy(),
            _ => "r".into(),
        };
        let mut oo = std::fs::OpenOptions::new();
        let m = mode.replace('b', "");
        match m.as_str() {
            "r" => {
                oo.read(true);
            }
            "w" => {
                oo.write(true).create(true).truncate(true);
            }
            "a" => {
                oo.append(true).create(true);
            }
            "r+" => {
                oo.read(true).write(true);
            }
            "w+" => {
                oo.read(true).write(true).create(true).truncate(true);
            }
            "a+" => {
                oo.read(true).append(true).create(true);
            }
            _ => return Err(arg_err(2, "open", "invalid mode")),
        }
        match oo.open(&path) {
            Ok(f) => Ok(vec![make_file(l, FileKind::File(f))]),
            Err(e) => Ok(vec![
                Value::Nil,
                Value::str(&format!("{}: {}", path, io_err_msg(&e))),
                Value::Num(e.raw_os_error().unwrap_or(0) as f64),
            ]),
        }
    });
    reg(&t, "popen", |l, a| {
        let cmd = String::from_utf8_lossy(&check_str(&a, 0, "popen")?).into_owned();
        let mode = match a.get(1) {
            Some(Value::Str(s)) => s.to_str_lossy(),
            _ => "r".into(),
        };
        let mut c = std::process::Command::new("/bin/sh");
        c.arg("-c").arg(&cmd);
        if mode.starts_with('w') {
            c.stdin(std::process::Stdio::piped());
            match c.spawn() {
                Ok(mut ch) => {
                    let i = ch.stdin.take();
                    Ok(vec![make_file(l, FileKind::ProcWrite(ch, i))])
                }
                Err(e) => Ok(vec![Value::Nil, Value::str(&io_err_msg(&e))]),
            }
        } else {
            c.stdout(std::process::Stdio::piped());
            match c.spawn() {
                Ok(mut ch) => {
                    let o = ch.stdout.take().unwrap();
                    Ok(vec![make_file(l, FileKind::ProcRead(ch, o))])
                }
                Err(e) => Ok(vec![Value::Nil, Value::str(&io_err_msg(&e))]),
            }
        }
    });
    let ci = cur_in.clone();
    reg(&t, "read", move |l, a| {
        let mut args = vec![ci.borrow().clone()];
        args.extend(a);
        file_read(l, args, 1)
    });
    let co = cur_out.clone();
    reg(&t, "write", move |l, a| {
        let f = co.borrow().clone();
        let w = l.index(&f, &Value::str("write"))?;
        let mut args = vec![f];
        args.extend(a);
        l.call(&w, args)
    });
    let ci2 = cur_in.clone();
    reg(&t, "lines", move |l, a| {
        match a.first() {
            Some(Value::Str(p)) => {
                let path = p.to_str_lossy();
                match std::fs::File::open(&path) {
                    Ok(f) => {
                        let fv = make_file(l, FileKind::File(f));
                        let fv2 = fv.clone();
                        Ok(vec![Lua::native("lines_iter", move |_l, _a| {
                            let r = with_file(&fv2, "lines", |f| Ok(f.read_line(false)))?;
                            match r {
                                Some(line) => Ok(vec![Value::bytes(&line)]),
                                None => {
                                    let _ = with_file(&fv2, "lines", |f| {
                                        f.close();
                                        Ok(())
                                    });
                                    Ok(vec![Value::Nil])
                                }
                            }
                        })])
                    }
                    Err(e) => Err(LuaError::rt(format!("{}: {}", path, io_err_msg(&e)))),
                }
            }
            _ => {
                let fv = ci2.borrow().clone();
                Ok(vec![Lua::native("lines_iter", move |_l, _a| {
                    with_file(&fv, "lines", |f| match f.read_line(false) {
                        Some(l) => Ok(vec![Value::bytes(&l)]),
                        None => Ok(vec![Value::Nil]),
                    })
                })])
            }
        }
    });
    reg(&t, "close", |l, a| {
        let f = match a.first() {
            Some(v) => v.clone(),
            None => return Ok(vec![]),
        };
        let c = l.index(&f, &Value::str("close"))?;
        l.call(&c, vec![f])
    });
    reg(&t, "flush", |_l, _a| {
        let _ = std::io::stdout().flush();
        Ok(vec![])
    });
    reg(&t, "type", |_l, a| {
        match a.first() {
            Some(Value::UserData(u)) => {
                if let Some(f) = u.data.borrow().downcast_ref::<LFile>() {
                    return Ok(vec![Value::str(if f.closed { "closed file" } else { "file" })]);
                }
                Ok(vec![Value::Nil])
            }
            _ => Ok(vec![Value::Nil]),
        }
    });
    let ci3 = cur_in;
    reg(&t, "input", move |l, a| {
        match a.first() {
            Some(Value::Str(p)) => {
                if let Ok(f) = std::fs::File::open(p.to_str_lossy()) {
                    *ci3.borrow_mut() = make_file(l, FileKind::File(f));
                }
            }
            Some(v @ Value::UserData(_)) => *ci3.borrow_mut() = v.clone(),
            _ => {}
        }
        Ok(vec![ci3.borrow().clone()])
    });
    let co3 = cur_out;
    reg(&t, "output", move |l, a| {
        match a.first() {
            Some(Value::Str(p)) => {
                if let Ok(f) = std::fs::File::create(p.to_str_lossy()) {
                    *co3.borrow_mut() = make_file(l, FileKind::File(f));
                }
            }
            Some(v @ Value::UserData(_)) => *co3.borrow_mut() = v.clone(),
            _ => {}
        }
        Ok(vec![co3.borrow().clone()])
    });
    reg(&t, "tmpfile", |l, _a| {
        let p = format!("/tmp/lua_tmp_{}_{}", std::process::id(), now_secs() as u64);
        match std::fs::OpenOptions::new()
            .read(true)
            .write(true)
            .create(true)
            .truncate(true)
            .open(&p)
        {
            Ok(f) => {
                let _ = std::fs::remove_file(&p);
                Ok(vec![make_file(l, FileKind::File(f))])
            }
            Err(e) => Ok(vec![Value::Nil, Value::str(&io_err_msg(&e))]),
        }
    });
    lua.set_global("io", Value::Table(t.clone()));
    lua.loaded.borrow_mut().set_str("io", Value::Table(t));
}

// ---------------- package / require ----------------

pub fn open_package(lua: &mut Lua) {
    let pkg = new_table();
    pkg.borrow_mut().set_str(
        "path",
        Value::str("./?.lua;/usr/local/share/luajit-2.1/?.lua;/usr/local/share/lua/5.1/?.lua;/usr/local/share/lua/5.1/?/init.lua"),
    );
    pkg.borrow_mut().set_str(
        "cpath",
        Value::str("./?.so;/usr/local/lib/lua/5.1/?.so;/usr/local/lib/lua/5.1/loadall.so"),
    );
    pkg.borrow_mut().set_str("config", Value::str("/\n;\n?\n!\n-\n"));
    pkg.borrow_mut()
        .set_str("loaded", Value::Table(lua.loaded.clone()));
    let preload = new_table();
    pkg.borrow_mut()
        .set_str("preload", Value::Table(preload.clone()));
    pkg.borrow_mut().set_str("loaders", Value::new_table());
    reg(&pkg, "loadlib", |_l, _a| {
        Ok(vec![Value::Nil, Value::str("dynamic libraries not enabled"), Value::str("absent")])
    });
    reg(&pkg, "seeall", |_l, _a| Ok(vec![]));
    reg(&pkg, "searchpath", |_l, a| {
        let name = String::from_utf8_lossy(&check_str(&a, 0, "searchpath")?).into_owned();
        let path = String::from_utf8_lossy(&check_str(&a, 1, "searchpath")?).into_owned();
        let n = name.replace('.', "/");
        let mut msg = String::new();
        for tmpl in path.split(';') {
            let f = tmpl.replace('?', &n);
            if std::fs::metadata(&f).map(|m| m.is_file()).unwrap_or(false) {
                return Ok(vec![Value::str(&f)]);
            }
            msg.push_str(&format!("\n\tno file '{}'", f));
        }
        Ok(vec![Value::Nil, Value::str(&msg)])
    });
    let pkg2 = pkg.clone();
    lua.set_global(
        "require",
        Lua::native("require", move |l, a| {
            let name = String::from_utf8_lossy(&check_str(&a, 0, "require")?).into_owned();
            let loaded = l.loaded.clone();
            let existing = loaded.borrow().get_str(&name);
            if !existing.is_nil() {
                return Ok(vec![existing]);
            }
            let pre = match pkg2.borrow().get_str("preload") {
                Value::Table(t) => t.borrow().get_str(&name),
                _ => Value::Nil,
            };
            let mut loader = Value::Nil;
            let mut filename = Value::str(":preload:");
            let mut msg = String::new();
            if !pre.is_nil() {
                loader = pre;
            } else {
                msg.push_str(&format!("\n\tno field package.preload['{}']", name));
                let path = match pkg2.borrow().get_str("path") {
                    Value::Str(s) => s.to_str_lossy(),
                    _ => String::new(),
                };
                let n = name.replace('.', "/");
                for tmpl in path.split(';') {
                    if tmpl.is_empty() {
                        continue;
                    }
                    let f = tmpl.replace('?', &n);
                    if std::fs::metadata(&f).map(|m| m.is_file()).unwrap_or(false) {
                        let src = std::fs::read(&f).map_err(|e| LuaError::rt(e.to_string()))?;
                        loader = l.load(&src, &format!("@{}", f)).map_err(|e| {
                            LuaError::rt(format!(
                                "error loading module '{}' from file '{}':\n\t{}",
                                name, f, e
                            ))
                        })?;
                        filename = Value::str(&f);
                        break;
                    }
                    msg.push_str(&format!("\n\tno file '{}'", f));
                }
                if loader.is_nil() {
                    let cpath = match pkg2.borrow().get_str("cpath") {
                        Value::Str(s) => s.to_str_lossy(),
                        _ => String::new(),
                    };
                    for tmpl in cpath.split(';') {
                        if tmpl.is_empty() {
                            continue;
                        }
                        let f = tmpl.replace('?', &n);
                        msg.push_str(&format!("\n\tno file '{}'", f));
                    }
                }
            }
            if loader.is_nil() {
                return Err(LuaError::rt(format!("module '{}' not found:{}", name, msg)));
            }
            loaded.borrow_mut().set_str(&name, Value::Bool(true));
            let r = l.call1(&loader, vec![Value::str(&name), filename]);
            let r = match r {
                Ok(v) => v,
                Err(e) => {
                    loaded.borrow_mut().set_str(&name, Value::Nil);
                    return Err(e);
                }
            };
            if !r.is_nil() {
                loaded.borrow_mut().set_str(&name, r);
            }
            let v = loaded.borrow().get_str(&name);
            Ok(vec![v])
        }),
    );
    lua.set_global("package", Value::Table(pkg.clone()));
    lua.loaded.borrow_mut().set_str("package", Value::Table(pkg));
    lua.loaded
        .borrow_mut()
        .set_str("_G", Value::Table(lua.globals.clone()));
}

pub fn open_misc(lua: &mut Lua) {
    // debug
    let d = new_table();
    reg(&d, "traceback", |l, a| {
        let msg = match a.first() {
            Some(Value::Str(s)) => format!("{}\n", s.to_str_lossy()),
            Some(Value::Nil) | None => String::new(),
            Some(v) => return Ok(vec![v.clone()]),
        };
        Ok(vec![Value::str(&format!("{}{}", msg, l.traceback()))])
    });
    reg(&d, "getinfo", |l, a| {
        let mut t = Table::new();
