pub fn open_package(lua: &mut Lua) {
    let pkg = new_table();
    pkg.borrow_mut().set_str(
        "path",
        Value::str("./?.lua;/usr/local/share/luajit-2.1/?.lua;/usr/local/share/lua/5.1/?.lua;/usr/local/share/lua/5.1/?/init.lua"),
    );
    pkg.borrow_mut().set_str(
        "cpath",
        Value::str("./?.so;/usr/local/lib/lua/5.1/?.so;/usr/local/lib/lua/5.1/loadall.so"),
    );
    pkg.borrow_mut().set_str("config", Value::str("/\n;\n?\n!\n-\n"));
    pkg.borrow_mut()
        .set_str("loaded", Value::Table(lua.loaded.clone()));
    let preload = new_table();
    pkg.borrow_mut()
        .set_str("preload", Value::Table(preload.clone()));
    pkg.borrow_mut().set_str("loaders", Value::new_table());
    reg(&pkg, "loadlib", |_l, _a| {
        Ok(vec![Value::Nil, Value::str("dynamic libraries not enabled"), Value::str("absent")])
    });
    reg(&pkg, "seeall", |_l, _a| Ok(vec![]));
    reg(&pkg, "searchpath", |_l, a| {
        let name = String::from_utf8_lossy(&check_str(&a, 0, "searchpath")?).into_owned();
        let path = String::from_utf8_lossy(&check_str(&a, 1, "searchpath")?).into_owned();
        let n = name.replace('.', "/");
        let mut msg = String::new();
        for tmpl in path.split(';') {
            let f = tmpl.replace('?', &n);
            if std::fs::metadata(&f).map(|m| m.is_file()).unwrap_or(false) {
                return Ok(vec![Value::str(&f)]);
            }
            msg.push_str(&format!("\n\tno file '{}'", f));
        }
        Ok(vec![Value::Nil, Value::str(&msg)])
    });
    let pkg2 = pkg.clone();
    lua.set_global(
        "require",
        Lua::native("require", move |l, a| {
            let name = String::from_utf8_lossy(&check_str(&a, 0, "require")?).into_owned();
            let loaded = l.loaded.clone();
            let existing = loaded.borrow().get_str(&name);
            if !existing.is_nil() {
                return Ok(vec![existing]);
            }
            let pre = match pkg2.borrow().get_str("preload") {
                Value::Table(t) => t.borrow().get_str(&name),
                _ => Value::Nil,
            };
            let mut loader = Value::Nil;
            let mut filename = Value::str(":preload:");
            let mut msg = String::new();
            if !pre.is_nil() {
                loader = pre;
            } else {
                msg.push_str(&format!("\n\tno field package.preload['{}']", name));
                let path = match pkg2.borrow().get_str("path") {
                    Value::Str(s) => s.to_str_lossy(),
                    _ => String::new(),
                };
                let n = name.replace('.', "/");
                for tmpl in path.split(';') {
                    if tmpl.is_empty() {
                        continue;
                    }
                    let f = tmpl.replace('?', &n);
                    if std::fs::metadata(&f).map(|m| m.is_file()).unwrap_or(false) {
                        let src = std::fs::read(&f).map_err(|e| LuaError::rt(e.to_string()))?;
                        loader = l.load(&src, &format!("@{}", f)).map_err(|e| {
                            LuaError::rt(format!(
                                "error loading module '{}' from file '{}':\n\t{}",
                                name, f, e
                            ))
                        })?;
                        filename = Value::str(&f);
                        break;
                    }
                    msg.push_str(&format!("\n\tno file '{}'", f));
                }
                if loader.is_nil() {
                    let cpath = match pkg2.borrow().get_str("cpath") {
                        Value::Str(s) => s.to_str_lossy(),
                        _ => String::new(),
                    };
                    for tmpl in cpath.split(';') {
                        if tmpl.is_empty() {
                            continue;
                        }
                        let f = tmpl.replace('?', &n);
                        msg.push_str(&format!("\n\tno file '{}'", f));
                    }
                }
            }
            if loader.is_nil() {
                return Err(LuaError::rt(format!("module '{}' not found:{}", name, msg)));
            }
            loaded.borrow_mut().set_str(&name, Value::Bool(true));
            let r = l.call1(&loader, vec![Value::str(&name), filename]);
            let r = match r {
                Ok(v) => v,
                Err(e) => {
                    loaded.borrow_mut().set_str(&name, Value::Nil);
                    return Err(e);
                }
            };
            if !r.is_nil() {
                loaded.borrow_mut().set_str(&name, r);
            }
            let v = loaded.borrow().get_str(&name);
            Ok(vec![v])
        }),
    );
    lua.set_global("package", Value::Table(pkg.clone()));
    lua.loaded.borrow_mut().set_str("package", Value::Table(pkg));
    lua.loaded
        .borrow_mut()
        .set_str("_G", Value::Table(lua.globals.clone()));
}

pub fn open_misc(lua: &mut Lua) {
