    let d = new_table();
    reg(&d, "traceback", |l, a| {
        let msg = match a.first() {
            Some(Value::Str(s)) => format!("{}\n", s.to_str_lossy()),
            Some(Value::Nil) | None => String::new(),
            Some(v) => return Ok(vec![v.clone()]),
        };
        Ok(vec![Value::str(&format!("{}{}", msg, l.traceback()))])
    });
    reg(&d, "getinfo", |l, a| {
        let mut t = Table::new();
        match a.first() {
            Some(Value::Func(super::value::Function::Lua(c))) => {
                t.set_str("source", Value::str(&c.proto.chunk));
                t.set_str("short_src", Value::str(&c.proto.chunk));
                t.set_str("linedefined", Value::Num(c.proto.line as f64));
                t.set_str("what", Value::str("Lua"));
            }
            Some(Value::Func(_)) => {
                t.set_str("source", Value::str("=[C]"));
                t.set_str("short_src", Value::str("[C]"));
                t.set_str("what", Value::str("C"));
            }
            Some(Value::Num(n)) => {
                let lvl = *n as usize;
                let idx = l.stack.len() as isize - 1 - lvl as isize;
                if idx < 0 {
                    return Ok(vec![Value::Nil]);
                }
                let ci = &l.stack[idx as usize];
                t.set_str("source", Value::str(&ci.chunk));
                t.set_str("short_src", Value::str(&ci.chunk));
                t.set_str("currentline", Value::Num(ci.line as f64));
                t.set_str("name", Value::str(&ci.name));
                t.set_str("what", Value::str(if ci.is_lua { "Lua" } else { "C" }));
            }
            _ => {}
        }
        Ok(vec![Value::table(t)])
    });
    reg(&d, "getmetatable", |l, a| {
        let v = arg(&a, 0);
        Ok(vec![match l.get_metatable(&v) {
            Some(m) => Value::Table(m),
            None => Value::Nil,
        }])
    });
    reg(&d, "setmetatable", |_l, a| {
        if let Value::Table(t) = arg(&a, 0) {
            t.borrow_mut().meta = match arg(&a, 1) {
                Value::Table(m) => Some(m),
                _ => None,
            };
        }
        Ok(vec![arg(&a, 0)])
    });
    for n in ["sethook", "gethook", "getlocal", "setlocal", "getupvalue", "setupvalue", "getregistry", "getfenv", "setfenv", "upvalueid", "upvaluejoin", "debug"] {
        reg(&d, n, |_l, _a| Ok(vec![]));
    }
    lua.set_global("debug", Value::Table(d.clone()));
    lua.loaded.borrow_mut().set_str("debug", Value::Table(d));

    // jit
    let j = new_table();
    j.borrow_mut().set_str("version", Value::str("LuaJIT 2.1.1736781742"));
    j.borrow_mut().set_str("version_num", Value::Num(20199.0));
    j.borrow_mut().set_str("os", Value::str("Linux"));
    j.borrow_mut().set_str("arch", Value::str("x64"));
    j.borrow_mut().set_str("opt", Value::new_table());
    for n in ["on", "off", "flush", "attach", "security"] {
        reg(&j, n, |_l, _a| Ok(vec![]));
    }
    reg(&j, "status", |_l, _a| Ok(vec![Value::Bool(true)]));
    lua.set_global("jit", Value::Table(j.clone()));
    lua.loaded.borrow_mut().set_str("jit", Value::Table(j));

    // coroutine (limited support)
    let c = new_table();
    super::coroutine::open(lua, &c);
    lua.set_global("coroutine", Value::Table(c.clone()));
    lua.loaded.borrow_mut().set_str("coroutine", Value::Table(c));

    // module (deprecated)
    reg(&lua.globals.clone(), "module", |_l, _a| Ok(vec![]));
}
