// Coroutines implemented with OS threads and strict hand-off.
use std::cell::RefCell;
use std::rc::Rc;
use std::sync::mpsc::{channel, Receiver, Sender};

use super::interp::{CallInfo, Lua};
use super::stdlib::{arg_err, reg};
use super::value::*;

struct SendBox<T>(T);
unsafe impl<T> Send for SendBox<T> {}

enum ToCo {
    Resume(Vec<Value>, usize),
}
enum FromCo {
    Yield(Vec<Value>),
    Done(Result<Vec<Value>, LuaError>),
}

#[derive(PartialEq, Clone, Copy)]
enum Status {
    Suspended,
    Running,
    Normal,
    Dead,
}

pub struct Coroutine {
    func: Option<Value>,
    status: Status,
    to_co: Option<Sender<SendBox<ToCo>>>,
    from_co: Option<Receiver<SendBox<FromCo>>>,
    saved_stack: Vec<CallInfo>,
    saved_depth: usize,
}

thread_local! {
    static CURRENT: RefCell<Vec<Value>> = const { RefCell::new(Vec::new()) };
}

// channels for the currently running coroutine (in its own thread)
struct CoCtx {
    to_parent: Sender<SendBox<FromCo>>,
    from_parent: Receiver<SendBox<ToCo>>,
    base: usize,
    co: Value,
}

thread_local! {
    static CTX: RefCell<Option<CoCtx>> = const { RefCell::new(None) };
}

fn get_co(v: &Value) -> Option<Rc<UserData>> {
    if let Value::UserData(u) = v {
        if u.data.borrow().is::<Coroutine>() {
            return Some(u.clone());
        }
    }
    None
}

fn resume(lua: &mut Lua, cov: &Value, args: Vec<Value>) -> Result<Vec<Value>, Value> {
    let u = match get_co(cov) {
        Some(u) => u,
        None => return Err(Value::str("bad argument #1 to 'resume' (coroutine expected)")),
    };
    let status = u.data.borrow().downcast_ref::<Coroutine>().unwrap().status;
    match status {
        Status::Dead => return Err(Value::str("cannot resume dead coroutine")),
        Status::Running | Status::Normal => {
            return Err(Value::str("cannot resume non-suspended coroutine"))
        }
        Status::Suspended => {}
    }
    // mark current as normal
    let parent = CURRENT.with(|c| c.borrow().last().cloned());
    if let Some(p) = &parent {
        if let Some(pu) = get_co(p) {
            pu.data.borrow_mut().downcast_mut::<Coroutine>().unwrap().status = Status::Normal;
        }
    }
    let base = lua.stack.len();
    let (func, saved, saved_depth) = {
        let mut d = u.data.borrow_mut();
        let co = d.downcast_mut::<Coroutine>().unwrap();
        co.status = Status::Running;
        (co.func.take(), std::mem::take(&mut co.saved_stack), co.saved_depth)
    };
    lua.stack.extend(saved);
    lua.depth += saved_depth;
    CURRENT.with(|c| c.borrow_mut().push(cov.clone()));
    if let Some(func) = func {
        // start thread
        let (to_co_tx, to_co_rx) = channel::<SendBox<ToCo>>();
        let (from_co_tx, from_co_rx) = channel::<SendBox<FromCo>>();
        let lp = SendBox(lua as *mut Lua);
        let fb = SendBox((func, cov.clone()));
        let builder = std::thread::Builder::new().stack_size(256 * 1024 * 1024);
        let _ = builder.spawn(move || {
            let lp = lp;
            let fb = fb;
            let (func, cov) = fb.0;
            let rx = to_co_rx;
            let tx = from_co_tx;
            let first = rx.recv();
            let (args, base) = match first {
                Ok(SendBox(ToCo::Resume(a, b))) => (a, b),
                Err(_) => return,
            };
            CTX.with(|c| {
                *c.borrow_mut() = Some(CoCtx {
                    to_parent: tx.clone(),
                    from_parent: rx,
                    base,
                    co: cov,
                })
            });
            let lua: &mut Lua = unsafe { &mut *lp.0 };
            let r = lua.call(&func, args);
            let _ = tx.send(SendBox(FromCo::Done(r)));
        });
        let mut d = u.data.borrow_mut();
        let co = d.downcast_mut::<Coroutine>().unwrap();
        co.to_co = Some(to_co_tx);
        co.from_co = Some(from_co_rx);
    }
    let (tx, rx) = {
        let mut d = u.data.borrow_mut();
        let co = d.downcast_mut::<Coroutine>().unwrap();
        (co.to_co.take().unwrap(), co.from_co.take().unwrap())
    };
    let _ = tx.send(SendBox(ToCo::Resume(args, base)));
