    type Ok = Value;
    type Error = SerdeError;
    fn serialize_element<T: Serialize + ?Sized>(&mut self, v: &T) -> Result<(), SerdeError> {
        let val = v.serialize(LuaSerializer)?;
        let n = self.t.arr.len() + 1;
        // keep positions even for nils
        let _ = self.t.set(Value::Num(n as f64), val.clone());
        if val.is_nil() {
            self.t.arr.push(Value::Nil);
        }
        Ok(())
    }
    fn end(self) -> Result<Value, SerdeError> {
        let mut t = self.t;
        while let Some(Value::Nil) = t.arr.last() {
