// ---------------- Deserializer ----------------

pub fn from_lua<'de, T: de::Deserialize<'de>>(v: Value) -> Result<T, SerdeError> {
    T::deserialize(LuaDeserializer(v))
}

pub struct LuaDeserializer(pub Value);

/// returns Some(len) if table is a non-empty sequence (keys 1..n only)
pub fn table_seq_len(t: &Table) -> Option<usize> {
    let n = t.len();
    let hn = t.hash_len_nonnil();
    let arr_nonnil = t.arr.iter().filter(|v| !v.is_nil()).count();
    if n == 0 {
        return None;
    }
    if arr_nonnil + hn == n {
        Some(n)
    } else {
        None
    }
}

impl<'de> de::Deserializer<'de> for LuaDeserializer {
    type Error = SerdeError;

    fn deserialize_any<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, SerdeError> {
        match self.0 {
            Value::Nil => visitor.visit_unit(),
            Value::Bool(b) => visitor.visit_bool(b),
            Value::Num(n) => {
                if n == n.trunc() && n.abs() < 9.2e18 {
                    if n >= 0.0 {
                        visitor.visit_u64(n as u64)
                    } else {
                        visitor.visit_i64(n as i64)
                    }
                } else {
                    visitor.visit_f64(n)
                }
            }
            Value::Str(s) => match std::str::from_utf8(s.as_bytes()) {
                Ok(st) => visitor.visit_str(st),
                Err(_) => visitor.visit_bytes(s.as_bytes()),
            },
            Value::Table(t) => {
                let is_seq = table_seq_len(&t.borrow());
                if let Some(n) = is_seq {
                    let items: Vec<Value> = (1..=n).map(|i| t.borrow().get_int(i)).collect();
                    visitor.visit_seq(SeqDe {
                        it: items.into_iter(),
                    })
                } else {
                    let pairs = t.borrow().iter_pairs();
                    visitor.visit_map(MapDe {
                        it: pairs.into_iter(),
                        val: None,
                    })
                }
            }
            Value::Func(_) => Err(SerdeError("unsupported value type `function`".into())),
            Value::UserData(_) => Err(SerdeError("unsupported value type `userdata`".into())),
        }
    }

    fn deserialize_option<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, SerdeError> {
        match self.0 {
            Value::Nil => visitor.visit_none(),
            v => visitor.visit_some(LuaDeserializer(v)),
        }
    }

    fn deserialize_seq<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, SerdeError> {
        match self.0 {
            Value::Table(t) => {
                let n = t.borrow().len();
                let items: Vec<Value> = (1..=n).map(|i| t.borrow().get_int(i)).collect();
                visitor.visit_seq(SeqDe {
                    it: items.into_iter(),
                })
            }
            v => LuaDeserializer(v).deserialize_any(visitor),
        }
    }

    fn deserialize_tuple<V: Visitor<'de>>(self, _len: usize, visitor: V) -> Result<V::Value, SerdeError> {
        self.deserialize_seq(visitor)
    }

    fn deserialize_tuple_struct<V: Visitor<'de>>(
        self,
        _name: &'static str,
        _len: usize,
        visitor: V,
    ) -> Result<V::Value, SerdeError> {
        self.deserialize_seq(visitor)
    }

    fn deserialize_map<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, SerdeError> {
        match self.0 {
            Value::Table(t) => {
                let pairs = t.borrow().iter_pairs();
                visitor.visit_map(MapDe {
                    it: pairs.into_iter(),
                    val: None,
                })
            }
            v => LuaDeserializer(v).deserialize_any(visitor),
        }
    }

    fn deserialize_struct<V: Visitor<'de>>(
        self,
        _name: &'static str,
        _fields: &'static [&'static str],
        visitor: V,
    ) -> Result<V::Value, SerdeError> {
        self.deserialize_map(visitor)
    }

    fn deserialize_enum<V: Visitor<'de>>(
        self,
        _name: &'static str,
        _variants: &'static [&'static str],
        visitor: V,
    ) -> Result<V::Value, SerdeError> {
        match self.0 {
            Value::Str(s) => {
                let st = s.to_str_lossy();
                visitor.visit_enum(st.into_deserializer())
            }
            Value::Table(t) => {
                let pairs = t.borrow().iter_pairs();
                if pairs.len() != 1 {
                    return Err(SerdeError(
                        "invalid value: map, expected map with a single key".into(),
                    ));
                }
                let (k, v) = pairs.into_iter().next().unwrap();
                let key = match k {
                    Value::Str(s) => s.to_str_lossy(),
                    _ => return Err(SerdeError("invalid enum key".into())),
                };
                visitor.visit_enum(EnumDe { key, val: v })
            }
            v => Err(SerdeError(format!(
                "invalid type: {}, expected enum",
                v.type_name()
            ))),
        }
    }

    fn deserialize_newtype_struct<V: Visitor<'de>>(
        self,
        _name: &'static str,
        visitor: V,
    ) -> Result<V::Value, SerdeError> {
        visitor.visit_newtype_struct(self)
    }

    fn deserialize_unit<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, SerdeError> {
        match self.0 {
            Value::Nil => visitor.visit_unit(),
            Value::Table(ref t) if t.borrow().iter_pairs().is_empty() => visitor.visit_unit(),
            v => LuaDeserializer(v).deserialize_any(visitor),
        }
    }

    serde::forward_to_deserialize_any! {
        bool i8 i16 i32 i64 i128 u8 u16 u32 u64 u128 f32 f64 char str string
        bytes byte_buf unit_struct identifier ignored_any
    }
}

struct SeqDe {
    it: std::vec::IntoIter<Value>,
}
impl<'de> SeqAccess<'de> for SeqDe {
    type Error = SerdeError;
    fn next_element_seed<T: DeserializeSeed<'de>>(&mut self, seed: T) -> Result<Option<T::Value>, SerdeError> {
        match self.it.next() {
            Some(v) => seed.deserialize(LuaDeserializer(v)).map(Some),
            None => Ok(None),
        }
    }
}

struct MapDe {
    it: std::vec::IntoIter<(Value, Value)>,
    val: Option<Value>,
}
impl<'de> MapAccess<'de> for MapDe {
    type Error = SerdeError;
    fn next_key_seed<K: DeserializeSeed<'de>>(&mut self, seed: K) -> Result<Option<K::Value>, SerdeError> {
        match self.it.next() {
            Some((k, v)) => {
                self.val = Some(v);
                let kd = match k {
                    Value::Num(n) if n == n.trunc() => LuaDeserializer(Value::Num(n)),
                    k => LuaDeserializer(k),
                };
                seed.deserialize(KeyDe(kd.0)).map(Some)
            }
            None => Ok(None),
        }
    }
    fn next_value_seed<V: DeserializeSeed<'de>>(&mut self, seed: V) -> Result<V::Value, SerdeError> {
        let v = self.val.take().unwrap_or(Value::Nil);
        seed.deserialize(LuaDeserializer(v))
    }
}

/// key deserializer: numbers can be deserialized as strings
struct KeyDe(Value);
impl<'de> de::Deserializer<'de> for KeyDe {
    type Error = SerdeError;
    fn deserialize_any<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, SerdeError> {
        LuaDeserializer(self.0).deserialize_any(visitor)
    }
    fn deserialize_string<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, SerdeError> {
        match self.0 {
            Value::Num(n) => visitor.visit_string(fmt_num(n)),
            v => LuaDeserializer(v).deserialize_any(visitor),
        }
    }
    fn deserialize_str<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, SerdeError> {
        self.deserialize_string(visitor)
    }
    fn deserialize_enum<V: Visitor<'de>>(
        self,
        name: &'static str,
        variants: &'static [&'static str],
        visitor: V,
    ) -> Result<V::Value, SerdeError> {
        LuaDeserializer(self.0).deserialize_enum(name, variants, visitor)
    }
    fn deserialize_option<V: Visitor<'de>>(self, visitor: V) -> Result<V::Value, SerdeError> {
        LuaDeserializer(self.0).deserialize_option(visitor)
    }
    fn deserialize_newtype_struct<V: Visitor<'de>>(
        self,
        _name: &'static str,
        visitor: V,
    ) -> Result<V::Value, SerdeError> {
        visitor.visit_newtype_struct(self)
    }
    serde::forward_to_deserialize_any! {
        bool i8 i16 i32 i64 i128 u8 u16 u32 u64 u128 f32 f64 char
        bytes byte_buf unit unit_struct seq tuple tuple_struct map struct identifier ignored_any
    }
}

struct EnumDe {
    key: String,
    val: Value,
}
impl<'de> de::EnumAccess<'de> for EnumDe {
    type Error = SerdeError;
    type Variant = VariantDe;
    fn variant_seed<V: DeserializeSeed<'de>>(self, seed: V) -> Result<(V::Value, VariantDe), SerdeError> {
        let k: de::value::StringDeserializer<SerdeError> = self.key.into_deserializer();
        let v = seed.deserialize(k)?;
        Ok((v, VariantDe(self.val)))
    }
}
struct VariantDe(Value);
impl<'de> de::VariantAccess<'de> for VariantDe {
    type Error = SerdeError;
    fn unit_variant(self) -> Result<(), SerdeError> {
        Ok(())
    }
    fn newtype_variant_seed<T: DeserializeSeed<'de>>(self, seed: T) -> Result<T::Value, SerdeError> {
        seed.deserialize(LuaDeserializer(self.0))
    }
    fn tuple_variant<V: Visitor<'de>>(self, _len: usize, visitor: V) -> Result<V::Value, SerdeError> {
        de::Deserializer::deserialize_seq(LuaDeserializer(self.0), visitor)
    }
    fn struct_variant<V: Visitor<'de>>(
        self,
        _fields: &'static [&'static str],
        visitor: V,
    ) -> Result<V::Value, SerdeError> {
        de::Deserializer::deserialize_map(LuaDeserializer(self.0), visitor)
    }
}
