// ---------------- Keys ----------------

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Key {
    pub name: String,
    pub ch: Option<char>,
    pub kind: KeyKind,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum KeyKind {
    Alphabet,
    Number,
    Special,
    Navigation,
    Function,
    Other,
    NotSupported,
}

impl Serialize for Key {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        s.serialize_str(&self.name)
    }
}

impl Key {
    fn new(name: &str, ch: Option<char>, kind: KeyKind) -> Key {
        Key {
            name: name.to_string(),
            ch,
            kind,
        }
    }

    pub fn not_supported() -> Key {
        Key::new("not-supported", None, KeyKind::NotSupported)
    }

    pub fn is_alphabet(&self) -> bool {
        self.kind == KeyKind::Alphabet
    }
    pub fn is_number(&self) -> bool {
        self.kind == KeyKind::Number
    }
    pub fn is_alphanumeric(&self) -> bool {
        self.is_alphabet() || self.is_number()
    }
    pub fn is_special_character(&self) -> bool {
        self.kind == KeyKind::Special
    }
    pub fn is_character(&self) -> bool {
        self.is_alphanumeric() || self.is_special_character()
    }
    pub fn is_navigation(&self) -> bool {
        self.kind == KeyKind::Navigation
    }
    pub fn is_function(&self) -> bool {
        self.kind == KeyKind::Function
    }

    pub fn to_char(&self) -> Option<char> {
        self.ch
    }

    pub fn from_char(c: char) -> Key {
        if c.is_ascii_alphabetic() {
            Key::new(&c.to_string(), Some(c), KeyKind::Alphabet)
        } else if c.is_ascii_digit() {
            Key::new(&c.to_string(), Some(c), KeyKind::Number)
        } else if c == ' ' {
            Key::new("space", Some(' '), KeyKind::Other)
        } else {
            Key::new(&c.to_string(), Some(c), KeyKind::Special)
        }
    }

