    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct ResolvedNode {
    pub absolute_path: String,
    pub extension: String,
    pub is_dir: bool,
    pub is_file: bool,
    pub is_readonly: bool,
    pub mime_essence: String,
    pub size: u64,
    pub human_size: String,
    pub created: Option<u128>,
    pub last_modified: Option<u128>,
    pub uid: u32,
    pub gid: u32,
}

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct Node {
    pub parent: String,
    pub relative_path: String,
    pub absolute_path: String,
    pub extension: String,
    pub is_dir: bool,
    pub is_file: bool,
    pub is_symlink: bool,
    pub is_broken: bool,
    pub is_readonly: bool,
    pub mime_essence: String,
    pub size: u64,
    pub human_size: String,
    pub permissions: Permissions,
    pub created: Option<u128>,
    pub last_modified: Option<u128>,
    pub uid: u32,
    pub gid: u32,
    pub canonical: Option<ResolvedNode>,
    pub symlink: Option<ResolvedNode>,
}

fn time_nanos(t: std::io::Result<std::time::SystemTime>) -> Option<u128> {
    t.ok()
        .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
        .map(|d| d.as_nanos())
}

pub fn extension_of(path: &Path) -> String {
    path.extension()
        .map(|e| e.to_string_lossy().to_string())
        .unwrap_or_default()
}

pub fn mime_for(path: &Path, is_dir: bool, executable: bool) -> String {
    if is_dir {
        return "inode/directory".into();
    }
    if let Some(ext) = path.extension() {
        let e = ext.to_string_lossy().to_lowercase();
        if let Ok(i) = crate::mime_table::MIME_TABLE.binary_search_by(|(k, _)| (*k).cmp(e.as_str())) {
            return crate::mime_table::MIME_TABLE[i].1.to_string();
        }
    }
    if executable {
        return "application/x-executable".into();
    }
    String::new()
}

pub fn human_size(size: u64) -> String {
    if size < 1000 {
        return format!("{} B", size);
    }
    let units = ["kB", "MB", "GB", "TB", "PB", "EB"];
    let mut v = size as f64;
    let mut i = 0;
    v /= 1000.0;
    while v >= 1000.0 && i < units.len() - 1 {
        v /= 1000.0;
        i += 1;
    }
    if v.fract() == 0.0 {
        format!("{:.0} {}", v, units[i])
    } else {
        format!("{:.2} {}", v, units[i])
    }
}

impl ResolvedNode {
    pub fn from_path(path: PathBuf) -> Self {
        let extension = extension_of(&path);
        let (is_dir, is_file, is_readonly, size, created, last_modified, uid, gid, mode) =
            match path.metadata() {
                Ok(m) => (
                    m.is_dir(),
                    m.is_file(),
                    m.permissions().readonly(),
                    m.len(),
                    time_nanos(m.created()),
                    time_nanos(m.modified()),
                    m.uid(),
                    m.gid(),
                    m.permissions().mode(),
                ),
                Err(_) => (false, false, false, 0, None, None, 0, 0, 0),
            };
        let mime_essence = mime_for(&path, is_dir, mode & 0o111 != 0);
        ResolvedNode {
            absolute_path: path.to_string_lossy().to_string(),
            extension,
            is_dir,
            is_file,
            is_readonly,
            mime_essence,
            size,
            human_size: human_size(size),
            created,
            last_modified,
            uid,
            gid,
        }
    }
}

impl Node {
    pub fn new(parent: String, relative_path: String) -> Self {
        let absolute_path = PathBuf::from(&parent)
            .join(&relative_path)
            .to_string_lossy()
            .to_string();
        let path = PathBuf::from(&absolute_path);
        let extension = extension_of(&path);
        let (is_broken, canonical) = match path.canonicalize() {
            Ok(p) => (false, Some(ResolvedNode::from_path(p))),
            Err(_) => (true, None),
        };
        let (is_symlink, is_dir, is_file, is_readonly, size, permissions, created, last_modified, uid, gid) =
            match path.symlink_metadata() {
                Ok(m) => (
                    m.file_type().is_symlink(),
                    m.is_dir(),
                    m.is_file(),
                    m.permissions().readonly(),
