    pub group_write: bool,
    pub group_execute: bool,
    pub other_read: bool,
    pub other_write: bool,
    pub other_execute: bool,
    pub sticky: bool,
    pub setgid: bool,
    pub setuid: bool,
}

impl Permissions {
    pub fn from_mode(m: u32) -> Self {
        Permissions {
            user_read: m & 0o400 != 0,
            user_write: m & 0o200 != 0,
            user_execute: m & 0o100 != 0,
            group_read: m & 0o040 != 0,
            group_write: m & 0o020 != 0,
            group_execute: m & 0o010 != 0,
            other_read: m & 0o004 != 0,
            other_write: m & 0o002 != 0,
            other_execute: m & 0o001 != 0,
            sticky: m & 0o1000 != 0,
            setgid: m & 0o2000 != 0,
            setuid: m & 0o4000 != 0,
        }
    }

    pub fn rwx(&self) -> String {
        let mut s = String::with_capacity(9);
        s.push(if self.user_read { 'r' } else { '-' });
        s.push(if self.user_write { 'w' } else { '-' });
        s.push(match (self.user_execute, self.setuid) {
            (true, true) => 's',
            (false, true) => 'S',
            (true, false) => 'x',
            (false, false) => '-',
        });
        s.push(if self.group_read { 'r' } else { '-' });
        s.push(if self.group_write { 'w' } else { '-' });
        s.push(match (self.group_execute, self.setgid) {
            (true, true) => 's',
            (false, true) => 'S',
            (true, false) => 'x',
            (false, false) => '-',
        });
        s.push(if self.other_read { 'r' } else { '-' });
        s.push(if self.other_write { 'w' } else { '-' });
        s.push(match (self.other_execute, self.sticky) {
            (true, true) => 't',
            (false, true) => 'T',
            (true, false) => 'x',
            (false, false) => '-',
        });
        s
    }

    pub fn octal(&self) -> [u8; 4] {
        let b = |x: bool, v: u8| if x { v } else { 0 };
        [
            b(self.setuid, 4) + b(self.setgid, 2) + b(self.sticky, 1),
            b(self.user_read, 4) + b(self.user_write, 2) + b(self.user_execute, 1),
            b(self.group_read, 4) + b(self.group_write, 2) + b(self.group_execute, 1),
            b(self.other_read, 4) + b(self.other_write, 2) + b(self.other_execute, 1),
