// Readline-like input buffer (similar semantics to tui-input)
use serde::{Deserialize, Serialize};

use crate::msg::InputOperation;

#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct Input {
    pub value: String,
    pub cursor: usize,
}

impl Input {
    pub fn new(value: String) -> Self {
        let cursor = value.chars().count();
        Input { value, cursor }
    }

    pub fn value(&self) -> &str {
        &self.value
    }

    pub fn cursor(&self) -> usize {
        self.cursor
    }

    pub fn visual_cursor(&self) -> usize {
        use unicode_width::UnicodeWidthChar;
        self.value
            .chars()
            .take(self.cursor)
            .map(|c| c.width().unwrap_or(0))
            .sum()
    }

    fn byte_index(&self, char_idx: usize) -> usize {
        self.value
            .char_indices()
            .nth(char_idx)
            .map(|(i, _)| i)
            .unwrap_or(self.value.len())
    }

    pub fn handle(&mut self, op: &InputOperation) {
        use InputOperation::*;
        let len = self.value.chars().count();
        match op {
            SetCursor(pos) => {
                self.cursor = (*pos).min(len);
            }
            InsertCharacter(c) => {
                if self.cursor >= len {
                    self.value.push(*c);
                } else {
                    let bi = self.byte_index(self.cursor);
                    self.value.insert(bi, *c);
                }
                self.cursor += 1;
            }
            GoToPreviousCharacter => {
                if self.cursor > 0 {
                    self.cursor -= 1;
                }
            }
            GoToNextCharacter => {
                if self.cursor < len {
                    self.cursor += 1;
                }
            }
            GoToPreviousWord => {
                if self.cursor == 0 {
                    return;
