                let chars: Vec<char> = self.value.chars().collect();
                let mut i = self.cursor;
                // skip non-word (whitespace) backward then word
                while i > 0 && !chars[i - 1].is_alphanumeric() {
                    i -= 1;
                }
                while i > 0 && chars[i - 1].is_alphanumeric() {
                    i -= 1;
                }
                self.cursor = i;
            }
            GoToNextWord => {
                if self.cursor >= len {
                    return;
                }
                let chars: Vec<char> = self.value.chars().collect();
                let mut i = self.cursor;
                while i < len && chars[i].is_alphanumeric() {
                    i += 1;
                }
                while i < len && !chars[i].is_alphanumeric() {
                    i += 1;
                }
                self.cursor = i;
            }
            GoToStart => self.cursor = 0,
            GoToEnd => self.cursor = len,
            DeletePreviousCharacter => {
                if self.cursor == 0 {
                    return;
                }
                let bi = self.byte_index(self.cursor - 1);
                self.value.remove(bi);
                self.cursor -= 1;
            }
            DeleteNextCharacter => {
                if self.cursor >= len {
                    return;
                }
                let bi = self.byte_index(self.cursor);
                self.value.remove(bi);
            }
            DeletePreviousWord => {
                if self.cursor == 0 {
                    return;
                }
                let chars: Vec<char> = self.value.chars().collect();
                let mut i = self.cursor;
                while i > 0 && !chars[i - 1].is_alphanumeric() {
                    i -= 1;
                }
                while i > 0 && chars[i - 1].is_alphanumeric() {
                    i -= 1;
                }
                let new: String = chars[..i].iter().chain(chars[self.cursor..].iter()).collect();
                self.value = new;
                self.cursor = i;
            }
            DeleteNextWord => {
                if self.cursor >= len {
                    return;
                }
                let chars: Vec<char> = self.value.chars().collect();
                let mut i = self.cursor;
                while i < len && !chars[i].is_alphanumeric() {
                    i += 1;
                }
                while i < len && chars[i].is_alphanumeric() {
                    i += 1;
                }
                let new: String = chars[..self.cursor].iter().chain(chars[i..].iter()).collect();
                self.value = new;
            }
            DeleteLine => {
                self.value.clear();
                self.cursor = 0;
            }
            DeleteTillEnd => {
                let bi = self.byte_index(self.cursor);
                self.value.truncate(bi);
            }
        }
    }
}
