use indexmap::IndexSet;
use rayon::prelude::*;
use serde::{Deserialize, Serialize};
use std::cmp::Ordering;
use std::path::Path;

use crate::config::*;
use crate::node::Node;

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct NodeSearcher {
    pub pattern: String,
    #[serde(default)]
    pub recoverable_focus: Option<String>,
    #[serde(default)]
    pub algorithm: SearchAlgorithm,
    #[serde(default)]
    pub unordered: bool,
    #[serde(default)]
    pub exact_mode: bool,
    #[serde(default)]
    pub rank_criteria: Option<Vec<RankCriteria>>,
}

#[derive(Debug, Clone, Default, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct ExplorerConfig {
    #[serde(default)]
    pub filters: IndexSet<NodeFilterApplicable>,
    #[serde(default)]
    pub sorters: IndexSet<NodeSorterApplicable>,
    #[serde(default)]
    pub searcher: Option<NodeSearcher>,
}

pub fn natord_cmp(a: &str, b: &str, ignore_case: bool) -> Ordering {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut i = 0;
    let mut j = 0;
    let dig = |c: char| c.to_digit(10);
    loop {
        // skip whitespace
        while i < a.len() && a[i].is_whitespace() {
            i += 1;
        }
        while j < b.len() && b[j].is_whitespace() {
            j += 1;
        }
        match (a.get(i), b.get(j)) {
            (None, None) => return Ordering::Equal,
            (None, _) => return Ordering::Less,
            (_, None) => return Ordering::Greater,
            (Some(&ca), Some(&cb)) => {
                if dig(ca).is_some() && dig(cb).is_some() {
                    let ord = if ca == '0' || cb == '0' {
                        // compare left aligned
                        loop {
                            match (a.get(i).and_then(|c| dig(*c)), b.get(j).and_then(|c| dig(*c))) {
                                (None, None) => break Ordering::Equal,
                                (None, _) => break Ordering::Less,
                                (_, None) => break Ordering::Greater,
                                (Some(x), Some(y)) => match x.cmp(&y) {
                                    Ordering::Equal => {
                                        i += 1;
                                        j += 1;
                                    }
                                    o => break o,
                                },
                            }
                        }
                    } else {
                        let mut bias = Ordering::Equal;
                        loop {
                            match (a.get(i).and_then(|c| dig(*c)), b.get(j).and_then(|c| dig(*c))) {
                                (None, None) => break bias,
                                (None, _) => break Ordering::Less,
                                (_, None) => break Ordering::Greater,
                                (Some(x), Some(y)) => {
                                    if bias == Ordering::Equal {
                                        bias = x.cmp(&y);
                                    }
                                    i += 1;
                                    j += 1;
                                }
                            }
                        }
                    };
                    if ord != Ordering::Equal {
                        return ord;
                    }
                } else {
                    let ord = if ignore_case {
                        ca.to_lowercase().cmp(cb.to_lowercase())
                    } else {
                        ca.cmp(&cb)
                    };
                    match ord {
                        Ordering::Equal => {
                            i += 1;
                            j += 1;
                        }
                        o => return o,
                    }
                }
            }
        }
    }
}

fn opt_cmp<T: Ord>(a: Option<T>, b: Option<T>) -> Ordering {
    a.cmp(&b)
}

impl NodeSorterApplicable {
    pub fn apply(&self, a: &Node, b: &Node) -> Ordering {
        use NodeSorter::*;
        let ca = a.canonical.as_ref();
        let cb = b.canonical.as_ref();
        let sa = a.symlink.as_ref();
        let sb = b.symlink.as_ref();
        let ord = match self.sorter {
            ByRelativePath => natord_cmp(&a.relative_path, &b.relative_path, false),
            ByIRelativePath => natord_cmp(&a.relative_path, &b.relative_path, true),
            ByExtension => a.extension.cmp(&b.extension),
            ByIsDir => a.is_dir.cmp(&b.is_dir),
            ByIsFile => a.is_file.cmp(&b.is_file),
            ByIsSymlink => a.is_symlink.cmp(&b.is_symlink),
            ByIsBroken => a.is_broken.cmp(&b.is_broken),
            ByIsReadonly => a.is_readonly.cmp(&b.is_readonly),
            ByMimeEssence => a.mime_essence.cmp(&b.mime_essence),
            BySize => a.size.cmp(&b.size),
            ByCreated => a.created.cmp(&b.created),
            ByLastModified => a.last_modified.cmp(&b.last_modified),
            ByCanonicalAbsolutePath => match (ca, cb) {
                (Some(x), Some(y)) => natord_cmp(&x.absolute_path, &y.absolute_path, false),
                (x, y) => opt_cmp(x.map(|_| ()), y.map(|_| ())),
            },
            ByICanonicalAbsolutePath => match (ca, cb) {
                (Some(x), Some(y)) => natord_cmp(&x.absolute_path, &y.absolute_path, true),
                (x, y) => opt_cmp(x.map(|_| ()), y.map(|_| ())),
            },
            ByCanonicalExtension => opt_cmp(ca.map(|x| &x.extension), cb.map(|x| &x.extension)),
            ByCanonicalIsDir => opt_cmp(ca.map(|x| x.is_dir), cb.map(|x| x.is_dir)),
            ByCanonicalIsFile => opt_cmp(ca.map(|x| x.is_file), cb.map(|x| x.is_file)),
            ByCanonicalIsReadonly => opt_cmp(ca.map(|x| x.is_readonly), cb.map(|x| x.is_readonly)),
            ByCanonicalMimeEssence => opt_cmp(ca.map(|x| &x.mime_essence), cb.map(|x| &x.mime_essence)),
            ByCanonicalSize => opt_cmp(ca.map(|x| x.size), cb.map(|x| x.size)),
            ByCanonicalCreated => opt_cmp(ca.map(|x| x.created), cb.map(|x| x.created)),
            ByCanonicalLastModified => opt_cmp(ca.map(|x| x.last_modified), cb.map(|x| x.last_modified)),
            BySymlinkAbsolutePath => match (sa, sb) {
                (Some(x), Some(y)) => natord_cmp(&x.absolute_path, &y.absolute_path, false),
                (x, y) => opt_cmp(x.map(|_| ()), y.map(|_| ())),
            },
            ByISymlinkAbsolutePath => match (sa, sb) {
                (Some(x), Some(y)) => natord_cmp(&x.absolute_path, &y.absolute_path, true),
                (x, y) => opt_cmp(x.map(|_| ()), y.map(|_| ())),
            },
            BySymlinkExtension => opt_cmp(sa.map(|x| &x.extension), sb.map(|x| &x.extension)),
            BySymlinkIsDir => opt_cmp(sa.map(|x| x.is_dir), sb.map(|x| x.is_dir)),
            BySymlinkIsFile => opt_cmp(sa.map(|x| x.is_file), sb.map(|x| x.is_file)),
            BySymlinkIsReadonly => opt_cmp(sa.map(|x| x.is_readonly), sb.map(|x| x.is_readonly)),
            BySymlinkMimeEssence => opt_cmp(sa.map(|x| &x.mime_essence), sb.map(|x| &x.mime_essence)),
            BySymlinkSize => opt_cmp(sa.map(|x| x.size), sb.map(|x| x.size)),
            BySymlinkCreated => opt_cmp(sa.map(|x| x.created), sb.map(|x| x.created)),
            BySymlinkLastModified => opt_cmp(sa.map(|x| x.last_modified), sb.map(|x| x.last_modified)),
        };
        if self.reverse {
            ord.reverse()
        } else {
            ord
        }
    }
}

fn regex_match(pat: &str, s: &str) -> Option<bool> {
    regex::Regex::new(pat).ok().map(|r| r.is_match(s))
}

impl NodeFilterApplicable {
    pub fn apply(&self, node: &Node) -> bool {
        use NodeFilter::*;
        let input = &self.input;
        let rel = &node.relative_path;
        let abs = &node.absolute_path;
        let il = input.to_lowercase();
        match self.filter {
            RelativePathIs => rel == input,
            RelativePathIsNot => rel != input,
            IRelativePathIs => rel.to_lowercase() == il,
            IRelativePathIsNot => rel.to_lowercase() != il,
            RelativePathDoesStartWith => rel.starts_with(input.as_str()),
            RelativePathDoesNotStartWith => !rel.starts_with(input.as_str()),
            IRelativePathDoesStartWith => rel.to_lowercase().starts_with(&il),
            IRelativePathDoesNotStartWith => !rel.to_lowercase().starts_with(&il),
            RelativePathDoesContain => rel.contains(input.as_str()),
            RelativePathDoesNotContain => !rel.contains(input.as_str()),
            IRelativePathDoesContain => rel.to_lowercase().contains(&il),
            IRelativePathDoesNotContain => !rel.to_lowercase().contains(&il),
            RelativePathDoesEndWith => rel.ends_with(input.as_str()),
            RelativePathDoesNotEndWith => !rel.ends_with(input.as_str()),
            IRelativePathDoesEndWith => rel.to_lowercase().ends_with(&il),
            IRelativePathDoesNotEndWith => !rel.to_lowercase().ends_with(&il),
            RelativePathDoesMatchRegex => regex_match(input, rel).unwrap_or(false),
            RelativePathDoesNotMatchRegex => regex_match(input, rel).map(|b| !b).unwrap_or(false),
            IRelativePathDoesMatchRegex => regex_match(&il, &rel.to_lowercase()).unwrap_or(false),
            IRelativePathDoesNotMatchRegex => regex_match(&il, &rel.to_lowercase())
                .map(|b| !b)
                .unwrap_or(false),
            AbsolutePathIs => abs == input,
            AbsolutePathIsNot => abs != input,
            IAbsolutePathIs => abs.to_lowercase() == il,
            IAbsolutePathIsNot => abs.to_lowercase() != il,
            AbsolutePathDoesStartWith => abs.starts_with(input.as_str()),
            AbsolutePathDoesNotStartWith => !abs.starts_with(input.as_str()),
            IAbsolutePathDoesStartWith => abs.to_lowercase().starts_with(&il),
            IAbsolutePathDoesNotStartWith => !abs.to_lowercase().starts_with(&il),
            AbsolutePathDoesContain => abs.contains(input.as_str()),
            AbsolutePathDoesNotContain => !abs.contains(input.as_str()),
            IAbsolutePathDoesContain => abs.to_lowercase().contains(&il),
            IAbsolutePathDoesNotContain => !abs.to_lowercase().contains(&il),
            AbsolutePathDoesEndWith => abs.ends_with(input.as_str()),
            AbsolutePathDoesNotEndWith => !abs.ends_with(input.as_str()),
            IAbsolutePathDoesEndWith => abs.to_lowercase().ends_with(&il),
