pub fn natord_cmp(a: &str, b: &str, ignore_case: bool) -> Ordering {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut i = 0;
    let mut j = 0;
    let dig = |c: char| c.to_digit(10);
    loop {
        // skip whitespace
        while i < a.len() && a[i].is_whitespace() {
            i += 1;
        }
        while j < b.len() && b[j].is_whitespace() {
            j += 1;
        }
        match (a.get(i), b.get(j)) {
            (None, None) => return Ordering::Equal,
            (None, _) => return Ordering::Less,
            (_, None) => return Ordering::Greater,
            (Some(&ca), Some(&cb)) => {
                if dig(ca).is_some() && dig(cb).is_some() {
                    let ord = if ca == '0' || cb == '0' {
                        // compare left aligned
                        loop {
                            match (a.get(i).and_then(|c| dig(*c)), b.get(j).and_then(|c| dig(*c))) {
                                (None, None) => break Ordering::Equal,
                                (None, _) => break Ordering::Less,
                                (_, None) => break Ordering::Greater,
                                (Some(x), Some(y)) => match x.cmp(&y) {
                                    Ordering::Equal => {
                                        i += 1;
                                        j += 1;
                                    }
                                    o => break o,
                                },
                            }
                        }
                    } else {
                        let mut bias = Ordering::Equal;
                        loop {
                            match (a.get(i).and_then(|c| dig(*c)), b.get(j).and_then(|c| dig(*c))) {
                                (None, None) => break bias,
                                (None, _) => break Ordering::Less,
                                (_, None) => break Ordering::Greater,
                                (Some(x), Some(y)) => {
                                    if bias == Ordering::Equal {
                                        bias = x.cmp(&y);
                                    }
                                    i += 1;
                                    j += 1;
                                }
                            }
                        }
                    };
                    if ord != Ordering::Equal {
                        return ord;
                    }
                } else {
                    let ord = if ignore_case {
                        ca.to_lowercase().cmp(cb.to_lowercase())
                    } else {
                        ca.cmp(&cb)
                    };
                    match ord {
                        Ordering::Equal => {
                            i += 1;
                            j += 1;
                        }
                        o => return o,
                    }
                }
            }
        }
    }
}

fn opt_cmp<T: Ord>(a: Option<T>, b: Option<T>) -> Ordering {
    a.cmp(&b)
}

impl NodeSorterApplicable {
    pub fn apply(&self, a: &Node, b: &Node) -> Ordering {
        use NodeSorter::*;
        let ca = a.canonical.as_ref();
        let cb = b.canonical.as_ref();
        let sa = a.symlink.as_ref();
        let sb = b.symlink.as_ref();
        let ord = match self.sorter {
            ByRelativePath => natord_cmp(&a.relative_path, &b.relative_path, false),
            ByIRelativePath => natord_cmp(&a.relative_path, &b.relative_path, true),
            ByExtension => a.extension.cmp(&b.extension),
            ByIsDir => a.is_dir.cmp(&b.is_dir),
            ByIsFile => a.is_file.cmp(&b.is_file),
            ByIsSymlink => a.is_symlink.cmp(&b.is_symlink),
            ByIsBroken => a.is_broken.cmp(&b.is_broken),
            ByIsReadonly => a.is_readonly.cmp(&b.is_readonly),
            ByMimeEssence => a.mime_essence.cmp(&b.mime_essence),
            BySize => a.size.cmp(&b.size),
            ByCreated => a.created.cmp(&b.created),
            ByLastModified => a.last_modified.cmp(&b.last_modified),
            ByCanonicalAbsolutePath => match (ca, cb) {
                (Some(x), Some(y)) => natord_cmp(&x.absolute_path, &y.absolute_path, false),
                (x, y) => opt_cmp(x.map(|_| ()), y.map(|_| ())),
            },
            ByICanonicalAbsolutePath => match (ca, cb) {
                (Some(x), Some(y)) => natord_cmp(&x.absolute_path, &y.absolute_path, true),
                (x, y) => opt_cmp(x.map(|_| ()), y.map(|_| ())),
            },
            ByCanonicalExtension => opt_cmp(ca.map(|x| &x.extension), cb.map(|x| &x.extension)),
            ByCanonicalIsDir => opt_cmp(ca.map(|x| x.is_dir), cb.map(|x| x.is_dir)),
            ByCanonicalIsFile => opt_cmp(ca.map(|x| x.is_file), cb.map(|x| x.is_file)),
            ByCanonicalIsReadonly => opt_cmp(ca.map(|x| x.is_readonly), cb.map(|x| x.is_readonly)),
            ByCanonicalMimeEssence => opt_cmp(ca.map(|x| &x.mime_essence), cb.map(|x| &x.mime_essence)),
            ByCanonicalSize => opt_cmp(ca.map(|x| x.size), cb.map(|x| x.size)),
            ByCanonicalCreated => opt_cmp(ca.map(|x| x.created), cb.map(|x| x.created)),
            ByCanonicalLastModified => opt_cmp(ca.map(|x| x.last_modified), cb.map(|x| x.last_modified)),
            BySymlinkAbsolutePath => match (sa, sb) {
                (Some(x), Some(y)) => natord_cmp(&x.absolute_path, &y.absolute_path, false),
                (x, y) => opt_cmp(x.map(|_| ()), y.map(|_| ())),
            },
            ByISymlinkAbsolutePath => match (sa, sb) {
                (Some(x), Some(y)) => natord_cmp(&x.absolute_path, &y.absolute_path, true),
                (x, y) => opt_cmp(x.map(|_| ()), y.map(|_| ())),
            },
            BySymlinkExtension => opt_cmp(sa.map(|x| &x.extension), sb.map(|x| &x.extension)),
            BySymlinkIsDir => opt_cmp(sa.map(|x| x.is_dir), sb.map(|x| x.is_dir)),
            BySymlinkIsFile => opt_cmp(sa.map(|x| x.is_file), sb.map(|x| x.is_file)),
            BySymlinkIsReadonly => opt_cmp(sa.map(|x| x.is_readonly), sb.map(|x| x.is_readonly)),
            BySymlinkMimeEssence => opt_cmp(sa.map(|x| &x.mime_essence), sb.map(|x| &x.mime_essence)),
            BySymlinkSize => opt_cmp(sa.map(|x| x.size), sb.map(|x| x.size)),
            BySymlinkCreated => opt_cmp(sa.map(|x| x.created), sb.map(|x| x.created)),
            BySymlinkLastModified => opt_cmp(sa.map(|x| x.last_modified), sb.map(|x| x.last_modified)),
        };
        if self.reverse {
            ord.reverse()
        } else {
            ord
        }
    }
}

