#[derive(Debug, Clone, Default, Serialize)]
pub struct History {
    pub loc: usize,
    pub paths: Vec<String>,
}

impl History {
    fn loc_exists(&self) -> bool {
        self.paths.len() > self.loc
    }

    pub fn peek(&self) -> Option<&String> {
        self.paths.get(self.loc)
    }

    pub fn push(&mut self, path: String) {
        if self.peek() != Some(&path) {
            self.paths.truncate(self.loc + 1);
            self.paths.push(path);
            self.loc = self.paths.len().max(1) - 1;
        }
    }

    pub fn visit_last(&mut self) {
        self.loc = self.loc.max(1) - 1;
    }

    pub fn visit_next(&mut self) {
        if self.loc + 1 < self.paths.len() {
            self.loc += 1;
        }
    }

    fn norm(p: &str) -> String {
        if p.len() > 1 {
            p.trim_end_matches('/').to_string()
        } else {
            p.to_string()
        }
    }

    fn is_leaf(&self, i: usize) -> bool {
        let p = Self::norm(&self.paths[i]);
        !self.paths.iter().any(|q| {
            let q = Self::norm(q);
            q != p && Path::new(&q).starts_with(&p)
        })
    }

    pub fn deep_branch(&self, pwd: &str, forward: bool) -> Option<String> {
        // collect leaves in order of first appearance
        let mut leaves: Vec<String> = vec![];
        for i in 0..self.paths.len() {
            if self.paths[i].ends_with('/') && self.is_leaf(i) {
                let p = Self::norm(&self.paths[i]);
                if !leaves.contains(&p) {
                    leaves.push(p);
                }
            }
        }
        let pos = leaves.iter().position(|p| p == pwd)?;
        if forward {
            leaves.get(pos + 1).cloned()
        } else if pos > 0 {
            leaves.get(pos - 1).cloned()
        } else {
            None
        }
    }
}

#[derive(Debug, Clone, Default, Serialize)]
pub struct InputBuffer {
    pub buffer: Option<Input>,
    pub prompt: String,
}

#[derive(Debug, Clone, Default, Serialize)]
pub struct Pipe {
    pub path: String,
    pub msg_in: String,
    pub selection_out: String,
    pub result_out: String,
    pub directory_nodes_out: String,
    pub global_help_menu_out: String,
    pub logs_out: String,
    pub history_out: String,
}

impl Pipe {
    pub fn from_session_path(path: &str) -> Self {
        let p = PathBuf::from(path).join("pipe");
        let j = |n: &str| p.join(n).to_string_lossy().to_string();
        Pipe {
            path: p.to_string_lossy().to_string(),
            msg_in: j("msg_in"),
            selection_out: j("selection_out"),
            result_out: j("result_out"),
            directory_nodes_out: j("directory_nodes_out"),
            global_help_menu_out: j("global_help_menu_out"),
            logs_out: j("logs_out"),
            history_out: j("history_out"),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Serialize)]
pub enum MsgOut {
    ExplorePwdAsync,
