    PrintPwdAndQuit,
    PrintFocusPathAndQuit,
    PrintSelectionAndQuit,
    PrintResultAndQuit,
    PrintAppStateAndQuit,
    Debug(String),
    Call(Command),
    Call0(Command),
    CallSilently(Command),
    CallSilently0(Command),
    CallLua(String),
    CallLuaSilently(String),
