#[derive(Debug, Clone, Serialize)]
pub struct App {
    pub bin: String,
    pub version: String,
    pub config: Config,
    pub hooks: Hooks,
    pub vroot: Option<String>,
    pub initial_vroot: Option<String>,
    pub pwd: String,
    pub initial_pwd: String,
    pub directory_buffer: Option<DirectoryBuffer>,
    pub last_focus: IndexMap<String, Option<String>>,
    pub selection: Vec<Node>,
    pub msg_out: VecDeque<MsgOut>,
    pub mode: Mode,
    pub layout: Layout,
    pub input: InputBuffer,
    pub pid: u32,
    pub session_path: String,
    pub pipe: Pipe,
    pub explorer_config: ExplorerConfig,
    pub logs: Vec<Log>,
    pub logs_hidden: bool,
    pub history: History,
    pub last_modes: Vec<Mode>,
    pub hostname: String,
    #[serde(skip)]
    pub table_height: usize,
    #[serde(skip)]
    pub delimiter: u8,
}

pub fn hostname() -> String {
    let mut buf = vec![0u8; 256];
    unsafe {
        libc::gethostname(buf.as_mut_ptr() as *mut libc::c_char, buf.len());
    }
    let n = buf.iter().position(|&b| b == 0).unwrap_or(buf.len());
    String::from_utf8_lossy(&buf[..n]).into_owned()
}

impl App {
    pub fn new(
        bin: String,
        pwd: String,
        config: Config,
        hooks: Hooks,
        vroot: Option<String>,
        startup_errors: Vec<String>,
    ) -> App {
        let pid = std::process::id();
        let runtime = std::env::var("XDG_RUNTIME_DIR")
            .ok()
            .filter(|s| !s.is_empty())
            .unwrap_or_else(|| "/tmp".to_string());
        let session_path = PathBuf::from(runtime)
            .join("xplr")
            .join("session")
            .join(pid.to_string())
            .to_string_lossy()
            .to_string();
        let pipe = Pipe::from_session_path(&session_path);

        let mut explorer_config = ExplorerConfig::default();
        if !config.general.show_hidden {
            explorer_config.filters.insert(NodeFilterApplicable {
                filter: NodeFilter::RelativePathDoesNotStartWith,
                input: ".".into(),
            });
        }
        if let Some(sorters) = &config.general.initial_sorting {
            explorer_config.sorters = sorters.clone();
        }

        let mut app = App {
            bin,
            version: VERSION.to_string(),
            config: config.clone(),
            hooks,
            vroot: vroot.clone(),
            initial_vroot: vroot,
            pwd: pwd.clone(),
            initial_pwd: pwd,
            directory_buffer: None,
            last_focus: IndexMap::new(),
            selection: vec![],
            msg_out: VecDeque::new(),
            mode: Mode::default(),
            layout: Layout::default(),
            input: InputBuffer {
                buffer: None,
                prompt: config.general.prompt.format.clone().unwrap_or_default(),
            },
            pid,
            session_path,
            pipe,
            explorer_config,
            logs: vec![],
            logs_hidden: false,
            history: History::default(),
            last_modes: vec![],
            hostname: hostname(),
            table_height: 0,
            delimiter: b'\n',
        };

        let initial_mode = config
            .general
            .initial_mode
            .clone()
            .unwrap_or_else(|| "default".into());
        let mode = config
            .modes
            .custom
            .get(&initial_mode)
            .or_else(|| config.modes.builtin.get(&initial_mode))
            .or_else(|| config.modes.builtin.get("default"))
            .cloned()
            .unwrap_or_default();
        app.mode = app.sanitize_mode(mode);
        if let Some(p) = &app.mode.prompt {
            app.input.prompt = p.clone();
        }

        let initial_layout = config
            .general
            .initial_layout
            .clone()
            .unwrap_or_else(|| "default".into());
        app.layout = config
            .layouts
            .custom
            .get(&initial_layout)
            .or_else(|| config.layouts.builtin.get(&initial_layout))
            .or_else(|| config.layouts.builtin.get("default"))
            .cloned()
            .unwrap_or_default();

        for e in startup_errors {
            app.log_error(e);
        }
        app
    }

    pub fn sanitize_mode(&self, mut mode: Mode) -> Mode {
        let read_only = self.config.general.read_only;
        mode.key_bindings = mode
            .key_bindings
            .clone()
            .extend(self.config.general.global_key_bindings.clone())
            .sanitized(read_only);
        mode
    }

    // ---------------- accessors ----------------
    pub fn focused_node(&self) -> Option<&Node> {
        self.directory_buffer.as_ref().and_then(|d| d.focused_node())
    }

    pub fn focused_node_str(&self) -> String {
        self.focused_node()
            .map(|n| n.absolute_path.clone())
            .unwrap_or_default()
    }

    pub fn is_selected(&self, node: &Node) -> bool {
        self.selection
            .iter()
            .any(|n| n.absolute_path == node.absolute_path)
    }

    pub fn result(&self) -> Vec<&Node> {
        if self.selection.is_empty() {
            self.focused_node().map(|n| vec![n]).unwrap_or_default()
        } else {
            self.selection.iter().collect()
        }
    }

    pub fn result_str(&self) -> String {
        self.result()
            .iter()
            .map(|n| n.absolute_path.clone())
            .collect::<Vec<_>>()
            .join("\n")
    }

    pub fn selection_str(&self) -> String {
        self.selection
            .iter()
            .map(|n| n.absolute_path.clone())
            .collect::<Vec<_>>()
            .join("\n")
    }

    pub fn input_value(&self) -> Option<String> {
        self.input.buffer.as_ref().map(|b| b.value.clone())
    }

    // ---------------- logging ----------------
    pub fn log(&mut self, level: LogLevel, msg: String) {
        self.logs.push(Log::new(level, msg));
        self.logs_hidden = false;
    }
    pub fn log_info(&mut self, msg: String) {
        self.log(LogLevel::Info, msg)
    }
    pub fn log_success(&mut self, msg: String) {
        self.log(LogLevel::Success, msg)
    }
    pub fn log_warning(&mut self, msg: String) {
        self.log(LogLevel::Warning, msg)
    }
    pub fn log_error(&mut self, msg: String) {
        self.log(LogLevel::Error, msg)
    }

    fn push_out(&mut self, m: MsgOut) {
        self.msg_out.push_back(m);
    }

    pub fn refresh(&mut self) {
        self.push_out(MsgOut::Refresh);
    }

    // ---------------- key handling ----------------
    pub fn handle_key(&mut self, key: Key) -> Vec<Task> {
        let kb = &self.mode.key_bindings;
        let default = kb.default.clone();
        let msgs = kb
            .on_key
            .get(&key.name)
            .map(|a| Some(a.messages.clone()))
            .unwrap_or_else(|| {
                if key.is_alphabet() {
                    kb.on_alphabet.as_ref().map(|a| a.messages.clone())
                } else {
                    None
                }
                .or_else(|| {
                    if key.is_number() {
                        kb.on_number.as_ref().map(|a| a.messages.clone())
                    } else {
                        None
                    }
                })
                .or_else(|| {
                    if key.is_alphanumeric() {
                        kb.on_alphanumeric.as_ref().map(|a| a.messages.clone())
                    } else {
                        None
                    }
                })
                .or_else(|| {
                    if key.is_special_character() {
                        kb.on_special_character.as_ref().map(|a| a.messages.clone())
                    } else {
                        None
                    }
                })
                .or_else(|| {
                    if key.is_character() {
                        kb.on_character.as_ref().map(|a| a.messages.clone())
                    } else {
                        None
                    }
                })
                .or_else(|| {
                    if key.is_navigation() {
                        kb.on_navigation.as_ref().map(|a| a.messages.clone())
                    } else {
                        None
                    }
                })
                .or_else(|| {
                    if key.is_function() {
                        kb.on_function.as_ref().map(|a| a.messages.clone())
                    } else {
                        None
                    }
                })
            })
            .or_else(|| default.map(|a| a.messages));
        match msgs {
            Some(msgs) => msgs
                .into_iter()
                .map(|m| Task::new(MsgIn::External(m), Some(key.clone())))
                .collect(),
            None => {
                if self.config.general.enable_recover_mode {
                    vec![Task::new(
                        MsgIn::External(ExternalMsg::SwitchModeBuiltin("recover".into())),
                        Some(key),
                    )]
                } else {
                    vec![Task::new(
                        MsgIn::External(ExternalMsg::LogWarning("key map not found.".into())),
                        Some(key),
                    )]
                }
            }
        }
    }

    // ---------------- task handling ----------------
    /// handle a task; returns extra tasks to be handled next (e.g. key -> messages)
    pub fn handle_task(&mut self, task: Task) -> Vec<Task> {
        match task.msg {
            MsgIn::Internal(m) => match m {
                InternalMsg::SetDirectory(dir) => {
                    self.set_directory(dir);
                    vec![]
                }
                InternalMsg::AddLastFocus(p, f) => {
                    self.last_focus.insert(p, f);
                    vec![]
                }
                InternalMsg::HandleKey(k) => self.handle_key(k),
            },
            MsgIn::External(m) => {
                self.handle_external(m, task.key.as_ref());
                vec![]
            }
        }
    }

    pub fn set_directory(&mut self, dir: DirectoryBuffer) {
        let focus = dir.focused_node().map(|n| n.relative_path.clone());
        self.last_focus.insert(dir.parent.clone(), focus);
        if dir.parent == self.pwd {
            let scroll = self
                .directory_buffer
                .as_ref()
                .filter(|d| d.parent == dir.parent)
                .map(|d| d.scroll_state.clone());
            let mut dir = dir;
            if let Some(s) = scroll {
                dir.scroll_state = s;
            }
            self.directory_buffer = Some(dir);
        }
    }

    pub fn explore_pwd(&mut self) {
        let focus = self.last_focus.get(&self.pwd).cloned().unwrap_or(None);
        let pwd = self.pwd.clone();
        self.last_focus.insert(pwd.clone(), focus.clone());
        let fallback = self.directory_buffer.as_ref().map(|d| d.focus).unwrap_or(0);
        match explorer::explore_sync(&self.explorer_config, &pwd, focus.as_deref(), fallback) {
            Ok(dir) => self.set_directory(dir),
            Err(e) => self.log_error(e.to_string()),
        }
    }

    fn handle_external(&mut self, msg: ExternalMsg, key: Option<&Key>) {
        use ExternalMsg::*;
        match msg {
            ExplorePwd => self.explore_pwd(),
            ExplorePwdAsync => self.push_out(MsgOut::ExplorePwdAsync),
            ExploreParentsAsync => self.push_out(MsgOut::ExploreParentsAsync),
            TryCompletePath => self.try_complete_path(),
            ClearScreen => self.push_out(MsgOut::ClearScreen),
            Refresh => self.refresh(),
            FocusNext => self.focus_next(),
            FocusNextSelection => self.focus_next_selection(),
            FocusNextByRelativeIndex(n) => self.focus_next_by_relative_index(n),
            FocusNextByRelativeIndexFromInput => {
                if let Some(n) = self.input_value().and_then(|v| v.parse::<usize>().ok()) {
                    self.focus_next_by_relative_index(n)
                }
            }
            FocusPrevious => self.focus_previous(),
            FocusPreviousSelection => self.focus_previous_selection(),
            FocusPreviousByRelativeIndex(n) => self.focus_previous_by_relative_index(n),
            FocusPreviousByRelativeIndexFromInput => {
                if let Some(n) = self.input_value().and_then(|v| v.parse::<usize>().ok()) {
                    self.focus_previous_by_relative_index(n)
                }
            }
            FocusFirst => self.focus_first(true),
            FocusLast => self.focus_last(true),
            FocusPath(p) => self.focus_path(&p, true),
            FocusPathFromInput => {
                if let Some(p) = self.input_value() {
                    self.focus_path(&p, true)
                }
            }
            FocusByIndex(i) => self.focus_by_index(i),
            FocusByIndexFromInput => {
                if let Some(i) = self.input_value().and_then(|v| v.parse::<usize>().ok()) {
                    self.focus_by_index(i)
                }
            }
            FocusByFileName(n) => self.focus_by_file_name(&n, true),
            ScrollUp => self.scroll_up(),
            ScrollDown => self.scroll_down(),
            ScrollUpHalf => self.scroll_up_half(),
            ScrollDownHalf => self.scroll_down_half(),
            ChangeDirectory(d) => self.change_directory(&d, true),
            Enter => self.enter(),
            Back => self.back(),
            LastVisitedPath => self.last_visited_path(),
            NextVisitedPath => self.next_visited_path(),
            PreviousVisitedDeepBranch => self.visit_deep_branch(false),
            NextVisitedDeepBranch => self.visit_deep_branch(true),
            FollowSymlink => self.follow_symlink(),
            SetVroot(p) => self.set_vroot(&p),
            UnsetVroot => self.unset_vroot(),
            ToggleVroot => self.toggle_vroot(),
            ResetVroot => self.reset_vroot(),
            SetInputPrompt(p) => {
                self.input.prompt = p;
                self.refresh();
            }
            UpdateInputBuffer(op) => self.update_input_buffer(&op),
            UpdateInputBufferFromKey => {
                if let Some(op) = key.and_then(|k| k.to_input_operation()) {
                    self.update_input_buffer(&op)
                }
            }
            BufferInput(s) => self.buffer_input(&s),
            BufferInputFromKey => {
                if let Some(c) = key.and_then(|k| k.to_char()) {
                    self.buffer_input(&c.to_string())
                }
            }
            SetInputBuffer(s) => self.set_input_buffer(s),
            RemoveInputBufferLastCharacter => {
                if let Some(buf) = self.input.buffer.as_mut() {
                    let mut v = buf.value.clone();
                    v.pop();
                    *buf = Input::new(v);
                    self.logs_hidden = true;
                }
                self.refresh();
            }
            RemoveInputBufferLastWord => {
                if let Some(buf) = self.input.buffer.as_mut() {
                    buf.handle(&InputOperation::GoToEnd);
                    buf.handle(&InputOperation::DeletePreviousWord);
                    self.logs_hidden = true;
                }
                self.refresh();
            }
            ResetInputBuffer => self.reset_input_buffer(),
            SwitchMode(m) => self.switch_mode(&m, false),
            SwitchModeKeepingInputBuffer(m) => self.switch_mode(&m, true),
            SwitchModeBuiltin(m) => self.switch_mode_builtin(&m, false),
            SwitchModeBuiltinKeepingInputBuffer(m) => self.switch_mode_builtin(&m, true),
            SwitchModeCustom(m) => self.switch_mode_custom(&m, false),
            SwitchModeCustomKeepingInputBuffer(m) => self.switch_mode_custom(&m, true),
            PopMode => {
                self.pop_mode_keeping_input_buffer();
                self.reset_input_buffer();
            }
            PopModeKeepingInputBuffer => self.pop_mode_keeping_input_buffer(),
            SwitchLayout(l) => self.switch_layout(&l),
            SwitchLayoutBuiltin(l) => self.switch_layout_builtin(&l),
            SwitchLayoutCustom(l) => self.switch_layout_custom(&l),
            Call(c) => self.push_out(MsgOut::Call(c)),
            Call0(c) => self.push_out(MsgOut::Call0(c)),
            CallSilently(c) => self.push_out(MsgOut::CallSilently(c)),
            CallSilently0(c) => self.push_out(MsgOut::CallSilently0(c)),
            BashExec(s) => self.push_out(MsgOut::Call(bash(s))),
            BashExec0(s) => self.push_out(MsgOut::Call0(bash(s))),
            BashExecSilently(s) => self.push_out(MsgOut::CallSilently(bash(s))),
            BashExecSilently0(s) => self.push_out(MsgOut::CallSilently0(bash(s))),
            CallLua(f) => self.push_out(MsgOut::CallLua(f)),
            CallLuaSilently(f) => self.push_out(MsgOut::CallLuaSilently(f)),
            LuaEval(c) => self.push_out(MsgOut::LuaEval(c)),
            LuaEvalSilently(c) => self.push_out(MsgOut::LuaEvalSilently(c)),
            Select => {
                if let Some(n) = self.focused_node().cloned() {
                    self.select_node(n);
                }
            }
            SelectAll => {
                let nodes: Vec<Node> = self
                    .directory_buffer
                    .as_ref()
                    .map(|d| d.nodes.clone())
                    .unwrap_or_default();
                for n in nodes {
                    self.select_node(n);
                }
            }
            SelectPath(p) => self.select_path(&p),
            UnSelect => {
                if let Some(n) = self.focused_node().cloned() {
                    self.unselect_node(&n);
                }
            }
            UnSelectAll => {
                let nodes: Vec<Node> = self
                    .directory_buffer
                    .as_ref()
                    .map(|d| d.nodes.clone())
                    .unwrap_or_default();
                for n in nodes {
                    self.unselect_node(&n);
                }
            }
            UnSelectPath(p) => {
                let p = self.absolutize(&p);
                self.selection.retain(|n| n.absolute_path != p);
            }
            ToggleSelection => {
                if let Some(n) = self.focused_node().cloned() {
                    if self.is_selected(&n) {
                        self.unselect_node(&n);
                    } else {
                        self.select_node(n);
                    }
                }
            }
            ToggleSelectAll => {
                let nodes: Vec<Node> = self
                    .directory_buffer
                    .as_ref()
                    .map(|d| d.nodes.clone())
                    .unwrap_or_default();
                if nodes.iter().all(|n| self.is_selected(n)) {
                    for n in nodes {
                        self.unselect_node(&n);
                    }
                } else {
                    for n in nodes {
                        self.select_node(n);
                    }
                }
            }
            ToggleSelectionByPath(p) => {
                let ap = self.absolutize(&p);
                if self.selection.iter().any(|n| n.absolute_path == ap) {
                    self.selection.retain(|n| n.absolute_path != ap);
                } else {
                    self.select_path(&p);
                }
            }
            ClearSelection => self.selection.clear(),
            AddNodeFilter(f) => {
                self.explorer_config.filters.insert(f);
            }
            RemoveNodeFilter(f) => {
                self.explorer_config.filters.shift_remove(&f);
            }
            ToggleNodeFilter(f) => {
                if self.explorer_config.filters.contains(&f) {
                    self.explorer_config.filters.shift_remove(&f);
                } else {
                    self.explorer_config.filters.insert(f);
                }
            }
            AddNodeFilterFromInput(f) => {
                if let Some(input) = self.input_value() {
                    self.explorer_config
                        .filters
                        .insert(NodeFilterApplicable { filter: f, input });
                }
            }
            RemoveNodeFilterFromInput(f) => {
                if let Some(input) = self.input_value() {
                    self.explorer_config
                        .filters
                        .shift_remove(&NodeFilterApplicable { filter: f, input });
                }
            }
            RemoveLastNodeFilter => {
                self.explorer_config.filters.pop();
            }
            ResetNodeFilters => {
                self.explorer_config.filters.clear();
                if !self.config.general.show_hidden {
                    self.explorer_config.filters.insert(NodeFilterApplicable {
                        filter: NodeFilter::RelativePathDoesNotStartWith,
                        input: ".".into(),
                    });
                }
            }
            ClearNodeFilters => self.explorer_config.filters.clear(),
            AddNodeSorter(s) => {
                self.explorer_config.sorters.insert(s);
            }
            RemoveNodeSorter(s) => {
                self.explorer_config.sorters.retain(|x| x.sorter != s);
            }
            ReverseNodeSorter(s) => {
                let sorters: indexmap::IndexSet<NodeSorterApplicable> = self
                    .explorer_config
                    .sorters
                    .iter()
                    .map(|x| {
                        let mut x = x.clone();
                        if x.sorter == s {
                            x.reverse = !x.reverse;
                        }
                        x
                    })
                    .collect();
                self.explorer_config.sorters = sorters;
            }
            ToggleNodeSorter(s) => {
                if self.explorer_config.sorters.contains(&s) {
                    self.explorer_config.sorters.shift_remove(&s);
                } else {
                    self.explorer_config.sorters.insert(s);
                }
            }
            ReverseNodeSorters => {
                let sorters: indexmap::IndexSet<NodeSorterApplicable> = self
                    .explorer_config
                    .sorters
                    .iter()
                    .map(|x| {
                        let mut x = x.clone();
                        x.reverse = !x.reverse;
                        x
                    })
                    .collect();
                self.explorer_config.sorters = sorters;
            }
            RemoveLastNodeSorter => {
                self.explorer_config.sorters.pop();
            }
            ResetNodeSorters => {
                self.explorer_config.sorters = self
                    .config
                    .general
                    .initial_sorting
                    .clone()
                    .unwrap_or_default();
            }
            ClearNodeSorters => self.explorer_config.sorters.clear(),
            Search(p) => self.search(p, None, None),
            SearchFromInput => {
                if let Some(p) = self.input_value() {
                    self.search(p, None, None)
                }
            }
            SearchFuzzy(p) => self.search(p, Some(SearchAlgorithm::Fuzzy), Some(false)),
            SearchFuzzyFromInput => {
                if let Some(p) = self.input_value() {
                    self.search(p, Some(SearchAlgorithm::Fuzzy), Some(false))
                }
            }
            SearchFuzzyUnordered(p) => self.search(p, Some(SearchAlgorithm::Fuzzy), Some(true)),
            SearchFuzzyUnorderedFromInput => {
                if let Some(p) = self.input_value() {
                    self.search(p, Some(SearchAlgorithm::Fuzzy), Some(true))
                }
            }
            SearchRegex(p) => self.search(p, Some(SearchAlgorithm::Regex), Some(false)),
            SearchRegexFromInput => {
                if let Some(p) = self.input_value() {
                    self.search(p, Some(SearchAlgorithm::Regex), Some(false))
                }
            }
            SearchRegexUnordered(p) => self.search(p, Some(SearchAlgorithm::Regex), Some(true)),
            SearchRegexUnorderedFromInput => {
                if let Some(p) = self.input_value() {
                    self.search(p, Some(SearchAlgorithm::Regex), Some(true))
                }
            }
            ToggleSearchAlgorithm => {
                if let Some(s) = self.explorer_config.searcher.as_mut() {
                    s.algorithm = match s.algorithm {
                        SearchAlgorithm::Fuzzy => SearchAlgorithm::Regex,
                        SearchAlgorithm::Regex => SearchAlgorithm::Fuzzy,
                    };
                } else {
                    let a = match self.config.general.search.algorithm {
                        SearchAlgorithm::Fuzzy => SearchAlgorithm::Regex,
                        SearchAlgorithm::Regex => SearchAlgorithm::Fuzzy,
                    };
                    self.config.general.search.algorithm = a;
                }
            }
            EnableSearchOrder => {
                if let Some(s) = self.explorer_config.searcher.as_mut() {
                    s.unordered = false;
                } else {
                    self.config.general.search.unordered = false;
                }
            }
            DisableSearchOrder => {
                if let Some(s) = self.explorer_config.searcher.as_mut() {
                    s.unordered = true;
                } else {
                    self.config.general.search.unordered = true;
                }
            }
            ToggleSearchOrder => {
                if let Some(s) = self.explorer_config.searcher.as_mut() {
                    s.unordered = !s.unordered;
                } else {
                    self.config.general.search.unordered = !self.config.general.search.unordered;
                }
            }
            AcceptSearch => self.accept_search(),
            CancelSearch => self.cancel_search(),
            EnableMouse => {
                self.config.general.enable_mouse = true;
                self.push_out(MsgOut::EnableMouse);
            }
            DisableMouse => {
                self.config.general.enable_mouse = false;
                self.push_out(MsgOut::DisableMouse);
            }
            ToggleMouse => {
                if self.config.general.enable_mouse {
                    self.config.general.enable_mouse = false;
                    self.push_out(MsgOut::DisableMouse);
                } else {
                    self.config.general.enable_mouse = true;
                    self.push_out(MsgOut::EnableMouse);
                }
            }
            StartFifo(p) => self.push_out(MsgOut::StartFifo(p)),
            StopFifo => self.push_out(MsgOut::StopFifo),
            ToggleFifo(p) => self.push_out(MsgOut::ToggleFifo(p)),
            LogInfo(m) => self.log_info(m),
            LogSuccess(m) => self.log_success(m),
            LogWarning(m) => self.log_warning(m),
            LogError(m) => self.log_error(m),
            Debug(p) => self.push_out(MsgOut::Debug(p)),
            Quit => self.push_out(MsgOut::Quit),
            PrintPwdAndQuit => self.push_out(MsgOut::PrintPwdAndQuit),
            PrintFocusPathAndQuit => self.push_out(MsgOut::PrintFocusPathAndQuit),
            PrintSelectionAndQuit => self.push_out(MsgOut::PrintSelectionAndQuit),
            PrintResultAndQuit => self.push_out(MsgOut::PrintResultAndQuit),
            PrintAppStateAndQuit => self.push_out(MsgOut::PrintAppStateAndQuit),
            Terminate => self.push_out(MsgOut::Terminate),
        }
    }

    // ---------------- paths ----------------
    pub fn absolutize(&self, p: &str) -> String {
        path_util::absolutize(p, &self.pwd)
    }

    fn within_vroot(&self, p: &str) -> bool {
        match &self.vroot {
            Some(v) => Path::new(p).starts_with(v),
            None => true,
        }
    }

    pub fn change_directory(&mut self, dir: &str, save_history: bool) {
        let target = self.absolutize(dir);
        let mut target_path = PathBuf::from(&target);
        if let Some(v) = &self.vroot {
            if !target_path.starts_with(v) {
                self.log_warning(format!("{} is outside of virtual root {}", target, v));
                return;
            }
        }
        if !target_path.is_dir() {
            // emulate set_current_dir error
            match std::fs::metadata(&target_path) {
                Err(e) => {
                    self.log_error(crate::lua_api::io_error_string(&e));
                }
                Ok(_) => {
                    self.log_error("Not a directory (os error 20)".into());
                }
            }
            return;
        }
        if let Err(e) = std::env::set_current_dir(&target_path) {
            self.log_error(crate::lua_api::io_error_string(&e));
            return;
        }
        target_path = PathBuf::from(&target);
        let target = target_path.to_string_lossy().to_string();
        let last = self.pwd.clone();
        let focus = self.focused_node().map(|n| n.relative_path.clone());
        self.pwd = target.clone();
        self.explorer_config.searcher = None;
        if save_history {
            if self.directory_buffer.as_ref().map(|d| d.parent == last).unwrap_or(false) {
                if let Some(f) = focus {
                    self.last_focus.insert(last, Some(f));
                }
            }
            let h = if target.ends_with('/') {
                target.clone()
            } else {
                format!("{}/", target)
            };
            self.history.push(h);
        }
        self.explore_pwd();
    }

    pub fn focus_path(&mut self, path: &str, save_history: bool) {
        let ap = self.absolutize(path);
        let p = PathBuf::from(&ap);
        match (p.parent(), p.file_name()) {
            (Some(parent), Some(name)) => {
                let parent = parent.to_string_lossy().to_string();
                let name = name.to_string_lossy().to_string();
                if parent != self.pwd {
                    self.change_directory(&parent, false);
                }
                if parent == self.pwd {
                    self.focus_by_file_name(&name, save_history);
                }
            }
            _ => self.focus_first(save_history),
        }
    }

    pub fn focus_by_file_name(&mut self, name: &str, save_history: bool) {
        let mut push = None;
        let mut found = false;
        if let Some(dir) = self.directory_buffer.as_mut() {
            if let Some(i) = dir.nodes.iter().position(|n| n.relative_path == name) {
                dir.focus = i;
                found = true;
                if save_history {
                    push = dir.focused_node().map(|n| n.absolute_path.clone());
                }
            }
        } else {
            return;
        }
        if let Some(p) = push {
            self.history.push(p);
        }
        if !found {
            self.log_error(format!("{} not found in $PWD", name));
        }
    }

    fn total(&self) -> usize {
        self.directory_buffer.as_ref().map(|d| d.total).unwrap_or(0)
    }

    fn set_focus(&mut self, i: usize) {
        if let Some(d) = self.directory_buffer.as_mut() {
            d.focus = i;
        }
    }

    fn focus(&self) -> usize {
        self.directory_buffer.as_ref().map(|d| d.focus).unwrap_or(0)
    }

    pub fn focus_first(&mut self, save_history: bool) {
        if self.total() == 0 {
            return;
        }
        self.set_focus(0);
        if save_history {
            if let Some(p) = self.focused_node().map(|n| n.absolute_path.clone()) {
                self.history.push(p);
            }
        }
    }

    pub fn focus_last(&mut self, save_history: bool) {
        let t = self.total();
        if t == 0 {
            return;
        }
        self.set_focus(t - 1);
        if save_history {
            if let Some(p) = self.focused_node().map(|n| n.absolute_path.clone()) {
                self.history.push(p);
            }
        }
    }

    fn focus_next(&mut self) {
        let t = self.total();
        if t == 0 {
            return;
        }
        let f = self.focus();
        let bounded = self.config.general.enforce_bounded_index_navigation;
        let n = if f + 1 >= t {
            if bounded {
                f
            } else {
                0
            }
        } else {
            f + 1
        };
        self.set_focus(n);
    }

    fn focus_previous(&mut self) {
        let t = self.total();
        if t == 0 {
            return;
        }
        let f = self.focus();
        let bounded = self.config.general.enforce_bounded_index_navigation;
        let n = if f == 0 {
            if bounded {
                0
            } else {
                t - 1
            }
        } else {
            f - 1
        };
        self.set_focus(n);
    }

    fn focus_next_by_relative_index(&mut self, n: usize) {
        let t = self.total();
        if t == 0 {
            return;
        }
        let f = self.focus();
        self.set_focus((f + n).min(t - 1));
    }

    fn focus_previous_by_relative_index(&mut self, n: usize) {
        let t = self.total();
        if t == 0 {
            return;
        }
        let f = self.focus();
        self.set_focus(f.saturating_sub(n));
    }

    fn focus_by_index(&mut self, i: usize) {
        let t = self.total();
        if t == 0 {
            return;
        }
        self.set_focus(i.min(t - 1));
    }

    fn focus_next_selection(&mut self) {
        let sel: Vec<String> = self.selection.iter().map(|n| n.absolute_path.clone()).collect();
        if sel.is_empty() {
            return;
        }
        let cur = self.focused_node().map(|n| n.absolute_path.clone());
        let idx = cur.and_then(|c| sel.iter().position(|s| *s == c));
        let next = match idx {
            Some(i) => sel[(i + 1) % sel.len()].clone(),
            None => sel[0].clone(),
        };
        self.focus_path(&next, true);
    }

    fn focus_previous_selection(&mut self) {
        let sel: Vec<String> = self.selection.iter().map(|n| n.absolute_path.clone()).collect();
        if sel.is_empty() {
            return;
        }
        let cur = self.focused_node().map(|n| n.absolute_path.clone());
        let idx = cur.and_then(|c| sel.iter().position(|s| *s == c));
        let prev = match idx {
            Some(i) => sel[(i + sel.len() - 1) % sel.len()].clone(),
            None => sel[sel.len() - 1].clone(),
        };
        self.focus_path(&prev, true);
    }

    fn scroll_height(&self) -> usize {
        self.table_height.max(1)
    }

    fn scroll_up(&mut self) {
        let h = self.scroll_height();
        let f = self.focus();
        self.set_focus(f.saturating_sub(h));
    }

    fn scroll_down(&mut self) {
        let t = self.total();
        if t == 0 {
            return;
        }
        let h = self.scroll_height();
        let f = self.focus();
        self.set_focus((f + h).min(t - 1));
    }

    fn scroll_up_half(&mut self) {
        let h = self.scroll_height() / 2;
        let f = self.focus();
        self.set_focus(f.saturating_sub(h));
    }

    fn scroll_down_half(&mut self) {
        let t = self.total();
        if t == 0 {
            return;
        }
        let h = self.scroll_height() / 2;
        let f = self.focus();
        self.set_focus((f + h).min(t - 1));
    }

    fn enter(&mut self) {
        if let Some(n) = self.focused_node().cloned() {
            let is_dir = n.is_dir || n.symlink.as_ref().map(|s| s.is_dir).unwrap_or(false);
            if is_dir {
                self.change_directory(&n.absolute_path, true);
            }
        }
    }

    fn back(&mut self) {
        let pwd = self.pwd.clone();
        if let Some(v) = &self.vroot {
            if Path::new(&pwd) == Path::new(v) {
                return;
            }
        }
        if Path::new(&pwd).parent().is_some() {
            self.focus_path(&pwd, true);
        }
    }

    fn visit_path_from_history(&mut self, path: String) {
        if path.ends_with('/') {
            self.change_directory(&path, false);
        } else {
            self.focus_path(&path, false);
        }
    }

    fn last_visited_path(&mut self) {
        self.history.visit_last();
        if let Some(p) = self.history.peek().cloned() {
            self.visit_path_from_history(p);
        }
    }

    fn next_visited_path(&mut self) {
        self.history.visit_next();
        if let Some(p) = self.history.peek().cloned() {
            self.visit_path_from_history(p);
        }
    }

    fn visit_deep_branch(&mut self, forward: bool) {
        let pwd = self.pwd.clone();
        if let Some(p) = self.history.deep_branch(&pwd, forward) {
            self.change_directory(&p, true);
        } else if let Some(p) = self.history.peek().cloned() {
            let pn = History::norm(&p);
            if !p.ends_with('/') && Path::new(&pn).starts_with(&pwd) && pn != pwd {
                let target = if Path::new(&pn).is_dir() { pn } else { return };
                self.change_directory(&target, false);
            }
        }
    }

    fn follow_symlink(&mut self) {
        if let Some(s) = self
            .focused_node()
            .and_then(|n| n.symlink.as_ref())
            .map(|s| s.absolute_path.clone())
        {
            self.focus_path(&s, true);
        }
    }

    // ---------------- vroot ----------------
    fn set_vroot(&mut self, p: &str) {
        let v = self.absolutize(p);
        if Path::new(&v).is_dir() {
            self.vroot = Some(v.clone());
            if !Path::new(&self.pwd).starts_with(&v) {
                self.change_directory(&v, true);
            }
        } else {
            self.log_error(format!("not a valid directory: {}", v));
        }
    }

    fn unset_vroot(&mut self) {
        self.vroot = None;
    }

    fn toggle_vroot(&mut self) {
        if self.vroot.is_some() && self.vroot == self.initial_vroot {
            self.unset_vroot();
        } else if self.vroot.is_some() && self.initial_vroot.is_none() {
            self.unset_vroot();
        } else if self.vroot.is_none() && self.initial_vroot.is_some() {
            self.reset_vroot();
        } else if self.vroot.is_some() {
            self.reset_vroot();
        } else {
            let pwd = self.pwd.clone();
            self.set_vroot(&pwd);
        }
    }

    fn reset_vroot(&mut self) {
        match self.initial_vroot.clone() {
            Some(v) => self.set_vroot(&v),
            None => self.unset_vroot(),
        }
    }

    // ---------------- input ----------------
    fn update_input_buffer(&mut self, op: &InputOperation) {
        if let Some(buf) = self.input.buffer.as_mut() {
            buf.handle(op);
            self.logs_hidden = true;
        } else {
            let mut buf = Input::default();
            buf.handle(op);
            self.input.buffer = Some(buf);
            self.logs_hidden = true;
        }
        self.refresh();
    }

    fn buffer_input(&mut self, s: &str) {
        if let Some(buf) = self.input.buffer.as_mut() {
            buf.handle(&InputOperation::GoToEnd);
            for c in s.chars() {
                buf.handle(&InputOperation::InsertCharacter(c));
            }
        } else {
            self.input.buffer = Some(Input::new(s.to_string()));
        }
        self.logs_hidden = true;
        self.refresh();
    }

    fn set_input_buffer(&mut self, s: String) {
        self.input.buffer = Some(Input::new(s));
        self.logs_hidden = true;
        self.refresh();
    }

    fn reset_input_buffer(&mut self) {
        self.input = InputBuffer {
            buffer: None,
            prompt: self
                .mode
                .prompt
                .clone()
                .or_else(|| self.config.general.prompt.format.clone())
                .unwrap_or_default(),
        };
        self.refresh();
    }

    // ---------------- modes ----------------
    fn push_mode(&mut self) {
        if Some(&self.mode) != self.last_modes.last() {
            self.last_modes.push(self.mode.clone());
        }
    }

    fn set_mode(&mut self, mode: Mode, keep_input: bool) {
        self.push_mode();
        self.mode = self.sanitize_mode(mode);
        if !keep_input {
            self.reset_input_buffer();
        } else {
            self.input.prompt = self
                .mode
                .prompt
                .clone()
                .or_else(|| self.config.general.prompt.format.clone())
                .unwrap_or_default();
        }
        self.refresh();
    }

    fn switch_mode(&mut self, name: &str, keep: bool) {
        if self.config.modes.custom.contains_key(name) {
            self.switch_mode_custom(name, keep)
        } else {
            self.switch_mode_builtin(name, keep)
        }
    }

    fn switch_mode_builtin(&mut self, name: &str, keep: bool) {
        match self.config.modes.builtin.get(name).cloned() {
            Some(m) => self.set_mode(m, keep),
            None => self.log_error(format!("Builtin mode not found: {}", name)),
        }
    }

    fn switch_mode_custom(&mut self, name: &str, keep: bool) {
        match self.config.modes.custom.get(name).cloned() {
            Some(m) => self.set_mode(m, keep),
            None => self.log_error(format!("Custom mode not found: {}", name)),
        }
    }

    fn pop_mode_keeping_input_buffer(&mut self) {
        if let Some(m) = self.last_modes.pop() {
            self.input.prompt = m
                .prompt
                .clone()
                .or_else(|| self.config.general.prompt.format.clone())
                .unwrap_or_default();
            self.mode = m;
        }
        self.refresh();
    }

    // ---------------- layouts ----------------
    fn switch_layout(&mut self, name: &str) {
        if self.config.layouts.custom.contains_key(name) {
            self.switch_layout_custom(name)
        } else {
            self.switch_layout_builtin(name)
        }
    }

    fn switch_layout_builtin(&mut self, name: &str) {
        match self.config.layouts.builtin.get(name).cloned() {
            Some(l) => {
                self.layout = l;
                self.refresh();
            }
            None => self.log_error(format!("Builtin layout not found: {}", name)),
        }
    }

    fn switch_layout_custom(&mut self, name: &str) {
        match self.config.layouts.custom.get(name).cloned() {
            Some(l) => {
                self.layout = l;
                self.refresh();
            }
            None => self.log_error(format!("Custom layout not found: {}", name)),
        }
    }

    // ---------------- selection ----------------
    fn select_node(&mut self, n: Node) {
        if !self.is_selected(&n) {
            self.selection.push(n);
        }
    }

    fn unselect_node(&mut self, n: &Node) {
        self.selection.retain(|x| x.absolute_path != n.absolute_path);
    }

    pub fn select_path(&mut self, p: &str) {
        let ap = self.absolutize(p);
        let path = PathBuf::from(&ap);
        let parent = path
            .parent()
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_default();
        let name = path
            .file_name()
            .map(|n| n.to_string_lossy().to_string())
            .unwrap_or_default();
        if path.symlink_metadata().is_err() {
            self.log_error(format!("{} not found", ap));
            return;
        }
        let node = Node::new(parent, name);
        self.select_node(node);
    }

    // ---------------- search ----------------
    fn search(&mut self, pattern: String, algorithm: Option<SearchAlgorithm>, unordered: Option<bool>) {
        let rf = self
            .explorer_config
            .searcher
            .as_ref()
            .map(|s| s.recoverable_focus.clone())
            .unwrap_or_else(|| self.focused_node().map(|n| n.absolute_path.clone()));
        let prev = self.explorer_config.searcher.clone();
        let algorithm = algorithm.unwrap_or_else(|| {
            prev.as_ref()
                .map(|s| s.algorithm)
                .unwrap_or(self.config.general.search.algorithm)
        });
        let unordered = unordered.unwrap_or_else(|| {
            prev.as_ref()
                .map(|s| s.unordered)
                .unwrap_or(self.config.general.search.unordered)
        });
        self.explorer_config.searcher = Some(NodeSearcher {
            pattern,
            recoverable_focus: rf,
            algorithm,
            unordered,
            exact_mode: self.config.general.search.exact_mode,
            rank_criteria: self.config.general.search.rank_criteria.clone(),
        });
    }

    fn accept_search(&mut self) {
        let focus = self.focused_node().map(|n| n.absolute_path.clone());
        self.explorer_config.searcher = None;
        self.explore_pwd();
        if let Some(f) = focus {
            self.focus_path(&f, true);
        }
    }

    fn cancel_search(&mut self) {
        let focus = self
            .explorer_config
            .searcher
            .as_ref()
            .and_then(|s| s.recoverable_focus.clone());
        self.explorer_config.searcher = None;
        self.explore_pwd();
        if let Some(f) = focus {
            self.focus_path(&f, false);
        }
    }

    // ---------------- completion ----------------
    fn try_complete_path(&mut self) {
        let input = match self.input_value() {
            Some(i) => i,
            None => return,
        };
        if let Some(c) = path_util::try_complete(&input, &self.pwd) {
            self.set_input_buffer(c);
        }
    }

    // ---------------- help menu ----------------
    pub fn global_help_menu_str(&self, delim: &str) -> String {
        let mut modes: Vec<Mode> = vec![self.mode.clone()];
        for (_, m) in self.config.modes.builtin.iter() {
            modes.push(self.sanitize_mode(m.clone()));
        }
        for (_, m) in self.config.modes.custom.iter() {
            modes.push(self.sanitize_mode(m.clone()));
        }
        let hide = self.config.general.hide_remaps_in_help_menu;
        let blocks: Vec<String> = modes
            .iter()
            .map(|m| {
                let mut lines: Vec<String> = vec![
                    format!("### {}", m.name),
                    String::new(),
                    format!(
                        " {:15} | {:25} | {}\n {} | {} | {}",
                        "key",
                        "remaps",
                        "action",
                        "-".repeat(15),
                        "-".repeat(25),
                        "-".repeat(6)
                    ),
                ];
                for l in crate::ui::help_menu_lines(m, hide) {
                    match l {
                        crate::ui::HelpMenuLine::Paragraph(p) => lines.push(p),
                        crate::ui::HelpMenuLine::KeyMap(k, r, h) => {
                            lines.push(format!(" {:15} | {:25} | {}", k, r.join("|"), h))
                        }
                    }
                }
                lines.join(delim)
            })
            .collect();
        blocks.join(&format!("{0}{0}{0}", delim))
    }

    pub fn history_str(&self, delim: &str) -> String {
        self.history.paths.join(delim)
    }

    pub fn logs_str(&self, delim: &str) -> String {
        self.logs
            .iter()
            .map(|l| format!("[{}] {} {}", l.created_at.display(), l.level.name(), l.message))
            .collect::<Vec<_>>()
            .join(delim)
    }

    pub fn directory_nodes_str(&self, delim: &str) -> String {
        self.directory_buffer
            .as_ref()
            .map(|d| {
                d.nodes
                    .iter()
                    .map(|n| n.absolute_path.clone())
                    .collect::<Vec<_>>()
                    .join(delim)
            })
            .unwrap_or_default()
    }
}

fn bash(script: String) -> Command {
    Command {
        command: "bash".into(),
        args: vec!["-c".into(), script],
    }
}
