use std::path::{Path, PathBuf};

use crate::config::*;
use crate::explorer::{self, DirectoryBuffer, ExplorerConfig, NodeSearcher};
use crate::input::Input;
use crate::msg::*;
use crate::node::Node;
use crate::path_util;

pub const VERSION: &str = "1.1.0";

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
pub enum LogLevel {
    #[serde(rename = "INFO")]
    Info,
    #[serde(rename = "WARNING")]
    Warning,
    #[serde(rename = "SUCCESS")]
    Success,
    #[serde(rename = "ERROR")]
    Error,
}

impl LogLevel {
    pub fn name(&self) -> &'static str {
        match self {
            LogLevel::Info => "INFO",
            LogLevel::Warning => "WARNING",
            LogLevel::Success => "SUCCESS",
            LogLevel::Error => "ERROR",
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Timestamp {
    pub secs: i64,
    pub nanos: u32,
}

impl Timestamp {
    pub fn now() -> Self {
        let d = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default();
        Timestamp {
            secs: d.as_secs() as i64,
            nanos: d.subsec_nanos(),
        }
    }

    pub fn local_tm(&self) -> (libc::tm, i64) {
        unsafe {
            let t: libc::time_t = self.secs as libc::time_t;
            let mut tm: libc::tm = std::mem::zeroed();
            libc::localtime_r(&t, &mut tm);
            let off = tm.tm_gmtoff as i64;
            (tm, off)
        }
    }

    pub fn hms(&self) -> String {
        let (tm, _) = self.local_tm();
        format!("{:02}:{:02}:{:02}", tm.tm_hour, tm.tm_min, tm.tm_sec)
    }

    pub fn display(&self) -> String {
        // like time::OffsetDateTime Display
        let (tm, off) = self.local_tm();
        let mut nanos = format!("{:09}", self.nanos);
        while nanos.len() > 1 && nanos.ends_with('0') {
            nanos.pop();
        }
        let sign = if off < 0 { '-' } else { '+' };
        let o = off.abs();
        format!(
            "{}-{:02}-{:02} {}:{:02}:{:02}.{} {}{:02}:{:02}:{:02}",
            tm.tm_year + 1900,
            tm.tm_mon + 1,
            tm.tm_mday,
            tm.tm_hour,
            tm.tm_min,
            tm.tm_sec,
            nanos,
            sign,
            o / 3600,
            (o % 3600) / 60,
            o % 60
        )
    }
}

impl Serialize for Timestamp {
    fn serialize<S: Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        let (tm, off) = self.local_tm();
        let o = off.abs();
        let sg = if off < 0 { -1 } else { 1 };
        let v: Vec<i64> = vec![
            (tm.tm_year + 1900) as i64,
            (tm.tm_yday + 1) as i64,
            tm.tm_hour as i64,
            tm.tm_min as i64,
            tm.tm_sec as i64,
            self.nanos as i64,
            sg * (o / 3600),
            sg * ((o % 3600) / 60),
            sg * (o % 60),
        ];
        v.serialize(s)
    }
}

#[derive(Debug, Clone, Serialize)]
pub struct Log {
    pub level: LogLevel,
