            | '\\' | '`' | '|' | '~'
    )
}

fn breaks_single_quote(c: char) -> bool {
    c == '\'' || c == '\\' || c.is_control() || (c.is_whitespace() && c != ' ')
}

pub fn shell_escape(s: &str) -> String {
    let mut nq = false;
    let mut sq = true;
    for c in s.chars() {
        if needs_quoting(c) {
            nq = true;
        }
        if breaks_single_quote(c) {
            sq = false;
        }
    }
    if !nq {
        return s.to_string();
    }
    if sq {
        return format!("'{}'", s);
    }
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '$' => out.push_str("\\$"),
            '`' => out.push_str("\\`"),
            '\n' => out.push_str("\\n"),
            '\t' => out.push_str("\\t"),
            '\r' => out.push_str("\\r"),
            '\x1b' => out.push_str("\\e"),
            c if c.is_control() || (c.is_whitespace() && c != ' ') => {
                out.push_str(&format!("\\u{{{:x}}}", c as u32))
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

