pub fn try_complete(input: &str, pwd: &str) -> Option<String> {
    let (dir_part, name_part) = match input.rfind('/') {
        Some(i) => (&input[..=i], &input[i + 1..]),
        None => ("", input),
    };
    let dir = if dir_part.is_empty() {
        PathBuf::from(pwd)
    } else if Path::new(dir_part).is_absolute() {
        PathBuf::from(dir_part)
    } else {
        Path::new(pwd).join(dir_part)
    };
    let rd = std::fs::read_dir(&dir).ok()?;
    let mut matches: Vec<(String, bool)> = rd
        .filter_map(|e| e.ok())
        .map(|e| {
            let n = e.file_name().to_string_lossy().to_string();
            let is_dir = e.path().is_dir();
            (n, is_dir)
        })
        .filter(|(n, _)| n.starts_with(name_part))
        .collect();
    if matches.is_empty() {
        return None;
    }
    matches.sort();
    if matches.len() == 1 {
        let (n, is_dir) = &matches[0];
        let mut out = format!("{}{}", dir_part, n);
        if *is_dir {
            out.push('/');
        }
        return Some(out);
    }
    // common prefix
    let first: Vec<char> = matches[0].0.chars().collect();
    let mut plen = first.len();
    for (m, _) in matches.iter().skip(1) {
        let mc: Vec<char> = m.chars().collect();
        let mut i = 0;
        while i < plen && i < mc.len() && mc[i] == first[i] {
            i += 1;
        }
        plen = i;
    }
    let prefix: String = first[..plen].iter().collect();
    Some(format!("{}{}", dir_part, prefix))
}
