// Minimal ANSI SGR to ratatui Text conversion (like ansi-to-tui)
use ratatui::style::{Color, Modifier, Style};
use ratatui::text::{Line, Span, Text};

fn color_from_code(n: u16) -> Option<Color> {
    Some(match n {
        30 | 40 => Color::Black,
        31 | 41 => Color::Red,
        32 | 42 => Color::Green,
        33 | 43 => Color::Yellow,
        34 | 44 => Color::Blue,
        35 | 45 => Color::Magenta,
        36 | 46 => Color::Cyan,
        37 | 47 => Color::Gray,
        90 | 100 => Color::DarkGray,
        91 | 101 => Color::LightRed,
        92 | 102 => Color::LightGreen,
        93 | 103 => Color::LightYellow,
        94 | 104 => Color::LightBlue,
        95 | 105 => Color::LightMagenta,
        96 | 106 => Color::LightCyan,
        97 | 107 => Color::White,
        _ => return None,
    })
}

fn apply_sgr(style: &mut Style, params: &[u16]) {
    let mut i = 0;
    if params.is_empty() {
        *style = Style::default();
        return;
    }
    while i < params.len() {
        let p = params[i];
        match p {
            0 => *style = Style::default(),
            1 => *style = style.add_modifier(Modifier::BOLD),
            2 => *style = style.add_modifier(Modifier::DIM),
            3 => *style = style.add_modifier(Modifier::ITALIC),
            4 => *style = style.add_modifier(Modifier::UNDERLINED),
            5 => *style = style.add_modifier(Modifier::SLOW_BLINK),
            6 => *style = style.add_modifier(Modifier::RAPID_BLINK),
            7 => *style = style.add_modifier(Modifier::REVERSED),
            8 => *style = style.add_modifier(Modifier::HIDDEN),
            9 => *style = style.add_modifier(Modifier::CROSSED_OUT),
            21 | 22 => *style = style.remove_modifier(Modifier::BOLD | Modifier::DIM),
            23 => *style = style.remove_modifier(Modifier::ITALIC),
            24 => *style = style.remove_modifier(Modifier::UNDERLINED),
            25 => *style = style.remove_modifier(Modifier::SLOW_BLINK | Modifier::RAPID_BLINK),
            27 => *style = style.remove_modifier(Modifier::REVERSED),
            28 => *style = style.remove_modifier(Modifier::HIDDEN),
            29 => *style = style.remove_modifier(Modifier::CROSSED_OUT),
            30..=37 | 90..=97 => *style = style.fg(color_from_code(p).unwrap()),
            40..=47 | 100..=107 => *style = style.bg(color_from_code(p).unwrap()),
            39 => *style = style.fg(Color::Reset),
            49 => *style = style.bg(Color::Reset),
            38 | 48 => {
                let fg = p == 38;
                if i + 1 < params.len() {
                    match params[i + 1] {
                        5 if i + 2 < params.len() => {
                            let c = Color::Indexed(params[i + 2] as u8);
                            *style = if fg { style.fg(c) } else { style.bg(c) };
                            i += 2;
                        }
                        2 if i + 4 < params.len() => {
                            let c = Color::Rgb(
                                params[i + 2] as u8,
                                params[i + 3] as u8,
                                params[i + 4] as u8,
                            );
                            *style = if fg { style.fg(c) } else { style.bg(c) };
                            i += 4;
                        }
                        _ => {}
                    }
                    i += 1;
                }
            }
            _ => {}
        }
        i += 1;
    }
}

pub fn ansi_to_text(s: &str) -> Text<'static> {
    let mut lines: Vec<Line<'static>> = vec![];
    let mut spans: Vec<Span<'static>> = vec![];
    let mut style = Style::default();
    let mut buf = String::new();
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '\x1b' && i + 1 < chars.len() && chars[i + 1] == '[' {
            // parse CSI
            let mut j = i + 2;
            let mut param = String::new();
            while j < chars.len() && (chars[j].is_ascii_digit() || chars[j] == ';' || chars[j] == ':') {
                param.push(chars[j]);
                j += 1;
            }
            if j < chars.len() {
                let fin = chars[j];
                if fin == 'm' {
                    if !buf.is_empty() {
                        spans.push(Span::styled(std::mem::take(&mut buf), style));
                    }
                    let params: Vec<u16> = if param.is_empty() {
                        vec![]
                    } else {
                        param
                            .split(|c| c == ';' || c == ':')
                            .map(|x| x.parse::<u16>().unwrap_or(0))
                            .collect()
                    };
                    apply_sgr(&mut style, &params);
                }
                i = j + 1;
                continue;
            } else {
                i = j;
                continue;
            }
        }
        if c == '\n' {
            if !buf.is_empty() {
                spans.push(Span::styled(std::mem::take(&mut buf), style));
            }
            lines.push(Line::from(std::mem::take(&mut spans)));
            i += 1;
            continue;
        }
        buf.push(c);
        i += 1;
    }
    if !buf.is_empty() {
        spans.push(Span::styled(buf, style));
    }
    lines.push(Line::from(spans));
    Text::from(lines)
}
EOF
echo ok

