use ratatui::layout::{Constraint as TuiConstraint, Direction, Layout as TuiLayout, Rect};
use ratatui::style::{Color as TuiColor, Modifier as TuiModifier, Style as TuiStyle};
use ratatui::text::{Line, Span, Text};
use ratatui::widgets::{Block, BorderType as TuiBorderType, Borders, Cell, List, ListItem, Paragraph, Row, Table};
