fn draw_selection(ctx: &mut DrawCtx, f: &mut Frame, area: Rect) {
    let app_config = ctx.app.config.clone();
    let panel_config = &app_config.general.panel_ui;
    let config = panel_config.default.extend(&panel_config.selection);
    let item = &app_config.general.selection.item;
    let height = (area.height as usize).saturating_sub(2);
    let total = ctx.app.selection.len();
    let sel: Vec<Node> = ctx.app.selection.iter().rev().take(height).rev().cloned().collect();
    let items: Vec<ListItem> = sel
        .iter()
        .map(|n| {
            let out = match &item.format {
                Some(fmt) => {
                    let v = crate::lua::serde::to_lua(n).unwrap_or(crate::lua::Value::Nil);
                    match lua_api::call_fn_string(ctx.lua, fmt, v) {
                        Ok(s) => s,
                        Err(e) => e,
                    }
                }
                None => n.absolute_path.clone(),
            };
            ListItem::new(ansi_to_text(&out)).style(tui_style(&item.style))
        })
        .collect();
    let title = if total == 0 {
        " Selection ".to_string()
    } else {
        format!(" Selection ({}) ", total)
    };
    let l = List::new(items).block(block(&config, title));
    f.render_widget(l, area);
}

fn sel_indicator(app: &App) -> String {
    let n = app.selection.len();
    if n == 0 {
        String::new()
    } else {
        format!(" {{{} sel}}", n)
    }
}

fn draw_input_buffer(ctx: &mut DrawCtx, f: &mut Frame, area: Rect) {
    let app_config = &ctx.app.config;
    let panel_config = &app_config.general.panel_ui;
    let config = panel_config.default.extend(&panel_config.input_and_logs);
    if let Some(input) = ctx.app.input.buffer.as_ref() {
        let prompt = ctx.app.input.prompt.clone();
        let cursor_offset_left = config
            .borders
            .as_ref()
            .map(|b| b.contains(&Border::Left))
            .unwrap_or(false) as u16
            + prompt.chars().map(|c| unicode_width::UnicodeWidthChar::width(c).unwrap_or(0) as u16).sum::<u16>();
        let cursor_offset_right = config
            .borders
            .as_ref()
            .map(|b| b.contains(&Border::Right))
            .unwrap_or(false) as u16
            + 1;
        let offset_width = cursor_offset_left + cursor_offset_right;
        let width = area.width.max(offset_width) - offset_width;
        let scroll = input.visual_cursor().max(width as usize) - width as usize;
        let ro = if app_config.general.read_only { " (r)" } else { "" };
        let p = Paragraph::new(Line::from(vec![
            Span::styled(prompt.clone(), tui_style(&app_config.general.prompt.style)),
            Span::raw(input.value.clone()),
        ]))
        .scroll((0, scroll as u16))
        .block(block(
            &config,
            format!(" Input [{}{}]{} ", ctx.app.mode.name, ro, sel_indicator(ctx.app)),
        ));
        f.render_widget(p, area);
        let cx = area.x + cursor_offset_left + (input.visual_cursor() - scroll) as u16;
        let cy = area.y + if config.borders.as_ref().map(|b| b.contains(&Border::Top)).unwrap_or(false) { 1 } else { 0 };
        f.set_cursor_position((cx, cy));
    }
}

fn draw_logs(ctx: &mut DrawCtx, f: &mut Frame, area: Rect) {
    let app_config = &ctx.app.config;
    let panel_config = &app_config.general.panel_ui;
    let config = panel_config.default.extend(&panel_config.input_and_logs);
    let logs_config = &app_config.general.logs;
    let logs = if ctx.app.logs_hidden {
        vec![]
    } else {
        ctx.app
            .logs
            .iter()
            .rev()
            .take(area.height as usize)
            .map(|l| {
                let time = l.created_at.hms();
                let cfg = match l.level {
                    LogLevel::Info => &logs_config.info,
                    LogLevel::Warning => &logs_config.warning,
                    LogLevel::Success => &logs_config.success,
                    LogLevel::Error => &logs_config.error,
                };
                let txt = format!(
                    "{}|{}) {}",
                    time,
                    cfg.format.clone().unwrap_or_default(),
                    l.message
                );
                ListItem::new(Text::from(txt)).style(tui_style(&cfg.style))
            })
            .collect::<Vec<ListItem>>()
    };
    let logs_count = ctx.app.logs.len();
    let logs_count = if logs_count == 0 {
        String::new()
    } else {
        format!(" ({})", logs_count)
    };
    let ro = if app_config.general.read_only { " (r)" } else { "" };
    let l = List::new(logs).block(block(
        &config,
        format!(
            " Logs{} [{}{}]{} ",
            logs_count,
            ctx.app.mode.name,
            ro,
            sel_indicator(ctx.app)
        ),
    ));
    f.render_widget(l, area);
}

fn draw_static(ctx: &mut DrawCtx, f: &mut Frame, area: Rect, panel: CustomPanel) {
    let defaultui = ctx.app.config.general.panel_ui.default.clone();
    match panel {
        CustomPanel::CustomParagraph { ui, body } => {
            let config = defaultui.extend(&ui);
            let body = ansi_to_text(&body);
            let p = Paragraph::new(body).block(block(&config, "".into()));
            f.render_widget(p, area);
        }
        CustomPanel::CustomList { ui, body } => {
            let config = defaultui.extend(&ui);
            let items: Vec<ListItem> = body.iter().map(|b| ListItem::new(ansi_to_text(b))).collect();
            let l = List::new(items).block(block(&config, "".into()));
            f.render_widget(l, area);
        }
        CustomPanel::CustomTable {
            ui,
            widths,
            col_spacing,
            body,
        } => {
            let config = defaultui.extend(&ui);
            let rows: Vec<Row> = body
                .iter()
                .map(|cols| Row::new(cols.iter().map(|c| Cell::from(ansi_to_text(c))).collect::<Vec<_>>()))
                .collect();
            let widths: Vec<TuiConstraint> = widths
                .iter()
                .map(|c| to_tui_constraint(c, ctx.screen, area))
                .collect();
            let t = Table::new(rows, widths)
                .column_spacing(col_spacing.unwrap_or(1))
                .block(block(&config, "".into()));
            f.render_widget(t, area);
        }
        CustomPanel::CustomLayout(layout) => draw_layout(ctx, layout, f, area),
    }
}

#[derive(Serialize)]
struct ContentRendererArg {
    app: lua_api::CallLuaArgLite,
    layout_size: Size,
    screen_size: Size,
    scrolltop: usize,
}

fn draw_dynamic(ctx: &mut DrawCtx, f: &mut Frame, area: Rect, func: &str) {
    let arg = ContentRendererArg {
        app: lua_api::CallLuaArgLite::from_app(ctx.app),
        layout_size: layout_size(area),
        screen_size: layout_size(ctx.screen),
        scrolltop: ctx
            .app
            .directory_buffer
            .as_ref()
            .map(|d| d.scroll_state.skipped_rows)
            .unwrap_or(0),
    };
    let v = crate::lua::serde::to_lua(&arg).unwrap_or(crate::lua::Value::Nil);
    let panel: Result<CustomPanel, String> = lua_api::call_fn_de(ctx.lua, func, v);
    match panel {
        Ok(p) => draw_static(ctx, f, area, p),
        Err(e) => {
            let defaultui = ctx.app.config.general.panel_ui.default.clone();
            let p = Paragraph::new(e).block(block(&defaultui, format!(" {} ", func)));
            f.render_widget(p, area);
        }
    }
}

