use ratatui::layout::{Constraint as TuiConstraint, Direction, Layout as TuiLayout, Rect};
use ratatui::style::{Color as TuiColor, Modifier as TuiModifier, Style as TuiStyle};
use ratatui::text::{Line, Span, Text};
use ratatui::widgets::{Block, BorderType as TuiBorderType, Borders, Cell, List, ListItem, Paragraph, Row, Table};
use ratatui::Frame;
use serde::Serialize;
use std::cmp::Ordering;

use crate::ansi::ansi_to_text;
use crate::app::{App, LogLevel, Size};
use crate::config::*;
use crate::lua::Lua;
use crate::lua_api;
use crate::node::{Node, Permissions, ResolvedNode};

// ---------------- conversions ----------------

pub fn tui_color(c: Color) -> TuiColor {
    match c {
        Color::Reset => TuiColor::Reset,
        Color::Black => TuiColor::Black,
        Color::Red => TuiColor::Red,
        Color::Green => TuiColor::Green,
        Color::Yellow => TuiColor::Yellow,
        Color::Blue => TuiColor::Blue,
        Color::Magenta => TuiColor::Magenta,
        Color::Cyan => TuiColor::Cyan,
        Color::Gray => TuiColor::Gray,
        Color::DarkGray => TuiColor::DarkGray,
        Color::LightRed => TuiColor::LightRed,
        Color::LightGreen => TuiColor::LightGreen,
        Color::LightYellow => TuiColor::LightYellow,
        Color::LightBlue => TuiColor::LightBlue,
        Color::LightMagenta => TuiColor::LightMagenta,
        Color::LightCyan => TuiColor::LightCyan,
        Color::White => TuiColor::White,
        Color::Rgb(r, g, b) => TuiColor::Rgb(r, g, b),
        Color::Indexed(i) => TuiColor::Indexed(i),
    }
}

pub fn tui_modifier(m: Modifier) -> TuiModifier {
    match m {
        Modifier::Bold => TuiModifier::BOLD,
        Modifier::Dim => TuiModifier::DIM,
        Modifier::Italic => TuiModifier::ITALIC,
        Modifier::Underlined => TuiModifier::UNDERLINED,
        Modifier::SlowBlink => TuiModifier::SLOW_BLINK,
        Modifier::RapidBlink => TuiModifier::RAPID_BLINK,
        Modifier::Reversed => TuiModifier::REVERSED,
        Modifier::Hidden => TuiModifier::HIDDEN,
        Modifier::CrossedOut => TuiModifier::CROSSED_OUT,
    }
}

pub fn tui_style(s: &Style) -> TuiStyle {
    let mut st = TuiStyle::default();
    if let Some(fg) = s.fg {
        st = st.fg(tui_color(fg));
    }
    if let Some(bg) = s.bg {
        st = st.bg(tui_color(bg));
    }
    let mut add = TuiModifier::empty();
    for m in s.add_modifiers.iter().flatten() {
        add |= tui_modifier(*m);
    }
    let mut sub = TuiModifier::empty();
    for m in s.sub_modifiers.iter().flatten() {
        sub |= tui_modifier(*m);
    }
    st.add_modifier = add;
    st.sub_modifier = sub;
    st
}

pub fn to_tui_constraint(c: &Constraint, screen: Rect, layout: Rect) -> TuiConstraint {
    match *c {
        Constraint::Percentage(n) => TuiConstraint::Percentage(n),
        Constraint::Ratio(x, y) => TuiConstraint::Ratio(x, y),
        Constraint::Length(n) => TuiConstraint::Length(n),
        Constraint::LengthLessThanScreenHeight(n) => TuiConstraint::Length(screen.height.max(n) - n),
        Constraint::LengthLessThanScreenWidth(n) => TuiConstraint::Length(screen.width.max(n) - n),
        Constraint::LengthLessThanLayoutHeight(n) => TuiConstraint::Length(layout.height.max(n) - n),
        Constraint::LengthLessThanLayoutWidth(n) => TuiConstraint::Length(layout.width.max(n) - n),
        Constraint::Max(n) => TuiConstraint::Max(n),
        Constraint::MaxLessThanScreenHeight(n) => TuiConstraint::Max(screen.height.max(n) - n),
        Constraint::MaxLessThanScreenWidth(n) => TuiConstraint::Max(screen.width.max(n) - n),
        Constraint::MaxLessThanLayoutHeight(n) => TuiConstraint::Max(layout.height.max(n) - n),
        Constraint::MaxLessThanLayoutWidth(n) => TuiConstraint::Max(layout.width.max(n) - n),
        Constraint::Min(n) => TuiConstraint::Min(n),
        Constraint::MinLessThanScreenHeight(n) => TuiConstraint::Min(screen.height.max(n) - n),
        Constraint::MinLessThanScreenWidth(n) => TuiConstraint::Min(screen.width.max(n) - n),
        Constraint::MinLessThanLayoutHeight(n) => TuiConstraint::Min(layout.height.max(n) - n),
        Constraint::MinLessThanLayoutWidth(n) => TuiConstraint::Min(layout.width.max(n) - n),
    }
}

fn block<'a>(config: &PanelUiConfig, default_title: String) -> Block<'a> {
    let mut borders = Borders::NONE;
    for b in config.borders.iter().flatten() {
        borders |= match b {
            Border::Top => Borders::TOP,
            Border::Right => Borders::RIGHT,
            Border::Bottom => Borders::BOTTOM,
            Border::Left => Borders::LEFT,
        };
    }
    let bt = match config.border_type {
        Some(BorderType::Rounded) => TuiBorderType::Rounded,
        Some(BorderType::Double) => TuiBorderType::Double,
        Some(BorderType::Thick) => TuiBorderType::Thick,
        _ => TuiBorderType::Plain,
    };
    let title = config.title.format.clone().unwrap_or(default_title);
    Block::default()
        .borders(borders)
        .title(Span::styled(title, tui_style(&config.title.style)))
        .style(tui_style(&config.style))
        .border_type(bt)
        .border_style(tui_style(&config.border_style))
}

// ---------------- help menu ----------------

#[derive(Debug, Clone)]
pub enum HelpMenuLine {
    Paragraph(String),
    KeyMap(String, Vec<String>, String),
}

pub fn help_menu_lines(mode: &Mode, hide_remaps: bool) -> Vec<HelpMenuLine> {
    if let Some(h) = &mode.help {
        return h.lines().map(|l| HelpMenuLine::Paragraph(l.to_string())).collect();
    }
    let mut lines: Vec<HelpMenuLine> = vec![];
    if let Some(e) = &mode.extra_help {
        for l in e.lines() {
            lines.push(HelpMenuLine::Paragraph(l.to_string()));
        }
    }
    let kb = &mode.key_bindings;
    let entries: Vec<(&String, &Action)> = kb.on_key.iter().collect();
    for (i, (k, a)) in entries.iter().enumerate() {
        let help = match &a.help {
            Some(h) => h,
            None => continue,
        };
        // skip if remap of an earlier key
        if entries[..i].iter().any(|(_, a2)| a2.help.is_some() && *a2 == *a) {
            continue;
        }
        let remaps: Vec<String> = if hide_remaps {
            vec![]
        } else {
            entries
                .iter()
                .filter(|(k2, a2)| k2 != k && *a2 == *a)
                .map(|(k2, _)| (*k2).clone())
                .collect()
        };
        lines.push(HelpMenuLine::KeyMap((*k).clone(), remaps, help.clone()));
    }
    let cats: [(&str, &Option<Action>); 8] = [
        ("[a-Z]", &kb.on_alphabet),
        ("[0-9]", &kb.on_number),
        ("[0-Z]", &kb.on_alphanumeric),
        ("[^0-Z]", &kb.on_special_character),
        ("[*]", &kb.on_character),
        ("[nav]", &kb.on_navigation),
        ("[f1-f12]", &kb.on_function),
        ("[default]", &kb.default),
    ];
    for (k, a) in cats {
        if let Some(a) = a {
            if let Some(h) = &a.help {
                lines.push(HelpMenuLine::KeyMap(k.to_string(), vec![], h.clone()));
            }
        }
    }
    lines
}

