pub fn node_type_of(nt: &NodeTypesConfig, node: &Node) -> NodeTypeConfig {
    let mut t = if node.is_symlink {
        nt.symlink.clone()
    } else if node.is_dir {
        nt.directory.clone()
    } else {
        nt.file.clone()
    };
    let mime = &node.mime_essence;
    let mut parts = mime.splitn(2, '/');
    let mtype = parts.next().unwrap_or("");
    let msub = parts.next().unwrap_or("");
    if let Some(m) = nt.mime_essence.get(mtype) {
        if let Some(x) = m.get("*") {
            t = t.extend(x);
        }
        if let Some(x) = m.get(msub) {
            t = t.extend(x);
        }
    }
    if let Some(x) = nt.extension.get(&node.extension) {
        t = t.extend(x);
    }
    if let Some(x) = nt.special.get(&node.relative_path) {
        t = t.extend(x);
    }
    t
}

// ---------------- drawing ----------------

pub struct DrawCtx<'a> {
    pub app: &'a mut App,
    pub lua: &'a mut Lua,
    pub screen: Rect,
}

pub fn draw(f: &mut Frame, app: &mut App, lua: &mut Lua) {
    let screen = f.area();
    let layout = app.mode.layout.clone().unwrap_or_else(|| app.layout.clone());
    let mut ctx = DrawCtx { app, lua, screen };
    draw_layout(&mut ctx, layout, f, screen);
}

fn draw_layout(ctx: &mut DrawCtx, layout: Layout, f: &mut Frame, area: Rect) {
    match layout {
        Layout::Nothing => draw_nothing(ctx, f, area),
        Layout::Table => draw_table(ctx, f, area),
        Layout::SortAndFilter => draw_sort_n_filter(ctx, f, area),
        Layout::HelpMenu => draw_help_menu(ctx, f, area),
        Layout::Selection => draw_selection(ctx, f, area),
        Layout::InputAndLogs => {
            if ctx.app.input.buffer.is_some() {
                draw_input_buffer(ctx, f, area)
            } else {
                draw_logs(ctx, f, area)
            }
        }
        Layout::Static(panel) => draw_static(ctx, f, area, *panel),
        Layout::Dynamic(func) => draw_dynamic(ctx, f, area, &func),
        Layout::CustomContent { title, body } => draw_custom_content(ctx, f, area, title, body),
        Layout::Horizontal { config, splits } => {
            draw_split(ctx, f, area, config, splits, Direction::Horizontal)
        }
        Layout::Vertical { config, splits } => {
            draw_split(ctx, f, area, config, splits, Direction::Vertical)
        }
    }
}

fn draw_split(
    ctx: &mut DrawCtx,
    f: &mut Frame,
    area: Rect,
    config: LayoutConfig,
    splits: Vec<Layout>,
    dir: Direction,
) {
    let constraints: Vec<TuiConstraint> = config
        .constraints
        .clone()
        .unwrap_or_default()
        .iter()
        .map(|c| to_tui_constraint(c, ctx.screen, area))
        .collect();
    let hm = config.horizontal_margin.or(config.margin).unwrap_or(0);
    let vm = config.vertical_margin.or(config.margin).unwrap_or(0);
    let chunks = TuiLayout::default()
        .direction(dir)
        .horizontal_margin(hm)
        .vertical_margin(vm)
        .constraints(constraints)
        .split(area);
    for (split, chunk) in splits.into_iter().zip(chunks.iter()) {
        draw_layout(ctx, split, f, *chunk);
    }
}

fn draw_nothing(ctx: &mut DrawCtx, f: &mut Frame, area: Rect) {
    let config = ctx.app.config.general.panel_ui.default.clone();
    let p = Paragraph::new("").block(block(&config, "".into()));
    f.render_widget(p, area);
}

fn layout_size(area: Rect) -> Size {
    Size {
        x: area.x,
        y: area.y,
        height: area.height,
        width: area.width,
    }
}

fn calc_skipped_rows(
    padding: usize,
    paginated: bool,
    height: usize,
    total: usize,
    focus: usize,
    last_focus: Option<usize>,
    first_visible_row: usize,
) -> usize {
    if paginated {
        return height * (focus / height.max(1));
    }
    let cushion = if height >= padding * 3 {
        padding
    } else if height >= 9 {
        3
    } else if height >= 3 {
        1
    } else {
        0
    };
    let start_cushion_row = first_visible_row + cushion;
    let end_cushion_row = (first_visible_row + height).saturating_sub(cushion + 1);
    match last_focus {
        None => 0,
        Some(_) if focus == 0 => 0,
        Some(_) if focus == total.saturating_sub(1) => total.saturating_sub(height),
        Some(_) if focus > start_cushion_row && focus <= end_cushion_row => first_visible_row,
        Some(lf) => match focus.cmp(&lf) {
            Ordering::Greater => {
                if focus > total.saturating_sub(cushion + 1) {
                    total.saturating_sub(height)
                } else {
                    focus.saturating_sub(height.saturating_sub(cushion + 1))
                }
            }
            Ordering::Less => {
                if focus < cushion {
                    0
                } else if focus > end_cushion_row {
                    first_visible_row
                } else {
                    focus.saturating_sub(cushion)
                }
            }
            Ordering::Equal => first_visible_row,
        },
    }
}

fn draw_table(ctx: &mut DrawCtx, f: &mut Frame, area: Rect) {
    let app_config = ctx.app.config.clone();
    let panel_config = &app_config.general.panel_ui;
    let config = panel_config.default.extend(&panel_config.table);
    let header_height = app_config.general.table.header.height.unwrap_or(1);
    let height: usize = (area.height.max(header_height + 2) - (header_height + 2)) as usize;
    ctx.app.table_height = height;
    let row_style = tui_style(&app_config.general.table.row.style);

    let mut rows: Vec<Row> = vec![];
    let padding = app_config.general.scroll_padding;
    let paginated = app_config.general.paginated_scrolling;
    let mut skip = 0usize;
    if let Some(dir) = ctx.app.directory_buffer.as_mut() {
        let st = &dir.scroll_state;
        let new_skip = calc_skipped_rows(
            padding,
            paginated,
            height,
            dir.total,
            dir.focus,
            st.last_focus,
            st.skipped_rows,
        );
        dir.scroll_state.skipped_rows = new_skip;
        dir.scroll_state.last_focus = Some(dir.focus);
        skip = new_skip;
    }
    let dir = ctx.app.directory_buffer.clone();
    if let Some(dir) = dir.as_ref() {
        let total = dir.total;
        for (index, node) in dir.nodes.iter().enumerate().skip(skip).take(height) {
            let is_focused = dir.focus == index;
            let is_selected = ctx.app.is_selected(node);
            let is_first = index == 0;
            let is_last = index == total.max(1) - 1;
            let tree = app_config
                .general
                .table
                .tree
                .as_ref()
                .map(|t| {
                    if is_last {
                        t.2.format.clone()
                    } else if is_first {
                        t.0.format.clone()
                    } else {
                        t.1.format.clone()
                    }
                })
                .unwrap_or_default()
                .unwrap_or_default();
            let node_type = node_type_of(&app_config.node_types, node);
            let (relative_index, is_before_focus, is_after_focus) = match dir.focus.cmp(&index) {
                Ordering::Greater => (dir.focus - index, true, false),
                Ordering::Less => (index - dir.focus, false, true),
                Ordering::Equal => (0, false, false),
            };
            let g = &app_config.general;
            let mut prefix = g.default_ui.prefix.clone();
            let mut suffix = g.default_ui.suffix.clone();
            let mut style = g.default_ui.style.extend(&node_type.style);
            let ui = if is_focused && is_selected {
                Some(&g.focus_selection_ui)
            } else if is_selected {
                Some(&g.selection_ui)
            } else if is_focused {
                Some(&g.focus_ui)
            } else {
                None
            };
            if let Some(ui) = ui {
                prefix = ui.prefix.clone().or(prefix);
                suffix = ui.suffix.clone().or(suffix);
                style = style.extend(&ui.style);
            }
            let meta = NodeUiMetadata {
                parent: node.parent.clone(),
                relative_path: node.relative_path.clone(),
                absolute_path: node.absolute_path.clone(),
                extension: node.extension.clone(),
                is_symlink: node.is_symlink,
                is_broken: node.is_broken,
                is_dir: node.is_dir,
                is_file: node.is_file,
                is_readonly: node.is_readonly,
                mime_essence: node.mime_essence.clone(),
                size: node.size,
                human_size: node.human_size.clone(),
                permissions: node.permissions,
                created: node.created,
                last_modified: node.last_modified,
                uid: node.uid,
                gid: node.gid,
                canonical: node.canonical.as_ref().map(Into::into),
                symlink: node.symlink.as_ref().map(Into::into),
                index,
                relative_index,
                is_before_focus,
                is_after_focus,
                tree,
                prefix: prefix.unwrap_or_default(),
                suffix: suffix.unwrap_or_default(),
                is_selected,
                is_focused,
                total,
                meta: node_type.meta.clone(),
                style,
            };
            let v = crate::lua::serde::to_lua(&meta).unwrap_or(crate::lua::Value::Nil);
            let cols: Vec<Cell> = app_config
                .general
                .table
                .row
                .cols
                .clone()
                .unwrap_or_default()
                .iter()
                .map(|c| {
                    let out = match &c.format {
                        Some(fmt) => match lua_api::call_fn_string(ctx.lua, fmt, v.clone()) {
                            Ok(s) => s,
                            Err(e) => e,
                        },
                        None => String::new(),
                    };
                    Cell::from(ansi_to_text(&out)).style(tui_style(&c.style))
                })
                .collect();
            rows.push(Row::new(cols).style(row_style));
        }
    }

    let constraints: Vec<TuiConstraint> = app_config
        .general
        .table
        .col_widths
        .clone()
        .unwrap_or_default()
        .iter()
        .map(|c| to_tui_constraint(c, ctx.screen, area))
        .collect();

    let pwd = ctx.app.pwd.clone();
    let pwd = match &ctx.app.vroot {
        Some(v) => {
            let rel = std::path::Path::new(&pwd)
                .strip_prefix(v)
                .map(|p| p.to_string_lossy().to_string())
                .unwrap_or(pwd.clone());
            format!("/{}", rel.trim_start_matches('/'))
        }
        None => pwd,
    };
    let vroot_indicator = if ctx.app.vroot.is_some() { "vroot:" } else { "" };
    let node_count = ctx.app.directory_buffer.as_ref().map(|d| d.total).unwrap_or(0);
    let node_count = if node_count == 0 {
        String::new()
    } else {
        format!("({}) ", node_count)
    };
    let title = format!(" {}{} {}", vroot_indicator, pwd, node_count);

    let header_cols: Vec<Cell> = app_config
        .general
        .table
        .header
        .cols
        .clone()
        .unwrap_or_default()
        .iter()
        .map(|c| {
            Cell::from(Text::from(c.format.clone().unwrap_or_default())).style(tui_style(&c.style))
        })
        .collect();
    let header = Row::new(header_cols)
        .height(header_height)
        .style(tui_style(&app_config.general.table.header.style));

    let table = Table::new(rows, constraints)
        .style(tui_style(&app_config.general.table.style))
        .column_spacing(app_config.general.table.col_spacing.unwrap_or(1))
        .block(block(&config, title))
        .header(header);
    f.render_widget(table, area);
}

fn draw_sort_n_filter(ctx: &mut DrawCtx, f: &mut Frame, area: Rect) {
    let app_config = &ctx.app.config;
    let panel_config = &app_config.general.panel_ui;
    let config = panel_config.default.extend(&panel_config.sort_and_filter);
    let ui = &app_config.general.sort_and_filter_ui;
    let filter_by = &ctx.app.explorer_config.filters;
    let sort_by = &ctx.app.explorer_config.sorters;
    let search = ctx.app.explorer_config.searcher.as_ref();
    let defaultui = &ui.default_identifier;
    let forward = &ui.sort_direction_identifiers.forward;
    let reverse = &ui.sort_direction_identifiers.reverse;
    let orderedui = &ui.search_direction_identifiers.ordered;
    let unorderedui = &ui.search_direction_identifiers.unordered;

    let is_ordered_search = search.as_ref().map(|s| !s.unordered).unwrap_or(false);

    let mut items: Vec<Vec<Span>> = vec![];
    for f in filter_by.iter() {
        let u = ui.filter_identifiers.get(&f.filter).unwrap_or(defaultui);
        items.push(vec![
            Span::styled(
                u.format.clone().unwrap_or_default(),
                tui_style(&defaultui.style.extend(&u.style)),
            ),
            Span::styled(f.input.clone(), tui_style(&defaultui.style.extend(&u.style))),
        ]);
    }
    if let Some(s) = search {
        let u = ui.search_identifiers.get(&s.algorithm).unwrap_or(defaultui);
        let dir = if s.unordered { unorderedui } else { orderedui };
        items.push(vec![
            Span::styled(
                u.format.clone().unwrap_or_default(),
                tui_style(&defaultui.style.extend(&u.style)),
            ),
            Span::styled(s.pattern.clone(), tui_style(&defaultui.style.extend(&u.style))),
            Span::styled(
                dir.format.clone().unwrap_or_default(),
                tui_style(&defaultui.style.extend(&dir.style)),
            ),
        ]);
    }
    if !is_ordered_search {
        for s in sort_by.iter() {
            let u = ui.sorter_identifiers.get(&s.sorter).unwrap_or(defaultui);
            let d = if s.reverse { reverse } else { forward };
            items.push(vec![
                Span::styled(
                    u.format.clone().unwrap_or_default(),
                    tui_style(&defaultui.style.extend(&u.style)),
                ),
                Span::styled(
                    d.format.clone().unwrap_or_default(),
                    tui_style(&defaultui.style.extend(&d.style)),
                ),
            ]);
        }
    }
    let mut spans: Vec<Span> = vec![];
    let sep = Span::styled(
        ui.separator.format.clone().unwrap_or_default(),
        tui_style(&ui.separator.style),
    );
    for (i, it) in items.into_iter().enumerate() {
        if i > 0 {
            spans.push(sep.clone());
        }
        spans.extend(it);
    }
    let count = filter_by.len() + if search.is_some() { 1 } else { 0 }
        + if is_ordered_search { 0 } else { sort_by.len() };
    let p = Paragraph::new(Line::from(spans))
        .block(block(&config, format!(" Sort & filter ({}) ", count)));
    f.render_widget(p, area);
}

fn draw_help_menu(ctx: &mut DrawCtx, f: &mut Frame, area: Rect) {
    let app_config = &ctx.app.config;
    let panel_config = &app_config.general.panel_ui;
    let config = panel_config.default.extend(&panel_config.help_menu);
    let hide = app_config.general.hide_remaps_in_help_menu;
    let lines = help_menu_lines(&ctx.app.mode, hide);
    let rows: Vec<Row> = lines
        .into_iter()
        .map(|l| match l {
            HelpMenuLine::Paragraph(p) => Row::new([Cell::from(p)]),
            HelpMenuLine::KeyMap(k, remaps, h) => {
                if hide {
                    Row::new([Cell::from(k), Cell::from(h)])
                } else {
                    Row::new([Cell::from(k), Cell::from(remaps.join("|")), Cell::from(h)])
                }
            }
        })
        .collect();
    let widths: Vec<TuiConstraint> = if hide {
        vec![TuiConstraint::Percentage(20), TuiConstraint::Percentage(80)]
    } else {
        vec![
            TuiConstraint::Percentage(20),
            TuiConstraint::Percentage(20),
            TuiConstraint::Percentage(60),
        ]
    };
    let ro = if app_config.general.read_only { " (r)" } else { "" };
    let t = Table::new(rows, widths).block(block(
        &config,
        format!(" Help [{}{}] ", ctx.app.mode.name, ro),
    ));
    f.render_widget(t, area);
}

fn draw_selection(ctx: &mut DrawCtx, f: &mut Frame, area: Rect) {
    let app_config = ctx.app.config.clone();
    let panel_config = &app_config.general.panel_ui;
    let config = panel_config.default.extend(&panel_config.selection);
    let item = &app_config.general.selection.item;
    let height = (area.height as usize).saturating_sub(2);
    let total = ctx.app.selection.len();
    let sel: Vec<Node> = ctx.app.selection.iter().rev().take(height).rev().cloned().collect();
    let items: Vec<ListItem> = sel
        .iter()
        .map(|n| {
            let out = match &item.format {
                Some(fmt) => {
                    let v = crate::lua::serde::to_lua(n).unwrap_or(crate::lua::Value::Nil);
                    match lua_api::call_fn_string(ctx.lua, fmt, v) {
                        Ok(s) => s,
                        Err(e) => e,
                    }
                }
                None => n.absolute_path.clone(),
            };
            ListItem::new(ansi_to_text(&out)).style(tui_style(&item.style))
        })
        .collect();
    let title = if total == 0 {
        " Selection ".to_string()
    } else {
        format!(" Selection ({}) ", total)
    };
    let l = List::new(items).block(block(&config, title));
    f.render_widget(l, area);
}

fn sel_indicator(app: &App) -> String {
    let n = app.selection.len();
    if n == 0 {
        String::new()
    } else {
        format!(" {{{} sel}}", n)
    }
}

fn draw_input_buffer(ctx: &mut DrawCtx, f: &mut Frame, area: Rect) {
    let app_config = &ctx.app.config;
    let panel_config = &app_config.general.panel_ui;
    let config = panel_config.default.extend(&panel_config.input_and_logs);
    if let Some(input) = ctx.app.input.buffer.as_ref() {
        let prompt = ctx.app.input.prompt.clone();
        let cursor_offset_left = config
            .borders
            .as_ref()
            .map(|b| b.contains(&Border::Left))
            .unwrap_or(false) as u16
            + prompt.chars().map(|c| unicode_width::UnicodeWidthChar::width(c).unwrap_or(0) as u16).sum::<u16>();
        let cursor_offset_right = config
            .borders
            .as_ref()
            .map(|b| b.contains(&Border::Right))
            .unwrap_or(false) as u16
            + 1;
        let offset_width = cursor_offset_left + cursor_offset_right;
        let width = area.width.max(offset_width) - offset_width;
        let scroll = input.visual_cursor().max(width as usize) - width as usize;
        let ro = if app_config.general.read_only { " (r)" } else { "" };
        let p = Paragraph::new(Line::from(vec![
            Span::styled(prompt.clone(), tui_style(&app_config.general.prompt.style)),
            Span::raw(input.value.clone()),
        ]))
        .scroll((0, scroll as u16))
        .block(block(
            &config,
            format!(" Input [{}{}]{} ", ctx.app.mode.name, ro, sel_indicator(ctx.app)),
        ));
        f.render_widget(p, area);
        let cx = area.x + cursor_offset_left + (input.visual_cursor() - scroll) as u16;
