// ---------------- error formatting ----------------

pub fn format_runtime_error(lua: &Lua, e: &LuaError) -> String {
    let _ = lua;
    let msg = match &e.value {
        Value::Str(s) => s.to_str_lossy(),
        Value::Nil => "nil".into(),
        v => crate::lua::interp::tostring_basic(v),
    };
    let tb = match &e.traceback {
        Some(t) if !e.needs_pos() => t.clone(),
        _ => String::new(),
    };
    if tb.is_empty() {
        format!("runtime error: {}", msg)
    } else {
        format!("runtime error: {}\n{}", msg, tb)
    }
}

// ---------------- function calls ----------------

pub fn resolve_fn(lua: &mut Lua, path: &str) -> Result<Value, String> {
    let full = format!("xplr.fn.{}", path);
    let mut parts = full.split('.');
    let mut cur = Value::Table(lua.globals.clone());
    loop {
        match parts.next() {
            Some(p) => {
                let next = match &cur {
                    Value::Table(t) => t.borrow().get_str(p),
                    _ => Value::Nil,
                };
                match next {
                    Value::Table(_) => cur = next,
                    Value::Func(_) => return Ok(next),
                    v => return Err(format!("{} is not a function", debug_value_name(&v))),
                }
            }
            None => return Err("Invalid path".into()),
        }
    }
}

fn debug_value_name(v: &Value) -> String {
    match v {
        Value::Nil => "Nil".into(),
        Value::Bool(b) => format!("Boolean({})", b),
        Value::Num(n) => {
            if *n == n.trunc() && n.abs() < 1e15 {
                format!("Integer({})", *n as i64)
            } else {
                format!("Number({:?})", n)
            }
        }
        Value::Str(s) => format!("String({:?})", s.to_str_lossy()),
        Value::UserData(_) => "UserData".into(),
        Value::Table(_) => "Table".into(),
        Value::Func(_) => "Function".into(),
    }
}

pub fn call_value(lua: &mut Lua, f: &Value, arg: Value) -> Result<Value, String> {
    let depth = lua.depth;
    let st = lua.stack.len();
    match lua.call(f, vec![arg]) {
        Ok(r) => Ok(r.into_iter().next().unwrap_or(Value::Nil)),
        Err(mut e) => {
            lua.depth = depth;
            lua.stack.truncate(st);
            if e.needs_pos() {
                e = LuaError::val(e.value.clone());
            }
            Err(format_runtime_error(lua, &e))
        }
    }
}

pub fn call_fn(lua: &mut Lua, path: &str, arg: Value) -> Result<Value, String> {
    let f = resolve_fn(lua, path)?;
    call_value(lua, &f, arg)
}

pub fn call_fn_string(lua: &mut Lua, path: &str, arg: Value) -> Result<String, String> {
    let v = call_fn(lua, path, arg)?;
    from_lua::<String>(v).map_err(|e| format!("deserialize error: {}", e))
}

pub fn call_fn_de<T: for<'de> Deserialize<'de>>(lua: &mut Lua, path: &str, arg: Value) -> Result<T, String> {
    let v = call_fn(lua, path, arg)?;
    from_lua::<T>(v).map_err(|e| format!("deserialize error: {}", e))
}

