fn is_ident(s: &str) -> bool {
    let mut c = s.chars();
    match c.next() {
        Some(f) if f.is_ascii_alphabetic() || f == '_' => {}
        _ => return false,
    }
    c.all(|x| x.is_ascii_alphanumeric() || x == '_')
}

fn debug_str(s: &str) -> String {
    format!("{:?}", s)
}

fn debug_fmt(v: &Value, indent: usize, out: &mut String, seen: &mut Vec<usize>) {
    match v {
        Value::Nil => out.push_str("nil"),
        Value::Bool(b) => out.push_str(if *b { "true" } else { "false" }),
        Value::Num(n) => out.push_str(&crate::lua::value::fmt_num(*n)),
        Value::Str(s) => out.push_str(&debug_str(&s.to_str_lossy())),
        Value::Func(_) => out.push_str(&format!("function: 0x{:x}", v.ptr())),
        Value::UserData(_) => {
            if is_null(v) {
                out.push_str("userdata: NULL")
            } else {
                out.push_str(&format!("userdata: 0x{:x}", v.ptr()))
            }
        }
        Value::Table(t) => {
            let p = v.ptr();
            if seen.contains(&p) {
                out.push_str(&format!("table: 0x{:x}", p));
                return;
            }
            let mut pairs = t.borrow().iter_pairs();
            if pairs.is_empty() {
                out.push_str("{}");
                return;
            }
            seen.push(p);
            let n = t.borrow().len();
            let is_seq = n == pairs.len();
            pairs.sort_by(|(a, _), (b, _)| match (a, b) {
                (Value::Num(x), Value::Num(y)) => x.partial_cmp(y).unwrap_or(std::cmp::Ordering::Equal),
                (Value::Num(_), _) => std::cmp::Ordering::Less,
                (_, Value::Num(_)) => std::cmp::Ordering::Greater,
                (Value::Str(x), Value::Str(y)) => x.as_bytes().cmp(y.as_bytes()),
                (Value::Str(_), _) => std::cmp::Ordering::Less,
                (_, Value::Str(_)) => std::cmp::Ordering::Greater,
                _ => std::cmp::Ordering::Equal,
            });
            out.push_str("{\n");
            let pad = "  ".repeat(indent + 1);
            for (k, val) in pairs {
                out.push_str(&pad);
                if !is_seq {
                    match &k {
                        Value::Str(s) if is_ident(&s.to_str_lossy()) => {
                            out.push_str(&s.to_str_lossy());
                        }
                        _ => {
                            out.push('[');
                            debug_fmt(&k, indent + 1, out, seen);
                            out.push(']');
                        }
                    }
                    out.push_str(" = ");
                }
                debug_fmt(&val, indent + 1, out, seen);
                out.push_str(",\n");
            }
            out.push_str(&"  ".repeat(indent));
            out.push('}');
            seen.pop();
        }
    }
}

pub fn debug_value(v: &Value) -> String {
    let mut s = String::new();
    debug_fmt(v, 0, &mut s, &mut vec![]);
    s
}

// ---------------- json/yaml bridge ----------------

pub fn lua_to_json(v: &Value) -> Result<serde_json::Value, String> {
    Ok(match v {
        Value::Nil => serde_json::Value::Null,
        Value::Bool(b) => serde_json::Value::Bool(*b),
        Value::Num(n) => {
            if *n == n.trunc() && n.abs() < 9.2e18 {
                if *n >= 0.0 {
                    serde_json::Value::from(*n as u64)
                } else {
                    serde_json::Value::from(*n as i64)
                }
            } else {
                serde_json::Number::from_f64(*n)
                    .map(serde_json::Value::Number)
                    .unwrap_or(serde_json::Value::Null)
            }
        }
        Value::Str(s) => serde_json::Value::String(s.to_str_lossy()),
        Value::Table(t) => {
            let tb = t.borrow();
            if let Some(n) = crate::lua::serde::table_seq_len(&tb) {
                let mut arr = vec![];
                for i in 1..=n {
                    arr.push(lua_to_json(&tb.get_int(i))?);
                }
                serde_json::Value::Array(arr)
            } else {
                let mut m = serde_json::Map::new();
                for (k, val) in tb.iter_pairs() {
                    let ks = match &k {
                        Value::Str(s) => s.to_str_lossy(),
                        Value::Num(n) => crate::lua::value::fmt_num(*n),
                        _ => return Err("unsupported key type".into()),
                    };
                    m.insert(ks, lua_to_json(&val)?);
                }
                serde_json::Value::Object(m)
            }
        }
        Value::Func(_) => return Err("serialize error: cannot serialize <function>".into()),
        Value::UserData(_) => {
            if is_null(v) {
                serde_json::Value::Null
            } else {
                return Err("serialize error: cannot serialize <userdata>".into());
            }
        }
    })
}

pub fn json_to_lua(v: &serde_json::Value) -> Value {
    match v {
        serde_json::Value::Null => null_value(),
        serde_json::Value::Bool(b) => Value::Bool(*b),
        serde_json::Value::Number(n) => Value::Num(n.as_f64().unwrap_or(0.0)),
        serde_json::Value::String(s) => Value::str(s),
        serde_json::Value::Array(a) => {
            let mut t = Table::new();
            for x in a {
                t.arr.push(json_to_lua(x));
            }
            Value::table(t)
        }
        serde_json::Value::Object(m) => {
            let mut t = Table::new();
            for (k, x) in m {
                t.set_str(k, json_to_lua(x));
            }
            Value::table(t)
        }
    }
}

fn yaml_to_json(v: serde_yaml::Value) -> serde_json::Value {
    match v {
        serde_yaml::Value::Null => serde_json::Value::Null,
        serde_yaml::Value::Bool(b) => serde_json::Value::Bool(b),
        serde_yaml::Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                serde_json::Value::from(i)
            } else if let Some(u) = n.as_u64() {
                serde_json::Value::from(u)
            } else {
                serde_json::Number::from_f64(n.as_f64().unwrap_or(0.0))
                    .map(serde_json::Value::Number)
                    .unwrap_or(serde_json::Value::Null)
            }
        }
        serde_yaml::Value::String(s) => serde_json::Value::String(s),
        serde_yaml::Value::Sequence(s) => {
            serde_json::Value::Array(s.into_iter().map(yaml_to_json).collect())
        }
        serde_yaml::Value::Mapping(m) => {
            let mut o = serde_json::Map::new();
            for (k, v) in m {
                let ks = match k {
                    serde_yaml::Value::String(s) => s,
                    other => serde_yaml::to_string(&other)
                        .unwrap_or_default()
                        .trim_end()
                        .to_string(),
                };
                o.insert(ks, yaml_to_json(v));
            }
            serde_json::Value::Object(o)
        }
        serde_yaml::Value::Tagged(t) => yaml_to_json(t.value),
    }
}

