fn ansi_bg(c: &Color) -> Option<String> {
    Some(match c {
        Color::Reset => return None,
        Color::Black => "40".into(),
        Color::Red => "41".into(),
        Color::Green => "42".into(),
        Color::Yellow => "43".into(),
        Color::Blue => "44".into(),
        Color::Magenta => "45".into(),
        Color::Cyan => "46".into(),
        Color::Gray => "107".into(),
        Color::DarkGray => "100".into(),
        Color::LightRed => "101".into(),
        Color::LightGreen => "102".into(),
        Color::LightYellow => "103".into(),
        Color::LightBlue => "104".into(),
        Color::LightMagenta => "105".into(),
        Color::LightCyan => "106".into(),
        Color::White => "47".into(),
        Color::Rgb(r, g, b) => format!("48;2;{};{};{}", r, g, b),
        Color::Indexed(i) => format!("48;5;{}", i),
    })
}

pub fn paint(s: &str, style: &Style) -> String {
    let mut codes: Vec<String> = vec![];
    let has = |m: Modifier| {
        style
            .add_modifiers
            .as_ref()
            .map(|a| a.contains(&m))
            .unwrap_or(false)
    };
    if has(Modifier::Bold) {
        codes.push("1".into());
    }
    if has(Modifier::Dim) {
        codes.push("2".into());
    }
    if has(Modifier::Italic) {
        codes.push("3".into());
    }
    if has(Modifier::Underlined) {
        codes.push("4".into());
    }
    if has(Modifier::SlowBlink) || has(Modifier::RapidBlink) {
        codes.push("5".into());
    }
    if has(Modifier::Reversed) {
        codes.push("7".into());
    }
    if has(Modifier::Hidden) {
        codes.push("8".into());
    }
    if has(Modifier::CrossedOut) {
        codes.push("9".into());
    }
    if let Some(bg) = style.bg.as_ref().and_then(ansi_bg) {
        codes.push(bg);
    }
    if let Some(fg) = style.fg.as_ref().and_then(ansi_fg) {
        codes.push(fg);
    }
    if codes.is_empty() {
        return s.to_string();
    }
    format!("\x1b[{}m{}\x1b[0m", codes.join(";"), s)
}

pub fn style_mix(styles: &[Style]) -> Style {
    let mut out = Style::default();
    for s in styles {
        out = out.extend(s);
    }
    out
}

// ---------------- textwrap ----------------

fn split_words(s: &str) -> Vec<(String, String)> {
    // returns (word, trailing whitespace)
    let mut out = vec![];
    let mut word = String::new();
    let mut ws = String::new();
    for c in s.chars() {
        if c == ' ' {
            ws.push(c);
        } else {
            if !ws.is_empty() {
                out.push((std::mem::take(&mut word), std::mem::take(&mut ws)));
            }
            word.push(c);
            if c == '-' {
                out.push((std::mem::take(&mut word), String::new()));
            }
        }
    }
    if !word.is_empty() || !ws.is_empty() {
        out.push((word, ws));
    }
    out.retain(|(w, s)| !w.is_empty() || !s.is_empty());
    out
}

fn uw(s: &str) -> usize {
    unicode_width::UnicodeWidthStr::width(s)
}

pub fn textwrap(text: &str, width: usize, initial: &str, subsequent: &str, break_words: bool) -> Vec<String> {
    let mut lines_out = vec![];
    for para in text.split('\n') {
        let words = split_words(para);
        let mut lines: Vec<String> = vec![];
        let mut cur = String::new();
        let mut cur_ws = String::new();
        let mut first = lines_out.is_empty() && lines.is_empty();
        let indent = |first: bool| if first { initial } else { subsequent };
        let mut cur_w = 0usize;
        let mut has_word = false;
        let mut pending: Vec<(String, String)> = words.into_iter().rev().collect();
        while let Some((w, ws)) = pending.pop() {
            let ind = indent(first);
            let avail = width.saturating_sub(uw(ind)).max(1);
            let ww = uw(&w);
            if has_word && cur_w + uw(&cur_ws) + ww > avail {
                lines.push(format!("{}{}", ind, cur));
                first = false;
                cur = String::new();
                cur_ws = String::new();
                cur_w = 0;
                has_word = false;
                pending.push((w, ws));
                continue;
            }
            if !has_word && ww > avail && break_words {
                // split the word
                let mut part = String::new();
                let mut pw = 0;
                let mut rest = String::new();
                let mut done = false;
                for c in w.chars() {
                    let cw = unicode_width::UnicodeWidthChar::width(c).unwrap_or(0);
                    if !done && pw + cw <= avail {
                        part.push(c);
                        pw += cw;
                    } else {
                        done = true;
                        rest.push(c);
                    }
                }
                lines.push(format!("{}{}", ind, part));
                first = false;
                pending.push((rest, ws));
                continue;
            }
            cur.push_str(&cur_ws);
            cur.push_str(&w);
            cur_w = uw(&cur);
            cur_ws = ws;
            has_word = true;
        }
        if has_word || lines.is_empty() {
            let ind = indent(first);
            lines.push(format!("{}{}", ind, cur));
        }
        lines_out.extend(lines);
    }
    lines_out
}

// ---------------- setup ----------------

fn opt_table_field(v: &Value, k: &str) -> Value {
    match v {
        Value::Table(t) => t.borrow().get_str(k),
        _ => Value::Nil,
    }
}

fn rel_config(v: &Value) -> RelativityConfig {
    RelativityConfig {
        base: match opt_table_field(v, "base") {
            Value::Str(s) => Some(s.to_str_lossy()),
            _ => None,
        },
        with_prefix_dots: opt_table_field(v, "with_prefix_dots").truthy(),
        without_suffix_dots: opt_table_field(v, "without_suffix_dots").truthy(),
    }
}

fn cwd() -> String {
    std::env::current_dir()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_else(|_| "/".into())
}

fn rerr(s: impl Into<String>) -> LuaError {
    LuaError::rt(s.into())
}

fn reg(t: &Rc<RefCell<Table>>, name: &str, f: impl Fn(&mut Lua, Vec<Value>) -> crate::lua::value::LResult<Vec<Value>> + 'static) {
    t.borrow_mut().set_str(name, Lua::native(name, f));
}

pub fn create_util(lua: &mut Lua) -> Value {
    let u = Rc::new(RefCell::new(Table::new()));
    reg(&u, "version", |_l, _a| {
        let mut t = Table::new();
        t.set_str("major", Value::Num(1.0));
        t.set_str("minor", Value::Num(1.0));
        t.set_str("patch", Value::Num(0.0));
        Ok(vec![Value::table(t)])
    });
    reg(&u, "debug", |_l, a| {
        let v = a.into_iter().next().unwrap_or(Value::Nil);
        let s = debug_value(&v);
        println!("{}", s);
        Ok(vec![Value::str(&s)])
    });
    reg(&u, "clone", |_l, a| {
        let v = a.into_iter().next().unwrap_or(Value::Nil);
        fn clone(v: &Value) -> Value {
            match v {
                Value::Table(t) => {
                    let tb = t.borrow();
                    let mut n = Table::new();
                    for (k, x) in tb.iter_pairs() {
                        let _ = n.set(clone(&k), clone(&x));
                    }
                    n.meta = tb.meta.clone();
                    Value::table(n)
                }
                o => o.clone(),
            }
        }
        Ok(vec![clone(&v)])
    });
    reg(&u, "exists", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "exists")?).into_owned();
        Ok(vec![Value::Bool(std::path::Path::new(&p).symlink_metadata().is_ok())])
    });
    reg(&u, "is_dir", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "is_dir")?).into_owned();
        Ok(vec![Value::Bool(std::path::Path::new(&p).is_dir())])
    });
    reg(&u, "is_file", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "is_file")?).into_owned();
        Ok(vec![Value::Bool(std::path::Path::new(&p).is_file())])
    });
    reg(&u, "is_symlink", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "is_symlink")?).into_owned();
        Ok(vec![Value::Bool(
            std::path::Path::new(&p)
                .symlink_metadata()
                .map(|m| m.file_type().is_symlink())
                .unwrap_or(false),
        )])
    });
    reg(&u, "is_absolute", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "is_absolute")?).into_owned();
        Ok(vec![Value::Bool(std::path::Path::new(&p).is_absolute())])
    });
    reg(&u, "path_split", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "path_split")?).into_owned();
        let mut t = Table::new();
        for c in std::path::Path::new(&p).components() {
            t.arr.push(Value::str(&c.as_os_str().to_string_lossy()));
        }
        Ok(vec![Value::table(t)])
    });
    reg(&u, "node", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "node")?).into_owned();
        let ap = path_util::absolutize(&p, &cwd());
        let pb = std::path::PathBuf::from(&ap);
        match (pb.parent(), pb.file_name()) {
            (Some(parent), Some(name)) => {
                let n = Node::new(
                    parent.to_string_lossy().to_string(),
                    name.to_string_lossy().to_string(),
                );
                Ok(vec![to_lua(&n).map_err(|e| rerr(e.0))?])
            }
            _ => Ok(vec![Value::Nil]),
        }
    });
    reg(&u, "node_type", |l, a| {
        let node: Node = from_lua(a.first().cloned().unwrap_or(Value::Nil))
            .map_err(|e| rerr(format!("deserialize error: {}", e)))?;
        let cfg_v = match a.get(1) {
            Some(v) if !v.is_nil() => v.clone(),
            _ => {
                let x = l.get_global("xplr");
                let c = opt_table_field(&x, "config");
                opt_table_field(&c, "node_types")
            }
        };
        let cfg: NodeTypesConfig =
            from_lua(cfg_v).map_err(|e| rerr(format!("deserialize error: {}", e)))?;
        let nt = crate::ui::node_type_of(&cfg, &node);
        Ok(vec![to_lua(&nt).map_err(|e| rerr(e.0))?])
    });
    reg(&u, "dirname", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "dirname")?).into_owned();
        Ok(vec![match std::path::Path::new(&p).parent() {
            Some(x) => Value::str(&x.to_string_lossy()),
            None => Value::Nil,
        }])
    });
    reg(&u, "basename", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "basename")?).into_owned();
        Ok(vec![match std::path::Path::new(&p).file_name() {
            Some(x) => Value::str(&x.to_string_lossy()),
            None => Value::Nil,
        }])
    });
    reg(&u, "absolute", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "absolute")?).into_owned();
        Ok(vec![Value::str(&path_util::absolutize(&p, &cwd()))])
    });
    reg(&u, "relative_to", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "relative_to")?).into_owned();
        let cfg = rel_config(a.get(1).unwrap_or(&Value::Nil));
        Ok(vec![Value::str(&path_util::relative_to(&p, &cfg, &cwd()))])
    });
    reg(&u, "shorten", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "shorten")?).into_owned();
        let cfg = rel_config(a.get(1).unwrap_or(&Value::Nil));
        Ok(vec![Value::str(&path_util::shorten(&p, &cfg, &cwd()))])
    });
    reg(&u, "explore", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "explore")?).into_owned();
        let cfg: ExplorerConfig = match a.get(1) {
            Some(v) if !v.is_nil() => {
                from_lua(v.clone()).map_err(|e| rerr(format!("deserialize error: {}", e)))?
            }
            _ => ExplorerConfig::default(),
        };
        let ap = path_util::absolutize(&p, &cwd());
        let nodes = crate::explorer::explore(&ap, &cfg).map_err(|e| rerr(io_error_string(&e)))?;
        Ok(vec![to_lua(&nodes).map_err(|e| rerr(e.0))?])
    });
    reg(&u, "shell_execute", |_l, a| {
        let prog = String::from_utf8_lossy(&check_str(&a, 0, "shell_execute")?).into_owned();
        let args: Vec<String> = match a.get(1) {
            Some(Value::Table(t)) => {
                let n = t.borrow().len();
                (1..=n)
                    .map(|i| match t.borrow().get_int(i) {
                        Value::Str(s) => s.to_str_lossy(),
                        Value::Num(n) => crate::lua::value::fmt_num(n),
                        _ => String::new(),
                    })
                    .collect()
            }
            _ => vec![],
        };
        let out = std::process::Command::new(&prog)
            .args(&args)
            .stdin(std::process::Stdio::null())
            .output()
            .map_err(|e| rerr(io_error_string(&e)))?;
        let mut t = Table::new();
        t.set_str("stdout", Value::bytes(&out.stdout));
        t.set_str("stderr", Value::bytes(&out.stderr));
        t.set_str(
            "returncode",
            match out.status.code() {
                Some(c) => Value::Num(c as f64),
                None => Value::Nil,
            },
        );
        Ok(vec![Value::table(t)])
    });
    reg(&u, "shell_quote", |_l, a| {
        let s = String::from_utf8_lossy(&check_str(&a, 0, "shell_quote")?).into_owned();
        Ok(vec![Value::str(&path_util::shell_quote(&s))])
    });
    reg(&u, "shell_escape", |_l, a| {
        let s = String::from_utf8_lossy(&check_str(&a, 0, "shell_escape")?).into_owned();
        Ok(vec![Value::str(&path_util::shell_escape(&s))])
    });
    reg(&u, "from_json", |_l, a| {
        let s = String::from_utf8_lossy(&check_str(&a, 0, "from_json")?).into_owned();
        let v: serde_json::Value = serde_json::from_str(&s).map_err(|e| rerr(e.to_string()))?;
        Ok(vec![json_to_lua(&v)])
    });
    reg(&u, "to_json", |_l, a| {
        let v = a.first().cloned().unwrap_or(Value::Nil);
        let pretty = opt_table_field(a.get(1).unwrap_or(&Value::Nil), "pretty").truthy();
        let j = lua_to_json(&v).map_err(rerr)?;
        let s = if pretty {
            serde_json::to_string_pretty(&j)
        } else {
            serde_json::to_string(&j)
        }
        .map_err(|e| rerr(e.to_string()))?;
        Ok(vec![Value::str(&s)])
    });
    reg(&u, "from_yaml", |_l, a| {
        let s = String::from_utf8_lossy(&check_str(&a, 0, "from_yaml")?).into_owned();
        let v: serde_yaml::Value = serde_yaml::from_str(&s).map_err(|e| rerr(e.to_string()))?;
        Ok(vec![json_to_lua(&yaml_to_json(v))])
    });
    reg(&u, "to_yaml", |_l, a| {
        let v = a.first().cloned().unwrap_or(Value::Nil);
        let j = lua_to_json(&v).map_err(rerr)?;
        let s = serde_yaml::to_string(&j).map_err(|e| rerr(e.to_string()))?;
        Ok(vec![Value::str(&s)])
    });
    let lsc = Rc::new(LsColors::from_env());
    reg(&u, "lscolor", move |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "lscolor")?).into_owned();
        let st = lsc.style_for_path(std::path::Path::new(&p));
        Ok(vec![to_lua(&st).map_err(|e| rerr(e.0))?])
    });
    reg(&u, "paint", |_l, a| {
        let s = String::from_utf8_lossy(&check_str(&a, 0, "paint")?).into_owned();
        let st: Style = match a.get(1) {
            Some(v) if !v.is_nil() => {
                from_lua(v.clone()).map_err(|e| rerr(format!("deserialize error: {}", e)))?
            }
            _ => Style::default(),
        };
        Ok(vec![Value::str(&paint(&s, &st))])
    });
    reg(&u, "style_mix", |_l, a| {
        let styles: Vec<Style> = from_lua(a.first().cloned().unwrap_or(Value::Nil))
            .map_err(|e| rerr(format!("deserialize error: {}", e)))?;
        Ok(vec![to_lua(&style_mix(&styles)).map_err(|e| rerr(e.0))?])
    });
    reg(&u, "textwrap", |_l, a| {
        let s = String::from_utf8_lossy(&check_str(&a, 0, "textwrap")?).into_owned();
        let (width, init, sub, bw) = match a.get(1) {
            Some(Value::Num(n)) => (*n as usize, String::new(), String::new(), true),
            Some(v @ Value::Table(_)) => {
                let w = match opt_table_field(v, "width") {
                    Value::Num(n) => n as usize,
                    _ => 80,
                };
                let i = match opt_table_field(v, "initial_indent") {
                    Value::Str(s) => s.to_str_lossy(),
                    _ => String::new(),
                };
                let si = match opt_table_field(v, "subsequent_indent") {
                    Value::Str(s) => s.to_str_lossy(),
                    _ => String::new(),
                };
                let b = match opt_table_field(v, "break_words") {
                    Value::Bool(b) => b,
                    _ => true,
                };
                (w, i, si, b)
            }
            _ => (80, String::new(), String::new(), true),
        };
        let lines = textwrap(&s, width, &init, &sub, bw);
        let mut t = Table::new();
        for l in lines {
            t.arr.push(Value::str(&l));
        }
        Ok(vec![Value::table(t)])
    });
    reg(&u, "layout_replace", |_l, a| {
        let de = |v: Option<&Value>| -> Result<Layout, LuaError> {
            from_lua(v.cloned().unwrap_or(Value::Nil))
                .map_err(|e| rerr(format!("deserialize error: {}", e)))
        };
        let layout = de(a.first())?;
        let target = de(a.get(1))?;
        let rep = de(a.get(2))?;
        Ok(vec![to_lua(&layout.replace(&target, &rep)).map_err(|e| rerr(e.0))?])
    });
    reg(&u, "permissions_rwx", |_l, a| {
        let p: Permissions = from_lua(a.first().cloned().unwrap_or(Value::Nil))
            .map_err(|e| rerr(format!("deserialize error: {}", e)))?;
        Ok(vec![Value::str(&p.rwx())])
    });
    reg(&u, "permissions_octal", |_l, a| {
        let p: Permissions = from_lua(a.first().cloned().unwrap_or(Value::Nil))
            .map_err(|e| rerr(format!("deserialize error: {}", e)))?;
        let o = p.octal();
        let mut t = Table::new();
        for x in o {
            t.arr.push(Value::Num(x as f64));
        }
        Ok(vec![Value::table(t)])
    });
    let _ = check_table;
    let _ = lua;
    Value::Table(u)
}

pub fn init_lua() -> Lua {
    let mut lua = crate::lua::new_state();
    let util = create_util(&mut lua);
    let mut fn_t = Table::new();
    fn_t.set_str("builtin", Value::new_table());
    fn_t.set_str("custom", Value::new_table());
    let mut x = Table::new();
    x.set_str("config", Value::new_table());
    x.set_str("fn", Value::table(fn_t));
    x.set_str("util", util);
    lua.set_global("xplr", Value::table(x));
    lua
}

pub fn run_default_init(lua: &mut Lua) -> Result<(), String> {
    match lua.load(DEFAULT_LUA_SCRIPT.as_bytes(), "xplr init") {
        Ok(f) => match lua.call(&f, vec![]) {
            Ok(_) => Ok(()),
            Err(e) => Err(format_runtime_error(lua, &e)),
        },
        Err(e) => Err(format!("syntax error: {}", e)),
    }
}

pub fn parse_version(version: &str) -> Result<(u16, u16, u16, usize), String> {
    let parts: Vec<&str> = version.split('.').collect();
    let major = parts
        .first()
        .copied()
        .unwrap_or("")
        .parse::<u16>()
        .map_err(|e| e.to_string())?;
    let minor = parts
        .get(1)
        .copied()
        .unwrap_or("")
        .parse::<u16>()
        .map_err(|e| e.to_string())?;
    let bugfix = parts
        .get(2)
        .copied()
        .unwrap_or("")
        .split('-')
        .next()
        .unwrap_or("")
        .parse::<u16>()
        .map_err(|e| e.to_string())?;
    Ok((major, minor, bugfix, parts.len()))
}

pub fn check_version(version: &str, path: &str) -> Result<(), String> {
    let (smajor, sminor, sbugfix, nparts) = parse_version(version)?;
    let ok = (version == "0.21.0")
        || (nparts == 3 && smajor == 1 && sminor <= 1 && sbugfix == 0);
    if ok {
        Ok(())
    } else {
        Err(format!(
            "incompatible script version in: {}. The script version is: {}, the required version is: {}. Visit {}",
            path,
            version,
            crate::app::VERSION,
            UPGRADE_GUIDE_LINK
        ))
    }
}

/// Load a user config file. Returns hooks
pub fn load_config_file(lua: &mut Lua, path: &str) -> Result<Hooks, String> {
    let src = std::fs::read(path).map_err(|e| io_error_string(&e))?;
    lua.set_global("version", Value::Nil);
    let f = lua
        .load(&src, path)
        .map_err(|e| format!("syntax error: {}", e))?;
    let r = match lua.call(&f, vec![]) {
        Ok(r) => r,
        Err(e) => {
            let mut e = e;
            if e.needs_pos() {
                e = LuaError::val(e.value.clone());
            }
            let tb = format!(
                "stack traceback:\n\t[C]: in ?\n\t{}: in main chunk",
                crate::lua::parser::chunkid(path)
            );
            e.traceback = Some(tb);
            return Err(format_runtime_error(lua, &e));
        }
    };
    let version = lua.get_global("version");
    match version {
        Value::Str(s) => check_version(&s.to_str_lossy(), path)?,
        Value::Nil => {
            return Err(format!("'version' must be defined globally in {}", path));
        }
        _ => {
            return Err(format!("'version' must be defined globally in {}", path));
        }
    }
    let ret = r.into_iter().next().unwrap_or(Value::Nil);
    if ret.is_nil() {
        return Ok(Hooks::default());
    }
    from_lua::<Hooks>(ret).map_err(|e| format!("deserialize error: {}", e))
}

pub fn read_config(lua: &mut Lua) -> Result<Config, String> {
    let x = lua.get_global("xplr");
    let c = opt_table_field(&x, "config");
    from_lua::<Config>(c).map_err(|e| format!("deserialize error: {}", e))
}

/// Evaluate lua code (LuaEval)
pub fn eval(lua: &mut Lua, code: &str, arg: Value) -> Result<Value, String> {
    let f = lua
        .load(code.as_bytes(), code)
        .map_err(|e| format!("syntax error: {}", e))?;
    let depth = lua.depth;
    let st = lua.stack.len();
    let r = match lua.call(&f, vec![]) {
        Ok(r) => r.into_iter().next().unwrap_or(Value::Nil),
        Err(e) => {
            lua.depth = depth;
            lua.stack.truncate(st);
            let e = if e.needs_pos() { LuaError::val(e.value.clone()) } else { e };
            return Err(format_runtime_error(lua, &e));
        }
    };
    if let Value::Func(_) = r {
        call_value(lua, &r, arg)
    } else {
        Ok(r)
    }
}
