pub fn paint(s: &str, style: &Style) -> String {
    let mut codes: Vec<String> = vec![];
    let has = |m: Modifier| {
        style
            .add_modifiers
            .as_ref()
            .map(|a| a.contains(&m))
            .unwrap_or(false)
    };
    if has(Modifier::Bold) {
        codes.push("1".into());
    }
    if has(Modifier::Dim) {
        codes.push("2".into());
    }
    if has(Modifier::Italic) {
        codes.push("3".into());
    }
    if has(Modifier::Underlined) {
        codes.push("4".into());
    }
    if has(Modifier::SlowBlink) || has(Modifier::RapidBlink) {
        codes.push("5".into());
    }
    if has(Modifier::Reversed) {
        codes.push("7".into());
    }
    if has(Modifier::Hidden) {
        codes.push("8".into());
    }
    if has(Modifier::CrossedOut) {
        codes.push("9".into());
    }
    if let Some(bg) = style.bg.as_ref().and_then(ansi_bg) {
        codes.push(bg);
    }
    if let Some(fg) = style.fg.as_ref().and_then(ansi_fg) {
        codes.push(fg);
    }
    if codes.is_empty() {
        return s.to_string();
    }
    format!("\x1b[{}m{}\x1b[0m", codes.join(";"), s)
}

