fn reg(t: &Rc<RefCell<Table>>, name: &str, f: impl Fn(&mut Lua, Vec<Value>) -> crate::lua::value::LResult<Vec<Value>> + 'static) {
    t.borrow_mut().set_str(name, Lua::native(name, f));
}

pub fn create_util(lua: &mut Lua) -> Value {
    let u = Rc::new(RefCell::new(Table::new()));
    reg(&u, "version", |_l, _a| {
        let mut t = Table::new();
        t.set_str("major", Value::Num(1.0));
        t.set_str("minor", Value::Num(1.0));
        t.set_str("patch", Value::Num(0.0));
        Ok(vec![Value::table(t)])
    });
    reg(&u, "debug", |_l, a| {
        let v = a.into_iter().next().unwrap_or(Value::Nil);
        let s = debug_value(&v);
        println!("{}", s);
        Ok(vec![Value::str(&s)])
    });
    reg(&u, "clone", |_l, a| {
        let v = a.into_iter().next().unwrap_or(Value::Nil);
        fn clone(v: &Value) -> Value {
            match v {
                Value::Table(t) => {
                    let tb = t.borrow();
                    let mut n = Table::new();
                    for (k, x) in tb.iter_pairs() {
                        let _ = n.set(clone(&k), clone(&x));
                    }
                    n.meta = tb.meta.clone();
                    Value::table(n)
                }
                o => o.clone(),
            }
        }
        Ok(vec![clone(&v)])
    });
    reg(&u, "exists", |_l, a| {
        let p = String::from_utf8_lossy(&check_str(&a, 0, "exists")?).into_owned();
        Ok(vec![Value::Bool(std::path::Path::new(&p).symlink_metadata().is_ok())])
