pub fn run_default_init(lua: &mut Lua) -> Result<(), String> {
    match lua.load(DEFAULT_LUA_SCRIPT.as_bytes(), "xplr init") {
        Ok(f) => match lua.call(&f, vec![]) {
            Ok(_) => Ok(()),
            Err(e) => Err(format_runtime_error(lua, &e)),
        },
        Err(e) => Err(format!("syntax error: {}", e)),
    }
}

pub fn parse_version(version: &str) -> Result<(u16, u16, u16, usize), String> {
    let parts: Vec<&str> = version.split('.').collect();
    let major = parts
        .first()
        .copied()
        .unwrap_or("")
        .parse::<u16>()
        .map_err(|e| e.to_string())?;
    let minor = parts
        .get(1)
        .copied()
        .unwrap_or("")
        .parse::<u16>()
        .map_err(|e| e.to_string())?;
    let bugfix = parts
        .get(2)
        .copied()
        .unwrap_or("")
        .split('-')
        .next()
        .unwrap_or("")
        .parse::<u16>()
        .map_err(|e| e.to_string())?;
    Ok((major, minor, bugfix, parts.len()))
}

pub fn check_version(version: &str, path: &str) -> Result<(), String> {
    let (smajor, sminor, sbugfix, nparts) = parse_version(version)?;
    let ok = (version == "0.21.0")
        || (nparts == 3 && smajor == 1 && sminor <= 1 && sbugfix == 0);
    if ok {
        Ok(())
    } else {
        Err(format!(
            "incompatible script version in: {}. The script version is: {}, the required version is: {}. Visit {}",
            path,
            version,
            crate::app::VERSION,
            UPGRADE_GUIDE_LINK
        ))
    }
}

/// Load a user config file. Returns hooks
pub fn load_config_file(lua: &mut Lua, path: &str) -> Result<Hooks, String> {
    let src = std::fs::read(path).map_err(|e| io_error_string(&e))?;
    lua.set_global("version", Value::Nil);
    let f = lua
        .load(&src, path)
        .map_err(|e| format!("syntax error: {}", e))?;
    let r = match lua.call(&f, vec![]) {
        Ok(r) => r,
        Err(e) => {
            let mut e = e;
            if e.needs_pos() {
                e = LuaError::val(e.value.clone());
            }
            let tb = format!(
                "stack traceback:\n\t[C]: in ?\n\t{}: in main chunk",
                crate::lua::parser::chunkid(path)
            );
            e.traceback = Some(tb);
            return Err(format_runtime_error(lua, &e));
        }
    };
    let version = lua.get_global("version");
    match version {
        Value::Str(s) => check_version(&s.to_str_lossy(), path)?,
        Value::Nil => {
            return Err(format!("'version' must be defined globally in {}", path));
        }
        _ => {
            return Err(format!("'version' must be defined globally in {}", path));
        }
    }
    let ret = r.into_iter().next().unwrap_or(Value::Nil);
    if ret.is_nil() {
        return Ok(Hooks::default());
    }
    from_lua::<Hooks>(ret).map_err(|e| format!("deserialize error: {}", e))
}

pub fn read_config(lua: &mut Lua) -> Result<Config, String> {
    let x = lua.get_global("xplr");
    let c = opt_table_field(&x, "config");
    from_lua::<Config>(c).map_err(|e| format!("deserialize error: {}", e))
}

/// Evaluate lua code (LuaEval)
pub fn eval(lua: &mut Lua, code: &str, arg: Value) -> Result<Value, String> {
    let f = lua
        .load(code.as_bytes(), code)
        .map_err(|e| format!("syntax error: {}", e))?;
    let depth = lua.depth;
    let st = lua.stack.len();
    let r = match lua.call(&f, vec![]) {
        Ok(r) => r.into_iter().next().unwrap_or(Value::Nil),
        Err(e) => {
            lua.depth = depth;
            lua.stack.truncate(st);
            let e = if e.needs_pos() { LuaError::val(e.value.clone()) } else { e };
            return Err(format_runtime_error(lua, &e));
        }
    };
    if let Value::Func(_) = r {
        call_value(lua, &r, arg)
    } else {
        Ok(r)
    }
}
