    )?;
    let ghm = app.global_help_menu_str(&d);
    std::fs::write(&p.global_help_menu_out, format!("{}{}", ghm, d))?;
    w(
        &p.logs_out,
        app.logs
            .iter()
            .map(|l| format!("[{}] {} {}", l.created_at.display(), l.level.name(), l.message))
            .collect(),
    )?;
    w(&p.history_out, app.history.paths.clone())?;
    Ok(())
}

fn read_msg_in(app: &App, delim: u8) -> Vec<Result<ExternalMsg, String>> {
    let data = match std::fs::read(&app.pipe.msg_in) {
        Ok(d) => d,
        Err(_) => return vec![],
    };
    let mut out = vec![];
    for chunk in data.split(|b| *b == delim) {
        let s = String::from_utf8_lossy(chunk);
        let s = s.trim();
        if s.is_empty() {
            continue;
        }
        let m: Result<ExternalMsg, String> = serde_yaml::from_str(s).map_err(|e| e.to_string());
        out.push(m);
    }
    let _ = std::fs::write(&app.pipe.msg_in, b"");
    out
}

fn set_env(cmd: &mut std::process::Command, app: &App) {
    let focus_index = app
        .directory_buffer
        .as_ref()
        .map(|d| d.focus)
        .unwrap_or(0)
        .to_string();
    cmd.env("XPLR", &app.bin)
        .env("XPLR_APP_VERSION", &app.version)
        .env("XPLR_PID", app.pid.to_string())
        .env("XPLR_INPUT_BUFFER", app.input_value().unwrap_or_default())
        .env("XPLR_INITIAL_PWD", &app.initial_pwd)
        .env("XPLR_FOCUS_PATH", app.focused_node_str())
        .env("XPLR_FOCUS_INDEX", focus_index)
        .env("XPLR_SESSION_PATH", &app.session_path)
        .env("XPLR_PIPE_MSG_IN", &app.pipe.msg_in)
        .env("XPLR_PIPE_SELECTION_OUT", &app.pipe.selection_out)
        .env("XPLR_PIPE_HISTORY_OUT", &app.pipe.history_out)
        .env("XPLR_MODE", &app.mode.name)
        .env("XPLR_PIPE_RESULT_OUT", &app.pipe.result_out)
        .env("XPLR_PIPE_GLOBAL_HELP_MENU_OUT", &app.pipe.global_help_menu_out)
        .env("XPLR_PIPE_DIRECTORY_NODES_OUT", &app.pipe.directory_nodes_out)
        .env("XPLR_PIPE_LOGS_OUT", &app.pipe.logs_out)
        .env("XPLR_VROOT", app.vroot.clone().unwrap_or_default());
}

pub struct Fifo {
    path: String,
    file: Option<std::fs::File>,
    last: Option<String>,
}

impl Runner {
    pub fn run(self) -> Result<Option<String>, String> {
        // ---- load lua config ----
        let mut errors: Vec<String> = vec![];
        let mut lua = lua_api::init_lua();
        if let Err(e) = lua_api::run_default_init(&mut lua) {
            return Err(e);
        }
        let mut hooks = Hooks::default();
        let config_file = self.config_file.clone().or_else(|| {
            let home = std::env::var("HOME").ok()?;
            let xdg = std::env::var("XDG_CONFIG_HOME")
                .ok()
                .filter(|x| !x.is_empty())
                .unwrap_or_else(|| format!("{}/.config", home));
            let p = format!("{}/xplr/init.lua", xdg);
            if PathBuf::from(&p).exists() {
                return Some(p);
            }
            let p = "/etc/xplr/init.lua".to_string();
            if PathBuf::from(&p).exists() {
                return Some(p);
            }
            None
        });
        let mut files: Vec<String> = vec![];
        if let Some(f) = config_file {
            files.push(f);
        }
        files.extend(self.extra_config_files.clone());
        let mut failed = false;
        for f in files.iter() {
            match lua_api::load_config_file(&mut lua, f) {
                Ok(h) => hooks = hooks.extend(h),
                Err(e) => {
                    errors.push(e);
                    failed = true;
                    break;
                }
            }
        }
        let mut config = match lua_api::read_config(&mut lua) {
            Ok(c) => c,
            Err(e) => {
                errors.push(e);
                failed = true;
                crate::config::Config::default()
            }
        };
        if failed {
            lua = lua_api::init_lua();
            let _ = lua_api::run_default_init(&mut lua);
            hooks = Hooks::default();
            config = lua_api::read_config(&mut lua).unwrap_or_default();
        }
        if self.read_only {
            config.general.read_only = true;
        }

        let mut app = App::new(
            self.bin.clone(),
            self.pwd.clone(),
            config,
            hooks,
            self.vroot.clone(),
            vec![],
        );
        for e in errors.iter() {
            app.log_error(e.clone());
        }
        let debug_mode = !errors.is_empty() && !app.config.general.disable_debug_error_mode;

        // session dir
        let _ = std::fs::create_dir_all(&app.pipe.path);
        let _ = std::env::set_current_dir(&app.pwd);

        // initial state
        let pwd = app.pwd.clone();
        app.change_directory(&pwd, true);
        app.focus_first(true);
        if let Some(f) = &self.focused_path {
            app.focus_path(f, true);
        }
        for s in self.selection.iter() {
            app.select_path(s);
        }
        if debug_mode {
            app.handle_task(Task::ext(ExternalMsg::SwitchModeBuiltin("debug_error".into())));
        }
        app.msg_out.clear();

        let mut terminal = setup_terminal(app.config.general.enable_mouse).map_err(|e| lua_api::io_error_string(&e))?;
        let mut mouse_enabled = app.config.general.enable_mouse;

        let (tx, rx): (Sender<Event2>, Receiver<Event2>) = channel();

        // key reader thread
        let tx_keys = tx.clone();
        let pause = std::sync::Arc::new(std::sync::atomic::AtomicBool::new(false));
        let pause_r = pause.clone();
        std::thread::spawn(move || loop {
            if pause_r.load(std::sync::atomic::Ordering::SeqCst) {
                std::thread::sleep(std::time::Duration::from_millis(50));
                continue;
            }
            match event::poll(std::time::Duration::from_millis(50)) {
                Ok(true) => {
                    if pause_r.load(std::sync::atomic::Ordering::SeqCst) {
                        continue;
                    }
                    match event::read() {
                        Ok(ev) => {
                            if tx_keys.send(Event2::Term(ev)).is_err() {
                                break;
                            }
                        }
                        Err(_) => {}
                    }
                }
                Ok(false) => {}
                Err(_) => std::thread::sleep(std::time::Duration::from_millis(50)),
            }
        });

        // pwd watcher
        let tx_pwd = tx.clone();
        let (tx_watch, rx_watch) = channel::<String>();
        std::thread::spawn(move || {
            let mut pwd = String::new();
            let mut last_mtime: Option<std::time::SystemTime> = None;
            loop {
                while let Ok(p) = rx_watch.try_recv() {
                    if p != pwd {
                        pwd = p;
                        last_mtime = std::fs::metadata(&pwd).and_then(|m| m.modified()).ok();
                    }
                }
                std::thread::sleep(std::time::Duration::from_millis(1000));
                if pwd.is_empty() {
                    continue;
                }
                let m = std::fs::metadata(&pwd).and_then(|m| m.modified()).ok();
                if m != last_mtime {
                    last_mtime = m;
                    if tx_pwd.send(Event2::PwdChanged(pwd.clone())).is_err() {
                        break;
                    }
                }
            }
        });
        let _ = tx_watch.send(app.pwd.clone());

        // initial messages
        let _ = tx.send(Event2::Task(Task::ext(ExternalMsg::ExploreParentsAsync)));
        for m in app.hooks.on_load.clone() {
            let _ = tx.send(Event2::Task(Task::ext(m)));
        }
        for m in self.on_load.clone() {
            let _ = tx.send(Event2::Task(Task::ext(m)));
        }
        if let Some(f) = app.config.general.start_fifo.clone() {
            let _ = tx.send(Event2::Task(Task::ext(ExternalMsg::StartFifo(f))));
        }

        let mut fifo: Option<Fifo> = None;
        let _ = terminal.draw(|f| crate::ui::draw(f, &mut app, &mut lua));

        let mut result: Result<Option<String>, String> = Ok(None);
        let delim = if self.write0 { "\0" } else { "\n" };

        'outer: loop {
            let ev = match rx.recv() {
                Ok(e) => e,
                Err(_) => break,
            };
            let task = match ev {
                Event2::Task(t) => t,
                Event2::PwdChanged(p) => {
                    if p == app.pwd {
                        Task::ext(ExternalMsg::ExplorePwdAsync)
                    } else {
                        continue;
                    }
                }
                Event2::Term(e) => match e {
                    Event::Key(k) => {
                        if k.kind != crossterm::event::KeyEventKind::Press {
                            continue;
                        }
                        let key = Key::from_event(&k);
                        Task::new(MsgIn::Internal(InternalMsg::HandleKey(key)), None)
                    }
                    Event::Resize(_, _) => {
                        let _ = terminal.autoresize();
                        let _ = terminal.draw(|f| crate::ui::draw(f, &mut app, &mut lua));
                        continue;
                    }
                    Event::Mouse(me) => {
                        if !mouse_enabled {
                            continue;
                        }
                        match me.kind {
                            MouseEventKind::ScrollDown => Task::ext(ExternalMsg::FocusNext),
                            MouseEventKind::ScrollUp => Task::ext(ExternalMsg::FocusPrevious),
                            _ => continue,
                        }
                    }
                    _ => continue,
                },
            };

            // snapshot for hooks
            let old_pwd = app.pwd.clone();
            let old_focus = app.focused_node().map(|n| n.absolute_path.clone());
            let old_mode = app.mode.name.clone();
            let old_layout = app.layout.clone();
            let old_sel: Vec<String> = app.selection.iter().map(|n| n.absolute_path.clone()).collect();

            let is_external = matches!(task.msg, MsgIn::External(_));
            let new_tasks = app.handle_task(task);
            for t in new_tasks {
                let _ = tx.send(Event2::Task(t));
            }
            let mut need_draw = is_external;

            while let Some(out) = app.msg_out.pop_front() {
                match out {
                    MsgOut::Refresh => need_draw = true,
                    MsgOut::ClearScreen => {
                        let _ = terminal.clear();
                        need_draw = true;
                    }
                    MsgOut::ExplorePwdAsync => {
                        let focus = app
                            .focused_node()
                            .filter(|_| app.directory_buffer.as_ref().map(|d| d.parent == app.pwd).unwrap_or(false))
                            .map(|n| n.relative_path.clone());
                        let fallback = app.directory_buffer.as_ref().map(|d| d.focus).unwrap_or(0);
                        match explorer::explore_sync(&app.explorer_config, &app.pwd, focus.as_deref(), fallback) {
                            Ok(buf) => {
                                let _ = tx.send(Event2::Task(Task::new(
                                    MsgIn::Internal(InternalMsg::SetDirectory(buf)),
                                    None,
                                )));
                            }
                            Err(e) => {
                                let _ = tx.send(Event2::Task(Task::ext(ExternalMsg::LogError(
                                    lua_api::io_error_string(&e),
                                ))));
                            }
                        }
                    }
                    MsgOut::ExploreParentsAsync => {
                        let mut parent = PathBuf::from(&app.pwd);
                        let mut focus: Option<String> = None;
                        loop {
                            let ps = parent.to_string_lossy().to_string();
                            let fallback = 0;
                            let f = if ps == app.pwd {
                                app.focused_node().map(|n| n.relative_path.clone())
                            } else {
                                focus.clone()
                            };
                            if let Ok(buf) = explorer::explore_sync(&app.explorer_config, &ps, f.as_deref(), fallback) {
                                let _ = tx.send(Event2::Task(Task::new(
                                    MsgIn::Internal(InternalMsg::SetDirectory(buf)),
                                    None,
                                )));
                            }
                            focus = parent.file_name().map(|n| n.to_string_lossy().to_string());
                            match parent.parent() {
                                Some(p) => parent = p.to_path_buf(),
                                None => break,
                            }
                        }
                    }
                    MsgOut::Quit => {
                        result = Ok(None);
                        break 'outer;
                    }
                    MsgOut::PrintPwdAndQuit => {
                        result = Ok(Some(format!("{}{}", app.pwd, delim)));
                        break 'outer;
                    }
                    MsgOut::PrintFocusPathAndQuit => {
                        result = Ok(app
                            .focused_node()
                            .map(|n| format!("{}{}", n.absolute_path, delim)));
                        break 'outer;
                    }
                    MsgOut::PrintSelectionAndQuit => {
                        let s: String = app
                            .selection
                            .iter()
                            .map(|n| format!("{}{}", n.absolute_path, delim))
                            .collect();
                        result = Ok(Some(s));
                        break 'outer;
                    }
                    MsgOut::PrintResultAndQuit => {
                        if self.print_pwd_as_result {
                            result = Ok(Some(format!("{}{}", app.pwd, delim)));
                        } else {
                            let s: String = app
                                .result()
                                .iter()
                                .map(|n| format!("{}{}", n.absolute_path, delim))
                                .collect();
                            result = Ok(Some(s));
                        }
                        break 'outer;
                    }
                    MsgOut::PrintAppStateAndQuit => {
                        let s = serde_yaml::to_string(&app).unwrap_or_default();
                        result = Ok(Some(s));
                        break 'outer;
                    }
                    MsgOut::Debug(path) => {
                        let s = serde_yaml::to_string(&app).unwrap_or_default();
                        if let Err(e) = std::fs::write(&path, s) {
                            app.log_error(lua_api::io_error_string(&e));
                        }
                    }
                    MsgOut::Terminate => {
                        result = Err(String::new());
                        break 'outer;
                    }
                    MsgOut::EnableMouse => {
                        if !mouse_enabled {
                            let _ = execute!(terminal.backend_mut(), crossterm::event::EnableMouseCapture);
                            mouse_enabled = true;
                        }
                    }
                    MsgOut::DisableMouse | MsgOut::ToggleMouse => {
                        if mouse_enabled {
                            let _ = execute!(terminal.backend_mut(), crossterm::event::DisableMouseCapture);
                            mouse_enabled = false;
                        }
                    }
                    MsgOut::StartFifo(p) => {
                        fifo = start_fifo(&mut app, &p);
                    }
                    MsgOut::StopFifo => {
                        fifo = None;
                    }
                    MsgOut::ToggleFifo(p) => {
                        if fifo.is_some() {
                            fifo = None;
                        } else {
                            fifo = start_fifo(&mut app, &p);
                        }
                    }
                    MsgOut::Call(c) | MsgOut::Call0(c) | MsgOut::CallSilently(c) | MsgOut::CallSilently0(c) => {
                        // unreachable pattern placeholder (handled below)
                        let _ = c;
                    }
                    MsgOut::CallLua(f) | MsgOut::CallLuaSilently(f) => {
                        let silent = matches!(app.msg_out.front(), Some(_)) && false;
                        let _ = silent;
                        let arg = lua_api::CallLuaArg::from_app(&app);
                        let v = crate::lua::serde::to_lua(&arg).unwrap_or(crate::lua::Value::Nil);
                        match lua_api::call_fn(&mut lua, &f, v) {
                            Ok(r) => enqueue_lua_result(&tx, &mut app, r),
                            Err(e) => app.log_error(e),
                        }
                        need_draw = true;
                    }
                    MsgOut::LuaEval(code) | MsgOut::LuaEvalSilently(code) => {
                        let arg = lua_api::CallLuaArg::from_app(&app);
                        let v = crate::lua::serde::to_lua(&arg).unwrap_or(crate::lua::Value::Nil);
                        match lua_api::eval(&mut lua, &code, v) {
                            Ok(r) => enqueue_lua_result(&tx, &mut app, r),
                            Err(e) => app.log_error(e),
                        }
                        need_draw = true;
                    }
                }
            }

            // commands are handled separately to keep ownership simple
            // (they were pushed again by handle_external)
            if let Some(cmds) = take_commands(&mut app) {
                for (cmd, silent, delim0) in cmds {
                    let d = if delim0 { 0u8 } else { b'\n' };
                    if let Err(e) = write_pipes(&app, d) {
                        app.log_error(lua_api::io_error_string(&e));
                    }
                    let mut c = std::process::Command::new(&cmd.command);
                    c.args(&cmd.args).current_dir(&app.pwd);
                    set_env(&mut c, &app);
                    if silent {
                        c.stdin(std::process::Stdio::null())
                            .stdout(std::process::Stdio::null())
                            .stderr(std::process::Stdio::null());
                        match c.status() {
                            Ok(_) => {}
                            Err(e) => app.log_error(lua_api::io_error_string(&e)),
                        }
                    } else {
                        pause.store(true, std::sync::atomic::Ordering::SeqCst);
                        std::thread::sleep(std::time::Duration::from_millis(60));
                        restore_terminal(&mut terminal, mouse_enabled);
                        match c.status() {
                            Ok(_) => {}
                            Err(e) => app.log_error(lua_api::io_error_string(&e)),
                        }
                        let _ = term::enable_raw_mode();
                        let _ = execute!(terminal.backend_mut(), term::EnterAlternateScreen);
                        if mouse_enabled {
                            let _ = execute!(terminal.backend_mut(), crossterm::event::EnableMouseCapture);
                        }
                        let _ = terminal.hide_cursor();
                        let _ = terminal.clear();
                        pause.store(false, std::sync::atomic::Ordering::SeqCst);
                    }
                    for m in read_msg_in(&app, d) {
                        match m {
                            Ok(m) => {
                                let _ = tx.send(Event2::Task(Task::ext(m)));
                            }
                            Err(e) => app.log_error(e),
                        }
                    }
                    need_draw = true;
                }
            }

            // hooks
            let new_focus = app.focused_node().map(|n| n.absolute_path.clone());
            if app.pwd != old_pwd {
                let _ = tx_watch.send(app.pwd.clone());
                for m in app.hooks.on_directory_change.clone() {
                    let _ = tx.send(Event2::Task(Task::ext(m)));
                }
            }
            if new_focus != old_focus {
                for m in app.hooks.on_focus_change.clone() {
                    let _ = tx.send(Event2::Task(Task::ext(m)));
                }
                if let Some(ff) = fifo.as_mut() {
                    write_fifo(ff, new_focus.clone());
                }
            }
            if app.mode.name != old_mode {
                for m in app.hooks.on_mode_switch.clone() {
                    let _ = tx.send(Event2::Task(Task::ext(m)));
                }
            }
            if app.layout != old_layout {
                for m in app.hooks.on_layout_switch.clone() {
                    let _ = tx.send(Event2::Task(Task::ext(m)));
                }
            }
            let new_sel: Vec<String> = app.selection.iter().map(|n| n.absolute_path.clone()).collect();
            if new_sel != old_sel {
                for m in app.hooks.on_selection_change.clone() {
                    let _ = tx.send(Event2::Task(Task::ext(m)));
                }
            }

            if need_draw {
                let _ = terminal.draw(|f| crate::ui::draw(f, &mut app, &mut lua));
            }
        }

        restore_terminal(&mut terminal, mouse_enabled);
        let _ = std::fs::remove_dir_all(&app.session_path);
        let _: &Layout = &app.layout;
        result
    }
}

fn enqueue_lua_result(tx: &Sender<Event2>, app: &mut App, r: crate::lua::Value) {
    if r.is_nil() {
        return;
    }
    match crate::lua::serde::from_lua::<Vec<ExternalMsg>>(r) {
        Ok(msgs) => {
            for m in msgs {
                let _ = tx.send(Event2::Task(Task::ext(m)));
            }
        }
        Err(e) => app.log_error(format!("deserialize error: {}", e)),
    }
}

fn take_commands(app: &mut App) -> Option<Vec<(Command, bool, bool)>> {
    if app.pending_commands.is_empty() {
        return None;
    }
    Some(std::mem::take(&mut app.pending_commands))
}

fn start_fifo(app: &mut App, path: &str) -> Option<Fifo> {
    match std::fs::OpenOptions::new().write(true).open(path) {
        Ok(f) => {
            let mut ff = Fifo {
                path: path.to_string(),
                file: Some(f),
                last: None,
            };
            write_fifo(&mut ff, app.focused_node().map(|n| n.absolute_path.clone()));
            Some(ff)
        }
        Err(e) => {
            app.log_error(lua_api::io_error_string(&e));
            None
        }
    }
}

fn write_fifo(ff: &mut Fifo, focus: Option<String>) {
    if ff.last == focus {
        return;
    }
    ff.last = focus.clone();
    if let Some(f) = ff.file.as_mut() {
        let _ = writeln!(f, "{}", focus.unwrap_or_default());
    }
    let _ = &ff.path;
}

pub fn queue_type() -> VecDeque<Task> {
    VecDeque::new()
}
