// A small re-implementation of the jf template formatting used by `xplr -m`.
use std::collections::HashMap;
use std::io::Read;

fn quote(s: &str) -> String {
    serde_json::to_string(s).unwrap_or_else(|_| "\"\"".into())
}

pub fn format(template: &str, args: &[String]) -> Result<String, String> {
    let chars: Vec<char> = template.chars().collect();
    let mut out = String::new();
    let mut pos_args = args.iter().enumerate();
    let mut named: Option<HashMap<String, String>> = None;
    let mut stdin_cache: Option<String> = None;
    let mut i = 0;

    let parse_named = |rest: Vec<(usize, &String)>| -> Result<HashMap<String, String>, String> {
        let mut m = HashMap::new();
        for (idx, a) in rest {
            if let Some(eq) = a.find('=') {
                let at = a.find('@');
                if at.map(|x| x < eq).unwrap_or(false) {
                    let at = at.unwrap();
                    let (k, f) = (&a[..at], &a[at + 1..]);
                    let c = std::fs::read_to_string(f).map_err(|e| e.to_string())?;
                    m.insert(k.to_string(), c);
                } else {
                    m.insert(a[..eq].to_string(), a[eq + 1..].to_string());
                }
            } else if let Some(at) = a.find('@') {
                let (k, f) = (&a[..at], &a[at + 1..]);
                let c = std::fs::read_to_string(f).map_err(|e| e.to_string())?;
                m.insert(k.to_string(), c);
            } else {
                return Err(format!(
                    "invalid syntax for value no. {}, use 'NAME=VALUE' or 'NAME@FILE' syntax",
                    idx + 1
                ));
            }
        }
        Ok(m)
    };

    while i < chars.len() {
        let c = chars[i];
        if c != '%' {
            out.push(c);
            i += 1;
            continue;
        }
        let start_col = i + 1;
        if i + 1 >= chars.len() {
            return Err(format!(
                "invalid placeholder '%' at column {}, use one of '%s' or '%q', or escape it using '%%'",
                start_col
            ));
        }
        let n = chars[i + 1];
        match n {
            '%' => {
                out.push('%');
                i += 2;
            }
            's' | 'q' => {
                let col = i + 1;
                match pos_args.next() {
                    Some((_, v)) => {
                        if n == 's' {
                            out.push_str(v)
                        } else {
                            out.push_str(&quote(v))
                        }
                    }
                    None => return Err(format!("placeholder missing value at column {}", col)),
                }
                i += 2;
            }
            '-' if i + 2 < chars.len() && (chars[i + 2] == 's' || chars[i + 2] == 'q') => {
                let col = i + 2;
                if stdin_cache.is_none() {
                    let mut s = String::new();
                    let _ = std::io::stdin().read_to_string(&mut s);
                    stdin_cache = Some(s);
                }
                let v = stdin_cache.clone().unwrap_or_default();
                if v.is_empty() {
                    return Err(format!("placeholder missing value at column {}", col));
                }
                if chars[i + 2] == 's' {
                    out.push_str(&v)
                } else {
                    out.push_str(&quote(&v))
                }
                i += 3;
            }
            '*' => {
                if i + 2 < chars.len() && (chars[i + 2] == 's' || chars[i + 2] == 'q') {
                    let q = chars[i + 2] == 'q';
                    let vals: Vec<String> = pos_args
                        .by_ref()
                        .map(|(_, v)| if q { quote(v) } else { v.clone() })
                        .collect();
                    out.push_str(&vals.join(", "));
                    i += 3;
                } else if i + 3 < chars.len()
                    && chars[i + 2] == '*'
                    && (chars[i + 3] == 's' || chars[i + 3] == 'q')
                {
                    let q = chars[i + 3] == 'q';
                    let vals: Vec<String> = pos_args.by_ref().map(|(_, v)| v.clone()).collect();
                    let mut parts = vec![];
                    for pair in vals.chunks(2) {
                        let k = &pair[0];
                        let v = pair.get(1).cloned().unwrap_or_default();
                        if q {
                            parts.push(format!("{}: {}", quote(k), quote(&v)));
                        } else {
                            parts.push(format!("{}: {}", k, v));
                        }
                    }
                    out.push_str(&parts.join(", "));
                    i += 4;
                } else {
                    let ph: String = chars[i..(i + 3).min(chars.len())].iter().collect();
                    return Err(format!(
                        "invalid placeholder '{}' at column {}, use one of '%s' or '%q', or escape it using '%%'",
                        ph, start_col
                    ));
                }
            }
            '(' => {
                // named
                let mut j = i + 2;
                let mut name = String::new();
                while j < chars.len() && chars[j] != ')' {
                    name.push(chars[j]);
                    j += 1;
                }
                if j + 1 >= chars.len() || (chars[j + 1] != 's' && chars[j + 1] != 'q') {
                    let ph: String = chars[i..(j + 2).min(chars.len())].iter().collect();
                    return Err(format!(
                        "invalid placeholder '{}' at column {}, use one of '%s' or '%q', or escape it using '%%'",
                        ph, start_col
                    ));
                }
                let q = chars[j + 1] == 'q';
                let col = j + 1;
                if named.is_none() {
                    let rest: Vec<(usize, &String)> = pos_args.by_ref().collect();
                    named = Some(parse_named(rest)?);
                }
                let map = named.as_ref().unwrap();
                let (nm, optional, default) = if let Some(n) = name.strip_suffix('?') {
                    (n.to_string(), true, None)
                } else if let Some(eq) = name.find('=') {
                    (name[..eq].to_string(), false, Some(name[eq + 1..].to_string()))
                } else {
                    (name.clone(), false, None)
                };
                match map.get(&nm).cloned().or(default) {
                    Some(v) => {
                        if q {
                            out.push_str(&quote(&v))
                        } else {
                            out.push_str(&v)
                        }
                    }
                    None => {
                        if optional {
                            out.push_str("null");
                        } else {
                            let ph: String = chars[i..j + 2].iter().collect();
                            return Err(format!("no value for placeholder '{}' at column {}", ph, col));
                        }
                    }
                }
                i = j + 2;
            }
            other => {
                return Err(format!(
                    "invalid placeholder '%{}' at column {}, use one of '%s' or '%q', or escape it using '%%'",
                    other, start_col
                ));
            }
        }
    }
    if pos_args.next().is_some() {
        return Err("too many positional values, not enough positional placeholders".into());
    }
    // parse as yaml, convert to json
    let v: serde_json::Value =
        serde_yaml::from_str(&out).map_err(|e| format!("yaml: {}", e))?;
    serde_json::to_string(&v).map_err(|e| format!("json: {}", e))
}
EOF
