{"command":"cat > /workspace/src/main.rs <<'EOF'
mod ansi;
mod app;
mod config;
mod explorer;
mod fuzzy;
mod input;
mod jf;
mod lua;
mod lua_api;
mod mime_table;
mod msg;
mod node;
mod path_util;
mod runner;
mod ui;

use std::io::{Read, Write};

const HELP: &str = "xplr 1.1.0
Arijit Basu <hi@arijitbasu.in>
A hackable, minimal, fast TUI file explorer

USAGE:
    xplr [FLAG]... [OPTION]... [PATH] [SELECTION]...

FLAGS:
  -                            Reads new-line (\\n) separated paths from stdin
  --                           Denotes the end of command-line flags and options
      --force-focus            Focuses on the given <PATH>, even if it is a directory
  -h, --help                   Prints help information
  -m, --pipe-msg-in            Helps safely passing messages to the active xplr
                                 session, use %%, %s and %q as the placeholders
  -M, --print-msg-in           Like --pipe-msg-in, but prints the message instead of
                                 passing to the active xplr session
      --print-pwd-as-result    Prints the present working directory when quitting
                                 with `PrintResultAndQuit`
      --read-only              Enables read-only mode (config.general.read_only)
      --read0                  Reads paths separated using the null character (\\0)
      --write0                 Prints paths separated using the null character (\\0)
  -0  --null                   Combines --read0 and --write0
  -V, --version                Prints version information

OPTIONS:
  -c, --config <PATH>             Specifies a custom config file (default is
                                    \"$HOME/.config/xplr/init.lua\")
  -C, --extra-config <PATH>...    Specifies extra config files to load
      --on-load <MESSAGE>...      Sends messages when xplr loads
      --vroot <PATH>              Treats the specified path as the virtual root

ARGS:
  <PATH>            Path to focus on, or enter if directory, (default is `.`)
  <SELECTION>...    Paths to select, requires <PATH> to be set explicitly
";

#[derive(Default)]
struct Cli {
    bin: String,
    read_only: bool,
    force_focus: bool,
    print_pwd_as_result: bool,
    read0: bool,
    write0: bool,
    help: bool,
    version: bool,
    vroot: Option<String>,
    config: Option<String>,
    extra_config: Vec<String>,
    on_load: Vec<msg::ExternalMsg>,
    paths: Vec<String>,
    pipe_msg_in: Vec<String>,
    print_msg_in: Vec<String>,
}

fn die(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    std::process::exit(1);
}

fn cwd() -> String {
    std::env::current_dir()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_else(|_| "/".into())
}

fn absolute(p: &str) -> String {
    path_util::absolutize(p, &cwd())
}

fn check_exists(p: &str) -> String {
    let a = absolute(p);
    if std::path::Path::new(&a).symlink_metadata().is_err() {
        die(&format!("path doesn't exist: {}", a));
    }
    a
}

fn parse_cli() -> Cli {
    let mut args: std::collections::VecDeque<String> = std::env::args().collect();
    let mut cli = Cli::default();
    let bin = args.pop_front().unwrap_or_else(|| "xplr".into());
    cli.bin = std::env::current_exe()
        .ok()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or(bin);
    let mut flag_ends = false;
    let mut read_stdin = false;
    while let Some(arg) = args.pop_front() {
        if flag_ends {
            cli.paths.push(arg);
            continue;
        }
        match arg.as_str() {
            "-" => read_stdin = true,
            "-h" | "--help" => cli.help = true,
            "-V" | "--version" => cli.version = true,
            "--read-only" => cli.read_only = true,
            "--force-focus" => cli.force_focus = true,
            "--print-pwd-as-result" => cli.print_pwd_as_result = true,
            "--read0" => cli.read0 = true,
            "--write0" => cli.write0 = true,
            "-0" | "--null" => {
                cli.read0 = true;
                cli.write0 = true;
            }
            "--" => flag_ends = true,
            "-c" | "--config" => match args.pop_front() {
                Some(p) => cli.config = Some(check_exists(&p)),
                None => die("usage: xplr -c PATH"),
            },
            "--vroot" => match args.pop_front() {
                Some(p) => cli.vroot = Some(check_exists(&p)),
                None => die("usage: xplr --vroot PATH"),
            },
            "-C" | "--extra-config" => {
                while let Some(p) = args.pop_front() {
                    if p.starts_with('-') && p != "-" {
                        args.push_front(p);
                        break;
                    }
                    cli.extra_config.push(check_exists(&p));
                }
            }
            "--on-load" => {
                while let Some(m) = args.pop_front() {
                    if m.starts_with('-') && m.len() > 1 {
                        args.push_front(m);
                        break;
                    }
                    match serde_yaml::from_str::<msg::ExternalMsg>(m.trim()) {
                        Ok(m) => cli.on_load.push(m),
                        Err(e) => die(&e.to_string()),
                    }
                }
            }
            "-m" | "--pipe-msg-in" => {
                cli.pipe_msg_in = args.drain(..).collect();
                if cli.pipe_msg_in.is_empty() {
                    die("usage: xplr -m FORMAT [ARGUMENT]...");
                }
            }
            "-M" | "--print-msg-in" => {
                cli.print_msg_in = args.drain(..).collect();
                if cli.print_msg_in.is_empty() {
                    die("usage: xplr -M FORMAT [ARGUMENT]...");
                }
            }
            a => {
                if a.starts_with('-') && a.len() > 1 {
                    die(&format!("invalid argument: {:?}, try `-- {:?}` or `--help`", a, a));
                }
                cli.paths.push(a.to_string());
            }
        }
    }
    if read_stdin {
        let mut s = Vec::new();
        let _ = std::io::stdin().read_to_end(&mut s);
        let d = if cli.read0 { 0u8 } else { b'\n' };
        for p in s.split(|b| *b == d) {
            let p = String::from_utf8_lossy(p).trim_end_matches('\r').to_string();
            if !p.trim().is_empty() {
                cli.paths.push(p);
            }
        }
    }
    cli
}

fn format_msg(args: &[String]) -> Result<String, String> {
    let fmt = &args[0];
    let rest: Vec<String> = args[1..].to_vec();
    let json = jf::format(fmt, &rest).map_err(|e| format!("xplr -m: {}", e))?;
    // validate
    serde_json::from_str::<msg::ExternalMsg>(&json).map_err(|e| e.to_string())?;
    Ok(json)
}

fn main() {
    let cli = parse_cli();

    if !cli.pipe_msg_in.is_empty() {
        let json = match format_msg(&cli.pipe_msg_in) {
            Ok(j) => j,
            Err(e) => die(&e),
        };
        match std::env::var("XPLR_PIPE_MSG_IN") {
            Ok(path) if !path.is_empty() => {
                let data = match std::fs::read(&path) {
                    Ok(d) => d,
                    Err(e) => die(&lua_api::io_error_string(&e)),
                };
                let delim = match data.first() {
                    Some(d) => *d,
                    None => die("failed to detect delimmiter"),
                };
                let mut f = match std::fs::OpenOptions::new().append(true).open(&path) {
                    Ok(f) => f,
                    Err(e) => die(&lua_api::io_error_string(&e)),
                };
                let mut buf = json.into_bytes();
                buf.push(delim);
                if let Err(e) = f.write_all(&buf) {
                    die(&lua_api::io_error_string(&e));
                }
            }
            _ => {
                println!("{}", json);
            }
        }
        return;
    }

    if !cli.print_msg_in.is_empty() {
        match format_msg(&cli.print_msg_in) {
            Ok(j) => {
                print!("{}", j);
                let _ = std::io::stdout().flush();
            }
            Err(e) => die(&e),
        }
        return;
    }

    // validate paths
    let mut paths: Vec<String> = cli.paths.iter().map(|p| check_exists(p)).collect();

    if cli.help {
        print!("{}", HELP);
        return;
    }
    if cli.version {
        println!("xplr 1.1.0");
        return;
    }

    let (pwd, focus) = if paths.is_empty() {
        (cwd(), None)
    } else {
        let first = paths.remove(0);
        let p = std::path::PathBuf::from(&first);
        if p.is_dir() && !cli.force_focus {
            (first, None)
        } else {
            let parent = p
                .parent()
                .map(|x| x.to_string_lossy().to_string())
                .unwrap_or_else(|| "/".into());
            (parent, Some(first))
        }
    };

    if let Some(v) = &cli.vroot {
        if !std::path::Path::new(&pwd).starts_with(v) {
            die(&format!("{:?} is outside of virtual root {:?}", pwd, v));
        }
    }

    let runner = runner::Runner {
        bin: cli.bin.clone(),
        pwd,
        focused_path: focus,
        config_file: cli.config.clone(),
        extra_config_files: cli.extra_config.clone(),
        on_load: cli.on_load.clone(),
        read_only: cli.read_only,
        print_pwd_as_result: cli.print_pwd_as_result,
        selection: paths,
        vroot: cli.vroot.clone(),
        write0: cli.write0,
    };

    let child = std::thread::Builder::new()
        .stack_size(512 * 1024 * 1024)
        .spawn(move || runner.run())
        .expect("failed to spawn");
    let result = child.join();
    match result {
        Ok(Ok(Some(out))) => {
            print!("{}", out);
            let _ = std::io::stdout().flush();
        }
        Ok(Ok(None)) => {}
        Ok(Err(e)) => {
            if !e.is_empty() {
                eprintln!("error: {}", e);
            }
            std::process::exit(1);
        }
        Err(_) => std::process::exit(1),
    }
}
