// Fuzzy / regex search (skim-like)
use crate::config::{RankCriteria, SearchAlgorithm};
use crate::explorer::NodeSearcher;
use crate::node::Node;

pub fn search(searcher: &NodeSearcher, nodes: Vec<Node>) -> Vec<Node> {
    let pattern = searcher.pattern.clone();
    let mut ranked: Vec<(Vec<i64>, usize, Node)> = vec![];
    for (idx, n) in nodes.into_iter().enumerate() {
        let r = match searcher.algorithm {
            SearchAlgorithm::Fuzzy => fuzzy_rank(&pattern, &n.relative_path, searcher.exact_mode),
            SearchAlgorithm::Regex => regex_rank(&pattern, &n.relative_path),
        };
        if let Some((score, begin, end)) = r {
            let len = n.relative_path.chars().count() as i64;
            let crit = searcher
                .rank_criteria
                .clone()
                .unwrap_or_else(|| vec![RankCriteria::Score, RankCriteria::Begin, RankCriteria::End]);
            let mut rank = vec![];
            for c in crit.iter().take(4) {
                rank.push(match c {
                    RankCriteria::Score => -score,
                    RankCriteria::NegScore => score,
                    RankCriteria::Begin => begin,
                    RankCriteria::NegBegin => -begin,
                    RankCriteria::End => end,
                    RankCriteria::NegEnd => -end,
                    RankCriteria::Length => len,
                    RankCriteria::NegLength => -len,
                    RankCriteria::Index => idx as i64,
                    RankCriteria::NegIndex => -(idx as i64),
                });
            }
            ranked.push((rank, idx, n));
        }
    }
    if !searcher.unordered {
        ranked.sort_by(|a, b| a.0.cmp(&b.0).then(a.1.cmp(&b.1)));
    }
    ranked.into_iter().map(|(_, _, n)| n).collect()
}

fn regex_rank(pattern: &str, s: &str) -> Option<(i64, i64, i64)> {
    let case_insensitive = !pattern.chars().any(|c| c.is_uppercase());
    let re = regex::RegexBuilder::new(pattern)
        .case_insensitive(case_insensitive)
        .build()
        .ok()?;
    let m = re.find(s)?;
    let begin = s[..m.start()].chars().count() as i64;
    let end = s[..m.end()].chars().count() as i64;
    Some((0, begin, end))
}

pub fn fuzzy_rank(pattern: &str, s: &str, exact: bool) -> Option<(i64, i64, i64)> {
    crate::fuzzy::andor_match(pattern, s, exact)
}

fn char_class(c: char) -> u8 {
    if c.is_lowercase() {
        1
    } else if c.is_uppercase() {
        2
    } else if c.is_numeric() {
        3
    } else if c.is_whitespace() {
        4
    } else if "/,:;|".contains(c) {
        5
    } else if c.is_alphanumeric() {
        1
    } else {
        6
    }
}

const SCORE_MATCH: i64 = 16;
const GAP_START: i64 = -3;
const GAP_EXT: i64 = -1;
const BONUS_BOUNDARY: i64 = SCORE_MATCH / 2;
const BONUS_NON_WORD: i64 = SCORE_MATCH / 2;
const BONUS_CAMEL: i64 = BONUS_BOUNDARY + GAP_EXT;
const BONUS_CONSECUTIVE: i64 = -(GAP_START + GAP_EXT);
const FIRST_MULT: i64 = 2;

fn bonus_for(prev: u8, cur: u8) -> i64 {
    // classes: 1 lower, 2 upper, 3 number, 4 white, 5 delimiter, 6 nonword
    let is_word = |c: u8| c == 1 || c == 2 || c == 3;
    if (prev == 4 || prev == 5 || prev == 6) && is_word(cur) {
        if prev == 4 {
            return BONUS_BOUNDARY + 2;
        }
        if prev == 5 {
            return BONUS_BOUNDARY + 1;
        }
        return BONUS_BOUNDARY;
    }
    if prev == 1 && cur == 2 || prev != 3 && cur == 3 {
        return BONUS_CAMEL;
    }
    if cur == 6 || cur == 5 {
        return BONUS_NON_WORD;
    }
    if cur == 4 {
        return BONUS_BOUNDARY + 2;
    }
    0
}

/// fzf v2 like fuzzy matching. Returns (score, begin, end)
pub fn fuzzy_match(pattern: &[char], text: &[char], case_sensitive: bool) -> Option<(i64, i64, i64)> {
    if pattern.is_empty() {
        return Some((0, 0, 0));
    }
    let eq = |a: char, b: char| -> bool {
        if case_sensitive {
            a == b
        } else {
            a.to_lowercase().eq(b.to_lowercase())
        }
    };
    // check order
    let mut pi = 0;
    for &c in text.iter() {
        if pi < pattern.len() && eq(c, pattern[pi]) {
            pi += 1;
        }
    }
    if pi < pattern.len() {
        return None;
    }
    let n = text.len();
    let m = pattern.len();
    let mut bonus = vec![0i64; n];
    let mut prev = 4u8;
    for (i, &c) in text.iter().enumerate() {
        let cl = char_class(c);
        bonus[i] = bonus_for(prev, cl);
        prev = cl;
    }
    const NEG: i64 = i64::MIN / 4;
    let mut h = vec![vec![NEG; n]; m];
    let mut cons = vec![vec![0i64; n]; m];
    for i in 0..m {
        let mut in_gap = false;
        let mut prev_h = NEG;
        for j in 0..n {
            let mut s_diag = NEG;
            let mut c_new = 0;
            if eq(text[j], pattern[i]) {
                let (base, pc) = if i == 0 {
                    (0, 0)
                } else if j > 0 {
                    (h[i - 1][j - 1], cons[i - 1][j - 1])
                } else {
                    (NEG, 0)
                };
                if base > NEG {
                    let mut b = bonus[j];
                    let consecutive = pc + 1;
                    let mut c2 = consecutive;
                    if consecutive > 1 {
                        let fb = bonus[j + 1 - consecutive as usize];
                        if b >= BONUS_BOUNDARY && b > fb {
                            c2 = 1;
                        } else {
                            b = b.max(BONUS_CONSECUTIVE.max(fb));
                        }
                    }
                    if i == 0 {
                        b *= FIRST_MULT;
                    }
                    s_diag = base + SCORE_MATCH + b;
                    c_new = c2;
                }
            }
            let s_gap = if prev_h > NEG {
                prev_h + if in_gap { GAP_EXT } else { GAP_START }
            } else {
                NEG
            };
            if s_diag >= s_gap && s_diag > NEG {
                h[i][j] = s_diag;
                cons[i][j] = c_new;
                in_gap = false;
            } else {
                h[i][j] = s_gap;
                cons[i][j] = 0;
                in_gap = true;
            }
            prev_h = h[i][j];
        }
    }
    // best in last row
    let mut best = NEG;
    let mut best_j = 0;
    for j in 0..n {
        if h[m - 1][j] > best {
            best = h[m - 1][j];
            best_j = j;
        }
    }
    if best <= NEG {
        return None;
    }
    // backtrack for begin
    let mut i = m - 1;
    let mut j = best_j;
    let end = best_j as i64 + 1;
    let begin;
    loop {
        // find position where pattern[i] matched at j via diag
        while j > 0 && cons[i][j] == 0 && h[i][j] == h[i][j - 1] + GAP_EXT || (j > 0 && cons[i][j] == 0 && !eq(text[j], pattern[i])) {
            j -= 1;
        }
        if i == 0 {
            begin = j as i64;
            break;
        }
        i -= 1;
        if j == 0 {
            begin = 0;
            break;
        }
        j -= 1;
    }
    Some((best, begin, end))
}

pub fn andor_match(pattern: &str, text: &str, exact_mode: bool) -> Option<(i64, i64, i64)> {
    let terms: Vec<&str> = pattern.split(' ').filter(|t| !t.is_empty()).collect();
    if terms.is_empty() {
        return Some((0, 0, 0));
    }
    let mut total = 0i64;
    let mut begin = i64::MAX;
    let mut end = 0i64;
    // OR groups: split by "|"
    let mut groups: Vec<Vec<&str>> = vec![vec![]];
    for t in terms {
        if t == "|" {
            groups.push(vec![]);
        } else {
            groups.last_mut().unwrap().push(t);
        }
    }
    let _ = groups.len();
    // AND across terms; terms separated by | form OR
    let mut and_terms: Vec<Vec<&str>> = vec![];
    for g in groups {
        if and_terms.is_empty() {
            for t in g {
                and_terms.push(vec![t]);
            }
        } else {
            let mut it = g.into_iter();
            if let Some(first) = it.next() {
                and_terms.last_mut().unwrap().push(first);
            }
            for t in it {
                and_terms.push(vec![t]);
            }
        }
    }
    for alts in and_terms {
        let mut matched: Option<(i64, i64, i64)> = None;
        for t in alts {
            if let Some(r) = term_match(t, text, exact_mode) {
                matched = Some(r);
                break;
            }
        }
        let (s, b, e) = matched?;
        total += s;
        begin = begin.min(b);
        end = end.max(e);
    }
    Some((total, if begin == i64::MAX { 0 } else { begin }, end))
}

fn term_match(term: &str, text: &str, exact_mode: bool) -> Option<(i64, i64, i64)> {
    let mut t = term;
    let mut inverse = false;
    if let Some(r) = t.strip_prefix('!') {
        inverse = true;
        t = r;
    }
    let mut exact = exact_mode;
    let mut prefix = false;
    let mut suffix = false;
    if let Some(r) = t.strip_prefix('\'') {
        exact = !exact_mode;
        t = r;
    }
    if let Some(r) = t.strip_prefix('^') {
        prefix = true;
        exact = true;
        t = r;
    }
    if t.len() > 1 && t.ends_with('$') && !t.ends_with("\\$") {
        suffix = true;
        exact = true;
        t = &t[..t.len() - 1];
    }
    if inverse {
        exact = true;
    }
    let case_sensitive = t.chars().any(|c| c.is_uppercase());
    let tc: Vec<char> = text.chars().collect();
    let pc: Vec<char> = t.chars().collect();
    let r = if exact {
        let (tl, pl): (Vec<char>, Vec<char>) = if case_sensitive {
            (tc.clone(), pc.clone())
        } else {
            (
                tc.iter().map(|c| c.to_lowercase().next().unwrap_or(*c)).collect(),
                pc.iter().map(|c| c.to_lowercase().next().unwrap_or(*c)).collect(),
            )
        };
        let found = if pl.is_empty() {
            Some(0)
        } else if prefix && suffix {
            if tl == pl {
                Some(0)
            } else {
                None
            }
        } else if prefix {
            if tl.starts_with(&pl) {
                Some(0)
            } else {
                None
            }
        } else if suffix {
            if tl.ends_with(&pl) {
                Some(tl.len() - pl.len())
            } else {
                None
            }
        } else {
            (0..=tl.len().saturating_sub(pl.len()))
                .find(|&i| tl.len() >= pl.len() && tl[i..i + pl.len()] == pl[..])
        };
        found.map(|b| (0i64, b as i64, (b + pl.len()) as i64))
    } else {
        fuzzy_match(&pc, &tc, case_sensitive)
    };
    if inverse {
        match r {
            Some(_) => None,
            None => Some((0, 0, 0)),
        }
    } else {
        r
    }
}
