#[derive(Default)]
struct Cli {
    bin: String,
    read_only: bool,
    force_focus: bool,
    print_pwd_as_result: bool,
    read0: bool,
    write0: bool,
    help: bool,
    version: bool,
    vroot: Option<String>,
    config: Option<String>,
    extra_config: Vec<String>,
    on_load: Vec<msg::ExternalMsg>,
    paths: Vec<String>,
    pipe_msg_in: Vec<String>,
    print_msg_in: Vec<String>,
}

fn die(msg: &str) -> ! {
    eprintln!("error: {}", msg);
    std::process::exit(1);
}

fn cwd() -> String {
    std::env::current_dir()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or_else(|_| "/".into())
}

fn absolute(p: &str) -> String {
    path_util::absolutize(p, &cwd())
}

fn check_exists(p: &str) -> String {
    let a = absolute(p);
    if std::path::Path::new(&a).symlink_metadata().is_err() {
        die(&format!("path doesn't exist: {}", a));
    }
    a
}

fn parse_cli() -> Cli {
    let mut args: std::collections::VecDeque<String> = std::env::args().collect();
    let mut cli = Cli::default();
    let bin = args.pop_front().unwrap_or_else(|| "xplr".into());
    cli.bin = std::env::current_exe()
        .ok()
        .map(|p| p.to_string_lossy().to_string())
        .unwrap_or(bin);
    let mut flag_ends = false;
    let mut read_stdin = false;
    while let Some(arg) = args.pop_front() {
        if flag_ends {
            cli.paths.push(arg);
            continue;
        }
        match arg.as_str() {
            "-" => read_stdin = true,
            "-h" | "--help" => cli.help = true,
            "-V" | "--version" => cli.version = true,
            "--read-only" => cli.read_only = true,
            "--force-focus" => cli.force_focus = true,
            "--print-pwd-as-result" => cli.print_pwd_as_result = true,
            "--read0" => cli.read0 = true,
            "--write0" => cli.write0 = true,
            "-0" | "--null" => {
                cli.read0 = true;
                cli.write0 = true;
            }
            "--" => flag_ends = true,
            "-c" | "--config" => match args.pop_front() {
                Some(p) => cli.config = Some(check_exists(&p)),
                None => die("usage: xplr -c PATH"),
            },
            "--vroot" => match args.pop_front() {
                Some(p) => cli.vroot = Some(check_exists(&p)),
                None => die("usage: xplr --vroot PATH"),
            },
            "-C" | "--extra-config" => {
                while let Some(p) = args.pop_front() {
                    if p.starts_with('-') && p != "-" {
                        args.push_front(p);
                        break;
                    }
                    cli.extra_config.push(check_exists(&p));
                }
            }
            "--on-load" => {
                while let Some(m) = args.pop_front() {
                    if m.starts_with('-') && m.len() > 1 {
                        args.push_front(m);
                        break;
                    }
                    match serde_yaml::from_str::<msg::ExternalMsg>(m.trim()) {
                        Ok(m) => cli.on_load.push(m),
                        Err(e) => die(&e.to_string()),
                    }
                }
            }
            "-m" | "--pipe-msg-in" => {
                cli.pipe_msg_in = args.drain(..).collect();
                if cli.pipe_msg_in.is_empty() {
                    die("usage: xplr -m FORMAT [ARGUMENT]...");
                }
            }
            "-M" | "--print-msg-in" => {
                cli.print_msg_in = args.drain(..).collect();
                if cli.print_msg_in.is_empty() {
                    die("usage: xplr -M FORMAT [ARGUMENT]...");
                }
            }
            a => {
                if a.starts_with('-') && a.len() > 1 {
                    die(&format!("invalid argument: {:?}, try `-- {:?}` or `--help`", a, a));
                }
                cli.paths.push(a.to_string());
            }
        }
    }
    if read_stdin {
        let mut s = Vec::new();
        let _ = std::io::stdin().read_to_end(&mut s);
        let d = if cli.read0 { 0u8 } else { b'\n' };
        for p in s.split(|b| *b == d) {
            let p = String::from_utf8_lossy(p).trim_end_matches('\r').to_string();
            if !p.trim().is_empty() {
                cli.paths.push(p);
            }
        }
    }
    cli
}

fn format_msg(args: &[String]) -> Result<String, String> {
    let fmt = &args[0];
    let rest: Vec<String> = args[1..].to_vec();
    let json = jf::format(fmt, &rest).map_err(|e| format!("xplr -m: {}", e))?;
    // validate
    serde_json::from_str::<msg::ExternalMsg>(&json).map_err(|e| e.to_string())?;
    Ok(json)
}

fn main() {
    let cli = parse_cli();

    if !cli.pipe_msg_in.is_empty() {
        let json = match format_msg(&cli.pipe_msg_in) {
            Ok(j) => j,
            Err(e) => die(&e),
        };
        match std::env::var("XPLR_PIPE_MSG_IN") {
            Ok(path) if !path.is_empty() => {
                let data = match std::fs::read(&path) {
                    Ok(d) => d,
                    Err(e) => die(&lua_api::io_error_string(&e)),
                };
                let delim = match data.first() {
                    Some(d) => *d,
                    None => die("failed to detect delimmiter"),
                };
                let mut f = match std::fs::OpenOptions::new().append(true).open(&path) {
                    Ok(f) => f,
                    Err(e) => die(&lua_api::io_error_string(&e)),
                };
                let mut buf = json.into_bytes();
                buf.push(delim);
                if let Err(e) = f.write_all(&buf) {
                    die(&lua_api::io_error_string(&e));
                }
            }
