    }
}

const NEG: i64 = i64::MIN / 4;

/// skim v2 like fuzzy matching. Returns (score, begin, end) with char indices (end inclusive)
pub fn fuzzy_match(pattern: &[char], text: &[char], case_sensitive: bool) -> Option<(i64, i64, i64)> {
    if pattern.is_empty() {
        return Some((0, 0, 0));
    }
    let eq = |a: char, b: char| -> bool {
        if case_sensitive {
            a == b
        } else {
            a == b || a.to_lowercase().eq(b.to_lowercase())
        }
    };
    let mut pi = 0;
    for &c in text.iter() {
        if pi < pattern.len() && eq(c, pattern[pi]) {
            pi += 1;
        }
    }
    if pi < pattern.len() {
        return None;
    }
    let n = text.len();
    let m = pattern.len();
    let bonus: Vec<i64> = (0..n)
        .map(|j| in_place_bonus(if j > 0 { Some(text[j - 1]) } else { None }, text[j]))
        .collect();
    let mut mm = vec![NEG; m * n];
    let mut pp = vec![NEG; m * n];
    let mut from_p = vec![false; m * n];
    let mut pf_p = vec![false; m * n];
    let idx = |i: usize, j: usize| i * n + j;
    for i in 0..m {
        for j in 0..n {
            if eq(text[j], pattern[i]) {
                let ms = 16 + if text[j] != pattern[i] { -2 } else { 0 };
                if i == 0 {
                    mm[idx(i, j)] = ms + bonus[j];
                } else if j > 0 {
                    let pm = mm[idx(i - 1, j - 1)];
                    let ppv = pp[idx(i - 1, j - 1)];
                    let c1 = if pm > NEG { pm + bonus[j].max(4) } else { NEG };
                    let c2 = if ppv > NEG { ppv + bonus[j] } else { NEG };
                    if c1 >= c2 && c1 > NEG {
                        mm[idx(i, j)] = c1 + ms;
                    } else if c2 > NEG {
                        mm[idx(i, j)] = c2 + ms;
                        from_p[idx(i, j)] = true;
                    }
                }
            }
            if j > 0 {
                let a = mm[idx(i, j - 1)];
                let b = pp[idx(i, j - 1)];
                let c1 = if a > NEG { a - 4 } else { NEG };
                let c2 = if b > NEG { b - 1 } else { NEG };
                if c1 >= c2 && c1 > NEG {
                    pp[idx(i, j)] = c1;
                } else if c2 > NEG {
                    pp[idx(i, j)] = c2;
                    pf_p[idx(i, j)] = true;
                }
            }
        }
    }
    let mut best = NEG;
    let mut bj = 0usize;
    for j in 0..n {
        let v = mm[idx(m - 1, j)];
        if v > NEG && v >= best {
            best = v;
            bj = j;
        }
    }
    if best <= NEG {
        return None;
    }
    let mut i = m - 1;
    let mut j = bj;
    while i > 0 {
        let f = from_p[idx(i, j)];
        i -= 1;
        j -= 1;
        if f {
            while pf_p[idx(i, j)] {
                j -= 1;
            }
            j -= 1;
        }
    }
    Some((best, j as i64, bj as i64))
}

